        function setProcessLoaderText(options = {}) {
            const title = document.getElementById('processLoaderTitle');
            const message = document.getElementById('processLoaderMessage');
            const chip = document.getElementById('processLoaderChip');
            const subtext = document.getElementById('processLoaderSubtext');
            const icon = document.getElementById('processLoaderIcon');
            const loader = document.getElementById('processLoader');
            const card = loader ? loader.querySelector('.process-loader-card') : null;
            if (loader && Object.prototype.hasOwnProperty.call(options, 'kind')) {
                loader.classList.remove('process-crop', 'process-print');
                if (options.kind === 'crop') loader.classList.add('process-crop');
                else if (options.kind === 'print') loader.classList.add('process-print');
            }
            if (card && (Object.prototype.hasOwnProperty.call(options, 'variant') || Object.prototype.hasOwnProperty.call(options, 'kind'))) {
                const fastVariant = options.variant === 'fast' || options.kind === 'upload';
                card.classList.toggle('is-fast', !!fastVariant);
                if (loader) loader.classList.toggle('process-simple', !!fastVariant);
            }
            if (icon) icon.className = options.kind === 'crop' ? 'fa-solid fa-crop-simple' : 'fa-solid fa-file-arrow-up';
            if (title) title.textContent = options.title || 'Processing';
            if (message) message.textContent = options.message || 'Please wait, kaam chal raha hai.';
            if (chip) chip.textContent = options.chip || 'ACTIVE';
            if (subtext) subtext.textContent = options.subtext || 'S Printer smart engine working';
        }

        function showProcessLoader(options = {}) {
            processLoaderDepth++;
            setProcessLoaderText(options);
            const loader = document.getElementById('processLoader');
            if (loader) {
                loader.classList.remove('hidden');
                loader.classList.add('flex');
            }
        }

        function updateProcessLoader(options = {}) {
            setProcessLoaderText(options);
        }

        function hideProcessLoader(force = false) {
            processLoaderDepth = force ? 0 : Math.max(0, processLoaderDepth - 1);
            if (processLoaderDepth > 0) return;
            const loader = document.getElementById('processLoader');
            if (loader) {
                loader.classList.add('hidden');
                loader.classList.remove('flex');
                loader.classList.remove('process-crop', 'process-print');
                loader.classList.remove('process-simple');
                const card = loader.querySelector('.process-loader-card');
                if (card) card.classList.remove('is-fast');
            }
        }

        function getPointerClient(ev) {
            if (ev?.touches && ev.touches.length > 0) {
                return { x: ev.touches[0].clientX, y: ev.touches[0].clientY };
            }
            if (ev?.changedTouches && ev.changedTouches.length > 0) {
                return { x: ev.changedTouches[0].clientX, y: ev.changedTouches[0].clientY };
            }
            return { x: ev?.clientX || 0, y: ev?.clientY || 0 };
        }

        function waitForLoaderPaint() {
            return new Promise((resolve) => {
                requestAnimationFrame(() => requestAnimationFrame(resolve));
            });
        }

        function waitForFastPaint() {
            return new Promise((resolve) => requestAnimationFrame(resolve));
        }

        function withTimeout(promise, timeoutMs, message = 'Operation timed out') {
            let timer = null;
            const timeout = new Promise((_, reject) => {
                timer = setTimeout(() => reject(new Error(message)), timeoutMs);
            });
            return Promise.race([promise, timeout]).finally(() => {
                if (timer) clearTimeout(timer);
            });
        }

