        function resizePreviewCanvas() {
            const host = previewCanvas.parentElement;
            if (!host) return;
            updatePreviewPageAspect();
            const rect = host.getBoundingClientRect();
            const dpr = Math.min(window.devicePixelRatio || 1, 2);
            const page = getSheetSize(currentType);
            const cssW = Math.max(260, Math.floor(host.offsetWidth || (rect.width / Math.max(1, previewPageZoom)) || 420));
            const cssH = Math.max(390, Math.floor(host.offsetHeight || (rect.height / Math.max(1, previewPageZoom)) || (cssW * (page.h / page.w))));
            const requestedW = cssW * dpr * Math.max(1, previewPageZoom);
            const requestedH = cssH * dpr * Math.max(1, previewPageZoom);
            const maxCanvasDimension = 4096;
            const resolutionCap = Math.min(1, maxCanvasDimension / Math.max(requestedW, requestedH));
            previewCanvas.width = Math.max(1, Math.round(requestedW * resolutionCap));
            previewCanvas.height = Math.max(1, Math.round(requestedH * resolutionCap));
            renderSheet();
        }

        function updatePreviewPageAspect() {
            const frame = document.getElementById('previewPageFrame');
            const stage = document.getElementById('previewPageStage');
            const printSection = document.getElementById('printSection');
            if (!frame || !stage) return;
            const page = getSheetSize(currentType);
            const isMobile = window.innerWidth < 1024;
            const baseMinHeight = currentType === 'pvc' && pvcPageSizeMode === 'photo4x6' ? 500 : 540;
            const targetHeight = Math.max(baseMinHeight, window.innerHeight - (isMobile ? 260 : 150));
            const sectionWidth = printSection?.clientWidth || window.innerWidth;
            const maxBaseWidth = Math.max(260, sectionWidth - (isMobile ? 24 : 48));
            let baseHeight = targetHeight;
            let baseWidth = baseHeight * (page.w / page.h);
            if (baseWidth > maxBaseWidth) {
                baseWidth = maxBaseWidth;
                baseHeight = baseWidth * (page.h / page.w);
            }
            baseWidth = Math.max(1, Math.round(baseWidth));
            baseHeight = Math.max(1, Math.round(baseHeight));
            frame.style.aspectRatio = `${page.w} / ${page.h}`;
            frame.style.width = `${baseWidth}px`;
            frame.style.height = `${baseHeight}px`;
            frame.style.minHeight = '0';
            frame.style.maxWidth = 'none';
            frame.style.setProperty('--preview-page-zoom', String(previewPageZoom));
            stage.style.width = `${Math.round(baseWidth * previewPageZoom)}px`;
            stage.style.height = `${Math.round(baseHeight * previewPageZoom)}px`;
            frame.classList.toggle('preview-page-zoomed', previewPageZoom > 1);
            if (printSection) printSection.classList.toggle('preview-page-zoom-active', previewPageZoom > 1);
            updatePreviewPageZoomUi();
        }

