        async function logActivity(action, details = '') {
            try {
                // Ensure key exists and signature is valid (Client-side pre-check)
                if (typeof window.sysKey === 'undefined' || !atob(window.sysKey).includes("AkPrintHub_Secure")) return;

                const res = await postToolAction(action, { details });
                
                // Sync Client count with Server response
                if(res.status === 'success' && res.count) {
                    window.siteConfig.downloadsUsed = res.count;
                }
            } catch (e) { console.error("Logging failed", e); }
        }

        function checkGatekeeper(action) {
            const config = window.siteConfig;

            // Guests may try Auto Crop and see its result, but exporting that
            // automatic result requires an account so the server quota remains
            // tied to a durable user before download or print.
            if (!config.isLoggedIn && documentAutoCropUsed) {
                showGatekeeperModal('login');
                return false;
            }
            
            // Phase Logic & Limit Check
            if (!config.isLoggedIn && config.guestLimit < 999999) {
                 if (config.downloadsUsed >= config.guestLimit) {
                    showGatekeeperModal('limit');
                    return false;
                }
            }

            // Permission Level Check
            if (config.permissionLevel === 2) { // Paid Phase
                if (!config.isLoggedIn) { 
                    showGatekeeperModal('login'); return false; 
                }
                else if (config.credits <= 0) { 
                    showGatekeeperModal('pay'); return false; 
                }
            }

            return true;
        }

        function showGatekeeperModal(type) {
            const config = window.siteConfig;
            const gateModal = document.getElementById('gatekeeperModal');
            const gateContent = document.getElementById('gatekeeperContent');
            const gateTitle = document.getElementById('gateTitle');
            const gateMsg = document.getElementById('gateMessage');
            const gateBtn = document.getElementById('gateBtn');
            const gateIcon = document.getElementById('gateIcon');
            const gateData = config.gateData || {};
            document.getElementById('gateGoogleBtn')?.classList.remove('hidden');

            gateModal.classList.remove('hidden');
            setTimeout(() => { 
                gateContent.classList.remove('scale-95', 'opacity-0'); 
                gateContent.classList.add('scale-100', 'opacity-100'); 
            }, 10);

            if (type === 'limit') {
                gateTitle.textContent = gateData.title || "Free Limit Reached";
                gateMsg.innerHTML = gateData.msg || "Limit reached. Please login.";
                gateBtn.textContent = gateData.btn || "Login";
                gateBtn.href = config.loginUrl;
                gateIcon.className = gateData.icon || "fas fa-lock";
                gateIcon.parentElement.className = `mx-auto flex h-16 w-16 items-center justify-center rounded-full mb-4 ${gateData.bg || 'bg-red-100'}`;
            } else if (type === 'pay') {
                gateTitle.textContent = "Premium Feature";
                gateMsg.textContent = "You need premium credits to print this.";
                gateBtn.textContent = "Upgrade Plan";
                gateBtn.href = config.pricingUrl;
                gateIcon.className = "fas fa-crown text-2xl text-yellow-500";
            } else {
                gateTitle.textContent = "Login Required";
                gateMsg.textContent = "Please login to continue.";
                gateBtn.textContent = "Login";
                gateBtn.href = config.loginUrl;
                gateIcon.className = "fas fa-user-lock text-2xl text-indigo-600";
            }
        }

        function closeGatekeeper() {
            const gateModal = document.getElementById('gatekeeperModal');
            const gateContent = document.getElementById('gatekeeperContent');
            gateContent.classList.remove('scale-100', 'opacity-100');
            gateContent.classList.add('scale-95', 'opacity-0');
            setTimeout(() => gateModal.classList.add('hidden'), 300);
        }

        // --- End Security Logic ---

