        function getDefaultPvcTemplate(docType = pvcAutoCropDocType) {
            if (docType === 'pan') docType = 'nsdl_pan';
            const template = getPvcKnownTemplate(docType);
            return template ? JSON.parse(JSON.stringify(template)) : null;
        }

        function isValidTemplateRect(r) {
            return !!r && Number.isFinite(r.x) && Number.isFinite(r.y) && Number.isFinite(r.w) && Number.isFinite(r.h) && r.w > 0 && r.h > 0;
        }

        function normalizeTemplateQuad(quad) {
            if (!Array.isArray(quad) || quad.length !== 4) return null;
            const clean = quad.map((point) => ({
                x: Math.max(0, Math.min(1, Number(point?.x))),
                y: Math.max(0, Math.min(1, Number(point?.y)))
            }));
            return clean.every((point) => Number.isFinite(point.x) && Number.isFinite(point.y))
                ? orderQuadPoints(clean).map((point) => ({ x: +point.x.toFixed(6), y: +point.y.toFixed(6) }))
                : null;
        }

        function normalizeTemplatePayload(data) {
            const singleSide = !!(data && (data.single_side || data.mode === 'single_side_card' || data.content_kind === 'single_side_pvc_card'));
            if (!data || !isValidTemplateRect(data.front) || (!singleSide && !isValidTemplateRect(data.back))) return null;
            const normalized = {
                front: {
                    x: +data.front.x,
                    y: +data.front.y,
                    w: +data.front.w,
                    h: +data.front.h
                },
                box_size_mm: data.box_size_mm || null,
                box_scale_percent: data.box_scale_percent || null,
                preset_version: data.preset_version || null,
                is_custom: data.is_custom === true,
                learned_template_id: data.learned_template_id || null,
                doc_type: data.doc_type || null,
                pdf_signature: data.pdf_signature || null,
                page_size_key: data.page_size_key || null,
                template_scope: data.template_scope || null,
                page_number: Math.max(0, Number(data.page_number || 0)),
                paired_page_count: Math.max(0, Number(data.paired_page_count || 0)),
                ai_auto_template: data.ai_auto_template || null,
                mode: singleSide ? 'single_side_card' : (data.mode || null),
                single_side: singleSide
            };
            if (!singleSide) {
                normalized.back = {
                    x: +data.back.x,
                    y: +data.back.y,
                    w: +data.back.w,
                    h: +data.back.h
                };
            }
            const frontQuad = normalizeTemplateQuad(data.front_quad);
            const backQuad = normalizeTemplateQuad(data.back_quad);
            const singleQuad = normalizeTemplateQuad(data.quad);
            const rectQuad = (rect) => normalizeTemplateQuad([
                { x: rect.x, y: rect.y },
                { x: rect.x + rect.w, y: rect.y },
                { x: rect.x + rect.w, y: rect.y + rect.h },
                { x: rect.x, y: rect.y + rect.h }
            ]);
            if (singleSide) {
                normalized.quad = singleQuad || frontQuad || rectQuad(normalized.front);
            } else {
                normalized.front_quad = frontQuad || rectQuad(normalized.front);
                normalized.back_quad = backQuad || rectQuad(normalized.back);
            }
            return normalized;
        }

        function loadPvcTemplateFromStorage() {
            try {
                pvcActiveCropSourceInfo = getPvcDefaultCropSourceInfo(pvcAutoCropDocType);
                if (pvcActivePdfMeta && getPvcTemplateScopeFromMeta(pvcActivePdfMeta).startsWith('two_page_pdf')) {
                    pvcActiveTemplateMatch = null;
                    pvcLockedTemplate = null;
                    pvcSingleSideAiMode = false;
                    isSingleSide = false;
                    pvcActiveCropSourceInfo = {
                        crop_source: 'two_page_pdf_coordinates',
                        doc_type: sanitizePvcDocType(pvcAutoCropDocType),
                        doc_label: getPvcDocTypeLabel(pvcAutoCropDocType),
                        match_reason: '2-page PDF uses independent page 1/page 2 coordinates'
                    };
                    syncSingleSideUI();
                    return;
                }
                if (pvcActiveTemplateMatch?.template && sanitizePvcDocType(pvcActiveTemplateMatch.doc_type) === sanitizePvcDocType(pvcAutoCropDocType)) {
                    pvcLockedTemplate = normalizeTemplatePayload(pvcActiveTemplateMatch.template);
                    pvcActiveCropSourceInfo = {
                        crop_source: 'allowed_template',
                        doc_type: sanitizePvcDocType(pvcActiveTemplateMatch.doc_type || pvcAutoCropDocType),
                        doc_label: pvcActiveTemplateMatch.doc_label || getPvcDocTypeLabel(pvcAutoCropDocType),
                        template_id: pvcActiveTemplateMatch.id || '',
                        template_name: pvcActiveTemplateMatch.name || pvcActiveTemplateMatch.doc_label || '',
                        match_score: Number(pvcActiveTemplateMatch.score || pvcActiveTemplateMatch.match_score || 0),
                        match_reason: pvcActiveTemplateMatch.match_reason || 'approved learned template matched'
                    };
                    if (pvcLockedTemplate) return;
                }
                if (pvcActivePdfMeta) {
                    pvcLockedTemplate = getDefaultPvcTemplate() || getDefaultPvcTemplate('aadhaar');
                    pvcSingleSideAiMode = false;
                    return;
                }
                let raw = localStorage.getItem(getPvcTemplateStorageKey());
                if (!raw && pvcAutoCropDocType === 'nsdl_pan') raw = localStorage.getItem('ak_pvc_template_coords_pan');
                if (!raw) {
                    pvcLockedTemplate = getDefaultPvcTemplate() || getDefaultPvcTemplate('aadhaar');
                    return;
                }
                const parsed = normalizeTemplatePayload(JSON.parse(raw));
                const presetVersion = PVC_TEMPLATE_PRESET_VERSION[pvcAutoCropDocType] || null;
                if (parsed && parsed.is_custom && (!presetVersion || parsed.preset_version === presetVersion)) {
                    pvcLockedTemplate = parsed;
                    pvcActiveCropSourceInfo = {
                        crop_source: 'local_saved_template',
                        doc_type: sanitizePvcDocType(pvcAutoCropDocType),
                        doc_label: getPvcDocTypeLabel(pvcAutoCropDocType),
                        match_reason: 'browser local template'
                    };
                } else {
                    pvcLockedTemplate = getDefaultPvcTemplate() || getDefaultPvcTemplate('aadhaar');
                    if (presetVersion) localStorage.setItem(getPvcTemplateStorageKey(), JSON.stringify({ ...pvcLockedTemplate, is_custom: true }));
                }
            } catch (e) {
                pvcActiveCropSourceInfo = getPvcDefaultCropSourceInfo(pvcAutoCropDocType);
                pvcLockedTemplate = pvcActivePdfMeta && getPvcTemplateScopeFromMeta(pvcActivePdfMeta).startsWith('two_page_pdf')
                    ? null
                    : (getDefaultPvcTemplate() || getDefaultPvcTemplate('aadhaar'));
            }
        }

        function makePvcTemplatePreviewDataUrl(dataUrl = currentPvcSourceDataUrl, maxDim = 960, quality = 0.82) {
            return new Promise((resolve) => {
                if (!dataUrl) {
                    resolve('');
                    return;
                }
                const img = new Image();
                img.onload = () => {
                    try {
                        const iw = img.naturalWidth || img.width;
                        const ih = img.naturalHeight || img.height;
                        const safeMaxDim = Math.max(160, Math.min(1200, Number(maxDim) || 960));
                        const safeQuality = Math.max(0.4, Math.min(0.9, Number(quality) || 0.82));
                        const ratio = Math.min(1, safeMaxDim / Math.max(iw, ih));
                        const c = document.createElement('canvas');
                        c.width = Math.max(1, Math.round(iw * ratio));
                        c.height = Math.max(1, Math.round(ih * ratio));
                        const x = c.getContext('2d');
                        x.fillStyle = '#ffffff';
                        x.fillRect(0, 0, c.width, c.height);
                        x.imageSmoothingEnabled = true;
                        x.imageSmoothingQuality = 'high';
                        x.drawImage(img, 0, 0, c.width, c.height);
                        resolve(c.toDataURL('image/jpeg', safeQuality));
                    } catch (e) {
                        resolve('');
                    }
                };
                img.onerror = () => resolve('');
                img.src = dataUrl;
            });
        }

        async function savePvcLearnedTemplate(template, options = {}) {
            const activeMeta = options.pdfMeta && typeof options.pdfMeta === 'object'
                ? options.pdfMeta
                : pvcActivePdfMeta;
            if (!template || !activeMeta) return;
            const rotationDegrees = normalizeRightAngle(Number(options.rotationDegrees || 0));
            let sourceDataUrl = options.sourceDataUrl || currentPvcSourceDataUrl || currentDocumentSourceDataUrl || '';
            if (!sourceDataUrl && isMatUsable(srcMat)) {
                try {
                    sourceDataUrl = getMatPreviewDataUrl(srcMat) || '';
                } catch (_) {
                    sourceDataUrl = '';
                }
            }
            const selectedDocType = sanitizePvcDocType(options.selectedDocType || pvcAutoCropDocType || 'custom_card');
            const selectedCropSide = (options.cropSide || currentSide) === 'back' ? 'back' : 'front';
            const templateScope = getPvcTemplateScopeFromMeta(activeMeta);
            const templatePageNumber = Math.max(0, Number(activeMeta.page_number || 0));
            const templatePairedPageCount = Math.max(0, Number(activeMeta.paired_page_count || (templateScope.startsWith('two_page_pdf') ? 2 : 0)));
            const normalizedGeometry = normalizeTemplatePayload(template);
            if (normalizedGeometry) template = { ...template, ...normalizedGeometry };
            template = mapPvcTemplateToSourceOrientation(template, rotationDegrees);
            const learnedDocType = sanitizePvcDocType(activeMeta.doc_type || selectedDocType || 'custom_card');
            const learnedDocLabel = activeMeta.doc_label || getPvcDocTypeLabel(learnedDocType);
            const captureReason = options.captureReason || 'user_recrop';
            const hasUserCorrection = Object.prototype.hasOwnProperty.call(options, 'hasUserCorrection')
                ? !!options.hasUserCorrection
                : !!template.ai_auto_template;
            const confirmedInCropper = Object.prototype.hasOwnProperty.call(options, 'confirmedInCropper')
                ? !!options.confirmedInCropper
                : hasUserCorrection;
            if (window.siteConfig?.pvcLearningSaveEnabled === false) {
                upsertPvcLearnedTemplateLocal({
                    id: `${learnedDocType}|${templateScope}|${templatePageNumber}|${activeMeta.pdf_signature || ''}|${activeMeta.page_size_key || ''}`,
                    status: 'pending',
                    doc_type: learnedDocType,
                    doc_label: learnedDocLabel,
                    capture_reason: captureReason,
                    template_scope: templateScope,
                    page_number: templatePageNumber,
                    paired_page_count: templatePairedPageCount,
                    pdf_signature: activeMeta.pdf_signature || '',
                    page_size_key: activeMeta.page_size_key || '',
                    template: {
                        ...template,
                        is_custom: true,
                        doc_type: learnedDocType,
                        template_scope: templateScope,
                        page_number: templatePageNumber,
                        paired_page_count: templatePairedPageCount,
                        preset_version: template.preset_version || 'local-only'
                    },
                    user_validation: {
                        confirmed_in_cropper: confirmedInCropper,
                        changed_from_ai: hasUserCorrection
                    },
                    correction_review: {
                        has_user_correction: hasUserCorrection,
                        capture_reason: captureReason
                    },
                    updated_at: new Date().toISOString()
                }, true);
                return;
            }
            const isSingleTemplate = !!(template.single_side || template.mode === 'single_side_card' || pvcSingleSideAiMode || (template.front && !template.back));
            const correctedTemplate = isSingleTemplate
                ? {
                    mode: 'single_side_card',
                    front: template.front,
                    ...(template.quad ? { quad: template.quad } : {})
                }
                : {
                    front: template.front,
                    back: template.back,
                    ...(template.front_quad ? { front_quad: template.front_quad } : {}),
                    ...(template.back_quad ? { back_quad: template.back_quad } : {})
                };
            const rawRectifiedTargets = options.rectifiedTargets && typeof options.rectifiedTargets === 'object'
                ? options.rectifiedTargets
                : {};
            const [learningAssets, hostReviewPreviewDataUrl] = await Promise.all([
                prepareLearningAssetSet(sourceDataUrl, {
                    ...(rawRectifiedTargets.front ? { front: rawRectifiedTargets.front } : {}),
                    ...(rawRectifiedTargets.back ? { back: rawRectifiedTargets.back } : {})
                }),
                makePvcTemplatePreviewDataUrl(sourceDataUrl, 220, 0.55)
            ]);
            const sourcePreviewDataUrl = learningAssets.sourcePreview;
            const rectifiedTargetFront = learningAssets.targets.front || '';
            const rectifiedTargetBack = learningAssets.targets.back || '';
            const sourceKind = activeMeta.source_kind || 'unknown';
            const learningWorkflow = inferCardLearningWorkflow('pvc', sourceKind, options.captureMeta || currentLearningCaptureMeta || {});
            const qualityQuad = correctedTemplate.quad || correctedTemplate.front_quad || null;
            const qualityProfile = await computeLearningQualityProfile(sourcePreviewDataUrl, qualityQuad);
            const sourceCapture = normalizeLearningCaptureMeta({
                ...(options.captureMeta || currentLearningCaptureMeta || {}),
                side: selectedCropSide,
                originalWidth: qualityProfile.source_width_px || 0,
                originalHeight: qualityProfile.source_height_px || 0
            });
            const [frontTargetProfile, backTargetProfile] = await Promise.all([
                getLearningTargetProfile(rectifiedTargetFront, 'rectified_front'),
                getLearningTargetProfile(rectifiedTargetBack, 'rectified_back')
            ]);
            const trainingProfile = {
                workflow: learningWorkflow,
                supervision_strength: hasUserCorrection ? 'strong_user_corrected_layout' : 'auto_layout_pending_review',
                paired_front_target: !!rectifiedTargetFront,
                paired_back_target: !!rectifiedTargetBack,
                eligible_for: 'document_classification,layout_detection,quad_regression,perspective_dewarp,content_preservation',
                not_eligible_for: 'pixel_exact_mask,alpha_matting,missing_content_reconstruction',
                manual_mask_priority: learningWorkflow === 'digital_pdf_pvc' ? 'not_required_for_pdf_crop' : (qualityProfile.difficulty_tier || 'unknown'),
                boundary_label_policy: 'printed_card_edge_excludes_background_and_lamination_overhang'
            };
            const entry = {
                id: `${learnedDocType}|${templateScope}|${templatePageNumber}|${activeMeta.pdf_signature || ''}|${activeMeta.page_size_key || ''}`,
                doc_type: learnedDocType,
                doc_label: learnedDocLabel,
                template_scope: templateScope,
                page_number: templatePageNumber,
                paired_page_count: templatePairedPageCount,
                capture_reason: captureReason,
                pdf_signature: activeMeta.pdf_signature || '',
                page_size_key: activeMeta.page_size_key || '',
                render_size_key: activeMeta.render_size_key || activeMeta.features?.layout?.render_size_key || '',
                text_signature: activeMeta.text_signature || '',
                layout_signature: activeMeta.layout_signature || activeMeta.features?.layout?.text_layout_signature || '',
                image_signature: activeMeta.image_signature || '',
                source_kind: activeMeta.source_kind || 'unknown',
                content_kind: isSingleTemplate ? 'single_side_pvc_card' : (activeMeta.content_kind || 'id_card'),
                learning_workflow: learningWorkflow,
                learning_profile_version: 'card_capture_v2',
                rotation_degrees: rotationDegrees,
                coordinate_space: 'source_preview_normalized',
                user_selection: {
                    family: 'pvc',
                    selected_doc_type: selectedDocType,
                    resolved_doc_type: learnedDocType,
                    crop_side: selectedCropSide,
                    confirmed_in_cropper: confirmedInCropper
                },
                user_validation: {
                    confirmed_in_cropper: confirmedInCropper,
                    changed_from_ai: hasUserCorrection,
                    ai_suggestion_available: !!template.ai_auto_template,
                    interface: 'id-card-print.php'
                },
                pdf_meta: {
                    ...activeMeta,
                    template_scope: templateScope,
                    page_number: templatePageNumber,
                    paired_page_count: templatePairedPageCount
                },
                features: activeMeta.features || {
                    text_markers: String(activeMeta.text_signature || '').split('-').filter(Boolean),
                    visual: lastVisualMeta?.visual || {},
                    layout: {}
                },
                source_capture: sourceCapture,
                quality_profile: qualityProfile,
                target_profile: {
                    front: frontTargetProfile,
                    back: backTargetProfile
                },
                training_sample: {
                    input_type: activeMeta.source_kind || 'unknown',
                    content_kind: isSingleTemplate ? 'single_side_pvc_card' : (activeMeta.content_kind || 'id_card'),
                    coordinate_space: 'source_preview_normalized',
                    layout_ready: true,
                    mask_ready: false,
                    mask_status: 'quad_or_rectangle_seed_requires_pixel_review',
                    paired_target: {
                        front_available: !!rectifiedTargetFront,
                        back_available: !!rectifiedTargetBack,
                        content_changed: false,
                        pixel_exact_mask: false
                    },
                    training_profile: trainingProfile,
                    source_rotation_degrees: rotationDegrees
                },
                correction_review: {
                    ai_auto_template: template.ai_auto_template || null,
                    user_corrected_template: correctedTemplate,
                    has_user_correction: hasUserCorrection,
                    capture_reason: captureReason,
                    captured_at: new Date().toISOString()
                },
                template: {
                    ...template,
                    ...(isSingleTemplate ? { mode: 'single_side_card', single_side: true, back: undefined } : {}),
                    is_custom: true,
                    doc_type: selectedDocType,
                    template_scope: templateScope,
                    page_number: templatePageNumber,
                    paired_page_count: templatePairedPageCount,
                    pdf_signature: activeMeta.pdf_signature || '',
                    page_size_key: activeMeta.page_size_key || '',
                    preset_version: template.preset_version || 'learned'
                },
                source_preview_data_url: sourcePreviewDataUrl,
                rectified_target_front_data_url: rectifiedTargetFront,
                rectified_target_back_data_url: rectifiedTargetBack,
                host_review_preview_data_url: hostReviewPreviewDataUrl,
                status: 'pending',
                created_at: new Date().toISOString(),
                updated_at: new Date().toISOString()
            };
            try {
                const res = await postEncryptedPvcTemplate(entry);
                if (res?.settings) syncPvcLearningSaveState(res.settings);
                if (res?.skipped) {
                    upsertPvcLearnedTemplateLocal(entry, true);
                    return;
                }
                if (res?.status === 'success') {
                    upsertPvcLearnedTemplateLocal({ ...entry, ...(res.template || {}) }, true);
                } else {
                    upsertPvcLearnedTemplateLocal(entry, true);
                }
                if (SHOW_BACKGROUND_AI_COLLECTION_FEEDBACK && res?.status === 'success' && !options.quiet) {
                    const approvedNow = (res.template?.status || entry.status) === 'approved';
                    showModal(
                        approvedNow ? "Auto Crop Learned" : "AI Review Pending",
                        approvedNow
                            ? "Crop correction save ho gaya. Same layout wali file future me isi crop se auto detect hogi."
                            : "Crop correction save ho gaya. Is browser me same file/layout turant use hoga; admin approve karega tabhi sab users ke future auto-crop me use hoga.",
                        "success"
                    );
                }
            } catch (e) {
                upsertPvcLearnedTemplateLocal(entry, true);
                console.warn('PVC learned template server save failed', e);
            }
        }

        function getA4QuadFromAiAnalysis(ai) {
            const quad = ai?.straighten?.quad || ai?.document?.quad || ai?.crop?.quad || null;
            if (!Array.isArray(quad) || quad.length !== 4) return null;
            return quad.map(normalizeAiPoint).map((p) => ({
                x: +Number(p.x || 0).toFixed(6),
                y: +Number(p.y || 0).toFixed(6)
            }));
        }

        async function queuePvcA4AutoDetectApprovalSample(reason = 'pvc_a4_auto_detect', ai = shadowPvcAiAnalysis, sourceDataUrl = currentPvcSourceDataUrl) {
            try {
                if (!pvcActivePdfMeta || !sourceDataUrl || window.siteConfig?.pvcLearningSaveEnabled === false) return false;
                const autoQuad = getA4QuadFromAiAnalysis(ai);
                const selectedQuad = normalizeCropperQuad(cropperPoints);
                const quad = selectedQuad || autoQuad || [
                    { x: 0, y: 0 },
                    { x: 1, y: 0 },
                    { x: 1, y: 1 },
                    { x: 0, y: 1 }
                ];
                const meta = {
                    ...(pvcActivePdfMeta || {}),
                    doc_type: 'a4_document',
                    doc_label: 'A4 Document',
                    content_kind: 'a4_document',
                    source_kind: pvcActivePdfMeta?.source_kind || reason
                };
                const [sourcePreviewDataUrl, hostReviewPreviewDataUrl] = await Promise.all([
                    makePvcTemplatePreviewDataUrl(sourceDataUrl, 960, 0.82),
                    makePvcTemplatePreviewDataUrl(sourceDataUrl, 220, 0.55)
                ]);
                const entry = {
                    doc_type: 'a4_document',
                    doc_label: 'A4 Page',
                    learning_workflow: 'document_page_crop',
                    learning_profile_version: 'card_capture_v2',
                    capture_reason: reason,
                    pdf_signature: meta.pdf_signature || '',
                    page_size_key: meta.page_size_key || '',
                    render_size_key: meta.render_size_key || meta.features?.layout?.render_size_key || '',
                    text_signature: meta.text_signature || '',
                    layout_signature: meta.layout_signature || meta.features?.layout?.text_layout_signature || '',
                    image_signature: meta.image_signature || '',
                    source_kind: meta.source_kind || reason,
                    content_kind: 'a4_document',
                    user_selection: {
                        family: 'pvc',
                        selected_doc_type: 'a4_document',
                        resolved_doc_type: 'a4_document',
                        crop_side: 'front',
                        confirmed_in_cropper: false
                    },
                    user_validation: {
                        confirmed_in_cropper: false,
                        changed_from_ai: !!(autoQuad && selectedQuad && quadDiffScore(selectedQuad, autoQuad) > 0.012),
                        ai_suggestion_available: !!autoQuad,
                        interface: 'id-card-print.php'
                    },
                    pdf_meta: meta,
                    features: meta.features || {
                        text_markers: String(meta.text_signature || '').split('-').filter(Boolean),
                        visual: lastVisualMeta?.visual || {},
                        layout: {}
                    },
                    training_sample: {
                        input_type: meta.source_kind || reason,
                        content_kind: 'a4_document',
                        label_type: 'a4_page_quad',
                        auto_labels: autoQuad ? { mode: 'a4_document', quad: autoQuad } : null,
                        labels: { mode: 'a4_document', quad }
                    },
                    correction_review: {
                        ai_auto_template: autoQuad ? { mode: 'a4_document', quad: autoQuad } : null,
                        user_corrected_template: { mode: 'a4_document', quad },
                        has_user_correction: false,
                        capture_reason: reason,
                        captured_at: new Date().toISOString()
                    },
                    template: {
                        quad,
                        is_custom: true,
                        doc_type: 'a4_document',
                        pdf_signature: meta.pdf_signature || '',
                        page_size_key: meta.page_size_key || '',
                        preset_version: 'pvc-a4-auto-detected'
                    },
                    source_preview_data_url: sourcePreviewDataUrl,
                    host_review_preview_data_url: hostReviewPreviewDataUrl,
                    status: 'pending',
                    created_at: new Date().toISOString(),
                    updated_at: new Date().toISOString()
                };
                const res = await postEncryptedPvcTemplate(entry);
                if (res?.settings) syncPvcLearningSaveState(res.settings);
                return res?.status === 'success' || !!res?.skipped;
            } catch (err) {
                console.warn('PVC A4 approval sample save failed', err);
                return false;
            }
        }

        function pointsToBoundingRect(points) {
            const valid = (points || []).filter((p) => Number.isFinite(p?.x) && Number.isFinite(p?.y));
            if (!valid.length) return null;
            const left = Math.min(...valid.map((p) => p.x));
            const top = Math.min(...valid.map((p) => p.y));
            const right = Math.max(...valid.map((p) => p.x));
            const bottom = Math.max(...valid.map((p) => p.y));
            return { x: left, y: top, w: right - left, h: bottom - top };
        }

        function buildPvcTemplateFromAppliedPoints(frontPoints, backPoints) {
            const refMat = isMatUsable(displayMat) ? displayMat : (isMatUsable(srcMat) ? srcMat : null);
            if (!refMat) return null;
            const front = pointsToBoundingRect(frontPoints);
            const back = pointsToBoundingRect(backPoints);
            if (!front || !back || front.w <= 0 || front.h <= 0 || back.w <= 0 || back.h <= 0) return null;
            return {
                front: normalizeRect(front, refMat.cols, refMat.rows),
                back: normalizeRect(back, refMat.cols, refMat.rows),
                front_quad: normalizeQuadAgainstMat(frontPoints, refMat),
                back_quad: normalizeQuadAgainstMat(backPoints, refMat),
                box_size_mm: getRectSizeMm(front, refMat.cols, refMat.rows),
                box_scale_percent: pvcLockedTemplate?.box_scale_percent || null,
                ai_auto_template: pvcLockedTemplate?.ai_auto_template || null,
                preset_version: pvcLockedTemplate?.preset_version || 'auto-captured'
            };
        }

        function getPvcTemplateMargins(template = pvcLockedTemplate) {
            const clean = normalizeTemplatePayload(template);
            if (!clean?.front) return {};
            const marginForRect = (rect) => ({
                left: +Number(rect.x || 0).toFixed(6),
                top: +Number(rect.y || 0).toFixed(6),
                right: +Number(Math.max(0, 1 - (Number(rect.x || 0) + Number(rect.w || 0)))).toFixed(6),
                bottom: +Number(Math.max(0, 1 - (Number(rect.y || 0) + Number(rect.h || 0)))).toFixed(6)
            });
            const out = { front: marginForRect(clean.front) };
            if (clean.back) out.back = marginForRect(clean.back);
            return out;
        }

        function recordPvcAutoCropMonitor(template = pvcLockedTemplate, extra = {}) {
            if (!window.siteConfig?.canApprovePvcTemplates) return;
            const clean = normalizeTemplatePayload(template);
            if (!clean?.front) return;
            const sourceInfo = extra.sourceInfo || pvcActiveCropSourceInfo || getPvcDefaultCropSourceInfo(pvcAutoCropDocType);
            const payload = {
                crop_source: extra.crop_source || sourceInfo.crop_source || 'unknown',
                doc_type: sourceInfo.doc_type || pvcActivePdfMeta?.doc_type || pvcAutoCropDocType || 'custom_card',
                doc_label: sourceInfo.doc_label || getPvcDocTypeLabel(pvcAutoCropDocType),
                content_kind: pvcActivePdfMeta?.content_kind || inferContentKindFromMeta(pvcActivePdfMeta || {}),
                source_kind: pvcActivePdfMeta?.source_kind || extra.source_kind || '',
                trigger: extra.trigger || 'auto_crop',
                template_id: sourceInfo.template_id || '',
                template_name: sourceInfo.template_name || '',
                match_score: sourceInfo.match_score || 0,
                match_reason: sourceInfo.match_reason || '',
                page_size_key: pvcActivePdfMeta?.page_size_key || '',
                pdf_signature: pvcActivePdfMeta?.pdf_signature || '',
                margins_json: JSON.stringify(getPvcTemplateMargins(clean)),
                box_size_mm_json: JSON.stringify(clean.box_size_mm || {}),
                template_json: JSON.stringify({
                    front: clean.front,
                    back: clean.back || null,
                    single_side: !!clean.single_side,
                    box_scale_percent: clean.box_scale_percent || null
                })
            };
            postToolAction('save_pvc_auto_crop_monitor', payload).catch((err) => console.warn('PVC crop monitor save failed', err));
        }

        function queuePvcAutoCropApprovalSample(frontPoints, backPoints, reason = 'auto_crop_upload', options = {}) {
            if (currentType !== 'pvc' || pvcRecropMode || forcePvcTemplatePlacement || !pvcActivePdfMeta) return;
            let template = null;
            if (Array.isArray(backPoints) && backPoints.length === 4) {
                template = buildPvcTemplateFromAppliedPoints(frontPoints, backPoints);
            } else {
                const refMat = isMatUsable(displayMat) ? displayMat : (isMatUsable(srcMat) ? srcMat : null);
                const frontRect = pointsToBoundingRect(frontPoints);
                if (refMat && frontRect?.w > 0 && frontRect?.h > 0) {
                    template = {
                        front: normalizeRect(frontRect, refMat.cols, refMat.rows),
                        quad: normalizeQuadAgainstMat(frontPoints, refMat),
                        mode: 'single_side_card',
                        single_side: true,
                        box_size_mm: getRectSizeMm(frontRect, refMat.cols, refMat.rows),
                        ai_auto_template: pvcLockedTemplate?.ai_auto_template || null,
                        preset_version: pvcLockedTemplate?.preset_version || 'auto-captured-single'
                    };
                }
            }
            if (!template) return;
            const learningMeta = JSON.parse(JSON.stringify(options.pdfMeta || pvcActivePdfMeta));
            const captureMeta = normalizeLearningCaptureMeta(options.captureMeta || currentLearningCaptureMeta || {});
            const selectedDocType = sanitizePvcDocType(options.selectedDocType || pvcAutoCropDocType || 'custom_card');
            const sourceDataUrl = options.sourceDataUrl || getActivePvcCropSourceDataUrl();
            const rectifiedTargets = options.rectifiedTargets && typeof options.rectifiedTargets === 'object'
                ? { ...options.rectifiedTargets }
                : {};
            queueBackgroundLearning(() => savePvcLearnedTemplate(template, {
                quiet: true,
                captureReason: reason,
                hasUserCorrection: false,
                confirmedInCropper: false,
                sourceDataUrl,
                rectifiedTargets,
                pdfMeta: learningMeta,
                captureMeta,
                selectedDocType
            }), 'PVC auto-crop learning');
        }

        function savePvcTemplateToStorage(template, options = {}) {
            const rotationDegrees = normalizeRightAngle(Number(options.rotationDegrees || 0));
            const cleaned = normalizeTemplatePayload(mapPvcTemplateToSourceOrientation(template, rotationDegrees));
            if (!cleaned) return;
            const learningMeta = options.pdfMeta && typeof options.pdfMeta === 'object'
                ? options.pdfMeta
                : pvcActivePdfMeta;
            cleaned.is_custom = true;
            cleaned.preset_version = PVC_TEMPLATE_PRESET_VERSION[pvcAutoCropDocType] || cleaned.preset_version || null;
            cleaned.doc_type = sanitizePvcDocType(pvcAutoCropDocType);
            cleaned.pdf_signature = learningMeta?.pdf_signature || null;
            cleaned.page_size_key = learningMeta?.page_size_key || null;
            pvcLockedTemplate = cleaned;
            if (!learningMeta) {
                try {
                    localStorage.setItem(getPvcTemplateStorageKey(), JSON.stringify(cleaned));
                } catch (e) {}
            }
            savePvcLearnedTemplate(cleaned, { ...options, rotationDegrees: 0 }).catch(() => false);
        }

        async function resetPvcTemplateToDefault() {
            const docType = sanitizePvcDocType(pvcApprovalFixState?.entry?.doc_type || pvcAutoCropDocType || 'custom_card');
            const hasServerOverride = PVC_DEFAULT_TEMPLATE_OVERRIDE_TYPES.has(docType);
            if (hasServerOverride && !hasPvcAdminCapability()) {
                showModal("Admin Required", "Server default reset karne ke liye admin login required hai.", "warn");
                return false;
            }
            if (hasServerOverride && !confirm(`${getPvcDocTypeLabel(docType)} ka admin server default hata kar built-in crop wapas lana hai?`)) {
                return false;
            }

            try {
                if (hasServerOverride) {
                    const res = await postToolAction('reset_pvc_default_template_override', { doc_type: docType });
                    if (res?.status !== 'success') throw new Error(res?.message || 'Server default reset failed');
                    restorePvcBuiltInDefaultTemplates();
                    Object.entries(res.overrides || {}).forEach(([overrideDocType, template]) => {
                        const key = sanitizePvcDocType(overrideDocType);
                        if (!template?.front || !template?.back) return;
                        PVC_DEFAULT_TEMPLATES[key] = {
                            ...(PVC_DEFAULT_TEMPLATES[key] || {}),
                            ...template
                        };
                        PVC_DEFAULT_TEMPLATE_OVERRIDE_TYPES.add(key);
                    });
                }

                try {
                    localStorage.removeItem(getPvcTemplateStorageKey(docType));
                } catch (e) {}

                const nextDefault = PVC_DEFAULT_TEMPLATES[docType] || PVC_BUILT_IN_DEFAULT_TEMPLATES[docType] || null;
                pvcLockedTemplate = nextDefault ? normalizeTemplatePayload(JSON.parse(JSON.stringify(nextDefault))) : null;
                forcePvcTemplatePlacement = false;
                pvcActiveCropSourceInfo = getPvcDefaultCropSourceInfo(docType);

                if (isMatUsable(displayMat) && pvcTemplatePlacementMode && nextDefault?.front && nextDefault?.back) {
                    pvcTemplateBoxes = {
                        front: denormalizeRect(nextDefault.front, displayMat.cols, displayMat.rows),
                        back: denormalizeRect(nextDefault.back, displayMat.cols, displayMat.rows)
                    };
                    drawCanvas();
                    syncPvcSizeUi();
                }

                showModal(
                    "Default Restored",
                    hasServerOverride
                        ? "Admin server override hata diya gaya; built-in PVC coordinates active hain."
                        : "Is browser ka custom crop hata diya gaya; current default coordinates active hain.",
                    "success"
                );
                return true;
            } catch (e) {
                showModal("Reset Failed", e?.message || "PVC default reset nahi hua.", "error");
                return false;
            }
        }

        function startPvcRecalibration() {
            if (currentType !== 'pvc') {
                showModal("PVC Required", "Pehle PVC mode select karein.", "warn");
                return;
            }
            if (!requirePvcProAction("PVC Re-Calibration")) return;
            forcePvcTemplatePlacement = true;
            clearPvcRecropTarget();
            showModal("Set New Crop", "Ab PDF upload karke naya crop template set karein.", "info");
            triggerUpload('front');
        }

        function syncDocumentAiRecropControls() {
            const visible = DOCALIGNER_TEST_MODE
                && isDocumentAutoCropEnabled()
                && documentItemRecropState.active
                && currentType !== 'pvc'
                && !!documentItemRecropState.sourceDataUrl;
            document.getElementById('cropperModal')?.classList.toggle('document-ai-recrop-active', visible);
            ['documentAiRecropMobileBar', 'documentAiRecropDesktopBar'].forEach((id) => {
                document.getElementById(id)?.classList.toggle('hidden', !visible);
            });
            ['btnDocumentAiRecropMobile', 'btnDocumentAiRecropDesktop'].forEach((id) => {
                const button = document.getElementById(id);
                if (!button) return;
                button.disabled = !visible || documentAiRecropBusy;
                const label = button.querySelector('[data-ai-recrop-label]');
                if (label) label.textContent = documentAiRecropBusy ? 'AI Crop…' : 'AI Crop';
                const icon = button.querySelector('i');
                if (icon) icon.className = documentAiRecropBusy
                    ? 'fa-solid fa-spinner fa-spin'
                    : 'fa-solid fa-wand-magic-sparkles';
            });
        }

        function resetDocumentItemRecropState() {
            documentAiRecropRequestSequence++;
            documentAiRecropBusy = false;
            documentItemRecropState = { active: false, targetId: '', side: 'front', sourceDataUrl: '' };
            syncDocumentAiRecropControls();
        }

        async function runAiCropForCurrentRecrop() {
            if (!isDocumentAutoCropEnabled()) return;
            const recropState = { ...documentItemRecropState };
            if (!DOCALIGNER_TEST_MODE || !recropState.active || !recropState.sourceDataUrl || currentType === 'pvc') {
                showModal('Re-Crop Required', 'Pehle preview se AI crop wala card select karke Re-Crop kholein.', 'warn');
                return;
            }
            if (documentAiRecropBusy) return;

            const target = batchQueue.find((item) => item?.queueItemId === recropState.targetId) || null;
            const requestToken = ++documentAiRecropRequestSequence;
            documentAiRecropBusy = true;
            syncDocumentAiRecropControls();
            showProcessLoader({
                kind: 'crop',
                variant: 'fast',
                title: 'AI Auto Crop',
                message: 'Original image par card boundary aur 4 corners check ho rahe hain.',
                chip: 'AI CROP',
                subtext: 'Result pehle cropper me dots ke roop me aayega'
            });

            try {
                await waitForFastPaint();
                const ai = await requestCropAiAnalysis('analyze_document_crop_ai', recropState.sourceDataUrl, null, {
                    docType: target?.type === 'a4' ? 'a4_document' : 'id_card',
                    contentKind: target?.type === 'a4' ? 'a4_document' : 'id_card',
                    sourceKind: 'image',
                    cropSide: recropState.side,
                    userSelectedFamily: target?.type || currentType,
                    userSelectedDocType: target?.type === 'a4' ? 'a4_document' : 'id_card',
                    timeoutMs: DOCALIGNER_BROWSER_TIMEOUT_MS
                });
                const stillCurrent = requestToken === documentAiRecropRequestSequence
                    && documentItemRecropState.active
                    && documentItemRecropState.targetId === recropState.targetId
                    && documentItemRecropState.side === recropState.side;
                if (!stillCurrent || !isDocumentAutoCropEnabled()) return;

                const preCrop = getDocAlignerPreCropOrientation(ai);
                if (preCrop && normalizeRightAngle(rotationAngle) !== preCrop.rotation) {
                    rotationAngle = preCrop.rotation;
                    refreshEditor(true);
                }
                const quad = getDocAlignerResultQuad(ai);
                const points = ai?.success && ai?.model_variant === 'docaligner'
                    ? aiQuadToDisplayPoints(quad)
                    : null;
                if (!points) {
                    document.getElementById('mobStatus').innerText = 'AI Auto Crop clear nahi mila; purane dots safe hain.';
                    showModal('Manual Adjust Ready', 'AI ko clear boundary nahi mili. Maujooda dots safe hain; manually adjust karke Done dabayein.', 'warn');
                    return;
                }

                cropperPoints = points;
                pendingDocAlignerPostCropRotation = getDocAlignerOutputRotation(ai);
                applyGpuAutoBrightness(ai);
                drawCanvas();
                requestAnimationFrame(() => focusEditorOnRect(pointsToBoundingRect(cropperPoints)));
                const confidence = Number(ai?.classification?.confidence || ai?.straighten?.confidence || ai?.document?.confidence || 0);
                recordAiActivity('docaligner_recrop_points_applied', {
                    crop_side: recropState.side,
                    selected_family: target?.type || currentType,
                    confidence: Number.isFinite(confidence) ? confidence : 0,
                    rotation_degrees: pendingDocAlignerPostCropRotation,
                    source_rotation_degrees: preCrop?.rotation || 0
                });
                document.getElementById('mobStatus').innerText = 'AI Auto Crop ke 4 dots set hain; check karke Done dabayein.';
                showModal('AI Crop Ready', 'AI ne cropper me 4 corner dots set kar diye. Zarurat ho to manually adjust karke Done dabayein.', 'success');
            } catch (error) {
                if (requestToken !== documentAiRecropRequestSequence) return;
                console.warn('AI re-crop points request failed', error);
                document.getElementById('mobStatus').innerText = 'AI Auto Crop nahi mila; manual dots safe hain.';
                showModal('Manual Adjust Ready', 'AI response nahi mila. Maujooda crop points safe hain; manually adjust kar sakte hain.', 'warn');
            } finally {
                if (requestToken === documentAiRecropRequestSequence) {
                    documentAiRecropBusy = false;
                    if (cropPaidActivationPending && documentCropAccess.paid === true) {
                        cropPaidActivationPending = false;
                        applyCropWorkflowMode('auto');
                    }
                    syncDocumentAiRecropControls();
                    syncCropWorkflowUi();
                    hideProcessLoader();
                }
            }
        }

        async function startSelectedDocAlignerRecrop() {
            const idx = Number(selectedItem.index);
            const item = idx >= 0 ? batchQueue[idx] : null;
            if (!item?.docAlignerAutoCrop) {
                showModal('Select AI Crop', 'Preview me AI se crop hua card select karein.', 'warn');
                return;
            }
            if (item.type === 'pvc') {
                startPvcRecropFromQueue();
                return;
            }
            const side = selectedItem.side === 'back' && isMatUsable(item.back) ? 'back' : 'front';
            const sourceDataUrl = side === 'back'
                ? (item.backSourceDataUrl || item.sourceDataUrl || '')
                : (item.frontSourceDataUrl || item.sourceDataUrl || '');
            const descriptor = side === 'back' ? item.backCropDescriptor : item.frontCropDescriptor;
            if (!sourceDataUrl) {
                showModal('Source Missing', 'Is AI crop ka original source available nahi hai.', 'warn');
                return;
            }
            try {
                showProcessLoader({
                    kind: 'crop',
                    variant: 'fast',
                    title: 'Manual Re-Crop open ho raha hai',
                    message: 'Original photo par saved AI corners load ho rahe hain.',
                    chip: 'RE-CROP',
                    subtext: 'Dots ko zarurat ke hisab se adjust karke Done dabayein'
                });
                await waitForFastPaint();
                safeDeleteMat(tempDocs.front);
                safeDeleteMat(tempDocs.back);
                tempDocs.front = null;
                tempDocs.back = null;
                pendingBackFile = null;
                // Re-crop original source par hota hai. AI/manual preview ki
                // saved reading direction dobara lagni chahiye, warna 90° card
                // Re-Crop ke baad phir sideways ho jata hai.
                pendingDocAlignerPostCropRotation = normalizeRightAngle(descriptor?.postCropRotation || 0);
                docAlignerDirectApplyActive = false;
                documentItemRecropState = {
                    active: true,
                    targetId: ensureBatchQueueItemId(item),
                    side,
                    sourceDataUrl
                };
                syncDocumentAiRecropControls();
                switchCurrentTypeForActiveCrop(item.type);
                currentSide = side;
                isSingleSide = !!item.singleSide;
                currentPvcSourceDataUrl = '';
                currentDocumentSourceDataUrl = sourceDataUrl;
                documentLearningContext = {
                    docType: item.type === 'a4' ? 'a4_document' : 'id_card',
                    docLabel: item.type === 'a4' ? 'A4 Document' : 'ID Card',
                    sourceKind: 'docaligner_manual_recrop',
                    contentKind: item.type === 'a4' ? 'a4_document' : 'id_card',
                    captureReason: 'docaligner_manual_recrop_done',
                    forceCorrection: true
                };
                await loadDataUrlToEditorWithFallback(sourceDataUrl);
                const savedSourceRotation = normalizeRightAngle(descriptor?.rotation || 0);
                if (normalizeRightAngle(rotationAngle) !== savedSourceRotation) {
                    rotationAngle = savedSourceRotation;
                    refreshEditor(true);
                }
                restoreDocumentEnhancement(descriptor);
                const savedPoints = aiQuadToDisplayPoints(descriptor?.points);
                if (savedPoints) {
                    cropperPoints = savedPoints;
                    drawCanvas();
                }
                syncDocumentAiRecropControls();
                document.getElementById('mobStatus').innerText = 'Re-Crop: AI Crop dabayein ya 4 dots manually adjust karein.';
            } catch (error) {
                console.warn('DocAligner selected item re-crop open failed', error);
                resetDocumentItemRecropState();
                showModal('Re-Crop Error', 'Original image cropper me open nahi ho payi.', 'error');
            } finally {
                hideProcessLoader();
            }
        }

        function startPvcRecropFromQueue() {
            if (currentType !== 'pvc') {
                showModal("PVC Required", "Pehle PVC mode select karein.", "warn");
                return;
            }
            if (!requirePvcProAction("PVC Re-Crop")) return;
            const selected = getSelectedPvcToolItem(true);
            if (selected.needsSelection) {
                showModal("Select PVC Card", "Preview me jis card ko re-crop karna hai, pehle usi card par tap/click karein.", "warn");
                return;
            }
            const idx = selected.index >= 0 ? selected.index : getLastPvcRecropIndex();
            const item = idx >= 0 ? batchQueue[idx] : null;
            if (item?.pvcDocType && !item.isAlbumCover) setPvcAutoCropDocType(item.pvcDocType);
            if (isDocumentAlbumLaunch && item?.isAlbumCover) {
                const coverSide = selectedItem.index === idx && selectedItem.side === 'back' ? 'back' : 'front';
                startAlbumCoverRecrop(coverSide);
                return;
            }
            if (item?.pvcTwoPagePair) {
                startPvcTwoPageRecrop(idx, item);
                return;
            }
            if (isDocumentAlbumLaunch && item) {
                const albumSide = selectedItem.index === idx && selectedItem.side === 'back' ? 'back' : 'front';
                startAlbumItemRecrop(idx, item, albumSide);
                return;
            }
            const dataUrl = item?.sourceDataUrl || (batchQueue.length <= 1 ? getActivePvcToolSourceDataUrl() : '');
            if (!dataUrl) {
                showModal("No Auto Crop Item", "Re-crop ke liye pehle ek PVC auto crop item hona chahiye.", "warn");
                return;
            }
            activatePvcItemLearningContext(item, 'front');
            activatePvcItemHighQualityContext(item);
            pvcRecropMode = true;
            pvcRecropQueueIndex = idx;
            pvcRecropTargetItem = item || null;
            pvcRecropTargetId = ensureBatchQueueItemId(item);
            pvcRecropSourceDataUrl = dataUrl;
            forcePvcTemplatePlacement = true;
            pendingPvcPdfDualFlow = true;
            currentPvcSourceDataUrl = dataUrl;
            currentSide = 'front';
            document.getElementById('mobStatus').innerText = "Re-Crop: boxes adjust karke TEST CROP karein";
            loadPvcRecropSourceToEditor(dataUrl).then((loadedDataUrl) => {
                currentPvcSourceDataUrl = loadedDataUrl;
                pvcRecropSourceDataUrl = loadedDataUrl;
                requestAnimationFrame(() => {
                    if (pvcRecropMode && currentType === 'pvc' && !pvcTemplatePlacementMode) {
                        beginPvcTemplatePlacement();
                    }
                });
            }).catch(() => {
                clearPvcRecropTarget();
                pendingPvcPdfDualFlow = false;
                currentPvcSourceDataUrl = '';
                showModal("Re-Crop Error", "Image load nahi ho payi. PDF ko dobara upload karke Set New Crop karein.", "error");
            });
        }

        function updateFileInputAccept() {
            const input = document.getElementById('fileInput');
            if (isDocumentAlbumLaunch && currentType === 'pvc' && currentSide === 'back') {
                input.accept = "image/*";
            } else if (currentType === 'pvc') {
                input.accept = "image/*,.pdf,application/pdf";
            } else if (isProUser()) {
                input.accept = "*/*";
            } else {
                input.accept = "image/*";
            }
        }

        function isPdfFile(file) {
            const name = (file?.name || '').toLowerCase();
            const type = (file?.type || '').toLowerCase();
            return type === 'application/pdf' || name.endsWith('.pdf');
        }

        function isImageFile(file) {
            const name = (file?.name || '').toLowerCase();
            return IMAGE_TYPE_RE.test(file?.type || '') || /\.(jpg|jpeg|png|webp|gif|bmp|tif|tiff)$/i.test(name);
        }

        function isTextLikeFile(file) {
            const type = (file?.type || '').toLowerCase();
            const name = (file?.name || '').toLowerCase();
            return TEXT_TYPE_RE.test(type) || /\.(txt|json|csv|xml|md|log)$/i.test(name);
        }

        function getProExportScale() {
            return isProUser() ? 2 : 1;
        }

        function normalizeExportQuality(quality = 'normal') {
            return quality === 'hd' ? 'hd' : 'normal';
        }

        function ensureQualityAllowed(quality = 'normal', featureName = 'HD export') {
            if (normalizeExportQuality(quality) !== 'hd') return true;
            return isProUser() || requireProFeature(featureName);
        }

        function getExportScaleForQuality(quality = 'normal') {
            return normalizeExportQuality(quality) === 'hd' ? 2 : 1;
        }

        function getExportMimeForQuality(quality = 'normal') {
            return normalizeExportQuality(quality) === 'hd' ? 'image/png' : 'image/jpeg';
        }

        function getExportJpegQuality(quality = 'normal') {
            return normalizeExportQuality(quality) === 'hd' ? 1.0 : 0.86;
        }

        function hasPvcQueueContent(includeTemp = true) {
            return batchQueue.some((item) => item?.type === 'pvc') || (includeTemp && currentType === 'pvc' && !!tempDocs.front);
        }

        function getPvcSheetExportScale() {
            const pvcConf = DOC_TYPES.pvc;
            const scaleToKeepCropPixels = Math.ceil((pvcConf.proW || pvcConf.w) / pvcConf.w);
            return Math.max(getProExportScale(), scaleToKeepCropPixels);
        }

        function getCurrentSheetSaveScale() {
            // PVC originals remain in savedPageMeta.items. This is only the page
            // thumbnail; do not retain a second 78MP bitmap of every album page.
            return hasPvcQueueContent(true) ? 1 : getProExportScale();
        }

        function getCurrentSheetSaveMime() {
            return (isProUser() || hasPvcQueueContent(true)) ? 'image/png' : 'image/jpeg';
        }

        function getCurrentSheetExportScaleForQuality(quality = 'normal') {
            return hasPvcQueueContent(true)
                ? Math.max(getExportScaleForQuality(quality), getPvcSheetExportScale())
                : getExportScaleForQuality(quality);
        }

        function getCurrentSheetExportMimeForQuality(quality = 'normal') {
            return 'image/jpeg';
        }

        function getCurrentSheetExportJpegQuality(quality = 'normal') {
            return 0.98;
        }

        function getRemotePrintScale() {
            return isProUser() ? 2 : 1.55;
        }

        function getMaxRemotePrintPayloadBytes() {
            return 15 * 1024 * 1024;
        }

        function getPdfRasterScale() {
            if (currentType === 'pvc' && (isProUser() || canOpenLockedPvcWorkspace())) return 5.2;
            return isProUser() ? 4.2 : 2.2;
        }

        function getPdfFinalRasterScale() {
            if (currentType === 'pvc' && (isProUser() || canOpenLockedPvcWorkspace())) return 8.5;
            return isProUser() ? 6.2 : 2.4;
        }

        function applyCustomDocSize(sizeKey = activeCustomDocSize) {
            const size = CUSTOM_DOC_SIZES[sizeKey] || CUSTOM_DOC_SIZES.large_doc;
            activeCustomDocSize = CUSTOM_DOC_SIZES[sizeKey] ? sizeKey : 'large_doc';
            DOC_TYPES.custom = {
                w: size.w,
                h: size.h,
                proW: size.proW || size.w * 2,
                proH: size.proH || size.h * 2,
                aspect: size.w / size.h,
                name: size.label.replace(/\s+-\s+.*$/, ''),
                limit: size.limit || 3
            };
        }

        function initCustomDocSizes() {
            applyCustomDocSize(activeCustomDocSize);
            const options = Object.entries(CUSTOM_DOC_SIZES).map(([key, size]) => `<option value="${key}">${size.label}</option>`).join('');
            const fullSelect = document.getElementById('customDocSizeSelect');
            if (fullSelect) {
                fullSelect.innerHTML = options;
                fullSelect.value = activeCustomDocSize;
            }
            syncCustomDocSizeUi();
        }

        function syncCustomDocSizeUi() {
            const el = document.getElementById('customDocSizeSelect');
            if (el) el.value = activeCustomDocSize;
            const panel = document.getElementById('customSizePanel');
            if (panel) panel.classList.toggle('hidden', currentType !== 'custom');
        }

        function setCustomDocSize(sizeKey, switchToCustom = false) {
            if (!isProUser()) {
                requireProFeature("Custom Document Size");
                syncCustomDocSizeUi();
                return;
            }
            applyCustomDocSize(sizeKey);
            syncCustomDocSizeUi();
            if (switchToCustom || currentType === 'custom') {
                attemptSetDocType('custom');
            }
        }

        function getItemLayoutForType(type, index = 0, hasBack = true) {
            const conf = DOC_TYPES[type] || DOC_TYPES.smart;
            const layoutSize = getDocLayoutSize(type);
            const page = getSheetSize(type);
            const wCanvas = page.w;
            const hCanvas = page.h;
            if (type === 'a4') {
                const scale = 0.94;
                const sW = layoutSize.width * scale;
                const sH = layoutSize.height * scale;
                return { w: layoutSize.width, h: layoutSize.height, scale, xF: (wCanvas - sW) / 2, yF: (hCanvas - sH) / 2, xB: 0, yB: 0 };
            }
            if (type === 'pvc' && isDocumentAlbumLaunch) {
                const scale = DOCUMENT_ALBUM_CARD_SCALE;
                const gap = DOCUMENT_ALBUM_DOCUMENT_GAP;
                const startY = DOCUMENT_ALBUM_START_Y;
                const cardWidth = layoutSize.width * scale;
                const cardHeight = layoutSize.height * scale;
                const albumIndex = Math.max(0, Math.min(DOCUMENT_ALBUM_PAGE_LIMIT - 1, Number(index) || 0));
                const rightColumn = albumIndex % 2 === 1;
                const pairStartRow = Math.floor(albumIndex / 2) * 2;
                const frontRow = pairStartRow + (rightColumn ? 1 : 0);
                const backRow = pairStartRow + (rightColumn ? 0 : 1);
                const totalRowW = (cardWidth * 2) + gap;
                const startX = (wCanvas - totalRowW) / 2;
                const x = startX + (rightColumn ? cardWidth + gap : 0);
                let frontY = startY + (frontRow * (cardHeight + gap));
                const backY = startY + (backRow * (cardHeight + gap));
                if (albumIndex === DOCUMENT_ALBUM_PAGE_LIMIT - 1) {
                    frontY += DOCUMENT_ALBUM_COVER_GAP - DOCUMENT_ALBUM_DOCUMENT_GAP;
                }
                return {
                    w: layoutSize.width,
                    h: layoutSize.height,
                    scale,
                    xF: x,
                    yF: frontY,
                    xB: x,
                    yB: backY
                };
            }
            if (type === 'pvc' && pvcPageSizeMode === 'photo4x6') {
                const gap = 10;
                const totalH = layoutSize.height + (hasBack ? gap + layoutSize.height : 0);
                const startY = Math.max(24, Math.round((hCanvas - totalH) * 0.24));
                const x = Math.round((wCanvas - layoutSize.width) / 2);
                return { w: layoutSize.width, h: layoutSize.height, scale: 1.0, xF: x, yF: startY, xB: x, yB: startY + layoutSize.height + gap };
            }
            const { gap, startY } = getSheetRowLayoutConfig(type);
            if (!hasBack) {
                const x = (wCanvas - layoutSize.width) / 2;
                const rowY = startY + (index * (layoutSize.height + gap));
                return { w: layoutSize.width, h: layoutSize.height, scale: 1.0, xF: x, yF: rowY, xB: x + layoutSize.width + gap, yB: rowY };
            }
            const totalRowW = (layoutSize.width * 2) + gap;
            const startX = (wCanvas - totalRowW) / 2;
            const rowY = startY + (index * (layoutSize.height + gap));
            return { w: layoutSize.width, h: layoutSize.height, scale: 1.0, xF: startX, yF: rowY, xB: startX + layoutSize.width + gap, yB: rowY };
        }

        function relayoutQueueItems(type) {
            const previousSelection = { ...selectedItem };
            batchQueue.forEach((item, index) => {
                const layout = getItemLayoutForType(type, index, !!item.back);
                item.type = type;
                Object.assign(item, layout);
                item.scaleX = 1;
                item.scaleY = 1;
                item.rotation = 0;
                if (type !== 'pvc') {
                    item.sourceDataUrl = null;
                    item.pvcDocType = null;
                }
            });
            selectedItem = previousSelection.index >= 0 && batchQueue[previousSelection.index]
                ? previousSelection
                : (batchQueue.length > 0 ? { index: 0, side: 'front' } : { index: -1, side: null });
            syncSelectionToolbar();
        }

        function renderSingleItemPageDataUrl(item, type = currentType, scale = getCurrentSheetSaveScale()) {
            const oldQueue = batchQueue;
            const oldSelected = selectedItem;
            const oldType = currentType;
            const layout = getItemLayoutForType(type, 0, !!item.back);
            const single = {
                ...item,
                type,
                w: layout.w,
                h: layout.h,
                xF: layout.xF,
                yF: layout.yF,
                xB: layout.xB,
                yB: layout.yB,
                scale: layout.scale,
                scaleX: 1,
                scaleY: 1,
                rotation: 0
            };
            try {
                batchQueue = [single];
                selectedItem = { index: -1, side: null };
                currentType = type;
                const canvas = buildExportCanvas(scale);
                try { return encodeCanvasDataUrl(canvas, getCurrentSheetSaveMime(), 1.0); }
                finally { releaseOutputCanvas(canvas); }
            } finally {
                batchQueue = oldQueue;
                selectedItem = oldSelected;
                currentType = oldType;
            }
        }

        function splitOverflowItemsToPages(type = currentType) {
            const limit = getCurrentPageItemLimit(type);
            if (batchQueue.length <= limit) return;
            while (batchQueue.length > limit) {
                const item = batchQueue.shift();
                if (!item) break;
                savedPages.push(renderSingleItemPageDataUrl(item, type));
                savedPageMeta.push({
                    type,
                    pageMode: type === 'pvc' ? pvcPageSizeMode : null,
                    page: getSheetSize(type),
                    items: type === 'pvc' ? cloneSavedPageItems([item]) : []
                });
                safeDeleteItemMats(item);
            }
            batchQueue.forEach((item, index) => Object.assign(item, getItemLayoutForType(type, index, !!item.back)));
            selectedItem = batchQueue.length ? { index: 0, side: 'front' } : { index: -1, side: null };
            updatePageCountUI();
        }

        function updatePreviewToolbarVisibility() {
            const emptyPro = document.getElementById('emptyProHeader');
            const printSection = document.getElementById('printSection');
            const pvcQualityNote = document.getElementById('pvcPreviewQualityNote');
            const hasCurrentContent = batchQueue.length > 0 || !!tempDocs.front;
            const selected = selectedItem.index >= 0 ? batchQueue[selectedItem.index] : null;
            const isPvcWorkspace = currentType === 'pvc' || selected?.type === 'pvc';
            const showProHeader = !isPvcCropOnlyLaunch && !isDocumentAlbumLaunch && !isProUser() && !hasCurrentContent && savedPages.length === 0 && window.innerWidth >= 1024;
            if (emptyPro) emptyPro.style.display = showProHeader ? 'flex' : 'none';
            if (printSection) printSection.classList.toggle('print-section-pro-open', showProHeader);
            if (pvcQualityNote) pvcQualityNote.classList.toggle('hidden', !(isPvcWorkspace && hasCurrentContent));
        }

        function liveApplyPreviewDocType(type, customKey = activeCustomDocSize) {
            if (isDocumentAlbumLaunch && type !== 'pvc') return;
            if (type === 'pvc' && !isProUser() && !canOpenLockedPvcWorkspace()) { requireProFeature("PVC Print Mode"); return; }
            if (type === 'custom' && !isProUser()) { requireProFeature("Custom Document Size"); syncCustomDocSizeUi(); return; }
            if (type === 'custom') applyCustomDocSize(customKey);
            currentType = type;
            relayoutQueueItems(type);
            splitOverflowItemsToPages(type);
            document.querySelectorAll('.doc-btn').forEach(b=>b.classList.remove('active'));
            const deskBtn = document.getElementById('btn-'+type);
            if (deskBtn) deskBtn.classList.add('active');
            document.querySelectorAll('.seg-btn').forEach(b=>b.classList.remove('active'));
            const mobBtn = document.getElementById('mob-type-'+type);
            if (mobBtn) mobBtn.classList.add('active');
            syncCustomDocSizeUi();
            syncPvcDocTypeUI();
            updateUploadLabels();
            syncUploadSideControls();
            updateListUI();
            resizePreviewCanvas();
            renderSheet();
            syncSelectionToolbar();
        }

        function getDocRenderSize(docType = currentType) {
            const conf = DOC_TYPES[docType];
            if (!conf) return { width: 1011, height: 638 };
            return isProUser()
                ? { width: conf.proW || conf.w, height: conf.proH || conf.h }
                : { width: conf.w, height: conf.h };
        }

        function getDocLayoutSize(docType = currentType) {
            const conf = DOC_TYPES[docType];
            if (!conf) return { width: 1011, height: 638 };
            return { width: conf.w, height: conf.h };
        }

        function getSheetSize(docType = currentType) {
            if ((docType === 'pvc' && pvcPageSizeMode === 'photo4x6') || docType === 'pvc_4x6' || docType === 'photo4x6') {
                return { w: 1200, h: 1800, label: '4x6' };
            }
            const conf = DOC_TYPES[docType] || {};
            return {
                w: conf.pageW || 2480,
                h: conf.pageH || 3508,
                label: conf.pageLabel || 'a4'
            };
        }

        function getPdfPageMm(docType = currentType) {
            if (docType === 'pvc_4x6' || docType === 'photo4x6' || (docType === 'pvc' && pvcPageSizeMode === 'photo4x6')) return { w: 101.6, h: 152.4, format: [101.6, 152.4] };
            return { w: 210, h: 297, format: 'a4' };
        }

        function getCurrentPageItemLimit(type = currentType) {
            if (type === 'pvc' && isDocumentAlbumLaunch) return DOCUMENT_ALBUM_PAGE_LIMIT;
            if (type === 'pvc' && pvcPageSizeMode === 'photo4x6') return 1;
            return DOC_TYPES[type]?.limit || 999;
        }

        function getSheetRowLayoutConfig(type = currentType) {
            if (type === 'pvc') {
                // Five complete PVC sets (Front + Back) fit on one A4 page:
                // 42 + (5 * 638) + (4 * 30) = 3352px, leaving a safe 156px
                // bottom margin on the 3508px print canvas.
                return { gap: 30, startY: 42 };
            }
            return { gap: 60, startY: 150 };
        }

        function cloneSavedPageItem(item) {
            if (!item) return null;
            const cloned = {
                ...item,
                queueItemId: createBatchQueueItemId(),
                front: item.front?.clone ? item.front.clone() : null,
                back: item.back?.clone ? item.back.clone() : null,
                pvcStoredBack: item.pvcStoredBack?.clone ? item.pvcStoredBack.clone() : null,
                pvcDisposed: false,
                _pvcHighQualityUpgradePromise: null
            };
            for (const side of ['front','back','pvcStoredBack']) {
                if (cloned[side] && enhancementComparisons.has(item[side])) {
                    enhancementComparisons.set(cloned[side], enhancementComparisons.get(item[side]));
                }
            }
            return cloned;
        }

        function safeDeleteItemMats(item) {
            if (!item) return;
            item.pvcDisposed = true;
            safeDeleteMat(item.front);
            safeDeleteMat(item.back);
            safeDeleteMat(item.pvcStoredBack);
            item.front = null;
            item.back = null;
            item.pvcStoredBack = null;
        }

        function cloneSavedPageItems(items = []) {
            return (Array.isArray(items) ? items : [])
                .map((item) => cloneSavedPageItem(item))
                .filter((item) => item && item.front);
        }

        function getSavedPageMetaItems(meta = {}) {
            if (Array.isArray(meta.items) && meta.items.length) return meta.items;
            return meta.item ? [meta.item] : [];
        }

        function buildSavedPageMetaForCurrentPage(type = currentType) {
            return {
                type,
                pageMode: type === 'pvc' ? pvcPageSizeMode : null,
                page: getSheetSize(type),
                items: type === 'pvc' ? cloneSavedPageItems(batchQueue) : []
            };
        }

        function cleanupSavedPageMeta(index) {
            const meta = savedPageMeta[index];
            if (Array.isArray(meta?.items)) {
                meta.items.forEach((item) => safeDeleteItemMats(item));
            }
            if (meta?.item) {
                safeDeleteItemMats(meta.item);
            }
        }

        function cleanupAllSavedPageMeta() {
            savedPageMeta.forEach((_, index) => cleanupSavedPageMeta(index));
            savedPageMeta = [];
        }

        function syncPvcPageSizeModeUi() {
            const nextMode = pvcPageSizeMode === 'photo4x6' ? 'a4' : 'photo4x6';
            const label = nextMode === 'photo4x6' ? 'Page 4x6' : 'Page A4';
            ['btnPvcPageSizeDesk', 'btnPvcPageSizeMob'].forEach((id) => {
                const button = document.getElementById(id);
                if (!button) return;
                setPvcFloatingToolLabel(
                    button,
                    label,
                    nextMode === 'photo4x6' ? 'PVC page ko 4x6 me badlein' : 'PVC page ko A4 me badlein'
                );
                button.classList.toggle('active', pvcPageSizeMode === 'photo4x6');
            });
        }

        function restoreSavedPvc4x6ItemsToQueue() {
            const restored = [];
            const keepPages = [];
            const keepMeta = [];
            savedPageMeta.forEach((meta, index) => {
                if (meta?.type === 'pvc' && meta?.pageMode === 'photo4x6' && getSavedPageMetaItems(meta).length) {
                    restored.push(...cloneSavedPageItems(getSavedPageMetaItems(meta)));
                    cleanupSavedPageMeta(index);
                } else {
                    keepPages.push(savedPages[index]);
                    keepMeta.push(meta);
                }
            });
            savedPages = keepPages;
            savedPageMeta = keepMeta;
            if (restored.length) {
                batchQueue = restored.concat(batchQueue);
            }
            return restored.length;
        }

        function setPvcPageSizeMode(mode = 'a4') {
            if (isDocumentAlbumLaunch) mode = 'a4';
            if (currentType !== 'pvc') {
                const activePvc = getActivePvcToolItem();
                if (!activePvc.item) {
                    showModal("PVC Required", "4x6 page size ke liye pehle PVC card select karein.", "warn");
                    return;
                }
                selectedItem = {
                    index: activePvc.index,
                    side: selectedItem.index === activePvc.index && selectedItem.side === 'back' && activePvc.item.back ? 'back' : 'front'
                };
                switchCurrentTypeForActiveCrop('pvc');
            }
            pvcPageSizeMode = mode === 'photo4x6' ? 'photo4x6' : 'a4';
            if (pvcPageSizeMode === 'a4') restoreSavedPvc4x6ItemsToQueue();
            relayoutQueueItems('pvc');
            splitOverflowItemsToPages('pvc');
            syncPvcPageSizeModeUi();
            updateListUI();
            resizePreviewCanvas();
            renderSheet();
            updatePageCountUI();
        }

        function togglePvcPageSizeMode() {
            if (!requirePvcProAction("PVC Page Size")) return;
            setPvcPageSizeMode(pvcPageSizeMode === 'photo4x6' ? 'a4' : 'photo4x6');
        }

        function isPvcPdfAutoCropEnabled(file) {
            return currentType === 'pvc' && (isProUser() || canOpenLockedPvcWorkspace()) && isPdfFile(file);
        }

        function attemptSetDocType(t){ if(batchQueue.length>0 && t!==currentType) showConfirm("Change Type?", "Current queue will be cleared. Continue?", ()=>setDocType(t)); else setDocType(t); }
        function setDocType(t){
            if (isDocumentAlbumLaunch && t !== 'pvc') return;
            if(t === 'pvc' && !isProUser() && !canOpenLockedPvcWorkspace()) { requireProFeature("PVC Print Mode"); return; }
            if(t === 'custom' && !isProUser()) { requireProFeature("Custom Document Size"); return; }
            if (pvcBatchUploadActive && t !== 'pvc') resetPvcBatchUploadState();
            if(t === 'custom') applyCustomDocSize(activeCustomDocSize);
            currentType=t; 
            if (t === 'pvc') schedulePvcLearnedTemplatesServerSync();
            syncCropWorkflowUi();
            recordAiActivity('document_family_selected', { selected_family: t });
            document.querySelectorAll('.doc-btn').forEach(b=>b.classList.remove('active')); 
            const deskBtn = document.getElementById('btn-'+t);
            if (deskBtn) deskBtn.classList.add('active');
            document.querySelectorAll('.seg-btn').forEach(b=>b.classList.remove('active'));
            const mobBtn = document.getElementById('mob-type-'+t);
            if (mobBtn) mobBtn.classList.add('active');

            const isSingleUploadMode = (t === 'a4' || t === 'pvc');
            if (batchQueue.length > 0) {
                relayoutQueueItems(t);
                splitOverflowItemsToPages(t);
            }
            if (t === 'pvc') syncPvcPageSizeModeUi();
            syncUploadSideControls();
            if (isSingleUploadMode) {
                document.getElementById('mobStatus').innerText = (t === 'pvc') ? `${getPvcDocTypeLabel()} Auto Crop Ready` : "Scan Page";
            } else {
                document.getElementById('mobStatus').innerText="Scan Front & Back";
            }
            updateUploadLabels();
            syncPvcDocTypeUI();
            syncCustomDocSizeUi();
            updateFileInputAccept();
            togglePasswordField(true);
            updatePvcRecropToolbarVisibility();
            resizePreviewCanvas();
            clearCurrent();
        }

        function toggleSingleSide(){ 
            isSingleSide=document.getElementById('chkSingleSide').checked; 
            syncSingleSideUI(); 
            if(isSingleSide && tempDocs.front && !tempDocs.back) { addToSheet(); }
        }
        function toggleSingleSideMob(){ 
            isSingleSide=document.getElementById('chkSingleSideMob').checked; 
            syncSingleSideUI();
            if(isSingleSide && tempDocs.front && !tempDocs.back) { addToSheet(); }
        }
        function syncSingleSideUI(){
            document.getElementById('chkSingleSide').checked=isSingleSide;
            document.getElementById('chkSingleSideMob').checked=isSingleSide;
            if (currentType === 'pvc' || currentType === 'a4') {
                document.getElementById('mobStatus').innerText = currentType === 'pvc' ? `${getPvcDocTypeLabel()} Auto Crop Ready` : "Scan Page";
                renderSheet();
                return;
            }
            if(isSingleSide){
                document.getElementById('backUploadBox').classList.add('opacity-50','pointer-events-none');
                document.getElementById('mobBackBtn').classList.add('opacity-50','pointer-events-none');
                document.getElementById('mobStatus').innerText="Single Side Mode";
            }else{
                document.getElementById('backUploadBox').classList.remove('opacity-50','pointer-events-none');
                document.getElementById('mobBackBtn').classList.remove('opacity-50','pointer-events-none');
                document.getElementById('mobStatus').innerText="Scan Front & Back";
            }
            renderSheet();
        }
        
        function getAlbumBackAttachIndex() {
            if (!isDocumentAlbumLaunch || currentType !== 'pvc') return -1;
            const eligible = (item) => item?.type === 'pvc' && !item.isAlbumCover && isMatUsable(item.front) && !isMatUsable(item.back);
            if (selectedItem.index >= 0) return eligible(batchQueue[selectedItem.index]) ? selectedItem.index : -1;
            for (let i = batchQueue.length - 1; i >= 0; i--) {
                if (eligible(batchQueue[i])) return i;
            }
            return -1;
        }

        function prepareUploadSide(s){
            // Picker uploads and drops must resolve the same existing front card
            // before processing a back image, including auto-cropped queue items.
            if(currentType === 'pvc' && !requirePvcProAction("PVC Auto Crop Upload")) return false;
            if (currentType === 'pvc' && !isDocumentAlbumLaunch) s = 'front';
            if (isDocumentAlbumLaunch && currentType === 'pvc' && s === 'back' && !isMatUsable(tempDocs.front) && getAlbumBackAttachIndex() < 0) {
                showModal('Front Required', 'Pehle ID card ka front JPG/PNG crop karke save karein; uske baad Back upload active hoga.', 'warn');
                return false;
            }
            pendingAttachBackIndex = -1;
            if (isDocumentAlbumLaunch && s === 'back' && !isMatUsable(tempDocs.front)) {
                pendingAttachBackIndex = getAlbumBackAttachIndex();
                isSingleSide = false;
            }
            if (s === 'back' && currentType !== 'a4' && currentType !== 'pvc') {
                const selectedCandidate = selectedItem.index >= 0 && batchQueue[selectedItem.index] && !batchQueue[selectedItem.index].back
                    ? selectedItem.index
                    : -1;
                pendingAttachBackIndex = selectedCandidate;
                if (pendingAttachBackIndex < 0) {
                    for (let i = batchQueue.length - 1; i >= 0; i--) {
                        if (batchQueue[i].type === currentType && !batchQueue[i].back) {
                            pendingAttachBackIndex = i;
                            break;
                        }
                    }
                }
            }
            currentSide=s;
            return true;
        }

        function triggerUpload(s){
            if (!prepareUploadSide(s)) return;
            document.getElementById('fileInput').value='';
            updateFileInputAccept();
            document.getElementById('fileInput').click();
        }

        document.getElementById('fileInput').addEventListener('change', e => {
            const files = Array.from(e.target.files || []);
            recordAiActivity('upload_files_selected', {
                file_count: files.length,
                file_extensions: files.slice(0, 5).map(fileExtensionOnly),
                file_size_buckets: files.slice(0, 5).map((file) => fileSizeBucket(file.size))
            });
            handleFileProcess(e.target.files);
        });
        document.getElementById('albumCoverInput')?.addEventListener('change', (event) => {
            const input = event.currentTarget;
            const file = input?.files?.[0] || null;
            const side = input?.dataset?.side === 'back' ? 'back' : 'front';
            handleAlbumCoverFile(file, side);
        });

        function initDragDrop() {
            setupDragZone('dropFront', 'front');
            setupDragZone('backUploadBox', 'back');
            setupDragZone('mobFrontIcon', 'front');
            setupDragZone('mobBackIcon', 'back');
        }

        function setupDragZone(id, side) {
            const el = document.getElementById(id);
            if(!el) return;
            el.addEventListener('dragover', (e) => { e.preventDefault(); el.classList.add('border-brand', 'bg-blue-50'); });
            el.addEventListener('dragleave', (e) => { e.preventDefault(); el.classList.remove('border-brand', 'bg-blue-50'); });
            el.addEventListener('drop', (e) => {
                e.preventDefault();
                el.classList.remove('border-brand', 'bg-blue-50');
                if(e.dataTransfer.files && e.dataTransfer.files.length > 0) {
                    if (!prepareUploadSide(side)) return;
                    handleFileProcess(e.dataTransfer.files);
                }
            });
        }

        function resetPvcBatchUploadState() {
            if (pvcBatchNextTimer) clearTimeout(pvcBatchNextTimer);
            pvcBatchNextTimer = null;
            pvcBatchUploadQueue = [];
            pvcBatchUploadActive = false;
            pvcBatchUploadBusy = false;
            pvcBatchCurrentFile = null;
            pvcBatchUploadTotal = 0;
            pvcBatchUploadCompleted = 0;
            pvcBatchUploadFailed = 0;
        }

        function scheduleNextPvcBatchUpload(delay = 140) {
            if (!pvcBatchUploadActive || pvcBatchUploadBusy || pvcBatchCurrentFile) return;
            if (pvcBatchNextTimer) clearTimeout(pvcBatchNextTimer);
            pvcBatchNextTimer = setTimeout(() => {
                pvcBatchNextTimer = null;
                processNextPvcBatchUpload();
            }, delay);
        }

        function finishPvcBatchUpload() {
            const completed = pvcBatchUploadCompleted;
            const failed = pvcBatchUploadFailed;
            const total = pvcBatchUploadTotal;
            resetPvcBatchUploadState();
            hideProcessLoader();
            updateListUI();
            renderSheetNow();
            showModal(
                failed ? 'PDF Batch Finished' : 'PDF Batch Ready',
                failed
                    ? `${completed} of ${total} files preview me add hui. ${failed} file ko manual/retry ki zarurat hai.`
                    : `${completed} files ek-ek karke auto-crop hokar preview me add ho gayi hain. Kisi bhi card par tap karke Enhance ya Border use karein.`,
                failed ? 'warn' : 'success'
            );
        }

        function completeCurrentPvcBatchUpload(success = true) {
            if (!pvcBatchUploadActive || !pvcBatchCurrentFile) return;
            pvcBatchCurrentFile = null;
            if (success) pvcBatchUploadCompleted += 1;
            else {
                pvcBatchUploadFailed += 1;
                safeDeleteMat(tempDocs.front);
                safeDeleteMat(tempDocs.back);
                tempDocs.front = null;
                tempDocs.back = null;
                pendingBackFile = null;
                resetPvcDualSession();
            }
            hideProcessLoader();
            if (!pvcBatchUploadQueue.length) {
                finishPvcBatchUpload();
                return;
            }
            scheduleNextPvcBatchUpload();
        }

        function schedulePvcBatchCropperCloseCheck() {
            if (!pvcBatchUploadActive || !pvcBatchCurrentFile) return;
            setTimeout(() => {
                if (!pvcBatchUploadActive || !pvcBatchCurrentFile || pvcBatchUploadBusy) return;
                const cropperVisible = !document.getElementById('cropperModal')?.classList.contains('hidden');
                if (!cropperVisible) completeCurrentPvcBatchUpload(false);
            }, 420);
        }

        async function processNextPvcBatchUpload() {
            if (!pvcBatchUploadActive || pvcBatchUploadBusy || pvcBatchCurrentFile) return;
            if (!pvcBatchUploadQueue.length) {
                finishPvcBatchUpload();
                return;
            }
            if (currentType !== 'pvc') {
                const remaining = pvcBatchUploadQueue.length;
                pvcBatchUploadFailed += remaining;
                pvcBatchUploadQueue = [];
                finishPvcBatchUpload();
                return;
            }
            const file = pvcBatchUploadQueue.shift();
            pvcBatchCurrentFile = file;
            pvcBatchUploadBusy = true;
            const sequence = pvcBatchUploadCompleted + pvcBatchUploadFailed + 1;
            showProcessLoader({
                kind: 'upload',
                variant: 'fast',
                title: `PDF ${sequence}/${pvcBatchUploadTotal} process ho rahi hai`,
                message: `${file?.name || 'Selected file'} ko auto-crop karke preview me add kar rahe hain.`,
                chip: `${sequence}/${pvcBatchUploadTotal}`,
                subtext: 'Har file complete hone ke baad agli file automatically start hogi'
            });
            await waitForFastPaint();
            try {
                currentSide = 'front';
                pendingBackFile = null;
                isSingleSide = false;
                pvcSingleSideAiMode = false;
                const loaded = await readFile(file);
                if (!loaded) completeCurrentPvcBatchUpload(false);
            } catch (error) {
                console.error('PVC batch file failed', error);
                completeCurrentPvcBatchUpload(false);
            } finally {
                pvcBatchUploadBusy = false;
                if (!pvcBatchCurrentFile) scheduleNextPvcBatchUpload();
                else {
                    const cropperVisible = !document.getElementById('cropperModal')?.classList.contains('hidden');
                    if (cropperVisible) hideProcessLoader();
                    else schedulePvcBatchCropperCloseCheck();
                }
            }
        }

        async function startPvcBatchUpload(files) {
            resetPvcBatchUploadState();
            pvcBatchUploadQueue = Array.from(files || []).slice(0, 5);
            pvcBatchUploadTotal = pvcBatchUploadQueue.length;
            pvcBatchUploadActive = pvcBatchUploadTotal > 0;
            if (pvcBatchUploadActive) await processNextPvcBatchUpload();
        }

        async function handleFileProcess(files) {
            if(!files || files.length === 0) return;
            if (remoteShopToken && getCustomerPrepareMode() === 'direct') {
                await submitDirectRemotePrintFiles(files);
                return;
            }
            const list = Array.from(files || []);
            const hasPdf = list.some((file) => isPdfFile(file));
            showProcessLoader({
                kind: 'upload',
                variant: 'fast',
                title: hasPdf ? 'PDF upload ho rahi hai' : 'File upload ho rahi hai',
                message: hasPdf ? 'PDF preview taiyar karke crop khola ja raha hai.' : 'Image read karke cropper open kiya ja raha hai.',
                chip: 'UPLOAD',
                subtext: 'Please wait, file prepare ho rahi hai'
            });
            await waitForFastPaint();
            try {
                if (isDocumentAlbumLaunch && currentType === 'pvc' && currentSide === 'back' && !list.every((file) => isImageFile(file))) {
                    showModal('Back Image Required', 'Album ID card ke Back side ke liye JPG, JPEG, PNG ya supported image upload karein.', 'warn');
                    return;
                }
                if (isDocumentAlbumLaunch && currentType === 'pvc' && list.every((file) => isImageFile(file))) {
                    if (currentSide === 'back' && !isMatUsable(tempDocs.front)) {
                        pendingAttachBackIndex = getAlbumBackAttachIndex();
                        if (pendingAttachBackIndex < 0) {
                            showModal('Select Front', 'Preview me front-only document select karke Back upload karein.', 'warn');
                            return;
                        }
                    }
                    const albumImages = list.slice(0, 2);
                    if (list.length > 2) {
                        showModal('Front + Back Only', 'Album ke ek document set me pehli 2 images Front aur Back ke roop me process hongi.', 'warn');
                    }
                    if (currentSide === 'back') {
                        pendingBackFile = null;
                        await readFile(albumImages[0]);
                    } else {
                        currentSide = 'front';
                        pendingBackFile = albumImages[1] || null;
                        if (pendingBackFile) { isSingleSide = false; syncSingleSideUI(); }
                        const firstLoaded = await readFile(albumImages[0]);
                        if (!firstLoaded) pendingBackFile = null;
                    }
                    return;
                }
                if (currentType === 'pvc') {
                    const pvcFiles = list.filter((file) => isPdfFile(file) || isImageFile(file));
                    if (!pvcFiles.length) {
                        showModal('Unsupported in PVC', 'PVC mode me PDF ya image file select karein.', 'warn');
                        return;
                    }
                    if (pvcFiles.length > 5) {
                        showModal('Maximum 5 Files', 'Ek batch me pehli 5 PDF/Image files process hongi. Baki files next batch me upload karein.', 'warn');
                    }
                    currentSide = 'front';
                    pendingBackFile = null;
                    if (pvcFiles.length > 1) {
                        if (pvcPageSizeMode === 'photo4x6') setPvcPageSizeMode('a4');
                        // addToSheet saves only after all five A4 slots are full.
                        // Pre-saving the page here could leave a four-set page when
                        // the user selected another batch with more than one file.
                        await startPvcBatchUpload(pvcFiles.slice(0, 5));
                    }
                    else await readFile(pvcFiles[0]);
                    return;
                }
                if(files.length >= 2) {
                    if(currentSide === 'back') {
                        await readFile(files[0]);
                    } else {
                        currentSide = 'front';
                        pendingBackFile = files[1];
                        const firstLoaded = await readFile(files[0]);
                        if (!firstLoaded) pendingBackFile = null;
                        else if (pendingBackFile && docAlignerDecisionState === 'gpu_committed'
                            && document.getElementById('cropperModal')?.classList.contains('hidden')) {
                            const nextBackFile = pendingBackFile;
                            pendingBackFile = null;
                            currentSide = 'back';
                            await readFile(nextBackFile);
                        }
                    }
                } else {
                    await readFile(files[0]);
                }
            } finally {
                if (!pvcBatchUploadActive) hideProcessLoader();
            }
        }

        async function renderFileToDirectPrintDataUrl(file) {
            let dataUrl = '';
            if (isImageFile(file)) {
                dataUrl = await readImageFileFastDataUrl(file);
            } else if (isPdfFile(file)) {
                dataUrl = await renderPdfFileToDataUrl(file);
            } else if (isTextLikeFile(file)) {
                dataUrl = await renderTextFileToDataUrl(file);
            } else {
                dataUrl = await renderGenericFileCardToDataUrl(file);
            }
            return fitDataUrlOnA4Canvas(dataUrl);
        }

        async function fitDataUrlOnA4Canvas(dataUrl) {
            const img = await loadImageFromDataUrl(dataUrl);
            const c = document.createElement('canvas');
            c.width = 2480;
            c.height = 3508;
            const x = c.getContext('2d');
            x.fillStyle = '#ffffff';
            x.fillRect(0, 0, c.width, c.height);
            x.imageSmoothingEnabled = true;
            x.imageSmoothingQuality = 'high';
            const margin = 42;
            const maxW = c.width - margin * 2;
            const maxH = c.height - margin * 2;
            const iw = img.naturalWidth || img.width;
            const ih = img.naturalHeight || img.height;
            const scale = Math.min(maxW / iw, maxH / ih);
            const dw = Math.round(iw * scale);
            const dh = Math.round(ih * scale);
            const dx = Math.round((c.width - dw) / 2);
            const dy = Math.round((c.height - dh) / 2);
            x.drawImage(img, dx, dy, dw, dh);
            if (/^data:image\/png/i.test(String(dataUrl || ''))) {
                return c.toDataURL('image/png');
            }
            return c.toDataURL('image/jpeg', 0.99);
        }

        async function fitDataUrlOnIdCardCanvas(dataUrl) {
            const img = await loadImageFromDataUrl(dataUrl);
            const c = document.createElement('canvas');
            c.width = 2480;
            c.height = 3508;
            const x = c.getContext('2d');
            x.fillStyle = '#ffffff';
            x.fillRect(0, 0, c.width, c.height);
            x.imageSmoothingEnabled = true;
            x.imageSmoothingQuality = 'high';
            const cardW = DOC_TYPES.smart.w;
            const cardH = DOC_TYPES.smart.h;
            const cardX = Math.round((c.width - cardW) / 2);
            const cardY = 40;
            x.fillStyle = '#ffffff';
            x.fillRect(cardX, cardY, cardW, cardH);
            x.strokeStyle = '#cbd5e1';
            x.lineWidth = 4;
            x.strokeRect(cardX, cardY, cardW, cardH);
            const pad = 0;
            const maxW = cardW - pad * 2;
            const maxH = cardH - pad * 2;
            const iw = img.naturalWidth || img.width;
            const ih = img.naturalHeight || img.height;
            const scale = Math.min(maxW / iw, maxH / ih);
            const dw = Math.round(iw * scale);
            const dh = Math.round(ih * scale);
            const dx = Math.round(cardX + (cardW - dw) / 2);
            const dy = Math.round(cardY + (cardH - dh) / 2);
            x.drawImage(img, dx, dy, dw, dh);
            return c.toDataURL('image/jpeg', 0.99);
        }

        async function makePrintPreviewDataUrl(dataUrl) {
            const img = await loadImageFromDataUrl(dataUrl);
            const c = document.createElement('canvas');
            c.width = 360;
            c.height = 510;
            const x = c.getContext('2d');
            x.fillStyle = '#ffffff';
            x.fillRect(0, 0, c.width, c.height);
            x.imageSmoothingEnabled = true;
            x.imageSmoothingQuality = 'high';
            const iw = img.naturalWidth || img.width;
            const ih = img.naturalHeight || img.height;
            const scale = Math.min(c.width / iw, c.height / ih);
            const dw = Math.round(iw * scale);
            const dh = Math.round(ih * scale);
            x.drawImage(img, Math.round((c.width - dw) / 2), Math.round((c.height - dh) / 2), dw, dh);
            return c.toDataURL('image/jpeg', 0.82);
        }

        function drawImageInsideBox(ctx, img, boxX, boxY, boxW, boxH, pad = 18) {
            const maxW = boxW - pad * 2;
            const maxH = boxH - pad * 2;
            const iw = img.naturalWidth || img.width;
            const ih = img.naturalHeight || img.height;
            const scale = Math.min(maxW / iw, maxH / ih);
            const dw = Math.round(iw * scale);
            const dh = Math.round(ih * scale);
            const dx = Math.round(boxX + (boxW - dw) / 2);
            const dy = Math.round(boxY + (boxH - dh) / 2);
            ctx.drawImage(img, dx, dy, dw, dh);
        }

        async function fitIdCardItemOnCanvas(item) {
            if (!item?.backDataUrl) return fitDataUrlOnIdCardCanvas(item?.dataUrl || '');
            const frontImg = await loadImageFromDataUrl(item.dataUrl);
            const backImg = await loadImageFromDataUrl(item.backDataUrl);
            const c = document.createElement('canvas');
            c.width = 2480;
            c.height = 3508;
            const x = c.getContext('2d');
            x.fillStyle = '#ffffff';
            x.fillRect(0, 0, c.width, c.height);
            x.imageSmoothingEnabled = true;
            x.imageSmoothingQuality = 'high';
            const cardW = DOC_TYPES.smart.w;
            const cardH = DOC_TYPES.smart.h;
            const cardX = Math.round((c.width - cardW) / 2);
            const freeY = Math.max(0, c.height - (cardH * 2));
            const topBottomGap = Math.round(freeY * 0.30);
            const middleGap = freeY - (topBottomGap * 2);
            const frontY = topBottomGap;
            const backY = topBottomGap + cardH + middleGap;
            const drawCard = (img, cardY) => {
                x.fillStyle = '#ffffff';
                x.fillRect(cardX, cardY, cardW, cardH);
                x.strokeStyle = '#cbd5e1';
                x.lineWidth = 4;
                x.strokeRect(cardX, cardY, cardW, cardH);
                drawImageInsideBox(x, img, cardX, cardY, cardW, cardH, 0);
            };
            drawCard(frontImg, frontY);
            drawCard(backImg, backY);
            return c.toDataURL('image/jpeg', 0.99);
        }

        async function submitDirectRemotePrintFiles(files) {
            const list = Array.from(files || []).slice(0, 10);
            if (!remoteShopToken || list.length === 0) return false;
            if (!remoteSettingsLoaded) {
                await loadRemoteShopSettings();
            }
            if (!remoteShopAutoPrintEnabled) {
                showModal("Subscription Required", "Is shop ka Auto Print subscription active nahi hai, isliye direct print submit nahi ho sakta.", "warn");
                setRemoteCustomerStatus('Shop Auto Print subscription inactive hai.');
                return false;
            }
            showProcessLoader({
                kind: 'upload',
                variant: 'fast',
                title: 'Direct print upload ho raha hai',
                message: `${list.length} file(s) shop printer queue ke liye ready ho rahi hain.`,
                chip: 'UPLOAD',
                subtext: 'Crop skip karke original file A4 par fit ho rahi hai'
            });
            await waitForFastPaint();
            try {
                const requestedMode = getCustomerPrintMode();
                const copies = getCustomerCopies();
                for (let i = 0; i < list.length; i++) {
                    updateProcessLoader({
                        kind: 'upload',
                        variant: 'fast',
                        title: `File ${i + 1}/${list.length} prepare ho rahi hai`,
                        message: `${copies} copy ke saath shop queue me submit kar rahe hain.`,
                        chip: 'UPLOAD',
                        subtext: 'Please upload complete hone tak wait karein'
                    });
                    const printData = await renderFileToDirectPrintDataUrl(list[i]);
                    const previewData = await makePrintPreviewDataUrl(printData);
                    const directPaymentMode = remotePaymentMode === 'cash' ? 'cash' : 'none';
                    const res = await postShopPrintAction('shop_submit_print_job', {
                        shop_token: remoteShopToken,
                        print_data: printData,
                        preview_data: previewData,
                        copies,
                        print_mode: requestedMode,
                        paper: 'a4',
                        source: 'customer-direct',
                        customer_name: 'QR Customer',
                        customer_wallet_id: getCustomerWalletId(),
                        payment_mode: directPaymentMode,
                        approval_required: remoteApprovalRequired ? '1' : '0',
                        payment_required: '0',
                        payment_amount: directPaymentMode === 'cash' ? normalizeMoney((requestedMode === 'gray' ? remoteRateGray : remoteRateColor) * copies) : '0',
                        payment_summary: `A4 ${getPrintModeLabel(requestedMode)} ${copies} copy, ${directPaymentMode === 'cash' ? 'cash payment' : 'no payment'}`
                    });
                    if (res.status !== 'success') throw new Error(res.message || 'Job submit failed');
                }
                showModal("Print Sent", `${list.length} file(s), ${copies} copy each, shop printer queue me bhej di gayi.`, "success");
                return true;
            } catch (e) {
                console.error(e);
                showModal("Direct Print Failed", e?.message || "Direct print submit nahi ho paya.", "error");
                return false;
            } finally {
                hideProcessLoader();
            }
        }

        function readAsDataUrl(file) {
            return new Promise((resolve, reject) => {
                const r = new FileReader();
                r.onload = ev => resolve(ev.target.result);
                r.onerror = () => reject(new Error("File read failed"));
                r.readAsDataURL(file);
            });
        }

        async function readImageFileFastDataUrl(file, maxDim = 6200) {
            if (!file) throw new Error("File missing");
            const fileSize = Number(file.size || 0);
            if (fileSize <= (3 * 1024 * 1024)) return readAsDataUrl(file);

            const objectUrl = URL.createObjectURL(file);
            try {
                const img = await loadImageFromDataUrl(objectUrl);
                const srcW = img.naturalWidth || img.width;
                const srcH = img.naturalHeight || img.height;
                if (!srcW || !srcH) throw new Error("Image size unavailable");
                const shouldRasterize = fileSize > (7 * 1024 * 1024) || Math.max(srcW, srcH) > maxDim;
                if (!shouldRasterize) return readAsDataUrl(file);
                const ratio = Math.min(1, maxDim / Math.max(srcW, srcH));
                const c = document.createElement('canvas');
                c.width = Math.max(1, Math.round(srcW * ratio));
                c.height = Math.max(1, Math.round(srcH * ratio));
                const x = c.getContext('2d', { alpha: false });
                x.imageSmoothingEnabled = true;
                x.imageSmoothingQuality = 'high';
                x.fillStyle = '#ffffff';
                x.fillRect(0, 0, c.width, c.height);
                x.drawImage(img, 0, 0, c.width, c.height);
                return c.toDataURL('image/jpeg', 0.98);
            } finally {
                URL.revokeObjectURL(objectUrl);
            }
        }

        function renderTextFileToDataUrl(file) {
            return new Promise((resolve, reject) => {
                const r = new FileReader();
                r.onload = () => {
                    const text = String(r.result || '').slice(0, 2200);
                    const c = document.createElement('canvas');
                    c.width = 1600; c.height = 1100;
                    const x = c.getContext('2d');
                    x.fillStyle = '#ffffff'; x.fillRect(0, 0, c.width, c.height);
                    x.fillStyle = '#0f172a'; x.font = 'bold 44px Segoe UI';
                    x.fillText(file.name || 'Text File', 60, 90);
                    x.fillStyle = '#334155'; x.font = '28px Consolas';
                    const lines = text.replace(/\r/g, '').split('\n');
                    let y = 150;
                    lines.forEach((line) => {
                        if (y > c.height - 40) return;
                        x.fillText(line.slice(0, 95), 60, y);
                        y += 34;
                    });
                    resolve(c.toDataURL('image/jpeg', 0.95));
                };
                r.onerror = () => reject(new Error("Could not read text file"));
                r.readAsText(file);
            });
        }

        function renderGenericFileCardToDataUrl(file) {
            const name = file.name || 'Document';
            const ext = (name.split('.').pop() || 'FILE').toUpperCase().slice(0, 8);
            const c = document.createElement('canvas');
            c.width = 1600; c.height = 1100;
            const x = c.getContext('2d');
            x.fillStyle = '#f8fafc'; x.fillRect(0, 0, c.width, c.height);
            x.fillStyle = '#2563eb'; x.fillRect(0, 0, c.width, 170);
            x.fillStyle = '#ffffff'; x.font = 'bold 62px Segoe UI'; x.fillText(ext, 60, 112);
            x.fillStyle = '#0f172a'; x.font = 'bold 46px Segoe UI';
            x.fillText('File Imported for ID Print', 60, 280);
            x.fillStyle = '#334155'; x.font = '32px Segoe UI';
            x.fillText(name.slice(0, 65), 60, 360);
            x.fillStyle = '#64748b'; x.font = '30px Segoe UI';
            x.fillText(`Type: ${file.type || 'unknown'}`, 60, 430);
            x.fillText(`Size: ${(file.size / 1024).toFixed(1)} KB`, 60, 490);
            x.fillText('Tip: Pro mode supports all file uploads in ID Print.', 60, 620);
            return Promise.resolve(c.toDataURL('image/jpeg', 0.95));
        }

        function computeCanvasVisualFeatures(sourceCanvas, sourceWidth = 0, sourceHeight = 0) {
            try {
                const originalWidth = Number(sourceWidth || sourceCanvas?.naturalWidth || sourceCanvas?.width || 1);
                const originalHeight = Number(sourceHeight || sourceCanvas?.naturalHeight || sourceCanvas?.height || 1);
                const size = 16;
                const c = document.createElement('canvas');
                c.width = size;
                c.height = size;
                const x = c.getContext('2d', { willReadFrequently: true });
                x.fillStyle = '#ffffff';
                x.fillRect(0, 0, size, size);
                x.imageSmoothingEnabled = true;
                x.imageSmoothingQuality = 'high';
                x.drawImage(sourceCanvas, 0, 0, size, size);
                const data = x.getImageData(0, 0, size, size).data;
                const gray = [];
                let sum = 0;
                let dark = 0;
                let ink = 0;
                for (let i = 0; i < data.length; i += 4) {
                    const g = (data[i] * 0.299) + (data[i + 1] * 0.587) + (data[i + 2] * 0.114);
                    gray.push(g);
                    sum += g;
                    if (g < 92) dark++;
                    if (g < 235) ink++;
                }
                const avg = sum / Math.max(1, gray.length);
                let bits = '';
                gray.forEach((g) => { bits += g >= avg ? '1' : '0'; });
                let hash = '';
                for (let i = 0; i < bits.length; i += 4) hash += parseInt(bits.slice(i, i + 4), 2).toString(16);
                let edge = 0;
                for (let y = 0; y < size; y++) {
                    for (let xx = 0; xx < size; xx++) {
                        const idx = y * size + xx;
                        if (xx + 1 < size) edge += Math.abs(gray[idx] - gray[idx + 1]);
                        if (y + 1 < size) edge += Math.abs(gray[idx] - gray[idx + size]);
                    }
                }
                const aspect = originalWidth / Math.max(1, originalHeight);
                return {
                    image_signature: hash,
                    visual_bucket: [
                        `aspect_${Math.round(aspect * 100)}`,
                        `ink_${Math.round((ink / gray.length) * 100)}`,
                        `dark_${Math.round((dark / gray.length) * 100)}`,
                        `edge_${Math.round(edge / 100)}`
                    ].join('|'),
                    visual: {
                        ahash_16: hash,
                        width_px: originalWidth,
                        height_px: originalHeight,
                        aspect: +aspect.toFixed(4),
                        ink_ratio: +(ink / gray.length).toFixed(4),
                        dark_ratio: +(dark / gray.length).toFixed(4),
                        edge_score: Math.round(edge)
                    }
                };
            } catch (e) {
                return { image_signature: '', visual_bucket: '', visual: {} };
            }
        }

        async function computeDataUrlVisualFeatures(dataUrl) {
            try {
                const img = await loadImageFromDataUrl(dataUrl);
                const srcW = img.naturalWidth || img.width || 1;
                const srcH = img.naturalHeight || img.height || 1;
                // The signature only needs 16x16 pixels; avoid allocating a second
                // full-resolution canvas just to downscale it again.
                return computeCanvasVisualFeatures(img, srcW, srcH);
            } catch (e) {
                return { image_signature: '', visual_bucket: '', visual: {} };
            }
        }

        async function ensurePdfJsReady() {
            await loadToolLibrary('PDF reader', PDFJS_CDN_BASE + 'pdf.min.js', () => {
                window.pdfjsLib = window.pdfjsLib || window['pdfjs-dist/build/pdf'];
                return !!window.pdfjsLib;
            });
            window.pdfjsLib.GlobalWorkerOptions.workerSrc = PDFJS_CDN_BASE + 'pdf.worker.min.js';
        }

        const PDFJS_CDN_BASE = 'https://cdnjs.cloudflare.com/ajax/libs/pdf.js/2.16.105/';

        function buildPdfDocumentOptions(pdfData, password = '') {
            return {
                data: pdfData,
                password: password || undefined,
                stopAtErrors: false,
                disableFontFace: false,
                useSystemFonts: true,
                cMapUrl: PDFJS_CDN_BASE + 'cmaps/',
                cMapPacked: true,
                standardFontDataUrl: PDFJS_CDN_BASE + 'standard_fonts/',
                isEvalSupported: false
            };
        }

        async function extractPdfTextForDetection(pdfDoc, maxPages = 1) {
            try {
                const pageCount = Math.min(maxPages, pdfDoc.numPages || 1);
                const chunks = [];
                const itemsForLocation = [];
                for (let pageNo = 1; pageNo <= pageCount; pageNo++) {
                    const page = await withTimeout(pdfDoc.getPage(pageNo), 2500, 'PDF text page read timed out');
                    const viewport = page.getViewport({ scale: 1 });
                    const content = await withTimeout(page.getTextContent(), 3000, 'PDF text read timed out');
                    (content.items || []).forEach((item) => {
                        if (!item?.str) return;
                        chunks.push(item.str);
                        if (pageNo === 1 && window.pdfjsLib?.Util?.transform) {
                            try {
                                const tx = window.pdfjsLib.Util.transform(viewport.transform, item.transform);
                                itemsForLocation.push({
                                    text: item.str,
                                    x: tx[4] / Math.max(1, viewport.width),
                                    y: tx[5] / Math.max(1, viewport.height)
                                });
                            } catch (e) {}
                        }
                    });
                    if (chunks.join(' ').length > 1200) break;
                }
                lastPdfDetectItems = itemsForLocation;
                return chunks.join(' ').slice(0, 1800);
            } catch (e) {
                lastPdfDetectItems = [];
                return '';
            }
        }

        async function renderPdfPageRasterDataUrl(file, password = '', scale = 4.2, maxRasterPixels = 16000000, quality = 0.94, timeoutMs = 15000, pageNumber = 1) {
            await ensurePdfJsReady();
            const pdfData = new Uint8Array(await file.arrayBuffer());
            const loadingTask = window.pdfjsLib.getDocument(buildPdfDocumentOptions(pdfData, password));
            let pdfDoc = null;
            let rasterCanvas = null;
            try {
                pdfDoc = await withTimeout(loadingTask.promise, Math.min(timeoutMs, 9000), 'PDF high-quality open timed out');
                const safePageNumber = Math.max(1, Math.min(Number(pageNumber) || 1, pdfDoc.numPages || 1));
                const page = await withTimeout(pdfDoc.getPage(safePageNumber), 4500, 'PDF high-quality page read timed out');
                let viewport = page.getViewport({ scale });
                const safeRatio = getSafeSheetBitmapScale({ w: viewport.width, h: viewport.height }, 1);
                maxRasterPixels = Math.min(maxRasterPixels, viewport.width * viewport.height * safeRatio * safeRatio);
                const rasterPixels = viewport.width * viewport.height;
                if (rasterPixels > maxRasterPixels) {
                    const adjustedScale = scale * Math.sqrt(maxRasterPixels / rasterPixels);
                    viewport = page.getViewport({ scale: adjustedScale });
                }
                const c = document.createElement('canvas');
                rasterCanvas = c;
                c.width = Math.ceil(viewport.width);
                c.height = Math.ceil(viewport.height);
                const x = c.getContext('2d');
                x.imageSmoothingEnabled = true;
                x.imageSmoothingQuality = 'high';
                x.fillStyle = '#ffffff';
                x.fillRect(0, 0, c.width, c.height);
                await withTimeout(page.render({ canvasContext: x, viewport }).promise, timeoutMs, 'PDF high-quality render timed out');
                return {
                    dataUrl: encodeCanvasDataUrl(c, 'image/jpeg', quality),
                    width: c.width,
                    height: c.height
                };
            } finally {
                releaseOutputCanvas(rasterCanvas);
                try { if (pdfDoc?.destroy) pdfDoc.destroy(); } catch (e) {}
            }
        }

        function prepareActivePdfHighQualityRaster(file, password = '') {
            activePdfHighQualityDataUrl = '';
            activePdfHighQualityPromise = null;
            activePdfHighQualityStarter = null;
            const token = ++activePdfHighQualityToken;
            if (!file || !isPdfFile(file)) return;
            const finalScale = getPdfFinalRasterScale();
            const previewScale = getPdfRasterScale();
            if (finalScale <= previewScale + 0.1) return;
            const isPvcRaster = currentType === 'pvc';
            const startHighQualityRender = () => renderPdfPageRasterDataUrl(
                file,
                password,
                finalScale,
                isPvcRaster ? 30000000 : 24000000,
                isPvcRaster ? 0.96 : 0.94,
                18000
            );
            let renderPromise = null;
            // Keep the 24-30MP final raster fully lazy. requestIdleCallback with a
            // timeout still starts CPU-heavy canvas work while the user is clicking,
            // which delays native file/Drive pickers on slower computers.
            activePdfHighQualityStarter = () => {
                if (renderPromise) return renderPromise;
                renderPromise = Promise.resolve()
                    .then(startHighQualityRender)
                    .then((result) => {
                        if (token === activePdfHighQualityToken) activePdfHighQualityDataUrl = result?.dataUrl || '';
                        return result;
                    })
                    .catch((err) => {
                        console.warn('PDF high-quality raster fallback unavailable', err);
                        if (token === activePdfHighQualityToken) activePdfHighQualityDataUrl = '';
                        return null;
                    });
                if (token === activePdfHighQualityToken) activePdfHighQualityPromise = renderPromise;
                return renderPromise;
            };
        }

        function startActivePdfHighQualityRaster() {
            if (activePdfHighQualityDataUrl) return Promise.resolve({ dataUrl: activePdfHighQualityDataUrl });
            if (activePdfHighQualityPromise) return activePdfHighQualityPromise;
            if (typeof activePdfHighQualityStarter !== 'function') return null;
            activePdfHighQualityPromise = activePdfHighQualityStarter();
            return activePdfHighQualityPromise;
        }

        function resetActivePdfHighQualityContext() {
            activePdfFastRasterSize = null;
            activePdfHighQualityDataUrl = '';
            activePdfHighQualityPromise = null;
            activePdfHighQualityStarter = null;
            activePdfHighQualityToken++;
        }

        function activatePvcItemHighQualityContext(item) {
            resetActivePdfHighQualityContext();
            const task = item?.pvcHighQualityTask || null;
            if (!task) return;
            activePdfHighQualityDataUrl = task.dataUrl || '';
            activePdfHighQualityPromise = task.promise || null;
            activePdfHighQualityStarter = typeof task.start === 'function' ? task.start : null;
        }

        async function renderPdfFileToDataUrl(file) {
            await ensurePdfJsReady();
            lastPdfDetectText = '';
            lastPdfDetectItems = [];
            lastPdfMeta = null;
            lastVisualMeta = null;
            pendingPvcTwoPagePdf = null;
            pvcTwoPageAutoCompleted = false;
            const pdfData = new Uint8Array(await file.arrayBuffer());
            let password = (lastPdfPassword || '').trim();
            let incorrectAttempt = false;

            for (let attempt = 0; attempt < 5; attempt++) {
                const loadingTask = window.pdfjsLib.getDocument(buildPdfDocumentOptions(pdfData, password));

                let pdfDoc;
                try {
                    pdfDoc = await withTimeout(loadingTask.promise, 7000, 'PDF open timed out');
                } catch (err) {
                    if (!isPdfPasswordError(err)) throw err;
                    const askedPassword = await requestPdfPassword(file?.name || 'Locked PDF', incorrectAttempt);
                    if (!askedPassword) {
                        const cancelError = new Error("PDF password required. Upload cancelled.");
                        cancelError.name = 'PdfPasswordCancelledError';
                        throw cancelError;
                    }
                    password = askedPassword.trim();
                    incorrectAttempt = true;
                    continue;
                }

                const page = await withTimeout(pdfDoc.getPage(1), 3500, 'PDF page read timed out');
                const baseViewport = page.getViewport({ scale: 1 });
                if (currentType === 'pvc') {
                    lastPdfDetectText = await extractPdfTextForDetection(pdfDoc, 1);
                    const pageWidthPt = +(baseViewport.width || 0).toFixed(2);
                    const pageHeightPt = +(baseViewport.height || 0).toFixed(2);
                    const pageSizeKey = `${Math.round(pageWidthPt)}x${Math.round(pageHeightPt)}`;
                    const sourceKind = String(lastPdfDetectText || '').trim().length > 20 ? 'pdf_text' : 'pdf_image';
                    const knownDocType = resolvePvcPdfDocTypeForMeta({
                        fileName: file?.name || '',
                        text: lastPdfDetectText,
                        pageSizeKey,
                        sourceKind
                    });
                    const textSignature = makeTextSignature(lastPdfDetectText || file?.name || '');
                    const layoutSignature = makeTextLayoutSignature(lastPdfDetectItems);
                    lastPdfMeta = {
                        doc_type: sanitizePvcDocType(knownDocType),
                        doc_label: getPvcDocTypeLabel(knownDocType),
                        page_width_pt: pageWidthPt,
                        page_height_pt: pageHeightPt,
                        page_count: pdfDoc.numPages || 1,
                        page_size_key: pageSizeKey,
                        text_signature: textSignature,
                        layout_signature: layoutSignature,
                        has_text: String(lastPdfDetectText || '').trim().length > 20,
                        source_kind: sourceKind,
                        content_kind: inferContentKindFromMeta({ doc_type: knownDocType, page_size_key: pageSizeKey }),
                        text_sample: redactPdfTextSample(lastPdfDetectText || '')
                    };
                }
                const rasterScale = getPdfRasterScale();
                let viewport = page.getViewport({ scale: rasterScale });
                const maxRasterPixels = currentType === 'pvc' ? 12000000 : 10000000;
                const rasterPixels = viewport.width * viewport.height;
                if (rasterPixels > maxRasterPixels) {
                    const adjustedScale = rasterScale * Math.sqrt(maxRasterPixels / rasterPixels);
                    viewport = page.getViewport({ scale: adjustedScale });
                }
                const c = document.createElement('canvas');
                c.width = Math.ceil(viewport.width);
                c.height = Math.ceil(viewport.height);
                const x = c.getContext('2d');
                x.imageSmoothingEnabled = true;
                x.imageSmoothingQuality = 'high';
                x.fillStyle = '#ffffff';
                x.fillRect(0, 0, c.width, c.height);
                await withTimeout(page.render({ canvasContext: x, viewport }).promise, 9000, 'PDF preview render timed out');
                activePdfFastRasterSize = { width: c.width, height: c.height };
                if (currentType === 'pvc') {
                    lastVisualMeta = computeCanvasVisualFeatures(c);
                    if (lastPdfMeta) {
                        lastPdfMeta.image_signature = lastVisualMeta.image_signature || '';
                        lastPdfMeta.visual_bucket = lastVisualMeta.visual_bucket || '';
                        lastPdfMeta.render_size_key = `${c.width}x${c.height}`;
                        lastPdfMeta.features = {
                            text_markers: String(lastPdfMeta.text_signature || '').split('-').filter(Boolean),
                            visual: lastVisualMeta.visual || {},
                            layout: {
                                page_width_pt: lastPdfMeta.page_width_pt,
                                page_height_pt: lastPdfMeta.page_height_pt,
                                render_width_px: c.width,
                                render_height_px: c.height,
                                render_size_key: `${c.width}x${c.height}`,
                                text_layout_signature: lastPdfMeta.layout_signature || ''
                            }
                        };
                        if (!lastPdfMeta.has_text) {
                            lastPdfMeta.doc_type = sanitizePvcDocType(inferPvcDocTypeFromFileName(file?.name || '') || 'image_only_document');
                            lastPdfMeta.doc_label = getPvcDocTypeLabel(lastPdfMeta.doc_type);
                            lastPdfMeta.text_signature = lastPdfMeta.text_signature === 'generic-document' ? '' : lastPdfMeta.text_signature;
                        }
                        lastPdfMeta.template_scope = getPvcTemplateScopeFromMeta(lastPdfMeta);
                        lastPdfMeta.pdf_signature = buildPdfSignature(lastPdfMeta);
                        setPvcActivePdfMeta(lastPdfMeta);
                    }
                }
                const frontPageDataUrl = c.toDataURL('image/jpeg', currentType === 'pvc' ? 0.94 : 0.93);
                if (currentType === 'pvc' && pendingPvcPdfDualFlow && (pdfDoc.numPages || 1) === 2) {
                    // Page-count routing must happen before any document preset.
                    // It also overrides a stale/user-selected single-side state.
                    pvcActiveTemplateMatch = null;
                    pvcLockedTemplate = null;
                    pvcSingleSideAiMode = false;
                    isSingleSide = false;
                    syncSingleSideUI();
                }
                if (currentType === 'pvc'
                    && pendingPvcPdfDualFlow
                    && (pdfDoc.numPages || 1) === 2) {
                    try {
                        updateProcessLoader({
                            title: '2-page PVC PDF read ho rahi hai',
                            message: 'Page 1 ko Front aur Page 2 ko Back banane ke liye doosra page taiyar ho raha hai.',
                            chip: '1 + 2'
                        });
                        const secondPage = await withTimeout(pdfDoc.getPage(2), 3500, 'PDF second page read timed out');
                        let secondViewport = secondPage.getViewport({ scale: rasterScale });
                        const secondPixels = secondViewport.width * secondViewport.height;
                        if (secondPixels > maxRasterPixels) {
                            const adjustedScale = rasterScale * Math.sqrt(maxRasterPixels / secondPixels);
                            secondViewport = secondPage.getViewport({ scale: adjustedScale });
                        }
                        const secondCanvas = document.createElement('canvas');
                        secondCanvas.width = Math.ceil(secondViewport.width);
                        secondCanvas.height = Math.ceil(secondViewport.height);
                        const secondContext = secondCanvas.getContext('2d');
                        secondContext.imageSmoothingEnabled = true;
                        secondContext.imageSmoothingQuality = 'high';
                        secondContext.fillStyle = '#ffffff';
                        secondContext.fillRect(0, 0, secondCanvas.width, secondCanvas.height);
                        await withTimeout(secondPage.render({ canvasContext: secondContext, viewport: secondViewport }).promise, 9000, 'PDF second page preview timed out');
                        pendingPvcTwoPagePdf = {
                            file,
                            password,
                            fileName: String(file?.name || '2-page PDF'),
                            frontDataUrl: frontPageDataUrl,
                            backDataUrl: secondCanvas.toDataURL('image/jpeg', 0.94),
                            frontRasterSize: { width: c.width, height: c.height },
                            backRasterSize: { width: secondCanvas.width, height: secondCanvas.height },
                            pdfMeta: lastPdfMeta ? JSON.parse(JSON.stringify(lastPdfMeta)) : null
                        };
                    } catch (secondPageError) {
                        // Page 1 remains fully usable through the existing PVC flow.
                        // A damaged/very heavy second page must never turn the upload
                        // into a user-facing failure.
                        console.warn('2-page PVC pairing skipped', secondPageError);
                        pendingPvcTwoPagePdf = null;
                    }
                }
                if (pdfDoc.destroy) pdfDoc.destroy();
                if (password) lastPdfPassword = password;
                prepareActivePdfHighQualityRaster(file, password);
                return frontPageDataUrl;
            }

            throw new Error("PDF password attempts exceeded.");
        }

        function isOpenCvReady() {
            return !!(window.cv && cv.Mat && cv.imread && cv.imshow);
        }

        function isMatUsable(mat) {
            if (!mat) return false;
            try {
                if (typeof mat.isDeleted === 'function' && mat.isDeleted()) return false;
                return Number.isFinite(mat.cols) && Number.isFinite(mat.rows) && mat.cols > 0 && mat.rows > 0;
            } catch (e) {
                return false;
            }
        }

        function safeDeleteMat(mat) {
            if (!mat) return;
            try {
                [matCanvasCache, matPreviewCanvasCache, matFastPreviewCanvasCache].forEach((cache) => {
                    const canvas = cache.get(mat);
                    if (canvas) { canvas.width = 0; canvas.height = 0; }
                });
                matCanvasCache?.delete(mat);
                matPreviewCanvasCache?.delete(mat);
                matFastPreviewCanvasCache?.delete(mat);
            } catch (e) {}
            try {
                if (typeof mat.isDeleted !== 'function' || !mat.isDeleted()) mat.delete();
            } catch (e) {}
        }

        function getSafeEditorSourceLimits(docType = currentType) {
            const cores = Math.max(1, Number(navigator.hardwareConcurrency) || 4);
            const memory = Math.max(1, Number(navigator.deviceMemory) || 4);
            const mobile = window.matchMedia?.('(max-width: 767px)')?.matches === true;
            const constrained = memory <= 4 || cores <= 4 || mobile;
            if (docType === 'smart') {
                // The largest ID output is 2022x1276. A 12 MP working source
                // retains ample crop detail without allocating a huge RGBA Mat.
                return constrained
                    ? { maxDimension: 3600, maxPixels: 9000000 }
                    : { maxDimension: 4200, maxPixels: 12000000 };
            }
            if (docType === 'pvc') {
                return constrained
                    ? { maxDimension: 4200, maxPixels: 14000000 }
                    : { maxDimension: 5600, maxPixels: 22000000 };
            }
            return constrained
                ? { maxDimension: 4400, maxPixels: 15000000 }
                : { maxDimension: 6200, maxPixels: 30000000 };
        }

        function releaseEditorWorkingMemory() {
            safeDeleteMat(displayMat);
            displayMat = null;
            safeDeleteMat(srcMat);
            srcMat = null;
            const img = document.getElementById('tempImgSource');
            if (img) {
                img.onload = null;
                img.onerror = null;
                img.removeAttribute('src');
            }
            clearEditorPreviewSurface();
        }

        async function waitForOpenCvReady(timeoutMs = 8000) {
            const timeoutAt = Date.now() + timeoutMs;
            while (!isOpenCvReady() && Date.now() < timeoutAt) {
                await new Promise((resolve) => setTimeout(resolve, 80));
            }
            if (!isOpenCvReady()) throw new Error("Image editor engine is still loading. Please try again.");
        }

        function readImageElementToMat(img) {
            const imgW = Number(img?.naturalWidth || img?.width || 0);
            const imgH = Number(img?.naturalHeight || img?.height || 0);
            const limits = getSafeEditorSourceLimits(currentType);
            const pixelRatio = imgW > 0 && imgH > 0
                ? Math.sqrt(limits.maxPixels / (imgW * imgH))
                : 1;
            const dimensionRatio = Math.max(imgW, imgH) > 0
                ? limits.maxDimension / Math.max(imgW, imgH)
                : 1;
            const safeRatio = Math.min(1, pixelRatio, dimensionRatio);
            if (safeRatio < 0.999) {
                const c = document.createElement('canvas');
                c.width = Math.max(1, Math.round(imgW * safeRatio));
                c.height = Math.max(1, Math.round(imgH * safeRatio));
                const x = c.getContext('2d', { alpha: false });
                x.imageSmoothingEnabled = true;
                x.imageSmoothingQuality = 'high';
                x.fillStyle = '#ffffff';
                x.fillRect(0, 0, c.width, c.height);
                x.drawImage(img, 0, 0, c.width, c.height);
                try { return cv.imread(c); }
                finally { c.width = 1; c.height = 1; }
            }
            try {
                return cv.imread(img);
            } catch (firstError) {
                const c = document.createElement('canvas');
                c.width = img.naturalWidth || img.width;
                c.height = img.naturalHeight || img.height;
                if (!c.width || !c.height) throw firstError;
                const x = c.getContext('2d');
                x.drawImage(img, 0, 0, c.width, c.height);
                try {
                    return cv.imread(c);
                } catch (canvasError) {
                    const err = new Error("Image editor could not process this file. Please try a smaller or different file.");
                    err.cause = canvasError || firstError;
                    throw err;
                }
            }
        }

        function clearEditorPreviewSurface() {
            try {
                ctx.clearRect(0, 0, canvas.width || 1, canvas.height || 1);
                editorSourceCanvas.width = 1;
                editorSourceCanvas.height = 1;
                editorEnhancedCanvas.width = 1;
                editorEnhancedCanvas.height = 1;
            } catch (e) {}
        }

        function loadDataUrlToEditor(dataUrl, options = {}) {
            return new Promise((resolve, reject) => {
                const img = document.getElementById('tempImgSource');
                clearEditorPreviewSurface();
                img.onload = async () => {
                    try { await waitForOpenCvReady(); await startEditor(options); resolve(); }
                    catch (e) { reject(e || new Error("Image decode failed")); }
                };
                img.onerror = () => reject(new Error("Image decode failed"));
                img.src = dataUrl;
            });
        }

        async function loadDataUrlToEditorWithFallback(dataUrl, options = {}) {
            try {
                await withTimeout(loadDataUrlToEditor(dataUrl, options), 9000, 'Crop editor open timed out');
                return dataUrl;
            } catch (firstError) {
                console.warn('Editor source load failed, retrying with safe raster', firstError);
                const safeDataUrl = await makeEditorSafeDataUrl(dataUrl);
                await withTimeout(loadDataUrlToEditor(safeDataUrl, options), 9000, 'Crop editor open timed out');
                return safeDataUrl;
            }
        }

        async function makeEditorSafeDataUrl(dataUrl, maxDim = 4200) {
            const img = await loadImageFromDataUrl(dataUrl);
            const srcW = img.naturalWidth || img.width;
            const srcH = img.naturalHeight || img.height;
            if (!srcW || !srcH) throw new Error("Image size unavailable");
            const ratio = Math.min(1, maxDim / Math.max(srcW, srcH));
            if (ratio >= 1) return dataUrl;
            const c = document.createElement('canvas');
            c.width = Math.max(1, Math.round(srcW * ratio));
            c.height = Math.max(1, Math.round(srcH * ratio));
            const x = c.getContext('2d');
            x.imageSmoothingEnabled = true;
            x.imageSmoothingQuality = 'high';
            x.fillStyle = '#ffffff';
            x.fillRect(0, 0, c.width, c.height);
            x.drawImage(img, 0, 0, c.width, c.height);
            return c.toDataURL('image/jpeg', 0.94);
        }

        async function makeAiPreviewDataUrl(dataUrl, maxDim = 900, quality = 0.78) {
            const img = await loadImageFromDataUrl(dataUrl);
            const srcW = img.naturalWidth || img.width;
            const srcH = img.naturalHeight || img.height;
            if (!srcW || !srcH) throw new Error("AI preview image size unavailable");
            const ratio = Math.min(1, maxDim / Math.max(srcW, srcH));
            const c = document.createElement('canvas');
            c.width = Math.max(1, Math.round(srcW * ratio));
            c.height = Math.max(1, Math.round(srcH * ratio));
            const x = c.getContext('2d');
            x.imageSmoothingEnabled = true;
            x.imageSmoothingQuality = 'high';
            x.fillStyle = '#ffffff';
            x.fillRect(0, 0, c.width, c.height);
            x.drawImage(img, 0, 0, c.width, c.height);
            let out = c.toDataURL('image/jpeg', quality);
            if (out.length > 1650000 && maxDim > 620) {
                out = await makeAiPreviewDataUrl(dataUrl, 620, 0.68);
            }
            return out;
        }

        function normalizeLearningCaptureMeta(meta = {}) {
            const cleanToken = (value, fallback = '') => String(value || fallback)
                .toLowerCase()
                .replace(/[^a-z0-9_.-]/g, '')
                .slice(0, 80);
            const inferredInterface = typeof window !== 'undefined' && window.matchMedia?.('(max-width: 768px)').matches
                ? 'mobile_ui'
                : 'desktop_ui';
            return {
                upload_channel: cleanToken(meta.uploadChannel ?? meta.upload_channel, 'local_tool'),
                interface_surface: cleanToken(meta.interfaceSurface ?? meta.interface_surface, inferredInterface),
                source_media: cleanToken(meta.sourceMedia ?? meta.source_media, 'image'),
                mime_group: cleanToken(meta.mimeGroup ?? meta.mime_group, 'image'),
                file_extension: cleanToken(meta.fileExtension ?? meta.file_extension, ''),
                file_size_bucket: cleanToken(meta.fileSizeBucket ?? meta.file_size_bucket, ''),
                customer_mobile_flow: meta.customerMobileFlow === true || meta.customer_mobile_flow === true,
                pdf_render: meta.pdfRender === true || meta.pdf_render === true,
                group_ref: cleanToken(meta.groupRef ?? meta.group_ref, ''),
                front_or_back: (meta.side ?? meta.front_or_back) === 'back' ? 'back' : 'front',
                preview_width_px: Math.max(0, Math.round(Number(meta.previewWidth ?? meta.preview_width_px ?? meta.originalWidth ?? 0))),
                preview_height_px: Math.max(0, Math.round(Number(meta.previewHeight ?? meta.preview_height_px ?? meta.originalHeight ?? 0)))
            };
        }

        function inferCardLearningWorkflow(selectedFamily, sourceKind = '', captureMeta = {}) {
            const family = String(selectedFamily || '').toLowerCase();
            const source = String(sourceKind || '').toLowerCase();
            const isPdfRender = captureMeta.pdfRender === true || captureMeta.pdf_render === true;
            const isCustomerMobile = captureMeta.customerMobileFlow === true || captureMeta.customer_mobile_flow === true;
            if (family === 'pvc') return source.includes('pdf') || isPdfRender ? 'digital_pdf_pvc' : 'pvc_image_crop';
            if (family === 'a4') return 'document_page_crop';
            if (isCustomerMobile || source.includes('customer') || source.includes('mobile')) return 'mobile_card_restore';
            if (source.includes('pdf') || isPdfRender) return 'digital_pdf_card_crop';
            return 'local_card_image_crop';
        }

        function getLearningQuadMetrics(quad) {
            if (!Array.isArray(quad) || quad.length !== 4) return {};
            const points = quad.map((point) => ({ x: Number(point?.x), y: Number(point?.y) }));
            if (points.some((point) => !Number.isFinite(point.x) || !Number.isFinite(point.y))) return {};
            const distance = (a, b) => Math.hypot(a.x - b.x, a.y - b.y);
            let signedArea = 0;
            for (let i = 0; i < points.length; i++) {
                const next = points[(i + 1) % points.length];
                signedArea += (points[i].x * next.y) - (next.x * points[i].y);
            }
            const areaRatio = Math.max(0, Math.min(1, Math.abs(signedArea) / 2));
            const top = distance(points[0], points[1]);
            const right = distance(points[1], points[2]);
            const bottom = distance(points[2], points[3]);
            const left = distance(points[3], points[0]);
            const edgeRatio = Math.max(
                top / Math.max(0.0001, bottom), bottom / Math.max(0.0001, top),
                left / Math.max(0.0001, right), right / Math.max(0.0001, left)
            );
            const touchesFrame = points.some((point) => point.x < 0.008 || point.y < 0.008 || point.x > 0.992 || point.y > 0.992);
            return {
                card_area_ratio: +areaRatio.toFixed(5),
                background_area_ratio: +(1 - areaRatio).toFixed(5),
                opposite_edge_ratio: +Math.min(20, edgeRatio).toFixed(4),
                touches_source_frame: touchesFrame
            };
        }

        async function computeLearningQualityProfile(dataUrl, normalizedQuad = null) {
            const geometry = getLearningQuadMetrics(normalizedQuad);
            try {
                const img = await loadImageFromDataUrl(dataUrl);
                const sourceWidth = img.naturalWidth || img.width || 1;
                const sourceHeight = img.naturalHeight || img.height || 1;
                const maxDim = 160;
                const scale = Math.min(1, maxDim / Math.max(sourceWidth, sourceHeight));
                const c = document.createElement('canvas');
                c.width = Math.max(8, Math.round(sourceWidth * scale));
                c.height = Math.max(8, Math.round(sourceHeight * scale));
                const x = c.getContext('2d', { willReadFrequently: true });
                x.drawImage(img, 0, 0, c.width, c.height);
                const pixels = x.getImageData(0, 0, c.width, c.height).data;
                const gray = new Float32Array(c.width * c.height);
                let sum = 0, sumSq = 0, dark = 0, highlight = 0, glare = 0;
                let red = 0, green = 0, blue = 0;
                const quadrantSum = [0, 0, 0, 0];
                const quadrantCount = [0, 0, 0, 0];
                for (let py = 0; py < c.height; py++) {
                    for (let px = 0; px < c.width; px++) {
                        const pixelIndex = py * c.width + px;
                        const dataIndex = pixelIndex * 4;
                        const r = pixels[dataIndex], g = pixels[dataIndex + 1], b = pixels[dataIndex + 2];
                        const luminance = (r * 0.299) + (g * 0.587) + (b * 0.114);
                        gray[pixelIndex] = luminance;
                        sum += luminance;
                        sumSq += luminance * luminance;
                        red += r; green += g; blue += b;
                        if (luminance < 55) dark++;
                        if (luminance > 235) highlight++;
                        if (luminance > 242 && (Math.max(r, g, b) - Math.min(r, g, b)) < 18) glare++;
                        const quadrant = (py >= c.height / 2 ? 2 : 0) + (px >= c.width / 2 ? 1 : 0);
                        quadrantSum[quadrant] += luminance;
                        quadrantCount[quadrant]++;
                    }
                }
                const count = Math.max(1, gray.length);
                const mean = sum / count;
                const contrast = Math.sqrt(Math.max(0, (sumSq / count) - (mean * mean)));
                let lapSum = 0, lapSq = 0, lapCount = 0;
                for (let py = 1; py < c.height - 1; py++) {
                    for (let px = 1; px < c.width - 1; px++) {
                        const idx = py * c.width + px;
                        const lap = (gray[idx] * 4) - gray[idx - 1] - gray[idx + 1] - gray[idx - c.width] - gray[idx + c.width];
                        lapSum += lap;
                        lapSq += lap * lap;
                        lapCount++;
                    }
                }
                const lapMean = lapSum / Math.max(1, lapCount);
                const sharpness = Math.max(0, (lapSq / Math.max(1, lapCount)) - (lapMean * lapMean));
                const quadrantMeans = quadrantSum.map((value, index) => value / Math.max(1, quadrantCount[index]));
                const lightingSpread = Math.max(...quadrantMeans) - Math.min(...quadrantMeans);
                const channelMeans = [red / count, green / count, blue / count];
                const colorCast = Math.max(...channelMeans) - Math.min(...channelMeans);
                const darkRatio = dark / count;
                const highlightRatio = highlight / count;
                const glareRatio = glare / count;
                const tags = [];
                if (mean < 78 || darkRatio > 0.34) tags.push('low_light');
                if (mean > 205 || highlightRatio > 0.3) tags.push('overexposed');
                if (glareRatio > 0.035) tags.push('glare_candidate');
                if (lightingSpread > 48) tags.push('uneven_lighting');
                if (sharpness < 95) tags.push('soft_or_blurry');
                if (colorCast > 34) tags.push('colour_cast');
                if (Number(geometry.opposite_edge_ratio || 1) > 1.22) tags.push('strong_perspective');
                if (Number(geometry.card_area_ratio || 1) < 0.52) tags.push('background_heavy');
                if (geometry.touches_source_frame) tags.push('source_edge_clipped_risk');
                const difficultyScore = Math.min(100, tags.reduce((score, tag) => score + ({
                    glare_candidate: 18, soft_or_blurry: 18, strong_perspective: 16,
                    source_edge_clipped_risk: 20, background_heavy: 10, uneven_lighting: 10
                }[tag] || 7), 0));
                return {
                    ...geometry,
                    source_width_px: sourceWidth,
                    source_height_px: sourceHeight,
                    mean_luminance: +mean.toFixed(2),
                    contrast_stddev: +contrast.toFixed(2),
                    dark_ratio: +darkRatio.toFixed(5),
                    highlight_ratio: +highlightRatio.toFixed(5),
                    glare_candidate_ratio: +glareRatio.toFixed(5),
                    lighting_spread: +lightingSpread.toFixed(2),
                    laplacian_variance: +sharpness.toFixed(2),
                    colour_cast_spread: +colorCast.toFixed(2),
                    degradation_tags: tags,
                    difficulty_score: difficultyScore,
                    difficulty_tier: difficultyScore >= 45 ? 'hard' : (difficultyScore >= 20 ? 'medium' : 'easy'),
                    automatic_tags_not_ground_truth: true
                };
            } catch (error) {
                return { ...geometry, degradation_tags: ['quality_scan_failed'], automatic_tags_not_ground_truth: true };
            }
        }

        async function prepareLearningAssetSet(sourceDataUrl, targetDataUrls = {}) {
            let sourcePreview = await makeAiPreviewDataUrl(sourceDataUrl, 760, 0.72);
            const preparedTargets = {};
            for (const [role, targetDataUrl] of Object.entries(targetDataUrls || {})) {
                if (!targetDataUrl) continue;
                try {
                    preparedTargets[role] = await makeAiPreviewDataUrl(targetDataUrl, 680, 0.82);
                } catch (_) {}
            }
            const totalLength = () => sourcePreview.length + Object.values(preparedTargets).reduce((sum, value) => sum + value.length, 0);
            if (totalLength() > 1550000) {
                sourcePreview = await makeAiPreviewDataUrl(sourceDataUrl, 600, 0.64);
                for (const [role, targetDataUrl] of Object.entries(targetDataUrls || {})) {
                    if (!targetDataUrl) continue;
                    try {
                        preparedTargets[role] = await makeAiPreviewDataUrl(targetDataUrl, 520, 0.72);
                    } catch (_) {
                        delete preparedTargets[role];
                    }
                }
            }
            return { sourcePreview, targets: preparedTargets };
        }

        async function getLearningTargetProfile(targetDataUrl, role = 'rectified_card') {
            if (!targetDataUrl) return { available: false, role };
            try {
                const img = await loadImageFromDataUrl(targetDataUrl);
                return {
                    available: true,
                    role,
                    width_px: Math.round(img.naturalWidth || img.width || 0),
                    height_px: Math.round(img.naturalHeight || img.height || 0),
                    content_preserving: true,
                    enhancement_state: 'existing_user_visible_crop_pipeline',
                    exact_alpha_mask: false
                };
            } catch (_) {
                return { available: false, role };
            }
        }

        function normalizeAiPoint(point) {
            if (Array.isArray(point)) return { x: Number(point[0]), y: Number(point[1]) };
            return { x: Number(point?.x), y: Number(point?.y) };
        }

        function aiQuadToDisplayPoints(quad) {
            if (!Array.isArray(quad) || quad.length !== 4 || !isMatUsable(displayMat)) return null;
            const w = displayMat.cols;
            const h = displayMat.rows;
            const points = quad.map(normalizeAiPoint).map((p) => ({
                x: Math.max(0, Math.min(w, p.x * w)),
                y: Math.max(0, Math.min(h, p.y * h))
            }));
            if (points.some((p) => !Number.isFinite(p.x) || !Number.isFinite(p.y))) return null;
            const ordered = orderQuadPoints(points);
            const edges = ordered.map((point, index) => dist2D(point, ordered[(index + 1) % ordered.length]));
            const area = Math.abs(ordered.reduce((sum, point, index) => {
                const next = ordered[(index + 1) % ordered.length];
                return sum + ((point.x * next.y) - (next.x * point.y));
            }, 0)) / 2;
            // A malformed/degenerate model quad can make OpenCV spend an
            // unbounded time in perspective processing on some devices.
            // Reject it before warp and use the existing manual fallback.
            if (Math.min(...edges) < Math.max(8, Math.min(w, h) * 0.012) || area < (w * h * 0.002)) return null;
            return ordered;
        }

        function aiRectToDisplayRect(rect) {
            if (!rect || !isMatUsable(displayMat)) return null;
            const w = displayMat.cols;
            const h = displayMat.rows;
            const out = {
                x: Number(rect.x) * w,
                y: Number(rect.y) * h,
                w: Number(rect.w) * w,
                h: Number(rect.h) * h
            };
            if (![out.x, out.y, out.w, out.h].every(Number.isFinite) || out.w <= 10 || out.h <= 10) return null;
            return out;
        }

        function aiCardToDisplayRect(card) {
            const rect = aiRectToDisplayRect(card?.rect);
            if (rect) return rect;
            const quad = aiQuadToDisplayPoints(card?.quad);
            return quad ? pointsToBoundingRect(quad) : null;
        }

        async function requestCropAiAnalysis(actionType, dataUrl, file, extra = {}) {
            let browserFallbackNeeded = false;
            if (actionType === 'analyze_document_crop_ai' && cropWorkflowMode === 'auto'
                && documentCropLimitReached() && !isPairedIdBackCrop()) {
                await showDocumentCropLimitIfDue();
            }
            if (actionType === 'analyze_document_crop_ai' && !isDocumentAutoCropEnabled()) return null;
            if (!ENABLE_BACKGROUND_AI_DATA_COLLECTION) {
                return null;
            }
            if (actionType === 'analyze_pvc_crop_ai') shadowPvcAiAnalysis = null;
            if (actionType === 'analyze_document_crop_ai') shadowDocumentAiAnalysis = null;
            try {
                const preview = await makeAiPreviewDataUrl(dataUrl);
                let quotaSourceHash = '';
                if (actionType === 'analyze_document_crop_ai' && window.crypto?.subtle) {
                    const digest = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(preview));
                    quotaSourceHash = Array.from(new Uint8Array(digest), byte => byte.toString(16).padStart(2, '0')).join('');
                    if (currentType === 'smart' && currentSide === 'front') documentQuotaFrontHash = quotaSourceHash;
                }
                const resolvedDocType = extra.docType
                    || lastPdfMeta?.doc_type
                    || pvcActivePdfMeta?.doc_type
                    || (currentType === 'pvc' ? pvcAutoCropDocType : (currentType === 'a4' ? 'a4_document' : (currentType === 'smart' ? 'id_card' : 'custom_card')));
                const resolvedContentKind = extra.contentKind
                    || lastPdfMeta?.content_kind
                    || pvcActivePdfMeta?.content_kind
                    || (currentType === 'pvc' ? 'pvc_card' : (currentType === 'a4' ? 'a4_document' : 'id_card'));
                const res = await withTimeout(postToolAction(actionType, {
                    source_preview_data_url: preview,
                    doc_type: resolvedDocType || 'custom_card',
                    content_kind: resolvedContentKind,
                    file_name: file?.name || extra.fileName || '',
                    source_kind: extra.sourceKind || lastPdfMeta?.source_kind || (file && isPdfFile(file) ? 'pdf' : 'image'),
                    text_sample: redactPdfTextSample(extra.textSample || lastPdfMeta?.text_sample || lastPdfDetectText || ''),
                    crop_side: extra.cropSide || currentSide || 'front',
                    page_count: Number(extra.pageCount || lastPdfMeta?.page_count || pvcActivePdfMeta?.page_count || 1),
                    page_size_key: extra.pageSizeKey || lastPdfMeta?.page_size_key || pvcActivePdfMeta?.page_size_key || '',
                    render_size_key: extra.renderSizeKey || lastPdfMeta?.render_size_key || pvcActivePdfMeta?.render_size_key || '',
                    user_selected_family: extra.userSelectedFamily || currentType || '',
                    user_selected_doc_type: extra.userSelectedDocType || getAiActivityDocType(),
                    quota_mode: currentType === 'a4' ? 'a4' : 'id',
                    quota_source_hash: quotaSourceHash,
                    quota_front_hash: currentType === 'smart'
                        ? (currentSide === 'back' ? documentQuotaFrontHash : quotaSourceHash)
                        : quotaSourceHash,
                    ai_model_variant: DOCALIGNER_TEST_MODE ? 'docaligner' : ''
                }), extra.timeoutMs || (DOCALIGNER_TEST_MODE ? DOCALIGNER_BROWSER_TIMEOUT_MS : 3500), 'AI crop analysis timed out');
                if (actionType === 'analyze_document_crop_ai' && res?.crop_access) {
                    applyDocumentCropAccess(res.crop_access);
                }
                if (res?.code === 'daily_limit' || res?.manual_only === true) {
                    applyDocumentCropAccess({
                        ...documentCropAccess,
                        ...(res?.crop_access || {}),
                        paid: false,
                        quotaEnabled: true,
                        exhausted: true,
                        remaining: 0
                    });
                    await showDocumentCropLimitIfDue();
                    return null;
                }
                if (res?.status === 'success' && res.ai?.success) {
                    if (actionType === 'analyze_pvc_crop_ai') shadowPvcAiAnalysis = res.ai;
                    if (actionType === 'analyze_document_crop_ai') {
                        shadowDocumentAiAnalysis = res.ai;
                        documentAutoCropUsed = true;
                    }
                    return res.ai;
                }
                if (res?.silent_fallback) {
                    browserFallbackNeeded = true;
                    if (DOCALIGNER_TEST_MODE) {
                        console.info('DocAligner test fallback', res?.ai_test_diagnostic || {});
                        const statusNode = document.getElementById('mobStatus');
                        if (statusNode) statusNode.innerText = 'AI Auto Crop clear result nahi mila; manual crop safe hai';
                    }
                    return extra.browserFallback === true
                        ? { success: false, browser_fallback_needed: true }
                        : null;
                }
                console.warn('Crop AI analysis skipped', res?.message || res);
                browserFallbackNeeded = Number(res?.http_status || 0) >= 500
                    || ['upstream_unavailable', 'crop_temporarily_unavailable'].includes(String(res?.code || ''));
            } catch (err) {
                console.warn('Crop AI analysis failed', err);
                browserFallbackNeeded = err?.cropStage === 'gpu'
                    || err?.name === 'AbortError'
                    || err?.name === 'TypeError'
                    || /timed out|failed to fetch|network/i.test(String(err?.message || ''));
                const statusNode = document.getElementById('mobStatus');
                if (statusNode) statusNode.innerText = err?.cropStage === 'authorization'
                    ? (err.httpStatus === 429 ? 'AI crop limit: thodi der baad retry karein.' : 'AI session verify nahi hua. Page refresh karke retry karein.')
                    : 'AI crop response nahi mila. Manual adjust karein ya dobara upload karein.';
            }
            return extra.browserFallback === true && browserFallbackNeeded
                ? { success: false, browser_fallback_needed: true }
                : null;
        }

        function markCropperUserInteraction(kind, details = {}) {
            cropAiInteractionVersion++;
            recordAiActivity(kind, {
                interaction_version: cropAiInteractionVersion,
                ...details
            });
        }

        function scheduleCropAiAnalysis(actionType, dataUrl, file, extra = {}) {
            if (actionType === 'analyze_document_crop_ai' && !isDocumentAutoCropEnabled()) return 0;
            if (!ENABLE_BACKGROUND_AI_DATA_COLLECTION || !dataUrl) return 0;
            const requestId = ++cropAiRequestSequence;
            activeCropAiRequestId = requestId;
            const interactionVersion = cropAiInteractionVersion;
            const scheduledAt = performance.now();
            const pipeline = actionType === 'analyze_pvc_crop_ai' ? 'pvc_auto_crop' : 'document_straighten_crop';
            const requestExtra = {
                ...extra,
                userSelectedFamily: extra.userSelectedFamily || currentType || '',
                userSelectedDocType: extra.userSelectedDocType || getAiActivityDocType()
            };
            recordAiActivity('ai_analysis_queued', { pipeline, request_id: requestId });

            if (DOCALIGNER_TEST_MODE && String(requestExtra.sourceKind || '').toLowerCase() !== 'pdf') {
                const statusNode = document.getElementById('mobStatus');
                if (statusNode) statusNode.innerText = 'AI Auto Crop card boundary check kar raha hai…';
            }

            const run = () => {
                recordAiActivity('ai_analysis_started', { pipeline, request_id: requestId });
                Promise.resolve(requestCropAiAnalysis(actionType, dataUrl, file, requestExtra)).then((ai) => {
                    const stale = requestId !== activeCropAiRequestId;
                    if (!stale) {
                        if (actionType === 'analyze_pvc_crop_ai') shadowPvcAiAnalysis = ai;
                        else shadowDocumentAiAnalysis = ai;
                    }
                    const userInteracted = cropAiInteractionVersion !== interactionVersion;
                    const applied = false;
                    const isDocAlignerResult = DOCALIGNER_TEST_MODE && ai?.model_variant === 'docaligner';
                    // Scheduled/background analysis is telemetry-only. It must
                    // never alter an already visible manual cropper: otherwise a
                    // late reply can race the Done button and create two items.
                    // The strict `(1)` upload path below is the only owner allowed
                    // to apply a DocAligner result directly to preview.
                    recordAiActivity('ai_analysis_completed', {
                        pipeline,
                        request_id: requestId,
                        success: !!ai,
                        stale,
                        applied,
                        collection_only: true,
                        model_variant: ai?.model_variant || '',
                        user_interacted: userInteracted,
                        duration_ms: Math.round(performance.now() - scheduledAt),
                        detected_mode: ai?.classification?.mode || '',
                        detected_doc_type: ai?.classification?.doc_type || '',
                        confidence: Number(ai?.classification?.confidence || ai?.straighten?.confidence || 0)
                    });
                }).catch((err) => {
                    console.warn('Background crop AI failed', err);
                    recordAiActivity('ai_analysis_failed', {
                        pipeline,
                        request_id: requestId,
                        duration_ms: Math.round(performance.now() - scheduledAt)
                    });
                });
            };

            // Start only after the cropper has painted. This promise is never awaited
            // by upload/crop code, so API upload, timeout or response cannot delay users.
            if ('requestIdleCallback' in window) window.requestIdleCallback(run, { timeout: 450 });
            else setTimeout(run, 0);
            return requestId;
        }

        function getPvcAiCardsByRole(ai) {
            const cards = Array.isArray(ai?.cards) ? ai.cards : [];
            if (cards.length < 2) return { front: cards[0] || null, back: null };
            const front = cards.find((card) => String(card?.role || '').toLowerCase() === 'front') || cards[0];
            const back = cards.find((card) => String(card?.role || '').toLowerCase() === 'back') || cards.find((card) => card !== front) || cards[1];
            return { front, back };
        }

        function beginPvcTemplatePlacementFromAi(ai) {
            if (currentType !== 'pvc' || !isMatUsable(displayMat) || !ai?.success) return false;
            const mode = String(ai?.classification?.mode || '');
            const confidence = Number(ai?.classification?.confidence || 0);
            const { front, back } = getPvcAiCardsByRole(ai);
            if (mode !== 'double_side_card' || !front || !back || confidence < 0.55) return false;
            const frontRect = aiCardToDisplayRect(front);
            const backRect = aiCardToDisplayRect(back);
            if (!frontRect || !backRect) return false;
            pvcTemplatePlacementMode = true;
            const defaults = getDefaultPvcTemplateBoxes(displayMat, pvcAutoCropDocType);
            pvcTemplateBaseBox = { w: defaults.front.w, h: defaults.front.h };
            pvcTemplateScale = { w: 100, h: 100 };
            pvcTemplateBoxes = { front: frontRect, back: backRect };
            clampTemplateRect(pvcTemplateBoxes.front);
            clampTemplateRect(pvcTemplateBoxes.back);
            const w = displayMat.cols;
            const h = displayMat.rows;
            pvcTemplateOriginalTemplate = {
                front: normalizeRect(pvcTemplateBoxes.front, w, h),
                back: normalizeRect(pvcTemplateBoxes.back, w, h),
                box_scale_percent: { width: pvcTemplateScale.w, height: pvcTemplateScale.h },
                engine: ai.engine || 'ak_cv_layout_v2',
                confidence
            };
            currentSide = 'front';
            setCropStepUI('AI Front/Back Boxes', 'template');
            syncPvcSizeUi();
            drawCanvas();
            requestAnimationFrame(() => focusEditorOnRect(getUnionRect([pvcTemplateBoxes.front, pvcTemplateBoxes.back])));
            document.getElementById('mobStatus').innerText = `AI ne ${Math.round(confidence * 100)}% match se PVC boxes set kiye`;
            return true;
        }

        function applyPvcSingleCardAiCrop(ai, options = {}) {
            if (currentType !== 'pvc' || !isMatUsable(displayMat) || !ai?.success) return false;
            const sourceLabel = String(options.sourceLabel || 'AI');
            const mode = String(ai?.classification?.mode || '');
            const confidence = Number(ai?.classification?.confidence || 0);
            const card = Array.isArray(ai.cards) ? ai.cards[0] : null;
            const points = aiQuadToDisplayPoints(card?.quad);
            if (mode !== 'single_side_card' || !points || confidence < 0.5) return false;
            pvcTemplatePlacementMode = false;
            syncPvcDefaultSaveControls();
            pvcSingleSideAiMode = true;
            cropperPoints = options.preservePerspective === true ? points : normalizePvcCardBoxPoints(points);
            currentSide = 'front';
            setCropStepUI('Single Side PVC', 'step-front');
            drawCanvas();
            document.getElementById('mobStatus').innerText = `${sourceLabel} ne single side PVC card detect kiya`;
            if (options.showNotice !== false) {
                showModal("Single Side PVC", "AI ko sirf ek card side mili hai. Seedha crop box check karke Done dabayein; back side chahiye ho to alag se upload karein.", "info");
            }
            return true;
        }

        function applyDocumentAiCropperPoints(ai, sourceLabel = 'AI') {
            if (!ai?.success || !isMatUsable(displayMat) || pvcTemplatePlacementMode) return false;
            const preCrop = getDocAlignerPreCropOrientation(ai);
            if (preCrop && normalizeRightAngle(rotationAngle) !== preCrop.rotation) {
                rotationAngle = preCrop.rotation;
                refreshEditor(true);
            }
            const quad = getDocAlignerResultQuad(ai) || ai?.straighten?.quad || ai?.document?.quad;
            const points = aiQuadToDisplayPoints(quad);
            if (!points) return false;
            cropperPoints = points;
            drawCanvas();
            const confidence = Number(ai?.classification?.confidence || ai?.straighten?.confidence || 0);
            document.getElementById('mobStatus').innerText = `${sourceLabel} ne 4 corner dots set kiye${confidence ? ` (${Math.round(confidence * 100)}%)` : ''}`;
            return true;
        }

        function isDocAlignerDocumentType(type = currentType) {
            return type === 'smart' || type === 'a4' || type === 'custom';
        }

        function getDocAlignerPreCropOrientation(ai) {
            const preCrop = ai?.orientation?.pre_crop;
            if (!preCrop || preCrop.applied !== true) return null;
            const rotation = normalizeRightAngle(preCrop.rotation_degrees_clockwise || 0);
            const rawQuad = preCrop.quad;
            if (!Array.isArray(rawQuad) || rawQuad.length !== 4) return null;
            const quad = rawQuad.map(normalizeAiPoint);
            if (quad.some((point) => !Number.isFinite(point.x) || !Number.isFinite(point.y))) return null;
            return { rotation, quad };
        }

        function getDocAlignerResultQuad(ai) {
            const preCrop = getDocAlignerPreCropOrientation(ai);
            const card = Array.isArray(ai?.cards) ? ai.cards[0] : null;
            const quad = preCrop?.quad || ai?.straighten?.quad || ai?.document?.quad || ai?.quad || card?.quad;
            if (!Array.isArray(quad) || quad.length !== 4) return null;
            const normalized = quad.map(normalizeAiPoint);
            if (normalized.some((point) => !Number.isFinite(point.x) || !Number.isFinite(point.y))) return null;
            return normalized;
        }

        function getDocAlignerOutputRotation(ai) {
            // Boundary-only production requests deliberately disable the slow
            // OCR orientation stage. In that case an explicit server-side zero
            // means "not evaluated", not "confirmed upright"; fall through to
            // the quad-shape rule so a sideways card/page is still turned 90°.
            const serverOrientationDisabled = String(ai?.orientation?.method || '').toLowerCase() === 'disabled';
            const serverCandidates = serverOrientationDisabled ? [] : [
                ai?.orientation?.rotation_degrees_clockwise,
                ai?.orientation?.rotation,
                ai?.output?.rotation_degrees_clockwise,
                ai?.output?.orientation_degrees_clockwise,
                ai?.straighten?.rotation_degrees_clockwise
            ];
            for (const candidate of serverCandidates) {
                if (candidate !== null && candidate !== undefined && candidate !== '' && Number.isFinite(Number(candidate))) {
                    return normalizeRightAngle(candidate);
                }
            }

            // Old/cached GPU responses may contain a valid DocAligner quad but no
            // orientation field. Perspective warp already removes every free
            // angle (1..360); this shape fallback only chooses the missing 90°
            // reading turn, so a sideways card is never squeezed into landscape.
            const quad = getDocAlignerResultQuad(ai);
            if (!quad) return 0;
            const orderedQuad = orderQuadPoints(quad);
            const edgeLength = (a, b) => Math.hypot(Number(b.x) - Number(a.x), Number(b.y) - Number(a.y));
            const horizontalEdge = (edgeLength(orderedQuad[0], orderedQuad[1]) + edgeLength(orderedQuad[2], orderedQuad[3])) / 2;
            const verticalEdge = (edgeLength(orderedQuad[1], orderedQuad[2]) + edgeLength(orderedQuad[3], orderedQuad[0])) / 2;
            if (currentType === 'a4') return horizontalEdge > verticalEdge * 1.04 ? 90 : 0;
            return verticalEdge > horizontalEdge * 1.04 ? 90 : 0;
        }

        const enhancementComparisons = new WeakMap();
        let enhancementWipeFrame = null;
        let uploadPipelineStartedAt = 0;
        let directCropPreparation = false;

        function makeComparisonCanvas(mat, rotation = 0) {
            const small = new cv.Mat();
            const base = document.createElement('canvas');
            try {
                const ratio = Math.min(1, 960 / Math.max(mat.cols, mat.rows));
                cv.resize(mat, small, new cv.Size(Math.max(1, Math.round(mat.cols*ratio)), Math.max(1, Math.round(mat.rows*ratio))), 0, 0, cv.INTER_AREA);
                cv.imshow(base, small);
            } finally { small.delete(); }
            if (!rotation) return base;
            const result = document.createElement('canvas');
            result.width = rotation === 180 ? base.width : base.height;
            result.height = rotation === 180 ? base.height : base.width;
            const context = result.getContext('2d');
            context.translate(result.width/2, result.height/2);
            context.rotate(rotation*Math.PI/180);
            context.drawImage(base, -base.width/2, -base.height/2);
            return result;
        }

        function drawInCardEnhancementWipe(targetCtx, mat, width, height) {
            // Only the existing sheet preview animates. Export/print always
            // draws the enhanced pixels immediately, even during this effect.
            if (targetCtx.canvas !== previewCanvas) return;
            const comparison = enhancementComparisons.get(mat);
            if (!comparison || comparison.wipeDone || !comparison.before) return;
            const now = performance.now();
            if (comparison.wipeStartedAt == null) comparison.wipeStartedAt = now;
            const progress = Math.min(1, Math.max(0, (now - comparison.wipeStartedAt) / 1600));
            if (progress >= 1 || window.matchMedia?.('(prefers-reduced-motion: reduce)').matches) {
                comparison.wipeDone = true;
                comparison.before = null;
                return;
            }
            const eased = progress * progress * (3 - 2 * progress);
            const edge = -width/2 + width * eased;
            targetCtx.save();
            targetCtx.beginPath();
            targetCtx.rect(edge, -height/2, width * (1-eased), height);
            targetCtx.clip();
            targetCtx.drawImage(comparison.before, -width/2, -height/2, width, height);
            targetCtx.restore();
            // A small sweep highlight inside the card, no new panel or controls.
            if (progress > 0) {
                targetCtx.save();
                targetCtx.strokeStyle = 'rgba(255,255,255,0.85)';
                targetCtx.lineWidth = Math.max(1, width / 450);
                targetCtx.beginPath();
                targetCtx.moveTo(edge, -height/2);
                targetCtx.lineTo(edge, height/2);
                targetCtx.stroke();
                targetCtx.restore();
            }
            if (enhancementWipeFrame == null) {
                enhancementWipeFrame = requestAnimationFrame(() => {
                    enhancementWipeFrame = null;
                    renderSheetNow();
                });
            }
        }

        let activeGpuExposure = null;
        let availableGpuExposure = null;
        function validatedDocumentIllumination(value) {
            if (!value || value.coordinate_space !== 'detected_document_quad' || value.width !== 32 || value.height !== 32) return null;
            if (!Array.isArray(value.gains) || value.gains.length !== 1024 ||
                !value.gains.every(v => Number.isFinite(v) && v >= 1 && v <= 2.8)) return null;
            if (!Array.isArray(value.source_quad) || value.source_quad.length !== 4 ||
                !value.source_quad.every(p => p && Number.isFinite(p.x) && Number.isFinite(p.y) && p.x >= 0 && p.x <= 1 && p.y >= 0 && p.y <= 1)) return null;
            let area = 0;
            value.source_quad.forEach((p, i) => { const q = value.source_quad[(i + 1) % 4]; area += p.x * q.y - q.x * p.y; });
            if (Math.abs(area) < 0.0001) return null;
            const validMask = (mask) => Array.isArray(mask) && mask.length === 1024
                && mask.every(v => Number.isFinite(v) && v >= 0 && v <= 1);
            const rawSegmentation = value.segmentation && typeof value.segmentation === 'object' ? value.segmentation : null;
            const segmentation = rawSegmentation
                && validMask(rawSegmentation.detail_mask)
                && validMask(rawSegmentation.photo_mask)
                && validMask(rawSegmentation.highlight_mask)
                ? {
                    width: 32,
                    height: 32,
                    detail_mask: rawSegmentation.detail_mask.slice(),
                    photo_mask: rawSegmentation.photo_mask.slice(),
                    highlight_mask: rawSegmentation.highlight_mask.slice(),
                    method: String(rawSegmentation.method || '').slice(0, 80)
                } : null;
            const rawProfile = value.pixel_profile && typeof value.pixel_profile === 'object' ? value.pixel_profile : {};
            const bounded = (input, fallback, max = 1) => Number.isFinite(Number(input))
                ? Math.max(0, Math.min(max, Number(input))) : fallback;
            return {
                width: 32,
                height: 32,
                gains: value.gains.slice(),
                source_quad: value.source_quad.map(p => ({ x: p.x, y: p.y })),
                coordinate_space: value.coordinate_space,
                segmentation,
                pixel_profile: {
                    level: ['soft', 'balanced', 'strong', 'adaptive'].includes(rawProfile.level) ? rawProfile.level : 'adaptive',
                    resolved_level: ['soft', 'balanced', 'strong'].includes(rawProfile.resolved_level) ? rawProfile.resolved_level : 'balanced',
                    text_protection: bounded(rawProfile.text_protection, 0.66),
                    photo_protection: bounded(rawProfile.photo_protection, 0.40),
                    highlight_protection: bounded(rawProfile.highlight_protection, 0.74),
                    detail_strength: bounded(rawProfile.detail_strength, 0.20, 0.40),
                    per_pixel_ink_protection: rawProfile.per_pixel_ink_protection === true,
                    per_pixel_colour_protection: rawProfile.per_pixel_colour_protection === true,
                    bounded_detail: rawProfile.bounded_detail === true
                }
            };
        }
        function applyGpuAutoBrightness(ai) {
            const recommendation = ai?.auto_brightness;
            if (!recommendation || recommendation.applied !== true) return null;
            const requested = Number(recommendation.slider_value);
            if (!Number.isFinite(requested)) return null;
            const illumination = ['document_illumination_ai_v1', 'document_illumination_segmented_ai_v2'].includes(recommendation.method)
                ? validatedDocumentIllumination(recommendation.illumination) : null;
            const hasCurve = recommendation.method === 'document_shadow_curve_v2'
                || recommendation.method === 'document_illumination_ai_v1'
                || recommendation.method === 'document_illumination_segmented_ai_v2';
            const brightness = hasCurve
                ? 0 : Math.max(0, Math.min(20, Math.round(requested)));
            activeGpuExposure = hasCurve
                ? { strength: illumination ? 0 : Math.max(0, Math.min(0.55, Number(recommendation.tone_strength) || 0)), illumination } : null;
            availableGpuExposure = activeGpuExposure;
            if (activeGpuExposure) {
                setEnhanceValue('inpContrast', 0);
                setEnhanceValue('inpSaturation', 0);
                setEnhanceValue('inpClarity', 0);
                setEnhanceValue('inpSharp', 0);
                setEnhanceValue('inpWarmth', 0);
            }
            setEnhanceValue('inpBright', brightness);
            updateFilters();
            return brightness;
        }

        function restoreDocumentEnhancement(descriptor) {
            if (!descriptor?.enhanceSettings) return;
            const saved = descriptor.enhanceSettings;
            const illumination = validatedDocumentIllumination(descriptor.gpuExposure?.illumination);
            availableGpuExposure = descriptor.gpuExposure
                ? { illumination, strength: illumination ? 0 : Math.max(0, Math.min(.55, Number(descriptor.gpuExposure.strength) || 0)) }
                : null;
            setMode(['magic', 'bw', 'color'].includes(descriptor.enhanceMode) ? descriptor.enhanceMode : 'magic', false);
            for (const [key, id] of [['brightness','inpBright'],['contrast','inpContrast'],['saturation','inpSaturation'],['warmth','inpWarmth'],['sharpness','inpSharp'],['clarity','inpClarity']]) {
                if (Number.isFinite(Number(saved[key]))) setEnhanceValue(id, Number(saved[key]));
            }
            updateFilters();
        }

        function recordDocAlignerDirectFallback(reason, details = {}) {
            recordAiActivity('docaligner_direct_fallback', {
                reason: String(reason || 'unknown').slice(0, 80),
                ...details
            });
        }

        async function waitForCropProcessorIdle(maxWaitMs = 6000) {
            const deadline = performance.now() + Math.max(0, Number(maxWaitMs) || 0);
            while (cropProcessBusy && performance.now() < deadline) {
                await new Promise((resolve) => setTimeout(resolve, 40));
            }
            return !cropProcessBusy;
        }

        async function tryApplyDocAlignerDirectResult(ai, originalDataUrl, editorReady = false) {
            const quad = getDocAlignerResultQuad(ai);
            const confidence = Number(ai?.classification?.confidence || ai?.straighten?.confidence || ai?.document?.confidence || 0);
            if (!ai?.success) {
                recordDocAlignerDirectFallback('api_unsuccessful');
                return false;
            }
            if (!['docaligner', 'browser_opencv'].includes(String(ai?.model_variant || ''))) {
                recordDocAlignerDirectFallback('wrong_model_variant', { model_variant: String(ai?.model_variant || '').slice(0, 60) });
                return false;
            }
            if (!quad) {
                recordDocAlignerDirectFallback('invalid_quad');
                return false;
            }
            // GPU endpoint already owns the acceptance threshold. When it says
            // success and returns a valid quad, the browser must not reject the
            // same crop through a second, different confidence gate.
            const acceptedConfidence = Number.isFinite(confidence) ? confidence : 0;

            let queuedBackFile = null;
            try {
                directCropPreparation = true;
                if (!editorReady) await loadDataUrlToEditorWithFallback(originalDataUrl, { deferCropper: true });
                const preCrop = getDocAlignerPreCropOrientation(ai);
                if (preCrop && normalizeRightAngle(rotationAngle) !== preCrop.rotation) {
                    rotationAngle = preCrop.rotation;
                    refreshEditor(true);
                }
                const autoBrightness = applyGpuAutoBrightness(ai);
                const points = aiQuadToDisplayPoints(quad);
                if (!points) {
                    recordDocAlignerDirectFallback('quad_mapping_failed', { confidence: acceptedConfidence });
                    return false;
                }
                cropperPoints = points;
                const outputRotation = getDocAlignerOutputRotation(ai);
                // Album has separate front/back uploads. Use the side-aware
                // commit flow below, not PVC's always-new-front shortcut.
                if (currentType === 'pvc' && !isDocumentAlbumLaunch) {
                    currentPvcSourceDataUrl = originalDataUrl;
                    const applied = await applyPvcSingleAutoCrop(points, {
                        fast: true,
                        sourceDataUrl: originalDataUrl,
                        approvalReason: 'docaligner_direct_auto_crop',
                        outputRotationDegrees: outputRotation,
                        docAlignerAutoCrop: true
                    });
                    if (applied) {
                        recordAiActivity('docaligner_direct_preview_added', {
                            confidence: acceptedConfidence,
                            rotation_degrees: outputRotation,
                            source_rotation_degrees: preCrop?.rotation || 0,
                            auto_brightness: autoBrightness,
                            selected_family: 'pvc'
                        });
                    } else {
                        recordDocAlignerDirectFallback('pvc_preview_commit_failed', { confidence });
                    }
                    return !!applied;
                }

                // A previous crop may still be committing when the next GPU reply
                // arrives (most commonly the back side immediately after front).
                // This wait runs only after a valid GPU success, so an offline or
                // failed GPU still reaches the manual cropper without this delay.
                if (!await waitForCropProcessorIdle()) {
                    recordDocAlignerDirectFallback('crop_processor_busy', { confidence: acceptedConfidence });
                    return false;
                }

                if (currentType === 'pvc') currentPvcSourceDataUrl = originalDataUrl;
                else currentDocumentSourceDataUrl = originalDataUrl;
                queuedBackFile = currentSide === 'front' ? pendingBackFile : null;
                if (queuedBackFile) {
                    pendingBackFile = null;
                    isSingleSide = false;
                }
                if (currentSide === 'front' && !queuedBackFile && currentType !== 'a4') isSingleSide = true;
                const saveSide = currentSide;
                const attachTargetBefore = saveSide === 'back' && pendingAttachBackIndex >= 0
                    ? batchQueue[pendingAttachBackIndex]
                    : null;
                const attachTargetId = attachTargetBefore ? ensureBatchQueueItemId(attachTargetBefore) : '';
                // Queue length is not a reliable success signal: when a page is
                // full, addToSheet auto-saves it and starts a fresh queue. Track
                // item IDs so the newly committed DocAligner crop is still seen.
                const queueItemIdsBefore = new Set(batchQueue.map((item) => ensureBatchQueueItemId(item)));
                const directCommitVersionBefore = docAlignerDirectCommitVersion;
                pendingDocAlignerPostCropRotation = outputRotation;
                docAlignerDirectApplyActive = true;
                await applyCropAndEnhance(true);
                const attachedTarget = attachTargetId
                    ? batchQueue.find((item) => item?.queueItemId === attachTargetId)
                    : null;
                const backAttached = !!(attachedTarget && isMatUsable(attachedTarget.back));
                const committedItem = batchQueue.find((item) => {
                    if (!item?.docAlignerAutoCrop) return false;
                    const itemId = ensureBatchQueueItemId(item);
                    return !!itemId && !queueItemIdsBefore.has(itemId);
                });
                const applied = docAlignerDirectCommitVersion > directCommitVersionBefore
                    || !!committedItem
                    || backAttached
                    || isMatUsable(tempDocs[saveSide]);
                if (!applied) {
                    if (queuedBackFile) pendingBackFile = queuedBackFile;
                    recordDocAlignerDirectFallback('preview_commit_not_observed', {
                        confidence: acceptedConfidence,
                        crop_side: saveSide,
                        queue_before: queueItemIdsBefore.size,
                        queue_after: batchQueue.length
                    });
                    return false;
                }
                recordAiActivity('docaligner_direct_preview_added', {
                    confidence: acceptedConfidence,
                    rotation_degrees: outputRotation,
                    source_rotation_degrees: preCrop?.rotation || 0,
                    auto_brightness: autoBrightness,
                    selected_family: currentType,
                    crop_side: saveSide
                });
                if (queuedBackFile) {
                    // Let handleFileProcess start the second file after this
                    // complete foreground run has unwound its shared flags.
                    // Recursing here let the second warp overlap the first
                    // run's direct-apply state and could leave its loader stuck.
                    pendingBackFile = queuedBackFile;
                }
                return true;
            } catch (error) {
                if (queuedBackFile) pendingBackFile = queuedBackFile;
                console.warn('DocAligner direct preview apply failed', error);
                recordDocAlignerDirectFallback('preview_apply_exception', {
                    error_type: String(error?.name || 'apply_error').slice(0, 60)
                });
                return false;
            } finally {
                pendingDocAlignerPostCropRotation = 0;
                docAlignerDirectApplyActive = false;
                directCropPreparation = false;
            }
        }

        function detectBrowserAutoCropQuad(sourceMat) {
            if (!isMatUsable(sourceMat)) return null;
            let work = sourceMat;
            let ownsWork = false;
            let gray = null, blur = null, edges = null, contours = null, hierarchy = null;
            try {
                const maximumSide = 1400;
                const scale = Math.min(1, maximumSide / Math.max(sourceMat.cols, sourceMat.rows));
                if (scale < 1) {
                    work = new cv.Mat();
                    ownsWork = true;
                    cv.resize(sourceMat, work, new cv.Size(
                        Math.max(2, Math.round(sourceMat.cols * scale)),
                        Math.max(2, Math.round(sourceMat.rows * scale))
                    ), 0, 0, cv.INTER_AREA);
                }
                gray = new cv.Mat();
                blur = new cv.Mat();
                edges = new cv.Mat();
                contours = new cv.MatVector();
                hierarchy = new cv.Mat();
                const channels = typeof work.channels === 'function' ? work.channels() : 4;
                if (channels === 4) cv.cvtColor(work, gray, cv.COLOR_RGBA2GRAY);
                else if (channels === 3) cv.cvtColor(work, gray, cv.COLOR_RGB2GRAY);
                else work.copyTo(gray);
                cv.GaussianBlur(gray, blur, new cv.Size(5, 5), 0);
                cv.Canny(blur, edges, 45, 150);
                cv.findContours(edges, contours, hierarchy, cv.RETR_LIST, cv.CHAIN_APPROX_SIMPLE);

                const targetAspect = currentType === 'a4' ? Math.SQRT2 : DOC_TYPES.pvc.aspect;
                const minimumAreaRatio = currentType === 'a4' ? 0.18 : 0.12;
                let best = null;
                let bestScore = -Infinity;
                for (let i = 0; i < contours.size(); i++) {
                    const contour = contours.get(i);
                    try {
                        const area = Math.abs(cv.contourArea(contour));
                        const areaRatio = area / Math.max(1, work.cols * work.rows);
                        if (areaRatio < minimumAreaRatio || areaRatio > 0.999) continue;
                        const perimeter = cv.arcLength(contour, true);
                        for (const epsilon of [0.015, 0.02, 0.025, 0.03]) {
                            const approx = new cv.Mat();
                            try {
                                cv.approxPolyDP(contour, approx, epsilon * perimeter, true);
                                if (approx.rows !== 4) continue;
                                const points = [];
                                for (let pointIndex = 0; pointIndex < 4; pointIndex++) {
                                    points.push({
                                        x: approx.data32S[pointIndex * 2],
                                        y: approx.data32S[(pointIndex * 2) + 1]
                                    });
                                }
                                const ordered = orderQuadPoints(points);
                                const top = dist2D(ordered[0], ordered[1]);
                                const right = dist2D(ordered[1], ordered[2]);
                                const bottom = dist2D(ordered[2], ordered[3]);
                                const left = dist2D(ordered[3], ordered[0]);
                                const longSide = Math.max((top + bottom) / 2, (left + right) / 2);
                                const shortSide = Math.min((top + bottom) / 2, (left + right) / 2);
                                const aspect = longSide / Math.max(1, shortSide);
                                const acceptable = currentType === 'a4'
                                    ? aspect >= 1.16 && aspect <= 1.78
                                    : (currentType === 'custom' ? aspect >= 1.05 && aspect <= 2.35 : aspect >= 1.18 && aspect <= 2.12);
                                if (!acceptable) continue;
                                const oppositeBalance = Math.min(top, bottom) / Math.max(1, Math.max(top, bottom))
                                    + Math.min(left, right) / Math.max(1, Math.max(left, right));
                                if (oppositeBalance < 0.9) continue;
                                const score = (areaRatio * 3) + oppositeBalance
                                    - (Math.abs(Math.log(aspect / targetAspect)) * 0.9);
                                if (score > bestScore) {
                                    bestScore = score;
                                    best = { points: ordered, areaRatio };
                                }
                            } finally { approx.delete(); }
                        }
                    } finally { contour.delete(); }
                }

                if (best) {
                    return {
                        points: best.points.map((point) => ({ x: point.x / scale, y: point.y / scale })),
                        confidence: Math.max(0.62, Math.min(0.91, 0.58 + best.areaRatio * 0.35)),
                        source: 'browser_edges'
                    };
                }

                // Scans and already-cropped camera images often have no outer
                // background edge. Only accept the whole frame when its aspect
                // is already close to the selected paper/card family.
                const frameAspect = Math.max(sourceMat.cols, sourceMat.rows) / Math.max(1, Math.min(sourceMat.cols, sourceMat.rows));
                if (Math.abs(Math.log(frameAspect / targetAspect)) <= 0.10) {
                    const insetX = Math.max(1, sourceMat.cols * 0.002);
                    const insetY = Math.max(1, sourceMat.rows * 0.002);
                    return {
                        points: rectToPoints({
                            x: insetX, y: insetY,
                            w: sourceMat.cols - (insetX * 2), h: sourceMat.rows - (insetY * 2)
                        }),
                        confidence: 0.74,
                        source: 'browser_full_frame'
                    };
                }
                return null;
            } catch (error) {
                console.warn('Browser auto crop fallback skipped', error);
                return null;
            } finally {
                safeDeleteMat(gray);
                safeDeleteMat(blur);
                safeDeleteMat(edges);
                safeDeleteMat(contours);
                safeDeleteMat(hierarchy);
                if (ownsWork) safeDeleteMat(work);
            }
        }

        async function tryApplyBrowserAutoCropFallback(originalDataUrl, editorReady = false) {
            if (!editorReady || !isMatUsable(displayMat)) return false;
            const detected = detectBrowserAutoCropQuad(displayMat);
            const quad = detected ? normalizeQuadAgainstMat(detected.points, displayMat) : null;
            if (!quad) {
                recordDocAlignerDirectFallback('browser_fallback_no_safe_quad');
                return false;
            }
            const ai = {
                success: true,
                model_variant: 'browser_opencv',
                classification: {
                    mode: currentType === 'a4' ? 'a4_document' : 'single_side_card',
                    confidence: detected.confidence
                },
                straighten: { quad, confidence: detected.confidence },
                orientation: { method: 'disabled' }
            };
            recordAiActivity('browser_auto_crop_fallback', {
                detector: detected.source,
                confidence: detected.confidence,
                selected_family: currentType
            });
            const applied = await tryApplyDocAlignerDirectResult(ai, originalDataUrl, true);
            if (applied) {
                const statusNode = document.getElementById('mobStatus');
                if (statusNode) statusNode.innerText = 'GPU offline tha; browser ne photo ko automatically crop kiya.';
            }
            return applied;
        }

        function switchCurrentTypeForActiveCrop(type) {
            currentType = type;
            document.querySelectorAll('.doc-btn').forEach(b => b.classList.remove('active'));
            document.getElementById('btn-' + type)?.classList.add('active');
            document.querySelectorAll('.seg-btn').forEach(b => b.classList.remove('active'));
            document.getElementById('mob-type-' + type)?.classList.add('active');
            syncUploadSideControls();
            updateUploadLabels();
            updateFileInputAccept();
        }

        function applyPvcA4DocumentAiCrop(ai) {
            const mode = String(ai?.classification?.mode || '');
            if (mode !== 'a4_document') return false;
            if (protectKnownVisualCardFromA4('ai_a4_guard_aadhaar_visual')) {
                document.getElementById('mobStatus').innerText = 'Aadhaar visual detect hua. A4 nahi, PVC card crop check karein.';
                return false;
            }
            currentDocumentSourceDataUrl = currentPvcSourceDataUrl || currentDocumentSourceDataUrl;
            currentPvcSourceDataUrl = '';
            pendingPvcPdfDualFlow = false;
            pvcTemplateNeedsManualReview = false;
            pvcSingleSideAiMode = false;
            switchCurrentTypeForActiveCrop('a4');
            const ok = applyDocumentAiCropperPoints(ai, 'A4 AI');
            if (ok) {
                document.getElementById('mobStatus').innerText = 'PVC upload me A4 document detect hua. 4 dots check karke Done dabayein.';
                showPvcA4CorrectionControls('a4_document');
                queueBackgroundLearning(() => queuePvcA4AutoDetectApprovalSample('pvc_ai_detected_a4_document', ai, currentDocumentSourceDataUrl), 'PVC A4 approval sample');
            }
            return ok;
        }

        function normalizeQuadAgainstMat(points, refMat = displayMat) {
            if (!Array.isArray(points) || points.length !== 4 || !isMatUsable(refMat)) return null;
            const w = refMat.cols;
            const h = refMat.rows;
            return orderQuadPoints(points).map((p) => ({
                x: +(Math.max(0, Math.min(1, p.x / w))).toFixed(6),
                y: +(Math.max(0, Math.min(1, p.y / h))).toFixed(6)
            }));
        }

        function normalizeCropperQuad(points) {
            return normalizeQuadAgainstMat(points, displayMat);
        }

        function mapNormalizedPointToSourceOrientation(point, rotationDegrees = 0) {
            const x = Math.max(0, Math.min(1, Number(point?.x) || 0));
            const y = Math.max(0, Math.min(1, Number(point?.y) || 0));
            const rotation = normalizeRightAngle(rotationDegrees);
            if (rotation === 90) return { x: y, y: 1 - x };
            if (rotation === -90 || rotation === 270) return { x: 1 - y, y: x };
            if (Math.abs(rotation) === 180) return { x: 1 - x, y: 1 - y };
            return { x, y };
        }

        function mapNormalizedQuadToSourceOrientation(quad, rotationDegrees = 0) {
            if (!Array.isArray(quad) || quad.length !== 4) return null;
            const mapped = quad.map((point) => mapNormalizedPointToSourceOrientation(point, rotationDegrees));
            return orderQuadPoints(mapped).map((point) => ({
                x: +Number(point.x || 0).toFixed(6),
                y: +Number(point.y || 0).toFixed(6)
            }));
        }

        function mapNormalizedRectToSourceOrientation(rect, rotationDegrees = 0) {
            if (!rect || !Number.isFinite(Number(rect.x)) || !Number.isFinite(Number(rect.y)) || !Number.isFinite(Number(rect.w)) || !Number.isFinite(Number(rect.h))) return null;
            const corners = [
                { x: Number(rect.x), y: Number(rect.y) },
                { x: Number(rect.x) + Number(rect.w), y: Number(rect.y) },
                { x: Number(rect.x) + Number(rect.w), y: Number(rect.y) + Number(rect.h) },
                { x: Number(rect.x), y: Number(rect.y) + Number(rect.h) }
            ].map((point) => mapNormalizedPointToSourceOrientation(point, rotationDegrees));
            const left = Math.min(...corners.map((point) => point.x));
            const top = Math.min(...corners.map((point) => point.y));
            const right = Math.max(...corners.map((point) => point.x));
            const bottom = Math.max(...corners.map((point) => point.y));
            return {
                x: +left.toFixed(6),
                y: +top.toFixed(6),
                w: +(right - left).toFixed(6),
                h: +(bottom - top).toFixed(6)
            };
        }

        function mapPvcTemplateToSourceOrientation(template, rotationDegrees = 0) {
            if (!template || normalizeRightAngle(rotationDegrees) === 0) return template ? { ...template } : template;
            return {
                ...template,
                ...(template.front ? { front: mapNormalizedRectToSourceOrientation(template.front, rotationDegrees) } : {}),
                ...(template.back ? { back: mapNormalizedRectToSourceOrientation(template.back, rotationDegrees) } : {}),
                ...(template.quad ? { quad: mapNormalizedQuadToSourceOrientation(template.quad, rotationDegrees) } : {}),
                ...(template.front_quad ? { front_quad: mapNormalizedQuadToSourceOrientation(template.front_quad, rotationDegrees) } : {}),
                ...(template.back_quad ? { back_quad: mapNormalizedQuadToSourceOrientation(template.back_quad, rotationDegrees) } : {})
            };
        }

        function getDocumentAiAutoLabels() {
            const quad = shadowDocumentAiAnalysis?.straighten?.quad || shadowDocumentAiAnalysis?.document?.quad || null;
            if (!Array.isArray(quad) || quad.length !== 4) return {};
            return {
                quad: quad.map(normalizeAiPoint).map((p) => ({ x: +Number(p.x || 0).toFixed(6), y: +Number(p.y || 0).toFixed(6) })),
                engine: shadowDocumentAiAnalysis?.engine || 'ak_cv_layout_v2',
                confidence: shadowDocumentAiAnalysis?.classification?.confidence || shadowDocumentAiAnalysis?.straighten?.confidence || 0,
                mode: shadowDocumentAiAnalysis?.classification?.mode || ''
            };
        }

        function quadDiffScore(a, b) {
            if (!Array.isArray(a) || !Array.isArray(b) || a.length !== 4 || b.length !== 4) return 1;
            let total = 0;
            for (let i = 0; i < 4; i++) {
                total += Math.hypot((Number(a[i].x) || 0) - (Number(b[i].x) || 0), (Number(a[i].y) || 0) - (Number(b[i].y) || 0));
            }
            return total / 4;
        }

        function queueBackgroundLearning(promiseFactory, label = 'AI learning') {
            const run = () => {
                try {
                    backgroundLearningQueue = backgroundLearningQueue
                        .catch(() => false)
                        .then(promiseFactory)
                        .catch((err) => {
                            console.warn(`${label} failed`, err);
                            return false;
                        });
                } catch (err) {
                    console.warn(`${label} failed`, err);
                }
            };
            // Learning is intentionally outside the visible crop/render path.
            // Let the result paint first, then use browser idle time; failures stay
            // silent and never change the user's crop result.
            if (typeof window.requestIdleCallback === 'function') {
                window.requestIdleCallback(run, { timeout: 1800 });
            } else {
                setTimeout(run, 120);
            }
        }

        async function saveDocumentCropLearningSample(correctedPoints, side = 'front', sourceDataUrl = currentDocumentSourceDataUrl, options = {}) {
            try {
                const selectedFamily = options.selectedFamily || currentType || '';
                const selectedDocType = options.selectedDocType || getAiActivityDocType();
                if (selectedFamily === 'pvc' || !sourceDataUrl) return false;
                const rotationDegrees = normalizeRightAngle(Number(options.rotationDegrees || 0));
                const displayQuad = Array.isArray(options.normalizedQuad) && options.normalizedQuad.length === 4
                    ? options.normalizedQuad
                    : normalizeCropperQuad(correctedPoints);
                const labels = { quad: mapNormalizedQuadToSourceOrientation(displayQuad, rotationDegrees) };
                if (!labels.quad) return false;
                const autoLabels = options.autoLabels && typeof options.autoLabels === 'object'
                    ? options.autoLabels
                    : getDocumentAiAutoLabels();
                const hasUserCorrection = !!autoLabels.quad && quadDiffScore(labels.quad, autoLabels.quad) > 0.012;
                const ctx = options.context && typeof options.context === 'object'
                    ? options.context
                    : (documentLearningContext || {});
                // Keep GPU learning for the Auto Crop flow: both an accepted
                // result and a user-corrected result are useful supervision.
                // Pure Manual Crop has no AI proposal, so do not upload it as
                // Auto Crop training data or create an unrelated hosting POST.
                if (!autoLabels.quad) return false;
                const resolvedDocType = ctx.docType || (selectedFamily === 'a4' ? 'a4_document' : 'id_card');
                const resolvedContentKind = ctx.contentKind || (selectedFamily === 'a4' ? 'a4_document' : 'id_card');
                const sourceKind = ctx.sourceKind || (remoteCropIndex >= 0 ? 'remote_customer_crop' : 'browser_crop');
                const rawTargetDataUrl = options.rectifiedTargetDataUrl || '';
                const assets = await prepareLearningAssetSet(sourceDataUrl, rawTargetDataUrl ? { rectified: rawTargetDataUrl } : {});
                const preview = assets.sourcePreview;
                const rectifiedTarget = assets.targets.rectified || '';
                const qualityProfile = await computeLearningQualityProfile(preview, labels.quad);
                const sourceCapture = normalizeLearningCaptureMeta({
                    ...(options.captureMeta || ctx.captureMeta || currentLearningCaptureMeta || {}),
                    side,
                    originalWidth: qualityProfile.source_width_px || 0,
                    originalHeight: qualityProfile.source_height_px || 0
                });
                const learningWorkflow = inferCardLearningWorkflow(selectedFamily, sourceKind, sourceCapture);
                const targetProfile = await getLearningTargetProfile(rectifiedTarget, learningWorkflow === 'document_page_crop' ? 'rectified_document' : 'rectified_card');
                const autoCornerDelta = autoLabels.quad ? quadDiffScore(labels.quad, autoLabels.quad) : null;
                const trainingProfile = {
                    workflow: learningWorkflow,
                    supervision_strength: hasUserCorrection || ctx.forceCorrection ? 'strong_user_corrected_quad' : 'user_confirmed_quad',
                    user_action: hasUserCorrection || ctx.forceCorrection ? 'corrected' : 'accepted',
                    auto_corner_delta: autoCornerDelta === null ? null : +autoCornerDelta.toFixed(6),
                    paired_rectified_target: !!rectifiedTarget,
                    eligible_for: 'card_detection,quad_regression,perspective_dewarp,content_preservation',
                    not_eligible_for: 'pixel_exact_mask,alpha_matting,missing_content_reconstruction',
                    manual_mask_priority: qualityProfile.difficulty_tier || 'unknown',
                    boundary_label_policy: 'printed_card_edge_excludes_background_and_lamination_overhang'
                };
                const res = await postToolAction('save_document_crop_learning_ai', {
                    source_preview_data_url: preview,
                    rectified_target_data_url: rectifiedTarget,
                    learning_workflow: learningWorkflow,
                    doc_type: resolvedDocType,
                    doc_label: ctx.docLabel || (selectedFamily === 'a4' ? 'A4 Document' : 'ID Card'),
                    source_kind: sourceKind,
                    content_kind: resolvedContentKind,
                    crop_side: side,
                    page_count: Number(ctx.pageCount || lastPdfMeta?.page_count || 1),
                    page_size_key: ctx.pageSizeKey || lastPdfMeta?.page_size_key || '',
                    render_size_key: ctx.renderSizeKey || lastPdfMeta?.render_size_key || '',
                    rotation_degrees: rotationDegrees,
                    coordinate_space: 'source_preview_normalized',
                    user_selected_family: selectedFamily,
                    user_selected_doc_type: selectedDocType,
                    auto_labels_json: JSON.stringify(autoLabels),
                    labels_json: JSON.stringify(labels),
                    has_user_correction: (hasUserCorrection || !!ctx.forceCorrection) ? '1' : '0',
                    user_confirmed: '1',
                    ai_suggestion_available: autoLabels.quad ? '1' : '0',
                    capture_reason: ctx.captureReason || (remoteCropIndex >= 0 ? 'remote_customer_crop_done' : 'document_crop_done'),
                    source_capture_json: JSON.stringify(sourceCapture),
                    quality_profile_json: JSON.stringify(qualityProfile),
                    target_profile_json: JSON.stringify(targetProfile),
                    training_profile_json: JSON.stringify(trainingProfile)
                });
                recordAiActivity('training_sample_saved', {
                    training_task: learningWorkflow === 'mobile_card_restore' ? 'mobile_card_photo_restore' : 'document_single_crop_straighten',
                    saved: res?.status === 'success',
                    has_user_correction: hasUserCorrection || !!ctx.forceCorrection,
                    ai_suggestion_available: !!autoLabels.quad,
                    paired_target: !!rectifiedTarget,
                    difficulty_tier: qualityProfile.difficulty_tier || 'unknown'
                });
                return res?.status === 'success';
            } catch (err) {
                console.warn('Document crop learning save failed', err);
                recordAiActivity('training_sample_save_failed', { training_task: 'document_single_crop_straighten' });
                return false;
            }
        }

        function getSelectedPvcConversionIndex() {
            if (selectedItem.index >= 0 && batchQueue[selectedItem.index]?.type === 'pvc') return selectedItem.index;
            return getLastPvcQueueIndex();
        }

        function getPvcItemMode(item) {
            if (!item) return 'unknown';
            if (item.singleSide || !item.back) return 'single_side_card';
            return 'double_side_card';
        }

        async function savePvcModeCorrectionSample(item, toMode, captureReason = 'pvc_mode_corrected') {
            try {
                if (!item?.sourceDataUrl) return false;
                const cropSide = item.learningCropSide === 'back' ? 'back' : 'front';
                const learningMeta = getPvcItemSideLearningMeta(item, cropSide) || {};
                const captureMeta = getPvcItemSideCaptureMeta(item, cropSide) || normalizeLearningCaptureMeta({ side: cropSide });
                const preview = await makeAiPreviewDataUrl(item.sourceDataUrl, 760, 0.72);
                const fromMode = getPvcItemMode(item);
                const labels = {
                    mode: toMode,
                    single_side: toMode === 'single_side_card',
                    a4_document: toMode === 'a4_document'
                };
                const res = await postToolAction('save_pvc_mode_correction_ai', {
                    source_preview_data_url: preview,
                    doc_type: item.pvcDocType || pvcAutoCropDocType || 'custom_card',
                    doc_label: getPvcDocTypeLabel(item.pvcDocType || pvcAutoCropDocType || 'custom_card'),
                    source_kind: 'browser_pvc_conversion',
                    content_kind: toMode === 'a4_document' ? 'a4_document' : 'pvc_card',
                    learning_workflow: inferCardLearningWorkflow('pvc', learningMeta.source_kind || 'browser_pvc_conversion', captureMeta),
                    user_selected_doc_type: item.pvcDocType || pvcAutoCropDocType || 'custom_card',
                    crop_side: cropSide,
                    page_count: Number(learningMeta.page_count || 1),
                    page_size_key: learningMeta.page_size_key || '',
                    source_capture_json: JSON.stringify(captureMeta),
                    from_mode: fromMode,
                    to_mode: toMode,
                    auto_labels_json: JSON.stringify({ mode: fromMode }),
                    labels_json: JSON.stringify(labels),
                    capture_reason: captureReason
                });
                return res?.status === 'success';
            } catch (err) {
                console.warn('PVC mode correction learning save failed', err);
                return false;
            }
        }

        async function convertSelectedPvcToA4() {
            if (!requirePvcProAction("PVC to A4 Correction")) return;
            const active = getActivePvcToolItem();
            const idx = active.index;
            const item = active.item;
            const sourceDataUrl = item?.sourceDataUrl || getActivePvcToolSourceDataUrl();
            if ((!item || item.type !== 'pvc') && currentType !== 'pvc') {
                showModal("PVC Required", "A4 me convert karne ke liye pehle PVC item select karein ya PVC upload open rakhein.", "warn");
                return;
            }
            if (!sourceDataUrl) {
                showModal("Source Missing", "Is item ka original source available nahi hai. Re-upload karke A4 select karein.", "warn");
                return;
            }
            try {
                showProcessLoader({
                    title: 'A4 correction open ho raha hai',
                    message: 'Source ko A4 cropper me reload kar rahe hain.',
                    chip: 'AI',
                    subtext: 'Done dabane par ye correction AI learning me save hogi.'
                });
                queueBackgroundLearning(() => savePvcModeCorrectionSample({
                    ...(item || {}),
                    type: 'pvc',
                    sourceDataUrl,
                    pvcDocType: item?.pvcDocType || pvcAutoCropDocType,
                    learningCropSide: selectedItem.index === idx && selectedItem.side === 'back' ? 'back' : 'front'
                }, 'a4_document', 'user_converted_pvc_to_a4'), 'PVC to A4 learning');
                pendingA4ReplaceIndex = idx >= 0 ? idx : -1;
                documentLearningContext = {
                    docType: 'a4_document',
                    docLabel: 'A4 Document',
                    sourceKind: 'pvc_to_a4_user_correction',
                    contentKind: 'a4_document',
                    captureReason: 'pvc_to_a4_crop_done',
                    forceCorrection: true
                };
                currentDocumentSourceDataUrl = sourceDataUrl;
                pendingDocumentAiAnalysis = null;
                pendingPvcAiAnalysis = null;
                shadowDocumentAiAnalysis = null;
                shadowPvcAiAnalysis = null;
                pvcSingleSideAiMode = false;
                switchCurrentTypeForActiveCrop('a4');
                const loadedDataUrl = await loadDataUrlToEditorWithFallback(sourceDataUrl);
                currentDocumentSourceDataUrl = loadedDataUrl;
                document.getElementById('mobStatus').innerText = 'A4 correction: 4 dots check karke Done dabayein.';
                recordAiActivity('pvc_converted_to_a4', { source: 'user_correction' });
                scheduleCropAiAnalysis('analyze_document_crop_ai', loadedDataUrl, null, {
                    docType: 'a4_document',
                    fileName: 'pvc-to-a4-correction',
                    sourceKind: 'pvc_to_a4_user_correction'
                });
            } catch (err) {
                console.warn(err);
                pendingA4ReplaceIndex = -1;
                documentLearningContext = null;
                showModal("A4 Convert Failed", "Source A4 cropper me open nahi ho paya. Re-upload karke try karein.", "error");
            } finally {
                hideProcessLoader();
            }
        }

        async function convertSelectedPvcToSingleSide() {
            if (!requirePvcProAction("PVC Side Mode")) return;
            const idx = getSelectedPvcConversionIndex();
            const item = idx >= 0 ? batchQueue[idx] : null;
            if (!item || item.type !== 'pvc') {
                showModal("PVC Required", "Single/Double badalne ke liye pehle PVC item select karein.", "warn");
                return;
            }
            if (currentType !== 'pvc') switchCurrentTypeForActiveCrop('pvc');
            const hasLearningSource = !!item?.sourceDataUrl;
            const learningItem = {
                ...item,
                learningCropSide: selectedItem.index === idx && selectedItem.side === 'back' ? 'back' : 'front'
            };
            const restoreDouble = !!item.singleSide;
            if (restoreDouble) {
                if (!isMatUsable(item.pvcStoredBack)) {
                    showModal("Back Side Missing", "Double-side wapas lane ke liye saved back side available nahi hai. Source ko Re-Crop karein.", "warn");
                    return;
                }
                queueBackgroundLearning(() => savePvcModeCorrectionSample(learningItem, 'double_side_card', 'user_restored_pvc_double_side'), 'PVC double-side learning');
                item.back = item.pvcStoredBack;
                item.pvcStoredBack = null;
                item.singleSide = false;
            } else {
                if (!isMatUsable(item.back)) {
                    showModal("Back Side Missing", "Ye card pehle se single-side hai ya back side available nahi hai.", "warn");
                    return;
                }
                queueBackgroundLearning(() => savePvcModeCorrectionSample(learningItem, 'single_side_card', 'user_converted_pvc_to_single_side'), 'PVC single-side learning');
                safeDeleteMat(item.pvcStoredBack);
                item.pvcStoredBack = item.back;
                item.back = null;
                item.singleSide = true;
            }
            recordAiActivity('pvc_side_mode_changed', {
                from_mode: restoreDouble ? 'single_side_card' : 'double_side_card',
                to_mode: restoreDouble ? 'double_side_card' : 'single_side_card'
            });
            const layout = getItemLayoutForType('pvc', idx, !!item.back);
            Object.assign(item, layout);
            if (selectedItem.side === 'back') selectedItem.side = 'front';
            syncSelectionToolbar();
            updateListUI();
            syncPvcPageSizeModeUi();
            resizePreviewCanvas();
            renderSheetNow();
            document.getElementById('mobStatus').innerText = restoreDouble ? 'PVC double-side restored.' : 'PVC single-side preview active.';
            showModal(
                restoreDouble ? "Double Side Restored" : "Single Side Set",
                restoreDouble
                    ? "Saved back side wapas aa gayi hai. Front aur back dono card preview me hain."
                    : (hasLearningSource ? "Back side safe rakhi gayi hai. Isi button par Double dabakar kabhi bhi wapas la sakte hain." : "Back side safe rakhi gayi hai; Double dabakar wapas la sakte hain."),
                "success"
            );
        }

        async function loadPvcRecropSourceToEditor(dataUrl, options = {}) {
            return loadDataUrlToEditorWithFallback(dataUrl, options);
        }

        async function readFile(file) {
            uploadPipelineStartedAt = performance.now();
            cropWorkflowBusy = true;
            syncCropWorkflowUi();
            try {
                if (!file) return;
                // Ask once at the point of use, not on page load. Manual choice
                // resumes THIS upload and keeps the same crop/print workspace.
                if (['smart', 'a4'].includes(currentType)
                    && documentCropLimitReached() && !isPairedIdBackCrop()) {
                    await showDocumentCropLimitIfDue();
                }
                const isPvc = currentType === 'pvc';
                if (isPvc) schedulePvcLearnedTemplatesServerSync();
                const fileIsImage = isImageFile(file);
                const fileIsPdf = isPdfFile(file);
                if (currentSide !== 'back' || !currentLearningGroupRef) {
                    currentLearningGroupRef = `grp_${Date.now().toString(36)}_${Math.random().toString(36).slice(2, 10)}`;
                }
                if (currentType === 'smart' && currentSide === 'front') documentQuotaFrontHash = '';
                currentLearningCaptureMeta = normalizeLearningCaptureMeta({
                    uploadChannel: 'local_id_card_print',
                    sourceMedia: fileIsPdf ? 'pdf' : (fileIsImage ? 'image' : 'rendered_file'),
                    mimeGroup: fileIsPdf ? 'application_pdf' : (fileIsImage ? 'image' : 'other'),
                    fileExtension: fileExtensionOnly(file),
                    fileSizeBucket: fileSizeBucket(file.size),
                    customerMobileFlow: false,
                    pdfRender: fileIsPdf,
                    groupRef: currentLearningGroupRef,
                    side: currentSide
                });
                if (!isPvc) {
                    documentLearningContext = {
                        docType: currentType === 'a4' ? 'a4_document' : 'id_card',
                        docLabel: currentType === 'a4' ? 'A4 Document' : 'ID Card',
                        sourceKind: fileIsPdf ? 'local_pdf_render' : (fileIsImage ? 'local_image_upload' : 'local_rendered_file'),
                        contentKind: currentType === 'a4' ? 'a4_document' : 'id_card',
                        captureReason: currentType === 'a4' ? 'local_a4_crop_done' : 'local_card_crop_done',
                        captureMeta: currentLearningCaptureMeta
                    };
                }
                albumCardImageUploadActive = !!(isDocumentAlbumLaunch && isPvc && fileIsImage);
                if (albumCardImageUploadActive && currentSide === 'front') {
                    albumPendingFrontSourceDataUrl = '';
                    albumPendingFrontLearningMeta = null;
                    albumPendingFrontCaptureMeta = null;
                    if (!isMatUsable(tempDocs.back)) {
                        albumPendingBackSourceDataUrl = '';
                        albumPendingBackLearningMeta = null;
                        albumPendingBackCaptureMeta = null;
                    }
                }
                recordAiActivity('upload_processing_started', {
                    input_type: fileIsPdf ? 'pdf' : (fileIsImage ? 'image' : 'rendered_file'),
                    file_extension: fileExtensionOnly(file),
                    file_size_bucket: fileSizeBucket(file.size)
                });

                if (isPvc && !isProUser() && !canOpenLockedPvcWorkspace()) {
                    requireProFeature("PVC Print Mode");
                    return false;
                }

                if (!isPvc && !isProUser() && !fileIsImage) {
                    requireProFeature("All file type upload in ID Card Print");
                    return false;
                }

                if (isPvc && !fileIsImage && !fileIsPdf) {
                    showModal("Unsupported in PVC", "PVC mode supports image/PDF only.", "warn");
                    return false;
                }

                if (isPvc && fileIsPdf) {
                    try {
                        // Initial upload matching must see the admin coordinates;
                        // otherwise a cached learned template can win before the
                        // background defaults sync finishes.
                        await withTimeout(
                            ensurePvcDefaultOverridesReady(),
                            4000,
                            'PVC default coordinates timed out'
                        );
                    } catch (error) {
                        console.warn('PVC default coordinates were not ready before upload', error);
                    }
                }

                lastPdfDetectText = '';
                lastVisualMeta = null;
                lastPdfMeta = null;
                activePdfFastRasterSize = null;
                activePdfHighQualityDataUrl = '';
                activePdfHighQualityPromise = null;
                activePdfHighQualityStarter = null;
                activePdfHighQualityToken++;
                pendingPvcHighQualityTask = null;
                pendingPvcTwoPagePdf = null;
                pvcTwoPageAutoCompleted = false;
                pvcActivePdfMeta = null;
                pvcActiveTemplateMatch = null;
                pvcTemplateNeedsManualReview = false;
                pendingPvcAiAnalysis = null;
                pendingDocumentAiAnalysis = null;
                shadowPvcAiAnalysis = null;
                shadowDocumentAiAnalysis = null;
                if (currentSide !== 'back') {
                    pendingDocumentCropDescriptors = { front: null, back: null };
                    pendingDocumentSourceDataUrls = { front: '', back: '' };
                }
                pendingDocAlignerPostCropRotation = 0;
                docAlignerDirectApplyActive = false;
                docAlignerDecisionState = 'preparing';
                pvcSingleSideAiMode = false;
                pendingPvcPdfDualFlow = isPvcPdfAutoCropEnabled(file) && (isDocumentAlbumLaunch || !isSingleSide);
                let pvcDocTypeDetected = isPvc ? applyPvcDocTypeFromFileName(file) : '';

                let dataUrl = '';
                if (fileIsImage) {
                    updateProcessLoader({
                        kind: 'upload',
                        variant: 'fast',
                        title: 'Image read ho rahi hai',
                        message: 'Image ko browser me optimize karke cropper ke liye ready kar rahe hain.',
                        chip: 'IMAGE',
                        subtext: 'Large image ko safe preview size me badla ja raha hai'
                    });
                    dataUrl = await readImageFileFastDataUrl(file, isPvc ? 5600 : 6200);
                    if (isPvc) {
                        updateProcessLoader({
                            kind: 'upload',
                            variant: 'fast',
                            title: 'PVC auto detect',
                            message: 'Image ka visual signature read karke auto crop template check ho raha hai.',
                            chip: 'PVC',
                            subtext: 'Crop match aur approval details prepare ho rahi hain'
                        });
                        lastVisualMeta = await computeDataUrlVisualFeatures(dataUrl);
                        const knownDocType = pvcDocTypeDetected
                            || inferDynamicPvcDocTypeFromText('', file?.name || '')
                            || (albumCardImageUploadActive ? 'custom_card' : 'image_only_document');
                        lastPdfMeta = {
                            doc_type: sanitizePvcDocType(knownDocType),
                            doc_label: getPvcDocTypeLabel(knownDocType),
                            page_width_pt: 0,
                            page_height_pt: 0,
                            page_count: 1,
                            page_size_key: lastVisualMeta?.visual?.width_px && lastVisualMeta?.visual?.height_px ? `${lastVisualMeta.visual.width_px}x${lastVisualMeta.visual.height_px}` : 'image',
                            render_size_key: lastVisualMeta?.visual?.width_px && lastVisualMeta?.visual?.height_px ? `${lastVisualMeta.visual.width_px}x${lastVisualMeta.visual.height_px}` : 'image',
                            text_signature: '',
                            image_signature: lastVisualMeta.image_signature || '',
                            visual_bucket: lastVisualMeta.visual_bucket || '',
                            has_text: false,
                            source_kind: 'image',
                            content_kind: albumCardImageUploadActive
                                ? 'id_card'
                                : inferContentKindFromMeta({
                                    doc_type: knownDocType,
                                    page_size_key: lastVisualMeta?.visual?.width_px && lastVisualMeta?.visual?.height_px ? `${lastVisualMeta.visual.width_px}x${lastVisualMeta.visual.height_px}` : 'image',
                                    features: { visual: lastVisualMeta?.visual || {} }
                                }),
                            text_sample: '',
                            features: {
                                text_markers: [],
                                visual: lastVisualMeta.visual || {},
                                layout: {
                                    image_width_px: lastVisualMeta?.visual?.width_px || 0,
                                    image_height_px: lastVisualMeta?.visual?.height_px || 0,
                                    render_size_key: lastVisualMeta?.visual?.width_px && lastVisualMeta?.visual?.height_px ? `${lastVisualMeta.visual.width_px}x${lastVisualMeta.visual.height_px}` : 'image'
                                }
                            }
                        };
                        lastPdfMeta.pdf_signature = buildPdfSignature(lastPdfMeta);
                        setPvcActivePdfMeta(lastPdfMeta);
                        pvcDocTypeDetected = applyLearnedPvcTemplateForUpload(file) || pvcDocTypeDetected;
                    }
                } else if (fileIsPdf) {
                    updateProcessLoader({
                        kind: 'upload',
                        variant: 'fast',
                        title: 'PDF read ho rahi hai',
                        message: 'PDF ka first page preview me convert ho raha hai.',
                        chip: 'PDF',
                        subtext: 'Cropper open karne ke liye preview ban raha hai'
                    });
                    dataUrl = await renderPdfFileToDataUrl(file);
                    if (isPvc && pendingPvcPdfDualFlow) {
                        pvcDocTypeDetected = applyLearnedPvcTemplateForUpload(file) || pvcDocTypeDetected;
                    }
                    if (isPvc && pendingPvcPdfDualFlow && !pvcDocTypeDetected) {
                        pvcDocTypeDetected = await ensurePvcDocTypeForUpload(file, true);
                    }
                } else if (isTextLikeFile(file)) {
                    dataUrl = await renderTextFileToDataUrl(file);
                } else {
                    dataUrl = await renderGenericFileCardToDataUrl(file);
                }

                updateProcessLoader({
                    kind: 'crop',
                    variant: 'fast',
                    title: 'Cropper open ho raha hai',
                    message: 'File ready hai. Crop engine canvas par preview set kar raha hai.',
                    chip: 'CROP',
                    subtext: 'Bas ek pal, crop screen open hogi'
                });
                if (isPvc && !fileIsPdf && !albumCardImageUploadActive) {
                    await ensurePvcDocTypeForUpload(file, false);
                }

                if (albumCardImageUploadActive) {
                    if (currentSide === 'back') {
                        albumPendingBackSourceDataUrl = dataUrl;
                        albumPendingBackLearningMeta = cloneLearningPlainObject(pvcActivePdfMeta || lastPdfMeta);
                        albumPendingBackCaptureMeta = cloneLearningPlainObject(currentLearningCaptureMeta);
                    } else {
                        albumPendingFrontSourceDataUrl = dataUrl;
                        albumPendingFrontLearningMeta = cloneLearningPlainObject(pvcActivePdfMeta || lastPdfMeta);
                        albumPendingFrontCaptureMeta = cloneLearningPlainObject(currentLearningCaptureMeta);
                    }
                }
                if (pendingPvcPdfDualFlow && currentType === 'pvc') {
                    updateProcessLoader({
                        kind: 'crop',
                        variant: 'fast',
                        title: 'Auto crop ready ho raha hai',
                        message: `${getPvcDocTypeLabel()} ke crop boxes preview par set ho rahe hain.`
                    });
                    await waitForFastPaint();
                }

                if (currentType === 'pvc') {
                    currentPvcSourceDataUrl = dataUrl;
                    currentDocumentSourceDataUrl = '';
                } else if (!pvcRecropMode) {
                    currentPvcSourceDataUrl = '';
                    currentDocumentSourceDataUrl = dataUrl;
                }

                // PDF inspection can reclassify a PVC upload as an A4 page.
                // Do not keep using the `isPvc` snapshot captured before that
                // switch: it sent an A4 page to the PVC analysis route and left
                // the successful response in collection-only mode.
                const activeUploadIsPvc = currentType === 'pvc';
                let backgroundAiAction = '';
                let backgroundAiExtra = null;
                if (activeUploadIsPvc && !pvcRecropMode && !forcePvcTemplatePlacement && !pvcActiveTemplateMatch) {
                    backgroundAiAction = 'analyze_pvc_crop_ai';
                    backgroundAiExtra = {
                        docType: lastPdfMeta?.doc_type || pvcActivePdfMeta?.doc_type || pvcAutoCropDocType,
                        sourceKind: lastPdfMeta?.source_kind || (fileIsPdf ? 'pdf' : 'image')
                    };
                } else if (!activeUploadIsPvc && isDocAlignerDocumentType(currentType) && isDocumentAutoCropEnabled()) {
                    backgroundAiAction = 'analyze_document_crop_ai';
                    backgroundAiExtra = {
                        docType: currentType === 'a4' ? 'a4_document' : 'id_card',
                        sourceKind: fileIsPdf ? 'pdf' : (fileIsImage ? 'image' : 'rendered_file')
                    };
                }

                // `(1)` rollout me har image DocAligner se pehle decide hogi.
                // Learned PVC rectangle bhi is test ko bypass nahi karega; GPU
                // false/offline/timeout ho tabhi neeche purana manual cropper khulega.
                const canApplyDocAlignerInForeground = fileIsImage
                    || (!activeUploadIsPvc && currentType === 'a4' && fileIsPdf);
                if (DOCALIGNER_TEST_MODE && isDocumentAutoCropEnabled() && canApplyDocAlignerInForeground && (activeUploadIsPvc || isDocAlignerDocumentType(currentType)) && !pvcRecropMode && !forcePvcTemplatePlacement) {
                    backgroundAiAction = activeUploadIsPvc ? 'analyze_pvc_crop_ai' : 'analyze_document_crop_ai';
                    backgroundAiExtra = {
                        ...(backgroundAiExtra || {}),
                        docType: activeUploadIsPvc
                            ? (lastPdfMeta?.doc_type || pvcActivePdfMeta?.doc_type || pvcAutoCropDocType || 'custom_card')
                            : (currentType === 'a4' ? 'a4_document' : 'id_card'),
                        contentKind: activeUploadIsPvc ? 'id_card' : (currentType === 'a4' ? 'a4_document' : 'id_card'),
                        sourceKind: fileIsPdf ? 'pdf' : 'image',
                        timeoutMs: DOCALIGNER_BROWSER_TIMEOUT_MS,
                        browserFallback: true
                    };
                }

                const waitForDocAligner = DOCALIGNER_TEST_MODE && canApplyDocAlignerInForeground && !!backgroundAiAction;
                if (waitForDocAligner) {
                    docAlignerDecisionState = 'waiting_for_gpu';
                    document.getElementById('cropperModal')?.classList.add('hidden');
                    updateProcessLoader({
                        kind: 'crop',
                        variant: 'fast',
                        title: 'AI Auto Crop',
                        message: 'Card automatically seedha aur crop ho raha hai.',
                        chip: 'AUTO CROP',
                        subtext: 'Clear result par seedha preview; zarurat par manual adjust'
                    });
                    await waitForFastPaint();
                    // Decode/prepare the original while the one GPU request
                    // computes crop, orientation and the active enhancement field.
                    // Never send separate rotate/enhance requests or decode twice.
                    let ai, directApplied = false;
                    directCropPreparation = true;
                    try {
                        const foregroundAiReply = withTimeout(
                            requestCropAiAnalysis(backgroundAiAction, dataUrl, file, backgroundAiExtra || {}),
                            DOCALIGNER_FOREGROUND_TIMEOUT_MS,
                            'AI auto crop preparation timed out'
                        ).catch((error) => {
                            console.warn('Foreground AI auto crop timed out; trying browser crop', error);
                            recordDocAlignerDirectFallback('foreground_total_timeout', {
                                timeout_ms: DOCALIGNER_FOREGROUND_TIMEOUT_MS
                            });
                            return { success: false, browser_fallback_needed: true };
                        });
                        const [reply, ready] = await Promise.all([
                            foregroundAiReply,
                            loadDataUrlToEditorWithFallback(dataUrl, { deferCropper: true }).then(() => true, () => false)
                        ]);
                        ai = reply;
                        docAlignerDecisionState = ai ? 'applying_gpu_result' : 'manual_fallback';
                        directApplied = ai?.browser_fallback_needed === true
                            ? await tryApplyBrowserAutoCropFallback(dataUrl, ready)
                            : (ai ? await tryApplyDocAlignerDirectResult(ai, dataUrl, ready) : false);
                    } finally { directCropPreparation = false; }
                    if (directApplied) {
                        docAlignerDecisionState = 'gpu_committed';
                        if (documentCropLimitReached() && !pendingBackFile) {
                            setTimeout(() => { showDocumentCropLimitIfDue(); }, 0);
                        }
                        return true;
                    }
                    docAlignerDecisionState = 'manual_fallback';
                    updateProcessLoader({
                        kind: 'crop',
                        variant: 'fast',
                        title: 'Manual cropper open ho raha hai',
                        message: 'AI Auto Crop clear nahi mila. Original safe cropper load ho raha hai.',
                        chip: 'SAFE FALLBACK',
                        subtext: '4 dots ko card boundary par set karke Done dabayein'
                    });
                    await waitForFastPaint();
                }

                dataUrl = await loadDataUrlToEditorWithFallback(dataUrl);
                if (pvcTwoPageAutoCompleted) {
                    // startEditor already added the paired item. Do not restore the
                    // first-page source or schedule a redundant GPU request after
                    // the local two-page result has been committed.
                    pendingPvcTwoPagePdf = null;
                    currentPvcSourceDataUrl = '';
                    currentDocumentSourceDataUrl = '';
                    return true;
                }
                if (currentType === 'pvc') {
                    currentPvcSourceDataUrl = dataUrl;
                    currentDocumentSourceDataUrl = '';
                    if (albumCardImageUploadActive) {
                        if (currentSide === 'back') albumPendingBackSourceDataUrl = dataUrl;
                        else albumPendingFrontSourceDataUrl = dataUrl;
                    }
                } else {
                    currentDocumentSourceDataUrl = dataUrl;
                }
                recordAiActivity('crop_editor_opened', {
                    input_type: fileIsPdf ? 'pdf' : (fileIsImage ? 'image' : 'rendered_file'),
                    ai_scheduled: !!backgroundAiAction,
                    image_width: Number(displayMat?.cols || 0),
                    image_height: Number(displayMat?.rows || 0),
                    page_size_key: lastPdfMeta?.page_size_key || pvcActivePdfMeta?.page_size_key || ''
                });
                if (backgroundAiAction && !waitForDocAligner) {
                    scheduleCropAiAnalysis(backgroundAiAction, dataUrl, file, backgroundAiExtra || {});
                }
                return true;
            } catch (e) {
                if (e?.name === 'PdfPasswordCancelledError') {
                    showModal("Upload Cancelled", "PDF password nahi diya gaya, isliye upload cancel ho gaya.", "warn");
                    return false;
                }
                console.error(e);
                recordAiActivity('upload_processing_failed', {
                    error_type: String(e?.name || 'read_error').slice(0, 60)
                });
                showModal("Read Error", e?.message || "Could not read this file.", "error");
                return false;
            } finally {
                cropWorkflowBusy = false;
                if (cropPaidActivationPending && documentCropAccess.paid === true) {
                    cropPaidActivationPending = false;
                    applyCropWorkflowMode('auto');
                }
                syncCropWorkflowUi();
            }
        }

        async function startEditor(options = {}) {
            try {
                if (!isOpenCvReady()) throw new Error("Image editor engine is still loading. Please try again.");
                const img = document.getElementById('tempImgSource');
                const imgW = img.naturalWidth || img.width;
                const imgH = img.naturalHeight || img.height;
                if (!imgW || !imgH) throw new Error("Image decode failed");
                const nextSrcMat = readImageElementToMat(img);
                if (!nextSrcMat || !nextSrcMat.cols || !nextSrcMat.rows) {
                    safeDeleteMat(nextSrcMat);
                    throw new Error("OpenCV image read failed");
                }
                safeDeleteMat(displayMat);
                displayMat = null;
                editorEnhancedDirty = true;
                if(srcMat) safeDeleteMat(srcMat);
                srcMat = nextSrcMat;
                availableGpuExposure = null;
                activeGpuExposure = null;
                rotationAngle = 0; 
                resetPvcDualSession();
                currentMode = 'magic';
                const lockPvcTwoPageRecrop = options.lockPvcTwoPageRecrop === true || pvcTwoPageRecropState.active;
                if (lockPvcTwoPageRecrop) {
                    // This source belongs to an already-created 2-page PVC pair.
                    // Open only the PVC four-corner editor; do not run upload-time
                    // type detection, template auto-apply, DocAligner, or A4 routing.
                    if (currentType !== 'pvc') switchCurrentTypeForActiveCrop('pvc');
                    setMode('magic', false);
                    toggleMobSliders(false);
                    refreshEditor(true);
                    document.getElementById('cropperModal').classList.remove('hidden');
                    return;
                }
                // GPU-first test flow me source/OpenCV ready rakho, lekin AI ka
                // final yes/no aane se pehle cropper kabhi screen par mat dikhao.
                if (options.deferCropper === true) {
                    setMode('magic', false);
                    toggleMobSliders(false);
                    refreshEditor(true);
                    return;
                }
                if (await tryApplyPvcTwoPagePdfPair()) return;
                // Some Ayushman downloads contain Front + Back beside each other
                // on one very-wide PDF page.  The conservative Ayushman fallback
                // intentionally treats unknown one-page layouts as a single card,
                // so recognise only this unmistakable pair shape before applying
                // that fallback.  Saved/admin Ayushman coordinates never enter
                // this branch and therefore remain unchanged.
                promoteAyushmanSinglePageFallbackToVisualPair(srcMat);
                const albumImageSideMode = !!(isDocumentAlbumLaunch && albumCardImageUploadActive && currentType === 'pvc');
                const requireVisualA4CardDecision = !albumImageSideMode && needsA4VsCardVisualDecision();
                if (currentType === 'pvc' && pendingPvcPdfDualFlow && !requireVisualA4CardDecision && !pendingPvcAiAnalysis && !pvcTemplateNeedsManualReview && !pvcRecropMode && !forcePvcTemplatePlacement && pvcLockedTemplate?.front && (pvcLockedTemplate?.back || pvcLockedTemplate?.single_side)) {
                    editorScale = 1;
                    if (!await applyLockedTemplateDirectFromSource({ fast: true })) {
                        refreshEditor(true);
                        document.getElementById('cropperModal').classList.remove('hidden');
                        beginPvcTemplatePlacement();
                    }
                    pendingPvcPdfDualFlow = false;
                    return;
                }
                setMode('magic', false);
                toggleMobSliders(false);
                refreshEditor(true);
                document.getElementById('cropperModal').classList.remove('hidden');
                if (albumImageSideMode) {
                    pendingPvcPdfDualFlow = false;
                    pvcTemplateNeedsManualReview = false;
                    prepareAlbumSingleImageCropBox();
                    setCropStepUI(`Album ${currentSide === 'back' ? 'Back' : 'Front'}`, currentSide === 'back' ? 'step-back' : 'step-front');
                    document.getElementById('mobStatus').innerText = `${currentSide === 'back' ? 'Back' : 'Front'} JPG/PNG ko ID-card box me crop karke Done dabayein`;
                    drawCanvas();
                }
                if (requireVisualA4CardDecision && !pvcRecropMode && !forcePvcTemplatePlacement) {
                    if (protectKnownVisualCardFromA4('a4_visual_decision_guard_aadhaar')) {
                        document.getElementById('mobStatus').innerText = 'Aadhaar visual detect hua. PVC crop boxes check karein.';
                    } else {
                    const visualPair = detectPvcCardPairVisual(displayMat);
                    if (!visualPair) {
                        const pvcSourceForApproval = currentPvcSourceDataUrl;
                        switchCurrentTypeForActiveCrop('a4');
                        currentDocumentSourceDataUrl = currentPvcSourceDataUrl;
                        currentPvcSourceDataUrl = '';
                        fitCropToFullImage();
                        documentLearningContext = {
                            docType: 'a4_document',
                            docLabel: 'A4 Document',
                            sourceKind: pvcActivePdfMeta?.source_kind || 'pvc_a4_visual_no_card_pair',
                            contentKind: 'a4_document',
                            captureReason: 'pvc_a4_visual_no_card_pair_crop_done',
                            forceCorrection: true
                        };
                        pendingPvcPdfDualFlow = false;
                        document.getElementById('mobStatus').innerText = 'A4 page detect hua. 4 dots check karke Done dabayein.';
                        showPvcA4CorrectionControls('a4_document');
                        queueBackgroundLearning(() => queuePvcA4AutoDetectApprovalSample('pvc_a4_visual_no_card_pair_auto_detect', null, pvcSourceForApproval), 'PVC A4 approval sample');
                        showModal("A4 Page Detected", "A4 size page me front/back card pair nahi mila, isliye A4 cropper open kiya gaya hai.", "warn");
                        requestAnimationFrame(() => adjustEditorZoom(0));
                        return;
                    }
                    if (pvcActivePdfMeta) {
                        setPvcActivePdfMeta({
                            ...pvcActivePdfMeta,
                            doc_type: pvcActivePdfMeta.doc_type === 'a4_document' ? 'image_only_document' : pvcActivePdfMeta.doc_type,
                            doc_label: pvcActivePdfMeta.doc_type === 'a4_document' ? 'Image-only Document' : pvcActivePdfMeta.doc_label,
                            content_kind: 'id_card',
                            visual_card_pair_detected: true
                        });
                    }
                    document.getElementById('mobStatus').innerText = 'A4 page me card pair mila. PVC crop boxes check karein.';
                    }
                }
                let pvcAiApplied = false;
                if (APPLY_LOCAL_AI_PVC_SUGGESTIONS && currentType === 'pvc' && pendingPvcAiAnalysis && !pvcRecropMode && !forcePvcTemplatePlacement) {
                    pvcAiApplied = applyPvcA4DocumentAiCrop(pendingPvcAiAnalysis);
                    if (!pvcAiApplied) pvcAiApplied = beginPvcTemplatePlacementFromAi(pendingPvcAiAnalysis);
                    if (!pvcAiApplied) pvcAiApplied = applyPvcSingleCardAiCrop(pendingPvcAiAnalysis);
                    const mode = String(pendingPvcAiAnalysis?.classification?.mode || '');
                    if (!pvcAiApplied && mode === 'a4_document' && applyPvcA4DocumentAiCrop(pendingPvcAiAnalysis)) {
                        pvcAiApplied = true;
                        showModal("A4 Page Detected", "AI ko PVC card pair ke bajay A4/document layout mila. Isko A4 page crop ke roop me process kiya jayega.", "warn");
                    }
                    if (pvcAiApplied) {
                        pendingPvcPdfDualFlow = false;
                        pvcTemplateNeedsManualReview = false;
                    }
                } else if (APPLY_LOCAL_AI_DOCUMENT_SUGGESTIONS && isDocumentAutoCropEnabled() && (currentType === 'a4' || currentType === 'smart') && pendingDocumentAiAnalysis) {
                    applyDocumentAiCropperPoints(pendingDocumentAiAnalysis, 'AI');
                }
                if (currentType === 'pvc'
                    && pendingPvcPdfDualFlow
                    && !pendingPvcAiAnalysis
                    && !pvcRecropMode
                    && !forcePvcTemplatePlacement
                    && !pvcActivePdfMeta?.visual_card_pair_detected
                    && (pvcActivePdfMeta?.content_kind === 'a4_document' || pvcActivePdfMeta?.doc_type === 'a4_document')) {
                    if (protectKnownVisualCardFromA4('meta_a4_guard_aadhaar_visual')) {
                        document.getElementById('mobStatus').innerText = 'Aadhaar visual detect hua. A4 nahi, PVC crop boxes check karein.';
                    } else {
                    const pvcSourceForApproval = currentPvcSourceDataUrl;
                    switchCurrentTypeForActiveCrop('a4');
                    currentDocumentSourceDataUrl = currentPvcSourceDataUrl;
                    currentPvcSourceDataUrl = '';
                    fitCropToFullImage();
                    documentLearningContext = {
                        docType: 'a4_document',
                        docLabel: 'A4 Document',
                        sourceKind: pvcActivePdfMeta?.source_kind || 'pvc_a4_auto_detect',
                        contentKind: 'a4_document',
                        captureReason: 'pvc_a4_auto_detect_crop_done',
                        forceCorrection: true
                    };
                    pendingPvcPdfDualFlow = false;
                    document.getElementById('mobStatus').innerText = 'A4 page detect hua. 4 dots check karke Done dabayein.';
                    showPvcA4CorrectionControls('a4_document');
                    queueBackgroundLearning(() => queuePvcA4AutoDetectApprovalSample('pvc_a4_auto_detected_from_meta', null, pvcSourceForApproval), 'PVC A4 approval sample');
                    showModal("A4 Page Detected", "Ye file Aadhaar/PVC pair nahi lag rahi. Isko A4 page crop ke roop me open kiya gaya hai.", "warn");
                    }
                }
                requestAnimationFrame(() => adjustEditorZoom(0));
                if (currentType === 'pvc' && (pendingPvcPdfDualFlow || pvcRecropMode || forcePvcTemplatePlacement)) {
                    requestAnimationFrame(async () => {
                        pendingBackFile = null;
                        if (pvcRecropMode || forcePvcTemplatePlacement || pvcTemplateNeedsManualReview || !pvcLockedTemplate?.front || (!pvcLockedTemplate?.back && !pvcLockedTemplate?.single_side)) {
                            beginPvcTemplatePlacement();
                        } else {
                            const done = await applyLockedTemplateToCurrentPdf();
                            if (!done) beginPvcTemplatePlacement();
                        }
                        pvcTemplateNeedsManualReview = false;
                        pendingPvcPdfDualFlow = false;
                    });
                }
            } catch(e) {
                throw e;
            }
        }
        function closeCropper() {
            activeCropAiRequestId = ++cropAiRequestSequence;
            cropAiActiveDragKind = '';
            const cancelRemoteIndex = remoteCropIndex;
            const cancelRemoteSide = remoteCropSide;
            const cancelRemoteItem = cancelRemoteIndex >= 0 ? remoteCustomerQueue[cancelRemoteIndex] : null;
            if (pendingA4ReplaceIndex >= 0 && !cropProcessBusy) {
                pendingA4ReplaceIndex = -1;
                documentLearningContext = null;
            }
            if (documentItemRecropState.active && !cropProcessBusy) resetDocumentItemRecropState();
            if (pvcTemplatePlacementMode) {
                forcePvcTemplatePlacement = false;
            }
            pvcApprovalFixState = null;
            pvcApprovalTeachMode = 'double_side_card';
            pvcTemplateOriginalTemplate = null;
            clearPvcRecropTarget();
            resetAlbumCoverCropState();
            resetAlbumItemRecropState();
            resetPvcTwoPageRecropState();
            remoteCropIndex = -1;
            resetPvcDualSession();
            pvcTemplatePlacementMode = false;
            pvcTemplateBoxes = { front: null, back: null };
            pvcTemplateDragKey = null;
            pvcTemplateDragMode = 'move';
            pvcTemplateDragStart = null;
            pvcTemplateScale = { w: 100, h: 100 };
            togglePvcSizePanel(false);
            closePvcCoordsModal();
            syncPvcApprovalTeachControls();
            hidePvcA4CorrectionControls();
            document.getElementById('cropperModal').classList.add('hidden');
            releaseEditorWorkingMemory();
            schedulePvcBatchCropperCloseCheck();
            if (cancelRemoteItem && getRemoteItemDocType(cancelRemoteItem) === 'idcard' && cancelRemoteSide === 'front' && !cancelRemoteItem.backDataUrl) {
                setTimeout(() => promptRemoteBackUpload(cancelRemoteIndex), 250);
            }
        }
        
        function toggleMobSliders(show) { const el = document.getElementById('mobileSliderPanel'); if(show) el.classList.add('active'); else el.classList.remove('active'); }
        function syncMobileFilters(val, type) { if(type === 'bright') { document.getElementById('inpBright').value = val; document.getElementById('mobValBright').innerText = val; } else { document.getElementById('inpContrast').value = val; document.getElementById('mobValContrast').innerText = val; } updateFilters(); }

        function adjustEditorZoom(delta) {
            editorZoom += delta;
            if(editorZoom < 0.1) editorZoom = 0.1; if(editorZoom > 5.0) editorZoom = 5.0;
            document.getElementById('zoomLabel').innerText = Math.round(editorZoom * 100) + "%";
            
            // Fixed Center Zoom Transformation
            const scrollArea = document.getElementById('editorScrollArea');
            const wrapper = document.getElementById('canvasWrapper');
            const canvas = document.getElementById('cropCanvas');
            // Set dimensions explicitly based on new zoom
            const zoomedW = canvas.width * editorZoom;
            const zoomedH = canvas.height * editorZoom;
            wrapper.style.width = zoomedW + "px";
            wrapper.style.height = zoomedH + "px";
            
            // Canvas scaling handled via CSS Transform
            canvas.style.transformOrigin = "top left";
            canvas.style.transform = `scale(${editorZoom})`;
            updateEditorScrollMode(zoomedW, zoomedH);
            updateCropHandleOverlay();
            
            drawCanvas();
        }

        function updateEditorScrollMode(zoomedW = canvas.width * editorZoom, zoomedH = canvas.height * editorZoom) {
            const scrollArea = document.getElementById('editorScrollArea');
            const wrapper = document.getElementById('canvasWrapper');
            if (!scrollArea || !wrapper) return;
            const needsX = zoomedW + 48 > scrollArea.clientWidth;
            const needsY = zoomedH + 48 > scrollArea.clientHeight;
            const needsFreeScroll = needsX || needsY;
            scrollArea.style.justifyContent = needsX ? 'flex-start' : 'center';
            scrollArea.style.alignItems = needsY ? 'flex-start' : 'center';
            wrapper.classList.toggle('zoom-scroll-mode', needsFreeScroll);
            requestAnimationFrame(() => {
                if (needsFreeScroll) {
                    scrollArea.scrollLeft = needsX ? Math.max(0, (scrollArea.scrollWidth - scrollArea.clientWidth) / 2) : 0;
                    scrollArea.scrollTop = needsY ? Math.max(0, (scrollArea.scrollHeight - scrollArea.clientHeight) / 2) : 0;
                } else {
                    scrollArea.scrollLeft = 0;
                    scrollArea.scrollTop = 0;
                }
            });
        }

        function updateCropHandleOverlay() {
            const wrapper = document.getElementById('canvasWrapper');
            if (!wrapper) return;
            const handles = wrapper.querySelectorAll('.crop-handle-overlay');
            if (!handles.length) return;
            const visible = Array.isArray(cropperPoints) && cropperPoints.length === 4 && !pvcTemplatePlacementMode;
            handles.forEach((handle, index) => {
                const point = cropperPoints[index];
                if (!visible || !point) {
                    handle.classList.add('hidden');
                    return;
                }
                handle.style.left = `${point.x * editorZoom}px`;
                handle.style.top = `${point.y * editorZoom}px`;
                handle.classList.remove('hidden');
            });
        }

        function orderQuadPoints(points) {
            const sums = points.map((p, i) => ({ i, v: p.x + p.y }));
            const diffs = points.map((p, i) => ({ i, v: p.x - p.y }));
            const tl = points[sums.reduce((a, b) => a.v < b.v ? a : b).i];
            const br = points[sums.reduce((a, b) => a.v > b.v ? a : b).i];
            const tr = points[diffs.reduce((a, b) => a.v > b.v ? a : b).i];
            const bl = points[diffs.reduce((a, b) => a.v < b.v ? a : b).i];
            return [tl, tr, br, bl];
        }

        function dist2D(p1, p2) {
            return Math.hypot(p1.x - p2.x, p1.y - p2.y);
        }

        function detectPvcQuad(mat, minimumAreaRatio = 0.09) {
            let gray = null, blur = null, edges = null, contours = null, hierarchy = null;
            try {
                gray = new cv.Mat();
                blur = new cv.Mat();
                edges = new cv.Mat();
                contours = new cv.MatVector();
                hierarchy = new cv.Mat();

                cv.cvtColor(mat, gray, cv.COLOR_RGBA2GRAY);
                cv.GaussianBlur(gray, blur, new cv.Size(5, 5), 0);
                cv.Canny(blur, edges, 60, 180);
                cv.findContours(edges, contours, hierarchy, cv.RETR_LIST, cv.CHAIN_APPROX_SIMPLE);

                const safeMinimumAreaRatio = Math.max(0.02, Math.min(0.35, Number(minimumAreaRatio) || 0.09));
                const areaThreshold = (mat.cols * mat.rows) * safeMinimumAreaRatio;
                const targetAspect = DOC_TYPES.pvc.aspect;
                let bestPoints = null;
                let bestScore = Infinity;

                for (let i = 0; i < contours.size(); i++) {
                    const cnt = contours.get(i);
                    const area = cv.contourArea(cnt);
                    if (area < areaThreshold) { cnt.delete(); continue; }

                    const peri = cv.arcLength(cnt, true);
                    const approx = new cv.Mat();
                    cv.approxPolyDP(cnt, approx, 0.03 * peri, true);

                    if (approx.rows === 4) {
                        const raw = [];
                        for (let j = 0; j < 4; j++) {
                            raw.push({ x: approx.data32S[j * 2], y: approx.data32S[(j * 2) + 1] });
                        }
                        const ordered = orderQuadPoints(raw);
                        const w = Math.max(dist2D(ordered[0], ordered[1]), dist2D(ordered[3], ordered[2]));
                        const h = Math.max(dist2D(ordered[0], ordered[3]), dist2D(ordered[1], ordered[2]));
                        const aspect = w / Math.max(1, h);

                        const aspectPenalty = Math.abs(aspect - targetAspect);
                        const areaPenalty = 1 - Math.min(1, area / (mat.cols * mat.rows));
                        const score = (aspectPenalty * 2.2) + areaPenalty;

                        if (score < bestScore) {
                            bestScore = score;
                            bestPoints = ordered;
                        }
                    }

                    approx.delete();
                    cnt.delete();
                }

                return bestPoints;
            } catch (err) {
                console.error("PVC detect error", err);
                return null;
            } finally {
                if (gray) gray.delete();
                if (blur) blur.delete();
                if (edges) edges.delete();
                if (contours) contours.delete();
                if (hierarchy) hierarchy.delete();
            }
        }

        function getPvcQuadArea(points) {
            if (!Array.isArray(points) || points.length !== 4) return 0;
            let twiceArea = 0;
            for (let i = 0; i < points.length; i++) {
                const current = points[i];
                const next = points[(i + 1) % points.length];
                twiceArea += (Number(current.x) || 0) * (Number(next.y) || 0);
                twiceArea -= (Number(next.x) || 0) * (Number(current.y) || 0);
            }
            return Math.abs(twiceArea) / 2;
        }

        function detectVisiblePvcContentBounds(sourceMat, sourceScale = 1) {
            if (!isMatUsable(sourceMat)) return null;
            let gray = null;
            let ink = null;
            try {
                gray = new cv.Mat();
                const channels = typeof sourceMat.channels === 'function' ? sourceMat.channels() : 4;
                if (channels === 4) cv.cvtColor(sourceMat, gray, cv.COLOR_RGBA2GRAY);
                else if (channels === 3) cv.cvtColor(sourceMat, gray, cv.COLOR_RGB2GRAY);
                else sourceMat.copyTo(gray);
                ink = new cv.Mat();
                cv.threshold(gray, ink, 245, 255, cv.THRESH_BINARY_INV);

                const rows = ink.rows;
                const cols = ink.cols;
                const rowCounts = new Uint32Array(rows);
                const colCounts = new Uint32Array(cols);
                const pixels = ink.data;
                for (let y = 0, index = 0; y < rows; y++) {
                    let rowCount = 0;
                    for (let x = 0; x < cols; x++, index++) {
                        if (pixels[index] === 0) continue;
                        rowCount++;
                        colCounts[x]++;
                    }
                    rowCounts[y] = rowCount;
                }

                const minRowInk = Math.max(3, Math.round(cols * 0.004));
                const minColInk = Math.max(3, Math.round(rows * 0.004));
                let minY = rowCounts.findIndex((count) => count >= minRowInk);
                let maxY = -1;
                for (let y = rows - 1; y >= 0; y--) {
                    if (rowCounts[y] >= minRowInk) { maxY = y; break; }
                }
                let minX = colCounts.findIndex((count) => count >= minColInk);
                let maxX = -1;
                for (let x = cols - 1; x >= 0; x--) {
                    if (colCounts[x] >= minColInk) { maxX = x; break; }
                }
                if (minX < 0 || minY < 0 || maxX <= minX || maxY <= minY) return null;

                const padX = Math.max(2, Math.round(cols * 0.003));
                const padY = Math.max(2, Math.round(rows * 0.003));
                minX = Math.max(0, minX - padX);
                minY = Math.max(0, minY - padY);
                maxX = Math.min(cols - 1, maxX + padX);
                maxY = Math.min(rows - 1, maxY + padY);
                const width = maxX - minX + 1;
                const height = maxY - minY + 1;
                const aspect = width / Math.max(1, height);
                const areaRatio = (width * height) / Math.max(1, cols * rows);
                // This fallback is only for a card artwork sitting on a mostly
                // blank PDF page. Busy photos/full-page documents are rejected.
                if (aspect < 1.15 || aspect > 2.60 || areaRatio < 0.06 || areaRatio > 0.90) return null;
                const scale = Math.max(0.0001, Number(sourceScale) || 1);
                return {
                    points: rectToPoints({
                        x: minX / scale,
                        y: minY / scale,
                        w: width / scale,
                        h: height / scale
                    }),
                    areaRatio,
                    source: 'visible_card_artwork_bounds'
                };
            } catch (error) {
                console.warn('Visible PDF card bounds detection skipped', error);
                return null;
            } finally {
                safeDeleteMat(gray);
                safeDeleteMat(ink);
            }
        }

        function detectSinglePvcCardOnPage(sourceMat) {
            if (!isMatUsable(sourceMat)) return null;
            let work = sourceMat;
            let ownsWork = false;
            let workScale = 1;
            try {
                const pageAspect = sourceMat.cols / Math.max(1, sourceMat.rows);
                // A PDF whose own page already has card proportions must retain
                // the complete page, including its outer printed border.
                if (pageAspect >= 1.35 && pageAspect <= 1.86) {
                    const insetX = Math.max(1, sourceMat.cols * 0.002);
                    const insetY = Math.max(1, sourceMat.rows * 0.002);
                    return {
                        points: rectToPoints({
                            x: insetX,
                            y: insetY,
                            w: sourceMat.cols - (insetX * 2),
                            h: sourceMat.rows - (insetY * 2)
                        }),
                        areaRatio: 0.99,
                        source: 'card_sized_page'
                    };
                }
                const maxDetectDimension = 1400;
                if (Math.max(sourceMat.cols, sourceMat.rows) > maxDetectDimension) {
                    workScale = maxDetectDimension / Math.max(sourceMat.cols, sourceMat.rows);
                    work = new cv.Mat();
                    ownsWork = true;
                    cv.resize(sourceMat, work, new cv.Size(0, 0), workScale, workScale, cv.INTER_AREA);
                }
                const detected = detectPvcQuad(work, 0.025);
                if (detected?.length === 4) {
                    const ordered = orderQuadPoints(detected);
                    const width = Math.max(dist2D(ordered[0], ordered[1]), dist2D(ordered[3], ordered[2]));
                    const height = Math.max(dist2D(ordered[0], ordered[3]), dist2D(ordered[1], ordered[2]));
                    const aspect = width / Math.max(1, height);
                    const areaRatio = getPvcQuadArea(ordered) / Math.max(1, work.cols * work.rows);
                    // Both pages must independently pass this test. The minimum area
                    // prevents a random small rectangle on an ordinary 2-page PDF
                    // from being mistaken for a front/back PVC pair.
                    if (aspect >= 1.25 && aspect <= 2.10 && areaRatio >= 0.035) {
                        return {
                            points: ordered.map((point) => ({ x: point.x / workScale, y: point.y / workScale })),
                            areaRatio,
                            source: 'detected_quad'
                        };
                    }
                }

                const visibleBounds = detectVisiblePvcContentBounds(work, workScale);
                if (visibleBounds) return visibleBounds;
                return null;
            } catch (error) {
                console.warn('Single-card PDF page detection skipped', error);
                return null;
            } finally {
                if (ownsWork) safeDeleteMat(work);
            }
        }

        function createPvcDescriptorForSource(points, sourceMat, rotation = 0) {
            if (!Array.isArray(points) || points.length !== 4 || !isMatUsable(sourceMat)) return null;
            return {
                rotation: normalizeRightAngle(rotation),
                points: points.map((point) => ({
                    x: Math.max(0, Math.min(1, Number(point.x) / Math.max(1, sourceMat.cols))),
                    y: Math.max(0, Math.min(1, Number(point.y) / Math.max(1, sourceMat.rows)))
                }))
            };
        }

        function makePvcTwoPageHighQualityStarter(session, pageNumber) {
            let promise = null;
            return () => {
                if (promise) return promise;
                promise = renderPdfPageRasterDataUrl(
                    session.file,
                    session.password || '',
                    getPdfFinalRasterScale(),
                    30000000,
                    0.96,
                    18000,
                    pageNumber
                ).catch((error) => {
                    console.warn(`PDF page ${pageNumber} high-quality raster unavailable`, error);
                    return null;
                });
                return promise;
            };
        }

        function capturePvcTwoPageHighQualityTask(session, frontMat, frontPoints, backMat, backPoints) {
            if (!session?.file || !isMatUsable(frontMat) || !isMatUsable(backMat)) return null;
            const options = {
                docType: 'pvc',
                renderSize: { ...getDocRenderSize('pvc') },
                rotationAngle: 0,
                enhanceSettings: { ...getEnhanceSettings() },
                mode: currentMode
            };
            return {
                id: ++pvcHighQualityTaskSequence,
                type: 'two_page_pdf',
                frontSide: {
                    start: makePvcTwoPageHighQualityStarter(session, 1),
                    fallbackDataUrl: session.frontDataUrl,
                    sourceWidth: frontMat.cols,
                    sourceHeight: frontMat.rows,
                    points: cloneQuad(frontPoints),
                    rotationAngle: 0,
                    enhanceSettings: { ...options.enhanceSettings },
                    mode: options.mode
                },
                backSide: {
                    start: makePvcTwoPageHighQualityStarter(session, 2),
                    fallbackDataUrl: session.backDataUrl,
                    sourceWidth: backMat.cols,
                    sourceHeight: backMat.rows,
                    points: cloneQuad(backPoints),
                    rotationAngle: 0,
                    enhanceSettings: { ...options.enhanceSettings },
                    mode: options.mode
                },
                options
            };
        }

        function queuePvcTwoPageLearningCandidate(session, side, candidate, sourceMat) {
            if (!session?.pdfMeta || !candidate?.points?.length || !isMatUsable(sourceMat)) return;
            const normalizedSide = side === 'back' ? 'back' : 'front';
            const pageNumber = normalizedSide === 'back' ? 2 : 1;
            const rect = pointsToBoundingRect(candidate.points);
            if (!rect) return;
            const template = {
                front: normalizeRect(rect, sourceMat.cols, sourceMat.rows),
                quad: normalizeQuadAgainstMat(candidate.points, sourceMat),
                mode: 'single_side_card',
                single_side: true,
                template_scope: 'two_page_pdf_side',
                page_number: pageNumber,
                paired_page_count: 2,
                preset_version: `two-page-pdf-page-${pageNumber}-auto-candidate`
            };
            const pageMeta = buildPvcTwoPageSideMeta(session.pdfMeta, pageNumber);
            const sourceDataUrl = normalizedSide === 'back' ? session.backDataUrl : session.frontDataUrl;
            const captureMeta = { ...(currentLearningCaptureMeta || {}), side: normalizedSide };
            const selectedDocType = sanitizePvcDocType(pvcAutoCropDocType || session.pdfMeta.doc_type || 'custom_card');
            queueBackgroundLearning(() => savePvcLearnedTemplate(template, {
                quiet: true,
                captureReason: `two_page_pdf_${normalizedSide}_auto_candidate`,
                hasUserCorrection: false,
                confirmedInCropper: false,
                cropSide: normalizedSide,
                sourceDataUrl,
                pdfMeta: pageMeta,
                captureMeta,
                selectedDocType
            }), `Two-page PDF ${normalizedSide} learning`);
        }

        function buildPvcTwoPageSideMeta(baseMeta = {}, pageNumber = 1) {
            const normalizedPage = Number(pageNumber) === 2 ? 2 : 1;
            const clonedMeta = baseMeta && typeof baseMeta === 'object'
                ? JSON.parse(JSON.stringify(baseMeta))
                : {};
            const signatureBase = String(clonedMeta.pdf_signature || 'two-page-pdf').replace(/-page-[12]$/, '');
            return {
                ...clonedMeta,
                pdf_signature: `${signatureBase}-page-${normalizedPage}`,
                source_kind: 'two_page_pdf_single_card_page',
                content_kind: 'single_side_pvc_card',
                page_count: 2,
                page_number: normalizedPage,
                paired_page_count: 2,
                template_scope: 'two_page_pdf_side'
            };
        }

        function getPvcTwoPageLearnedCandidate(session, pageNumber, sourceMat) {
            if (!session?.pdfMeta || !isMatUsable(sourceMat)) return null;
            const pageMeta = buildPvcTwoPageSideMeta(session.pdfMeta, pageNumber);
            const docType = sanitizePvcDocType(pvcAutoCropDocType || pageMeta.doc_type || 'custom_card');
            const learned = findBestPvcLearnedTemplate(pageMeta, docType);
            if (!learned || !isPvcTemplateScopeCompatible(learned, pageMeta) || !isPvcLearnedCoordinateTrusted(learned)) return null;
            const geometry = normalizeTemplatePayload({
                ...(learned.template || {}),
                mode: 'single_side_card',
                single_side: true
            });
            if (!geometry?.front) return null;
            const normalizedQuad = geometry.quad || geometry.front_quad || normalizeTemplateQuad([
                { x: geometry.front.x, y: geometry.front.y },
                { x: geometry.front.x + geometry.front.w, y: geometry.front.y },
                { x: geometry.front.x + geometry.front.w, y: geometry.front.y + geometry.front.h },
                { x: geometry.front.x, y: geometry.front.y + geometry.front.h }
            ]);
            if (!normalizedQuad) return null;
            const points = normalizedQuad.map((point) => ({
                x: point.x * sourceMat.cols,
                y: point.y * sourceMat.rows
            }));
            const areaRatio = getPvcQuadArea(points) / Math.max(1, sourceMat.cols * sourceMat.rows);
            if (!Number.isFinite(areaRatio) || areaRatio < 0.003) return null;
            return {
                points: orderQuadPoints(points),
                areaRatio,
                source: `two_page_saved_page_${Number(pageNumber) === 2 ? 2 : 1}`,
                templateEntry: learned,
                pageMeta
            };
        }

        function createPvcTwoPageManualSeed(sourceMat) {
            if (!isMatUsable(sourceMat)) return null;
            const cardAspect = 85.6 / 53.98;
            let width = sourceMat.cols * 0.88;
            let height = width / cardAspect;
            const maxHeight = sourceMat.rows * 0.88;
            if (height > maxHeight) {
                height = maxHeight;
                width = height * cardAspect;
            }
            const rect = {
                x: Math.max(0, (sourceMat.cols - width) / 2),
                y: Math.max(0, (sourceMat.rows - height) / 2),
                w: Math.max(2, width),
                h: Math.max(2, height)
            };
            return {
                points: rectToPoints(rect),
                areaRatio: (rect.w * rect.h) / Math.max(1, sourceMat.cols * sourceMat.rows),
                source: 'two_page_manual_seed'
            };
        }

        function createPvcFullPageCandidate(sourceMat, source = 'full_page_card') {
            if (!isMatUsable(sourceMat)) return null;
            return {
                points: rectToPoints({ x: 0, y: 0, w: sourceMat.cols, h: sourceMat.rows }),
                areaRatio: 1,
                source
            };
        }

        async function tryApplyPvcTwoPagePdfPair() {
            const session = pendingPvcTwoPagePdf;
            if (!session || currentType !== 'pvc' || !isMatUsable(srcMat)) return false;
            pendingPvcTwoPagePdf = null;
            pvcActiveTemplateMatch = null;
            pvcLockedTemplate = null;
            pvcSingleSideAiMode = false;
            isSingleSide = false;
            syncSingleSideUI();
            let backMat = null;
            let frontWarp = null;
            let backWarp = null;
            try {
                backMat = await loadDataUrlToMat(session.backDataUrl);
                let frontLearned = getPvcTwoPageLearnedCandidate(session, 1, srcMat);
                let backLearned = getPvcTwoPageLearnedCandidate(session, 2, backMat);
                const frontDetected = detectSinglePvcCardOnPage(srcMat);
                const backDetected = detectSinglePvcCardOnPage(backMat);
                const shouldRejectStaleTwoPageCandidate = (learned, detected, sourceMat) => {
                    if (!learned || !detected || !isMatUsable(sourceMat)) return false;
                    const pageAspect = sourceMat.cols / Math.max(1, sourceMat.rows);
                    const detectedSource = String(detected.source || '');
                    const hasTrustedSmallerDetection = detectedSource === 'detected_quad'
                        || detectedSource === 'visible_card_artwork_bounds';
                    if (pageAspect >= 1.20 || !hasTrustedSmallerDetection || Number(detected.areaRatio || 1) >= 0.85) {
                        return false;
                    }

                    // Older builds could learn either the complete portrait page
                    // or the centred manual seed (about 70% x 80%) as the card.
                    // Keep deliberate admin/user corrections, but replace an old
                    // auto-candidate whenever the fresh visual boundary disagrees.
                    const learnedEntry = learned.templateEntry || {};
                    const captureReason = String(learnedEntry.capture_reason || learnedEntry.correction_review?.capture_reason || '').toLowerCase();
                    const presetVersion = String(learnedEntry.template?.preset_version || '').toLowerCase();
                    const explicitlyCorrected = learnedEntry.admin_corrected === true
                        || captureReason.includes('admin_corrected_two_page_pdf_side')
                        || captureReason.includes('user_recrop')
                        || captureReason.includes('approval_fix');
                    const isOldAutoCandidate = captureReason.includes('auto_candidate')
                        || presetVersion.includes('auto-candidate');
                    const learnedArea = Number(learned.areaRatio || 0);
                    if (learnedArea >= 0.90) return true;
                    if (explicitlyCorrected || !isOldAutoCandidate) return false;

                    const learnedRect = pointsToBoundingRect(learned.points);
                    const detectedRect = pointsToBoundingRect(detected.points);
                    if (!learnedRect || !detectedRect) return Math.abs(learnedArea - Number(detected.areaRatio || 0)) >= 0.08;
                    const width = Math.max(1, sourceMat.cols);
                    const height = Math.max(1, sourceMat.rows);
                    const geometryDelta = Math.max(
                        Math.abs(learnedRect.x - detectedRect.x) / width,
                        Math.abs(learnedRect.y - detectedRect.y) / height,
                        Math.abs(learnedRect.w - detectedRect.w) / width,
                        Math.abs(learnedRect.h - detectedRect.h) / height
                    );
                    return geometryDelta >= 0.08 || Math.abs(learnedArea - Number(detected.areaRatio || 0)) >= 0.08;
                };
                if (shouldRejectStaleTwoPageCandidate(frontLearned, frontDetected, srcMat)) {
                    recordAiActivity('pvc_two_page_stale_candidate_rejected', { page_number: 1 });
                    frontLearned = null;
                }
                if (shouldRejectStaleTwoPageCandidate(backLearned, backDetected, backMat)) {
                    recordAiActivity('pvc_two_page_stale_candidate_rejected', { page_number: 2 });
                    backLearned = null;
                }
                const frontCandidate = frontLearned
                    || frontDetected
                    || createPvcTwoPageManualSeed(srcMat);
                const backCandidate = backLearned
                    || backDetected
                    || createPvcTwoPageManualSeed(backMat);
                if (!frontCandidate || !backCandidate) return false;

                const previewOptions = {
                    docType: 'pvc',
                    renderSize: { width: DOC_TYPES.pvc.w, height: DOC_TYPES.pvc.h },
                    rotationAngle: 0,
                    enhanceSettings: { ...getEnhanceSettings() },
                    mode: currentMode
                };
                frontWarp = createWarpedCardFromSourcePointsWithOptions(srcMat, frontCandidate.points, previewOptions);
                backWarp = createWarpedCardFromSourcePointsWithOptions(backMat, backCandidate.points, previewOptions);
                const highQualityTask = capturePvcTwoPageHighQualityTask(
                    session,
                    srcMat,
                    frontCandidate.points,
                    backMat,
                    backCandidate.points
                );

                safeDeleteMat(tempDocs.front);
                safeDeleteMat(tempDocs.back);
                tempDocs.front = frontWarp;
                tempDocs.back = backWarp;
                frontWarp = null;
                backWarp = null;
                pendingPvcHighQualityTask = highQualityTask;
                pendingPvcCropDescriptors = {
                    front: createPvcDescriptorForSource(frontCandidate.points, srcMat),
                    back: createPvcDescriptorForSource(backCandidate.points, backMat)
                };
                pvcSingleSideAiMode = false;
                isSingleSide = false;
                pendingPvcPdfDualFlow = false;
                recordAiActivity('pvc_two_page_pdf_paired', {
                    page_count: 2,
                    front_detection: frontCandidate.source,
                    back_detection: backCandidate.source
                });
                if (!frontLearned) queuePvcTwoPageLearningCandidate(session, 'front', frontCandidate, srcMat);
                if (!backLearned) queuePvcTwoPageLearningCandidate(session, 'back', backCandidate, backMat);
                closeCropper();
                const addedItem = await addToSheet({
                    pvcSourceDataUrl: session.frontDataUrl,
                    pvcFrontSourceDataUrl: session.frontDataUrl,
                    pvcBackSourceDataUrl: session.backDataUrl,
                    pvcLearningMeta: { ...session.pdfMeta, template_scope: 'two_page_pdf' },
                    pvcFrontLearningMeta: buildPvcTwoPageSideMeta(session.pdfMeta, 1),
                    pvcBackLearningMeta: buildPvcTwoPageSideMeta(session.pdfMeta, 2),
                    pvcLearningCaptureMeta: currentLearningCaptureMeta,
                    pvcFrontCaptureMeta: { ...(currentLearningCaptureMeta || {}), side: 'front' },
                    pvcBackCaptureMeta: { ...(currentLearningCaptureMeta || {}), side: 'back' },
                    pvcTwoPagePair: true
                });
                if (!addedItem?.pvcTwoPagePair) throw new Error('2-page PVC item was not committed');
                pvcTwoPageAutoCompleted = true;
                const needsManualReview = frontCandidate.source === 'two_page_manual_seed' || backCandidate.source === 'two_page_manual_seed';
                document.getElementById('mobStatus').innerText = needsManualReview
                    ? 'PDF Page 1 Front + Page 2 Back added. Zarurat ho to Re-Crop karein.'
                    : 'PDF Page 1 Front + Page 2 Back added.';
                return true;
            } catch (error) {
                console.warn('2-page PVC auto pair skipped; normal crop remains available', error);
                const committedItem = batchQueue.find((item) => item?.pvcTwoPagePair
                    && item.frontSourceDataUrl === session.frontDataUrl
                    && item.backSourceDataUrl === session.backDataUrl);
                if (committedItem) {
                    pvcTwoPageAutoCompleted = true;
                    return true;
                }
                safeDeleteMat(tempDocs.front);
                safeDeleteMat(tempDocs.back);
                tempDocs.front = null;
                tempDocs.back = null;
                pendingPvcHighQualityTask = null;
                pendingPvcCropDescriptors = { front: null, back: null };
                pvcTwoPageAutoCompleted = false;
                return false;
            } finally {
                safeDeleteMat(backMat);
                safeDeleteMat(frontWarp);
                safeDeleteMat(backWarp);
            }
        }

        function setAutoPvcCropPoints() {
            if (!isMatUsable(displayMat) || currentType !== 'pvc') return false;
            const detected = detectPvcQuad(displayMat);
            if (detected && detected.length === 4) {
                cropperPoints = normalizePvcCardBoxPoints(detected);
                drawCanvas();
                return true;
            }
            return false;
        }

        function shiftQuad(quad, dx = 0, dy = 0) {
            return (quad || []).map((p) => ({ x: p.x + dx, y: p.y + dy }));
        }

        function getQuadCenter(quad) {
            const sum = quad.reduce((acc, p) => ({ x: acc.x + p.x, y: acc.y + p.y }), { x: 0, y: 0 });
            return { x: sum.x / 4, y: sum.y / 4 };
        }

        function getDefaultPvcDualQuads(mat) {
            const w = mat.cols, h = mat.rows, aspect = DOC_TYPES.pvc.aspect;
            let boxH = h * 0.29;
            let boxW = boxH * aspect;
            if (boxW > w * 0.9) {
                boxW = w * 0.9;
                boxH = boxW / aspect;
            }
            const cx = w / 2;
            const topCy = h * 0.32;
            const bottomCy = h * 0.72;
            const mk = (cy) => ([
                { x: cx - boxW / 2, y: cy - boxH / 2 },
                { x: cx + boxW / 2, y: cy - boxH / 2 },
                { x: cx + boxW / 2, y: cy + boxH / 2 },
                { x: cx - boxW / 2, y: cy + boxH / 2 }
            ]);
            return { front: mk(topCy), back: mk(bottomCy) };
        }

        function detectPvcDualQuads(mat) {
            if (!mat) return null;
            try {
                const halfY = Math.floor(mat.rows / 2);
                const topRoi = mat.roi(new cv.Rect(0, 0, mat.cols, halfY));
                const bottomRoi = mat.roi(new cv.Rect(0, halfY, mat.cols, mat.rows - halfY));

                const topQuad = detectPvcQuad(topRoi);
                const bottomQuad = detectPvcQuad(bottomRoi);

                topRoi.delete();
                bottomRoi.delete();

                if (topQuad?.length === 4 && bottomQuad?.length === 4) {
                    return {
                        front: orderQuadPoints(shiftQuad(topQuad, 0, 0)),
                        back: orderQuadPoints(shiftQuad(bottomQuad, 0, halfY))
                    };
                }
            } catch (err) {
                console.error('PVC dual detect error', err);
            }
            return null;
        }

        function detectPvcCardPairVisual(mat) {
            let gray = null, blur = null, edges = null, contours = null, hierarchy = null;
            try {
                if (!isMatUsable(mat)) return null;
                gray = new cv.Mat();
                blur = new cv.Mat();
                edges = new cv.Mat();
                contours = new cv.MatVector();
                hierarchy = new cv.Mat();
                cv.cvtColor(mat, gray, cv.COLOR_RGBA2GRAY);
                cv.GaussianBlur(gray, blur, new cv.Size(5, 5), 0);
                cv.Canny(blur, edges, 45, 155);
                cv.findContours(edges, contours, hierarchy, cv.RETR_EXTERNAL, cv.CHAIN_APPROX_SIMPLE);
                const pageArea = Math.max(1, mat.cols * mat.rows);
                const candidates = [];
                for (let i = 0; i < contours.size(); i++) {
                    const cnt = contours.get(i);
                    const area = cv.contourArea(cnt);
                    const rectCv = cv.boundingRect(cnt);
                    cnt.delete();
                    const rect = { x: rectCv.x, y: rectCv.y, w: rectCv.width, h: rectCv.height };
                    const areaRatio = (rect.w * rect.h) / pageArea;
                    const aspectLong = Math.max(rect.w / Math.max(1, rect.h), rect.h / Math.max(1, rect.w));
                    const widthRatio = rect.w / Math.max(1, mat.cols);
                    const heightRatio = rect.h / Math.max(1, mat.rows);
                    if (areaRatio < 0.012 || areaRatio > 0.26) continue;
                    if (aspectLong < 1.22 || aspectLong > 2.25) continue;
                    if (widthRatio > 0.82 || heightRatio > 0.58) continue;
                    candidates.push({ ...rect, areaRatio, aspectLong, centerX: rect.x + rect.w / 2, centerY: rect.y + rect.h / 2 });
                }
                candidates.sort((a, b) => (b.areaRatio - a.areaRatio));
                const unique = [];
                candidates.forEach((candidate) => {
                    if (unique.some((item) => rectIou(item, candidate) > 0.62)) return;
                    unique.push(candidate);
                });
                let best = null;
                let bestScore = -Infinity;
                for (let i = 0; i < unique.length; i++) {
                    for (let j = i + 1; j < unique.length; j++) {
                        const a = unique[i];
                        const b = unique[j];
                        if (rectIou(a, b) > 0.12) continue;
                        const areaSimilarity = Math.min(a.areaRatio, b.areaRatio) / Math.max(a.areaRatio, b.areaRatio);
                        const aspectSimilarity = 1 - Math.min(1, Math.abs(a.aspectLong - b.aspectLong) / 0.65);
                        const sameRow = 1 - Math.min(1, Math.abs(a.centerY - b.centerY) / Math.max(1, mat.rows * 0.28));
                        const sameColumn = 1 - Math.min(1, Math.abs(a.centerX - b.centerX) / Math.max(1, mat.cols * 0.30));
                        const layoutScore = Math.max(sameRow, sameColumn * 0.82);
                        const score = areaSimilarity * 0.38 + aspectSimilarity * 0.30 + layoutScore * 0.32;
                        if (score > bestScore) {
                            bestScore = score;
                            best = { front: a, back: b, score };
                        }
                    }
                }
                return best && best.score >= 0.56 ? best : null;
            } catch (err) {
                console.warn('PVC visual pair check failed', err);
                return null;
            } finally {
                if (gray) gray.delete();
                if (blur) blur.delete();
                if (edges) edges.delete();
                if (contours) contours.delete();
                if (hierarchy) hierarchy.delete();
            }
        }

        function detectAyushmanWideSinglePagePair(mat) {
            if (!isMatUsable(mat)) return null;
            const pageAspect = mat.cols / Math.max(1, mat.rows);
            // Two landscape PVC sides placed horizontally are normally about
            // 2.5-3.4:1.  Keeping this gate narrow avoids changing the many
            // portrait/A4/single-card Ayushman PDF variants.
            if (pageAspect < 2.35 || pageAspect > 3.80) return null;

            const splitX = Math.floor(mat.cols / 2);
            const detectHalf = (x, width, role) => {
                let roi = null;
                try {
                    roi = mat.roi(new cv.Rect(x, 0, width, mat.rows));
                    let localPoints = detectPvcQuad(roi, 0.05);
                    let source = 'detected_quad';
                    if (localPoints?.length === 4) {
                        const ordered = orderQuadPoints(localPoints);
                        const cardWidth = Math.max(dist2D(ordered[0], ordered[1]), dist2D(ordered[3], ordered[2]));
                        const cardHeight = Math.max(dist2D(ordered[0], ordered[3]), dist2D(ordered[1], ordered[2]));
                        const cardAspect = cardWidth / Math.max(1, cardHeight);
                        const areaRatio = getPvcQuadArea(ordered) / Math.max(1, roi.cols * roi.rows);
                        // Reject QR/text-box contours; a side in this generator
                        // occupies a substantial part of its half page.
                        if (cardAspect < 1.22 || cardAspect > 2.20 || areaRatio < 0.30) {
                            localPoints = null;
                        } else {
                            localPoints = ordered;
                        }
                    }

                    if (!localPoints) {
                        const visible = detectVisiblePvcContentBounds(roi, 1);
                        if (visible?.points?.length === 4 && Number(visible.areaRatio || 0) >= 0.30) {
                            localPoints = visible.points;
                            source = visible.source || 'visible_card_artwork_bounds';
                        }
                    }

                    if (!localPoints) {
                        const halfAspect = roi.cols / Math.max(1, roi.rows);
                        if (halfAspect < 1.25 || halfAspect > 1.95) return null;
                        // The PDF page itself is a side-by-side card strip.  A
                        // tiny inset removes the split seam without clipping the
                        // printed outer border.
                        const insetX = Math.max(1, roi.cols * 0.002);
                        const insetY = Math.max(1, roi.rows * 0.002);
                        localPoints = rectToPoints({
                            x: insetX,
                            y: insetY,
                            w: roi.cols - (insetX * 2),
                            h: roi.rows - (insetY * 2)
                        });
                        source = 'wide_pair_half_page';
                    }

                    return {
                        role,
                        source,
                        points: orderQuadPoints(localPoints).map((point) => ({
                            x: point.x + x,
                            y: point.y
                        }))
                    };
                } catch (error) {
                    console.warn(`Ayushman ${role} pair detection skipped`, error);
                    return null;
                } finally {
                    safeDeleteMat(roi);
                }
            };

            const front = detectHalf(0, splitX, 'front');
            const back = detectHalf(splitX, mat.cols - splitX, 'back');
            return front && back ? { front, back, source: 'ayushman_wide_single_page_pair' } : null;
        }

        function promoteAyushmanSinglePageFallbackToVisualPair(sourceMat) {
            const meta = pvcActivePdfMeta || {};
            const isUnconfiguredFallback = currentType === 'pvc'
                && meta.full_page_card_fallback === true
                && isAyushmanSinglePagePdf(meta, pvcAutoCropDocType)
                && !PVC_DEFAULT_TEMPLATE_OVERRIDE_TYPES.has('ayushman')
                && !!pvcLockedTemplate?.single_side;
            if (!isUnconfiguredFallback) return false;

            const pair = detectAyushmanWideSinglePagePair(sourceMat);
            if (!pair) return false;
            const frontRect = pointsToBoundingRect(pair.front.points);
            const backRect = pointsToBoundingRect(pair.back.points);
            if (!frontRect || !backRect) return false;

            const template = normalizeTemplatePayload({
                front: normalizeRect(frontRect, sourceMat.cols, sourceMat.rows),
                back: normalizeRect(backRect, sourceMat.cols, sourceMat.rows),
                doc_type: 'ayushman',
                template_scope: 'single_page_pdf',
                page_number: 1,
                paired_page_count: 0,
                preset_version: 'ayushman-wide-single-page-visual-pair-v1'
            });
            if (!template?.front || !template?.back) return false;

            pvcLockedTemplate = template;
            pvcActiveTemplateMatch = null;
            pvcTemplateNeedsManualReview = false;
            pvcSingleSideAiMode = false;
            isSingleSide = false;
            setPvcActivePdfMeta({
                ...meta,
                doc_type: 'ayushman',
                doc_label: getPvcDocTypeLabel('ayushman'),
                content_kind: 'id_card',
                full_page_card_fallback: false,
                visual_card_pair_detected: true,
                visual_pair_source: pair.source
            });
            pvcActiveCropSourceInfo = {
                crop_source: 'ayushman_single_page_visual_pair',
                doc_type: 'ayushman',
                doc_label: getPvcDocTypeLabel('ayushman'),
                match_reason: 'Front and Back detected side-by-side on one PDF page'
            };
            syncSingleSideUI();
            recordAiActivity('ayushman_single_page_pair_detected', {
                page_aspect: Number((sourceMat.cols / Math.max(1, sourceMat.rows)).toFixed(4)),
                front_detection: pair.front.source,
                back_detection: pair.back.source
            });
            return true;
        }

        function detectAadhaarLikeVisual(mat) {
            try {
                if (!isMatUsable(mat)) return false;
                const sourceCanvas = document.createElement('canvas');
                cv.imshow(sourceCanvas, mat);
                const maxDim = 720;
                const ratio = Math.min(1, maxDim / Math.max(sourceCanvas.width || 1, sourceCanvas.height || 1));
                const c = document.createElement('canvas');
                c.width = Math.max(1, Math.round(sourceCanvas.width * ratio));
                c.height = Math.max(1, Math.round(sourceCanvas.height * ratio));
                const ctx = c.getContext('2d', { willReadFrequently: true });
                ctx.drawImage(sourceCanvas, 0, 0, c.width, c.height);
                const image = ctx.getImageData(0, 0, c.width, c.height).data;
                const rowOrange = new Array(c.height).fill(0);
                const rowGreen = new Array(c.height).fill(0);
                const colOrange = new Array(c.width).fill(0);
                const colGreen = new Array(c.width).fill(0);
                for (let y = 0; y < c.height; y += 2) {
                    for (let x = 0; x < c.width; x += 2) {
                        const idx = (y * c.width + x) * 4;
                        const r = image[idx] || 0;
                        const g = image[idx + 1] || 0;
                        const b = image[idx + 2] || 0;
                        const orange = r > 168 && g > 65 && g < 188 && b < 128 && r > g * 1.08;
                        const green = g > 95 && r < 145 && b < 145 && g > r * 1.16;
                        if (orange) {
                            rowOrange[y]++;
                            colOrange[x]++;
                        }
                        if (green) {
                            rowGreen[y]++;
                            colGreen[x]++;
                        }
                    }
                }
                const rowThreshold = Math.max(5, c.width * 0.018);
                const colThreshold = Math.max(5, c.height * 0.014);
                const orangeRows = rowOrange.filter((v) => v >= rowThreshold).length;
                const greenRows = rowGreen.filter((v) => v >= rowThreshold).length;
                const orangeCols = colOrange.filter((v) => v >= colThreshold).length;
                const greenCols = colGreen.filter((v) => v >= colThreshold).length;
                const hasBandColors = orangeRows >= 2
                    && greenRows >= 2
                    && orangeCols >= c.width * 0.045
                    && greenCols >= c.width * 0.045;
                if (!hasBandColors) return false;
                const pair = detectPvcCardPairVisual(mat);
                return !!pair || (orangeRows + greenRows >= 6 && orangeCols + greenCols >= c.width * 0.14);
            } catch (err) {
                console.warn('Aadhaar visual check failed', err);
                return false;
            }
        }

        function protectKnownVisualCardFromA4(reason = 'visual_card_detected') {
            if (currentType !== 'pvc' || !isMatUsable(displayMat)) return false;
            if (!detectAadhaarLikeVisual(displayMat)) return false;
            if (pvcActivePdfMeta) {
                setPvcActivePdfMeta({
                    ...pvcActivePdfMeta,
                    doc_type: 'aadhaar',
                    doc_label: 'Aadhaar Card',
                    content_kind: 'id_card',
                    visual_card_pair_detected: true,
                    visual_doc_guard: reason
                });
            }
            setPvcAutoCropDocType('aadhaar');
            const aadhaarTemplate = getDefaultPvcTemplate('aadhaar');
            if (aadhaarTemplate) {
                pvcLockedTemplate = JSON.parse(JSON.stringify(aadhaarTemplate));
            }
            syncPvcDocTypeUI();
            return true;
        }

        function setThumbBySide(side, url) {
            if (side === 'front') {
                document.getElementById('thumbFront').src = url;
                document.getElementById('thumbFront').classList.remove('hidden');
                document.getElementById('checkFront').classList.remove('hidden');
                document.getElementById('mobThumbFront').src = url;
                document.getElementById('mobThumbFront').classList.remove('hidden');
            } else {
                document.getElementById('thumbBack').src = url;
                document.getElementById('thumbBack').classList.remove('hidden');
                document.getElementById('checkBack').classList.remove('hidden');
                document.getElementById('mobThumbBack').src = url;
                document.getElementById('mobThumbBack').classList.remove('hidden');
            }
        }

        function rectToPoints(rect) {
            return [
                { x: rect.x, y: rect.y },
                { x: rect.x + rect.w, y: rect.y },
                { x: rect.x + rect.w, y: rect.y + rect.h },
                { x: rect.x, y: rect.y + rect.h }
            ];
        }

        function usesFixedPvcCardBoxCropper() {
            if (currentType !== 'pvc' || pvcTemplatePlacementMode) return false;
            if (DOCALIGNER_TEST_MODE && pvcSingleSideAiMode) return false;
            if (pvcApprovalFixState?.templateId && getPvcApprovalTeachMode() === 'a4_document') return false;
            return pvcA4CorrectionMode !== 'a4_document';
        }

        function normalizePvcCardBoxPoints(points) {
            const rect = pointsToBoundingRect(points);
            return rect ? rectToPoints(rect) : cloneQuad(points || []);
        }

        function resizeFixedPvcCardBoxCorner(index, pointerX, pointerY) {
            const points = normalizePvcCardBoxPoints(cropperPoints);
            if (points.length !== 4 || index < 0 || index > 3) return;
            const opposite = points[[2, 3, 0, 1][index]];
            const minSize = Math.max(20, Math.min(canvas.width, canvas.height) * 0.025);
            let left;
            let top;
            let right;
            let bottom;
            if (index === 0) {
                left = Math.max(0, Math.min(pointerX, opposite.x - minSize));
                top = Math.max(0, Math.min(pointerY, opposite.y - minSize));
                right = opposite.x;
                bottom = opposite.y;
            } else if (index === 1) {
                left = opposite.x;
                top = Math.max(0, Math.min(pointerY, opposite.y - minSize));
                right = Math.min(canvas.width, Math.max(pointerX, opposite.x + minSize));
                bottom = opposite.y;
            } else if (index === 2) {
                left = opposite.x;
                top = opposite.y;
                right = Math.min(canvas.width, Math.max(pointerX, opposite.x + minSize));
                bottom = Math.min(canvas.height, Math.max(pointerY, opposite.y + minSize));
            } else {
                left = Math.max(0, Math.min(pointerX, opposite.x - minSize));
                top = opposite.y;
                right = opposite.x;
                bottom = Math.min(canvas.height, Math.max(pointerY, opposite.y + minSize));
            }
            cropperPoints = rectToPoints({ x: left, y: top, w: right - left, h: bottom - top });
        }

        function normalizeRect(rect, w, h) {
            return {
                x: +(rect.x / w).toFixed(6),
                y: +(rect.y / h).toFixed(6),
                w: +(rect.w / w).toFixed(6),
                h: +(rect.h / h).toFixed(6)
            };
        }

        function denormalizeRect(rectN, w, h) {
            return {
                x: rectN.x * w,
                y: rectN.y * h,
                w: rectN.w * w,
                h: rectN.h * h
            };
        }

        function getDefaultPvcTemplateBoxes(mat, docType = pvcAutoCropDocType) {
            const w = mat.cols;
            const h = mat.rows;
            const template = getDefaultPvcTemplate(docType);
            if (template?.front && template?.back) {
                return {
                    front: denormalizeRect(template.front, w, h),
                    back: denormalizeRect(template.back, w, h)
                };
            }
            const fallback = getDefaultPvcTemplate('aadhaar');
            return {
                front: denormalizeRect(fallback.front, w, h),
                back: denormalizeRect(fallback.back, w, h)
            };
        }

        function pointInRect(x, y, rect) {
            return !!rect && x >= rect.x && x <= (rect.x + rect.w) && y >= rect.y && y <= (rect.y + rect.h);
        }

        function getPvcTemplateHandles(rect) {
            if (!rect) return [];
            const cx = rect.x + (rect.w / 2);
            const cy = rect.y + (rect.h / 2);
            return [
                { mode: 'resize-left-top', x: rect.x, y: rect.y },
                { mode: 'resize-top', x: cx, y: rect.y },
                { mode: 'resize-right-top', x: rect.x + rect.w, y: rect.y },
                { mode: 'resize-right', x: rect.x + rect.w, y: cy },
                { mode: 'resize-right-bottom', x: rect.x + rect.w, y: rect.y + rect.h },
                { mode: 'resize-bottom', x: cx, y: rect.y + rect.h },
                { mode: 'resize-left-bottom', x: rect.x, y: rect.y + rect.h },
                { mode: 'resize-left', x: rect.x, y: cy }
            ];
        }

        function hitPvcTemplateTarget(x, y) {
            const hitRadius = Math.max(10, 24 / Math.max(editorZoom, 0.25));
            let best = null;
            ['front', 'back'].forEach((key) => {
                const rect = pvcTemplateBoxes[key];
                getPvcTemplateHandles(rect).forEach((handle) => {
                    const d = Math.hypot(x - handle.x, y - handle.y);
                    if (d <= hitRadius && (!best || d < best.d)) best = { key, mode: handle.mode, d };
                });
            });
            if (best) return best;
            if (pointInRect(x, y, pvcTemplateBoxes.front)) return { key: 'front', mode: 'move' };
            if (pointInRect(x, y, pvcTemplateBoxes.back)) return { key: 'back', mode: 'move' };
            return null;
        }

        function syncPvcTemplateScaleFromBox(box) {
            if (!box || !pvcTemplateBaseBox.w || !pvcTemplateBaseBox.h) return;
            pvcTemplateScale.w = Math.max(40, Math.min(220, Math.round((box.w / pvcTemplateBaseBox.w) * 100)));
            pvcTemplateScale.h = Math.max(40, Math.min(220, Math.round((box.h / pvcTemplateBaseBox.h) * 100)));
            syncPvcSizeUi();
        }

        function resizePvcTemplateBox(box, mode, x, y) {
            if (!box || !pvcTemplateDragStart) return;
            const start = pvcTemplateDragStart.rect;
            const minW = Math.max(28, pvcTemplateBaseBox.w * 0.28);
            const minH = Math.max(18, pvcTemplateBaseBox.h * 0.28);
            const right = start.x + start.w;
            const bottom = start.y + start.h;
            let nextX = start.x;
            let nextY = start.y;
            let nextW = start.w;
            let nextH = start.h;
            if (mode.includes('left')) {
                nextX = Math.max(0, Math.min(x, right - minW));
                nextW = right - nextX;
            }
            if (mode.includes('right')) {
                nextW = Math.max(minW, Math.min(x - start.x, canvas.width - start.x));
            }
            if (mode.includes('top')) {
                nextY = Math.max(0, Math.min(y, bottom - minH));
                nextH = bottom - nextY;
            }
            if (mode.includes('bottom')) {
                nextH = Math.max(minH, Math.min(y - start.y, canvas.height - start.y));
            }
            box.x = nextX;
            box.y = nextY;
            box.w = nextW;
            box.h = nextH;
            clampTemplateRect(box);
            syncPvcTemplateScaleFromBox(box);
        }

        function getUnionRect(rects) {
            const valid = rects.filter(Boolean);
            if (!valid.length) return null;
            const left = Math.min(...valid.map((r) => r.x));
            const top = Math.min(...valid.map((r) => r.y));
            const right = Math.max(...valid.map((r) => r.x + r.w));
            const bottom = Math.max(...valid.map((r) => r.y + r.h));
            return { x: left, y: top, w: right - left, h: bottom - top };
        }

        function expandRectWithin(rect, mat, padX, padY) {
            const x = Math.max(0, Math.floor(rect.x - padX));
            const y = Math.max(0, Math.floor(rect.y - padY));
            const right = Math.min(mat.cols, Math.ceil(rect.x + rect.w + padX));
            const bottom = Math.min(mat.rows, Math.ceil(rect.y + rect.h + padY));
            return { x, y, w: Math.max(1, right - x), h: Math.max(1, bottom - y) };
        }

        function rectCenter(rect) {
            return { x: rect.x + rect.w / 2, y: rect.y + rect.h / 2 };
        }

        function rectIou(a, b) {
            const x1 = Math.max(a.x, b.x);
            const y1 = Math.max(a.y, b.y);
            const x2 = Math.min(a.x + a.w, b.x + b.w);
            const y2 = Math.min(a.y + a.h, b.y + b.h);
            const iw = Math.max(0, x2 - x1);
            const ih = Math.max(0, y2 - y1);
            const inter = iw * ih;
            const union = (a.w * a.h) + (b.w * b.h) - inter;
            return union > 0 ? inter / union : 0;
        }

        function detectPvcRectNearTemplate(mat, expectedRect) {
            if (!isMatUsable(mat) || !expectedRect) return null;
            let roi = null, gray = null, blur = null, edges = null, closed = null, kernel = null, contours = null, hierarchy = null;
            try {
                const search = expandRectWithin(
                    expectedRect,
                    mat,
                    Math.max(45, expectedRect.w * 0.42),
                    Math.max(45, expectedRect.h * 0.55)
                );
                roi = mat.roi(new cv.Rect(search.x, search.y, search.w, search.h));
                gray = new cv.Mat();
                blur = new cv.Mat();
                edges = new cv.Mat();
                closed = new cv.Mat();
                contours = new cv.MatVector();
                hierarchy = new cv.Mat();
                kernel = cv.Mat.ones(5, 5, cv.CV_8U);

                cv.cvtColor(roi, gray, cv.COLOR_RGBA2GRAY);
                cv.GaussianBlur(gray, blur, new cv.Size(5, 5), 0);
                cv.Canny(blur, edges, 45, 150);
                cv.morphologyEx(edges, closed, cv.MORPH_CLOSE, kernel);
                cv.findContours(closed, contours, hierarchy, cv.RETR_EXTERNAL, cv.CHAIN_APPROX_SIMPLE);

                const expectedAspect = expectedRect.w / Math.max(1, expectedRect.h);
                const expectedArea = expectedRect.w * expectedRect.h;
                const expectedCenter = rectCenter(expectedRect);
                let bestRect = null;
                let bestScore = Infinity;

                for (let i = 0; i < contours.size(); i++) {
                    const cnt = contours.get(i);
                    const area = Math.abs(cv.contourArea(cnt));
                    if (area < expectedArea * 0.20) { cnt.delete(); continue; }
                    const rr = cv.boundingRect(cnt);
                    cnt.delete();

                    const candidate = {
                        x: rr.x + search.x,
                        y: rr.y + search.y,
                        w: rr.width,
                        h: rr.height
                    };
                    const aspect = candidate.w / Math.max(1, candidate.h);
                    const areaRatio = (candidate.w * candidate.h) / Math.max(1, expectedArea);
                    if (areaRatio < 0.48 || areaRatio > 1.75) continue;
                    const aspectDiff = Math.abs(aspect - expectedAspect) / Math.max(expectedAspect, 0.01);
                    if (aspectDiff > 0.28) continue;
                    const center = rectCenter(candidate);
                    const dx = Math.abs(center.x - expectedCenter.x) / Math.max(1, expectedRect.w);
                    const dy = Math.abs(center.y - expectedCenter.y) / Math.max(1, expectedRect.h);
                    if (dx > 0.42 || dy > 0.55) continue;
                    const iou = rectIou(candidate, expectedRect);
                    if (iou < 0.32) continue;

                    const sizePenalty = Math.abs(Math.log(areaRatio));
                    const score = (aspectDiff * 1.4) + (dx * 0.9) + (dy * 0.9) + (sizePenalty * 0.35) + ((1 - iou) * 0.6);
                    if (score < bestScore) {
                        bestScore = score;
                        bestRect = candidate;
                    }
                }

                if (!bestRect || bestScore > 1.12) return null;
                return bestRect;
            } catch (err) {
                console.warn('PVC near-template detect failed', err);
                return null;
            } finally {
                safeDeleteMat(roi);
                safeDeleteMat(gray);
                safeDeleteMat(blur);
                safeDeleteMat(edges);
                safeDeleteMat(closed);
                safeDeleteMat(kernel);
                safeDeleteMat(contours);
                safeDeleteMat(hierarchy);
            }
        }

        function scoreCandidateRect(candidate, expectedRect) {
            const expectedAspect = expectedRect.w / Math.max(1, expectedRect.h);
            const expectedArea = expectedRect.w * expectedRect.h;
            const expectedCenter = rectCenter(expectedRect);
            const aspect = candidate.w / Math.max(1, candidate.h);
            const areaRatio = (candidate.w * candidate.h) / Math.max(1, expectedArea);
            if (areaRatio < 0.42 || areaRatio > 1.9) return Infinity;
            const aspectDiff = Math.abs(aspect - expectedAspect) / Math.max(expectedAspect, 0.01);
            if (aspectDiff > 0.32) return Infinity;
            const center = rectCenter(candidate);
            const dx = Math.abs(center.x - expectedCenter.x) / Math.max(1, expectedRect.w);
            const dy = Math.abs(center.y - expectedCenter.y) / Math.max(1, expectedRect.h);
            if (dx > 0.55 || dy > 0.75) return Infinity;
            const iou = rectIou(candidate, expectedRect);
            if (iou < 0.22) return Infinity;
            const sizePenalty = Math.abs(Math.log(areaRatio));
            return (aspectDiff * 1.25) + (dx * 0.75) + (dy * 0.75) + (sizePenalty * 0.35) + ((1 - iou) * 0.52);
        }

        function detectPvcContentRectNearTemplate(mat, expectedRect) {
            if (!isMatUsable(mat) || !expectedRect) return null;
            let roi = null, gray = null, mask = null, closed = null, kernel = null, contours = null, hierarchy = null;
            try {
                const search = expandRectWithin(
                    expectedRect,
                    mat,
                    Math.max(70, expectedRect.w * 0.55),
                    Math.max(70, expectedRect.h * 0.85)
                );
                roi = mat.roi(new cv.Rect(search.x, search.y, search.w, search.h));
                gray = new cv.Mat();
                mask = new cv.Mat();
                closed = new cv.Mat();
                contours = new cv.MatVector();
                hierarchy = new cv.Mat();
                kernel = cv.Mat.ones(9, 9, cv.CV_8U);

                cv.cvtColor(roi, gray, cv.COLOR_RGBA2GRAY);
                cv.threshold(gray, mask, 244, 255, cv.THRESH_BINARY_INV);
                cv.morphologyEx(mask, closed, cv.MORPH_CLOSE, kernel);
                cv.dilate(closed, closed, kernel);
                cv.findContours(closed, contours, hierarchy, cv.RETR_EXTERNAL, cv.CHAIN_APPROX_SIMPLE);

                let best = null;
                let bestScore = Infinity;
                const minArea = expectedRect.w * expectedRect.h * 0.18;
                for (let i = 0; i < contours.size(); i++) {
                    const cnt = contours.get(i);
                    const area = Math.abs(cv.contourArea(cnt));
                    if (area < minArea) { cnt.delete(); continue; }
                    const rr = cv.boundingRect(cnt);
                    cnt.delete();
                    const candidate = {
                        x: rr.x + search.x,
                        y: rr.y + search.y,
                        w: rr.width,
                        h: rr.height
                    };
                    const score = scoreCandidateRect(candidate, expectedRect);
                    if (score < bestScore) {
                        bestScore = score;
                        best = candidate;
                    }
                }
                if (!best || bestScore > 1.18) return null;
                const padX = Math.max(2, best.w * 0.015);
                const padY = Math.max(2, best.h * 0.02);
                return expandRectWithin(best, mat, padX, padY);
            } catch (err) {
                console.warn('PVC content detect failed', err);
                return null;
            } finally {
                safeDeleteMat(roi);
                safeDeleteMat(gray);
                safeDeleteMat(mask);
                safeDeleteMat(closed);
                safeDeleteMat(kernel);
                safeDeleteMat(contours);
                safeDeleteMat(hierarchy);
            }
        }

        function getAutoPvcTemplateRectsForMat(mat) {
            if (!pvcLockedTemplate || !isMatUsable(mat)) return null;
            const w = mat.cols;
            const h = mat.rows;
            const activeDocType = sanitizePvcDocType(pvcAutoCropDocType || pvcActivePdfMeta?.doc_type || pvcLockedTemplate?.doc_type || '');
            // This e-EPIC preset is measured on the PDF's printed border. The
            // generic content-refine step deliberately adds 1.5%/2% padding,
            // which puts page-white back outside that border. Keep this exact
            // preset fixed; other Voter/learned layouts can still be refined.
            const exactVoterBorderPreset = activeDocType === 'voter'
                && String(pvcLockedTemplate?.preset_version || '') === String(PVC_TEMPLATE_PRESET_VERSION.voter || '');
            const skipDynamicRefine = activeDocType === 'ration' || exactVoterBorderPreset;
            const dynamicSkippedReason = activeDocType === 'ration'
                ? 'ration_card_color_blocks'
                : (exactVoterBorderPreset ? 'voter_exact_printed_border' : '');
            if (pvcLockedTemplate.single_side || pvcLockedTemplate.mode === 'single_side_card') {
                const fixedFront = denormalizeRect(pvcLockedTemplate.front, w, h);
                if (pvcRecropMode || forcePvcTemplatePlacement || skipDynamicRefine) return { front: fixedFront, back: null, singleSide: true, usedDynamic: false };
                const detectedFront = detectPvcContentRectNearTemplate(mat, fixedFront) || detectPvcRectNearTemplate(mat, fixedFront);
                return {
                    front: detectedFront || fixedFront,
                    back: null,
                    singleSide: true,
                    usedDynamic: !!detectedFront
                };
            }
            const fixed = {
                front: denormalizeRect(pvcLockedTemplate.front, w, h),
                back: denormalizeRect(pvcLockedTemplate.back, w, h)
            };
            if (pvcRecropMode || forcePvcTemplatePlacement || skipDynamicRefine) {
                return {
                    ...fixed,
                    usedDynamic: false,
                    dynamicSkippedReason
                };
            }
            const detectedFront = detectPvcContentRectNearTemplate(mat, fixed.front) || detectPvcRectNearTemplate(mat, fixed.front);
            const detectedBack = detectPvcContentRectNearTemplate(mat, fixed.back) || detectPvcRectNearTemplate(mat, fixed.back);
            return {
                front: detectedFront || fixed.front,
                back: detectedBack || fixed.back,
                usedDynamic: !!(detectedFront || detectedBack)
            };
        }

        function focusEditorOnRect(rect) {
            if (!rect) return;
            const scrollArea = document.getElementById('editorScrollArea');
            const wrapper = document.getElementById('canvasWrapper');
            if (!scrollArea || !wrapper) return;
            const maxZoomForArea = Math.min(
                (scrollArea.clientWidth * 0.82) / Math.max(rect.w, 1),
                (scrollArea.clientHeight * 0.72) / Math.max(rect.h, 1)
            );
            editorZoom = Math.max(1.15, Math.min(4.2, maxZoomForArea));
            document.getElementById('zoomLabel').innerText = Math.round(editorZoom * 100) + "%";
            const zoomedW = canvas.width * editorZoom;
            const zoomedH = canvas.height * editorZoom;
            wrapper.style.width = zoomedW + "px";
            wrapper.style.height = zoomedH + "px";
            canvas.style.transformOrigin = "top left";
            canvas.style.transform = `scale(${editorZoom})`;
            updateEditorScrollMode(zoomedW, zoomedH);
            updateCropHandleOverlay();
            drawCanvas();
            requestAnimationFrame(() => {
                const centerX = (rect.x + rect.w / 2) * editorZoom;
                const centerY = (rect.y + rect.h / 2) * editorZoom;
                scrollArea.scrollLeft = Math.max(0, centerX - (scrollArea.clientWidth / 2));
                scrollArea.scrollTop = Math.max(0, centerY - (scrollArea.clientHeight / 2));
            });
        }

        function drawPvcTemplateBoxes() {
            if (!pvcTemplatePlacementMode || !pvcTemplateBoxes.front || !pvcTemplateBoxes.back) return;
            const front = pvcTemplateBoxes.front;
            const back = pvcTemplateBoxes.back;
            const visualScale = 1 / Math.max(editorZoom, 0.1);

            // Photoshop-style dark outside mask with transparent crop windows
            ctx.save();
            ctx.fillStyle = 'rgba(0, 0, 0, 0.50)';
            ctx.beginPath();
            ctx.rect(0, 0, canvas.width, canvas.height);
            ctx.rect(front.x, front.y, front.w, front.h);
            ctx.rect(back.x, back.y, back.w, back.h);
            ctx.fill('evenodd');
            ctx.restore();

            const drawCornerHandles = (rect, color) => {
                const dot = Math.max(2.7, 4.2 * visualScale);
                const edgeDot = Math.max(1.8, 2.8 * visualScale);
                getPvcTemplateHandles(rect).forEach((handle) => {
                    const isCorner = (handle.mode.includes('left') || handle.mode.includes('right')) && (handle.mode.includes('top') || handle.mode.includes('bottom'));
                    const r = isCorner ? dot : edgeDot;
                    ctx.save();
                    ctx.shadowColor = color;
                    ctx.shadowBlur = 5 * visualScale;
                    ctx.fillStyle = color;
                    ctx.strokeStyle = 'rgba(255,255,255,0.98)';
                    ctx.lineWidth = Math.max(0.9, 1.25 * visualScale);
                    ctx.beginPath();
                    ctx.arc(handle.x, handle.y, r, 0, Math.PI * 2);
                    ctx.fill();
                    ctx.stroke();
                    ctx.restore();
                });
            };

            const drawOne = (rect, label, color) => {
                const mm = getRectSizeMm(rect, canvas.width, canvas.height);
                ctx.save();
                ctx.shadowColor = color;
                ctx.shadowBlur = 10 * visualScale;
                ctx.strokeStyle = 'rgba(255,255,255,0.88)';
                ctx.lineWidth = Math.max(0.8, 1.1 * visualScale);
                ctx.strokeRect(rect.x, rect.y, rect.w, rect.h);
                ctx.shadowBlur = 4 * visualScale;
                ctx.strokeStyle = color;
                ctx.lineWidth = Math.max(0.75, 1.0 * visualScale);
                ctx.setLineDash([7 * visualScale, 5 * visualScale]);
                ctx.strokeRect(rect.x, rect.y, rect.w, rect.h);
                ctx.setLineDash([]);

                const fs = 14 * visualScale;
                const fs2 = 11 * visualScale;
                const pad = 8 * visualScale;
                const titleW = 86 * visualScale;
                const titleH = 18 * visualScale;

                // Label chip
                ctx.fillStyle = 'rgba(15, 23, 42, 0.78)';
                ctx.fillRect(rect.x + pad, rect.y + pad, titleW, titleH);
                ctx.fillStyle = '#ffffff';
                ctx.font = `bold ${fs}px Segoe UI`;
                ctx.fillText(label, rect.x + pad + (6 * visualScale), rect.y + pad + (13 * visualScale));

                // Size label
                ctx.fillStyle = color;
                ctx.font = `bold ${fs2}px Segoe UI`;
                ctx.fillText(`${mm.width_mm}mm x ${mm.height_mm}mm`, rect.x + pad, rect.y + pad + (titleH + 14 * visualScale));
                ctx.restore();
                drawCornerHandles(rect, color);
            };
            drawOne(front, 'FRONT', '#3b82f6');
            drawOne(back, 'BACK', '#22c55e');
        }

        function beginPvcTemplatePlacement() {
            if (!isMatUsable(displayMat)) {
                showModal("Re-Crop Error", "Source image ready nahi hai. File dobara upload karke try karein.", "error");
                return;
            }
            pvcTemplatePlacementMode = true;
            const defaults = getDefaultPvcTemplateBoxes(displayMat, pvcAutoCropDocType);
            const w = displayMat.cols;
            const h = displayMat.rows;
            let starting = {
                front: { ...defaults.front },
                back: { ...defaults.back }
            };
            if (pvcLockedTemplate?.front && pvcLockedTemplate?.back) {
                starting = {
                    front: denormalizeRect(pvcLockedTemplate.front, w, h),
                    back: denormalizeRect(pvcLockedTemplate.back, w, h)
                };
            }
            pvcTemplateBaseBox = { w: defaults.front.w, h: defaults.front.h };
            const defaultScaleW = pvcLockedTemplate?.box_scale_percent?.width || 104;
            const defaultScaleH = pvcLockedTemplate?.box_scale_percent?.height || 115;
            pvcTemplateScale = { w: Math.round(defaultScaleW), h: Math.round(defaultScaleH) };
            pvcTemplateBoxes = {
                front: { ...starting.front },
                back: { ...starting.back }
            };
            clampTemplateRect(pvcTemplateBoxes.front);
            clampTemplateRect(pvcTemplateBoxes.back);
            pvcTemplateOriginalTemplate = {
                front: normalizeRect(pvcTemplateBoxes.front, w, h),
                back: normalizeRect(pvcTemplateBoxes.back, w, h),
                box_scale_percent: { width: pvcTemplateScale.w, height: pvcTemplateScale.h }
            };
            syncPvcSizeUi();
            currentSide = 'front';
            setCropStepUI('Move Front/Back Boxes', 'template');
            document.getElementById('mobStatus').innerText = `${getPvcDocTypeLabel()} box set karein`;
            drawCanvas();
            requestAnimationFrame(() => focusEditorOnRect(getUnionRect([pvcTemplateBoxes.front, pvcTemplateBoxes.back])));
            if (!pvcRecropMode) {
                showModal("Set Crop Boxes", `${getPvcDocTypeLabel()} ke liye boxes drag karein. Chhota/bada karne ke liye corner dots pakdein ya Width/Height sliders use karein, phir TEST CROP karein.`, "info");
            }
        }

        async function applyLockedTemplateToCurrentPdf() {
            if (!pvcLockedTemplate || !isMatUsable(displayMat)) return false;
            try {
                const rects = getAutoPvcTemplateRectsForMat(displayMat);
                if (!rects) return false;
                const replaceIndex = resolvePvcRecropReplaceIndex();
                let ok = false;
                if (rects.singleSide || !rects.back) {
                    ok = await applyPvcSingleAutoCrop(rectToPoints(rects.front), {
                        replaceIndex,
                        sourceDataUrl: getActivePvcCropSourceDataUrl()
                    });
                } else {
                    ok = await applyPvcDualAutoCrop(rectToPoints(rects.front), rectToPoints(rects.back), {
                        replaceIndex,
                        sourceDataUrl: getActivePvcCropSourceDataUrl()
                    });
                }
                if (ok) recordPvcAutoCropMonitor(pvcLockedTemplate, { trigger: rects.singleSide || !rects.back ? 'locked_template_single_auto' : 'locked_template_dual_auto' });
                return ok;
            } catch (err) {
                console.error("Locked template apply failed", err);
                return false;
            }
        }

        async function applyLockedTemplateDirectFromSource(opts = {}) {
            if (!pvcLockedTemplate || !isMatUsable(srcMat)) return false;
            const prevScale = editorScale || 1;
            try {
                const rects = getAutoPvcTemplateRectsForMat(srcMat);
                if (!rects) return false;
                const replaceIndex = resolvePvcRecropReplaceIndex();
                editorScale = 1;
                let ok = false;
                if (rects.singleSide || !rects.back) {
                    ok = await applyPvcSingleAutoCrop(rectToPoints(rects.front), {
                        replaceIndex,
                        sourceDataUrl: getActivePvcCropSourceDataUrl(),
                        fast: opts.fast === true
                    });
                } else {
                    ok = await applyPvcDualAutoCrop(rectToPoints(rects.front), rectToPoints(rects.back), {
                        replaceIndex,
                        sourceDataUrl: getActivePvcCropSourceDataUrl(),
                        fast: opts.fast === true
                    });
                }
                if (ok) recordPvcAutoCropMonitor(pvcLockedTemplate, { trigger: rects.singleSide || !rects.back ? 'direct_template_single_auto' : 'direct_template_dual_auto' });
                return ok;
            } catch (err) {
                console.error("Direct PVC template apply failed", err);
                return false;
            } finally {
                editorScale = prevScale;
            }
        }

        function createWarpedCardFromPoints(displayPoints, options = {}) {
            if (!isMatUsable(srcMat)) throw new Error("Source image is not available. Please upload again.");
            const sourcePoints = displayPoints.map((p) => ({ x: p.x / editorScale, y: p.y / editorScale }));
            return createWarpedCardFromSourcePoints(srcMat, sourcePoints, options);
        }

        function createWarpedCardFromSourcePoints(sourceMat, sourcePoints, options = {}) {
            return createWarpedCardFromSourcePointsWithOptions(sourceMat, sourcePoints, {
                docType: currentType,
                renderSize: getDocRenderSize(currentType),
                rotationAngle,
                enhanceSettings: getEnhanceSettings(),
                mode: currentMode,
                ...options
            });
        }

        function createWarpedCardFromSourcePointsWithOptions(sourceMat, sourcePoints, options = {}) {
            if (!isMatUsable(sourceMat)) throw new Error("Source image is not available. Please upload again.");
            const docType = options.docType || currentType;
            const renderSize = options.renderSize || getDocRenderSize(docType);
            const postWarpRotation = normalizeRightAngle(options.postWarpRotationDegrees || 0);
            // 90/270 degree output ko pehle swapped canvas par perspective-warp
            // karo, phir rotate karo. Isse final ID/PVC size landscape hi rehta
            // hai aur sideways source stretch nahi hota.
            const warpRenderSize = (postWarpRotation === 90 || postWarpRotation === 270)
                ? { width: renderSize.height, height: renderSize.width }
                : renderSize;
            const sourceRotation = Number.isFinite(options.rotationAngle) ? options.rotationAngle : rotationAngle;
            let full = sourceMat;
            let ownsFull = false;
            if (sourceRotation !== 0) {
                ownsFull = true;
                const r = new cv.Mat();
                if (sourceRotation === 90 || sourceRotation === -270) cv.rotate(full, r, cv.ROTATE_90_CLOCKWISE);
                else if (sourceRotation === -90 || sourceRotation === 270) cv.rotate(full, r, cv.ROTATE_90_COUNTERCLOCKWISE);
                else if (Math.abs(sourceRotation) === 180) cv.rotate(full, r, cv.ROTATE_180);
                full = r;
            }

            const pts = [];
            sourcePoints.forEach((p) => pts.push(p.x, p.y));
            const srcTri = cv.matFromArray(4, 1, cv.CV_32FC2, pts);
            const dstTri = cv.matFromArray(4, 1, cv.CV_32FC2, [0, 0, warpRenderSize.width, 0, warpRenderSize.width, warpRenderSize.height, 0, warpRenderSize.height]);
            const M = cv.getPerspectiveTransform(srcTri, dstTri);
            const warped = new cv.Mat();
            const warpInterpolation = docType === 'pvc'
                ? (typeof cv.INTER_LANCZOS4 === 'number' ? cv.INTER_LANCZOS4 : cv.INTER_CUBIC)
                : cv.INTER_LINEAR;
            cv.warpPerspective(full, warped, M, new cv.Size(warpRenderSize.width, warpRenderSize.height), warpInterpolation, cv.BORDER_REPLICATE);

            const effectiveSettings = options.enhanceSettings || getEnhanceSettings();
            const comparison = {
                before: makeComparisonCanvas(warped, postWarpRotation),
                level: effectiveSettings.documentIllumination?.pixel_profile?.level || options.mode || currentMode,
                startedAt: directCropPreparation ? uploadPipelineStartedAt : 0,
                elapsed: null
            };
            applyAdvancedEnhancementWithSettings(
                warped,
                effectiveSettings,
                options.mode || currentMode,
                documentOriginalSourceQuad(sourcePoints, full.cols, full.rows, sourceRotation)
            );

            if (ownsFull) safeDeleteMat(full);
            safeDeleteMat(srcTri);
            safeDeleteMat(dstTri);
            safeDeleteMat(M);
            if (postWarpRotation === 0) {
                if (comparison) enhancementComparisons.set(warped, comparison);
                return warped;
            }
            const oriented = new cv.Mat();
            if (postWarpRotation === 90) cv.rotate(warped, oriented, cv.ROTATE_90_CLOCKWISE);
            else if (postWarpRotation === 180) cv.rotate(warped, oriented, cv.ROTATE_180);
            else cv.rotate(warped, oriented, cv.ROTATE_90_COUNTERCLOCKWISE);
            safeDeleteMat(warped);
            if (comparison) enhancementComparisons.set(oriented, comparison);
            return oriented;
        }

        function getRangeNumber(id, fallback = 0) {
            const el = document.getElementById(id);
            if (!el) return fallback;
            const n = parseFloat(el.value);
            return Number.isFinite(n) ? n : fallback;
        }

        function getEnhanceSettings() {
            const settings = {
                brightness: getRangeNumber('inpBright', 0),
                autoToneStrength: activeGpuExposure?.strength || 0,
                documentIllumination: activeGpuExposure?.illumination || null,
                contrast: getRangeNumber('inpContrast', 0),
                saturation: getRangeNumber('inpSaturation', 0),
                warmth: getRangeNumber('inpWarmth', 0),
                sharpness: getRangeNumber('inpSharp', 0),
                clarity: getRangeNumber('inpClarity', 0)
            };
            if (!isProUser()) {
                settings.saturation = 0;
                settings.warmth = 0;
                settings.sharpness = 0;
                settings.clarity = 0;
            }
            return settings;
        }

        function applyAdvancedEnhancement(mat) {
            applyAdvancedEnhancementWithSettings(mat, getEnhanceSettings(), currentMode,
                documentOriginalSourceQuad([{x:0,y:0},{x:1,y:0},{x:1,y:1},{x:0,y:1}], 1, 1, rotationAngle));
        }

        function applyDocumentShadowCurve(mat, strength) {
            // The shipped OpenCV.js build has no cv.LUT binding. Apply the
            // bounded GPU-selected curve to the existing pixels directly.
            // Alpha is coverage, not brightness; leave it unchanged.
            const lut = new Uint8Array(256);
            for (let i = 0; i < 256; i++) {
                const t = i / 255;
                lut[i] = Math.round(255 * (t + strength * 4 * t * (1 - t) * (1 - t)));
            }
            const channels = mat.channels();
            const colorChannels = channels === 4 ? 3 : channels;
            const applyPixels = (pixels) => {
                for (let offset = 0; offset < pixels.length; offset += channels) {
                    for (let channel = 0; channel < colorChannels; channel++) {
                        pixels[offset + channel] = lut[pixels[offset + channel]];
                    }
                }
            };
            if (mat.isContinuous()) {
                applyPixels(mat.data);
            } else {
                for (let y = 0; y < mat.rows; y++) {
                    const row = mat.row(y);
                    try { applyPixels(row.data); }
                    finally { row.delete(); }
                }
            }
        }

        function documentOriginalSourceQuad(points, width, height, rotation) {
            const angle = ((Number(rotation) || 0) % 360 + 360) % 360;
            return points.map(p => {
                const x = p.x / width, y = p.y / height;
                if (angle === 90) return {x: y, y: 1 - x};
                if (angle === 180) return {x: 1 - x, y: 1 - y};
                if (angle === 270) return {x: 1 - y, y: x};
                return {x, y};
            });
        }

        function applyDocumentIllumination(mat, illumination, outputSourceQuad) {
            if (!illumination || !outputSourceQuad) return;
            const allocated = [];
            const width = mat.cols, height = mat.rows;
            try {
                const points = quad => { const m = cv.matFromArray(4, 1, cv.CV_32FC2, quad.flatMap(p => [p.x, p.y])); allocated.push(m); return m; };
                const unit = points([{x:0,y:0},{x:1,y:0},{x:1,y:1},{x:0,y:1}]);
                const source = points(illumination.source_quad);
                const target = points(outputSourceQuad);
                const inverse = cv.getPerspectiveTransform(source, unit); allocated.push(inverse);
                const forward = cv.getPerspectiveTransform(unit, target); allocated.push(forward);
                const a = inverse.data64F, b = forward.data64F, m = new Float64Array(9);
                for (let r = 0; r < 3; r++) for (let c = 0; c < 3; c++)
                    for (let k = 0; k < 3; k++) m[r * 3 + c] += a[r * 3 + k] * b[k * 3 + c];
                if (!Array.from(m).every(Number.isFinite)) return;
                const channels = mat.channels(), colours = channels === 4 ? 3 : channels;
                const grid = illumination.gains, gw = illumination.width, gh = illumination.height;
                const segmentation = illumination.segmentation;
                const detailGrid = segmentation?.detail_mask || null;
                const photoGrid = segmentation?.photo_mask || null;
                const highlightGrid = segmentation?.highlight_mask || null;
                const profile = illumination.pixel_profile || {};
                const sampleGrid = (values, fx, fy, fallback = 0) => {
                    if (!values) return fallback;
                    const ix = Math.min(gw - 2, Math.floor(fx)), iy = Math.min(gh - 2, Math.floor(fy));
                    const dx = fx - ix, dy = fy - iy, i = iy * gw + ix;
                    return (values[i] * (1-dx) + values[i+1] * dx) * (1-dy)
                        + (values[i+gw] * (1-dx) + values[i+gw+1] * dx) * dy;
                };
                const continuous = mat.isContinuous(), pixels = mat.data;
                for (let y = 0; y < height; y++) {
                    const row = continuous ? null : mat.row(y);
                    try {
                        const data = row ? row.data : pixels;
                        const v = y / Math.max(1, height - 1);
                        for (let x = 0; x < width; x++) {
                            const u = x / Math.max(1, width - 1), denom = m[6] * u + m[7] * v + m[8];
                            if (Math.abs(denom) < 1e-9) continue;
                            const gx = (m[0] * u + m[1] * v + m[2]) / denom;
                            const gy = (m[3] * u + m[4] * v + m[5]) / denom;
                            if (gx < -0.00001 || gy < -0.00001 || gx > 1.00001 || gy > 1.00001) continue;
                            const fx = Math.max(0, Math.min(gw - 1, gx * (gw - 1))), fy = Math.max(0, Math.min(gh - 1, gy * (gh - 1)));
                            const rawGain = sampleGrid(grid, fx, fy, 1);
                            const offset = (continuous ? y * width + x : x) * channels;
                            let peak = 0, minimum = 255;
                            for (let c = 0; c < colours; c++) {
                                peak = Math.max(peak, data[offset+c]);
                                minimum = Math.min(minimum, data[offset+c]);
                            }
                            if (peak === 0) continue;
                            let photoProtection = sampleGrid(photoGrid, fx, fy);
                            if (profile.per_pixel_colour_protection) {
                                photoProtection = Math.max(photoProtection,
                                    Math.max(0, Math.min(1, ((peak - minimum) / peak - .12) / .50)));
                            }
                            const protection = Math.max(0, Math.min(0.92,
                                sampleGrid(detailGrid, fx, fy) * (profile.text_protection || 0)
                                + photoProtection * (profile.photo_protection || 0)
                                + sampleGrid(highlightGrid, fx, fy) * (profile.highlight_protection || 0)
                            ));
                            let gain = 1 + (rawGain - 1) * (1 - protection);
                            if (!(gain > 1.001)) continue;
                            if (profile.per_pixel_ink_protection) {
                                gain = 1 + (gain - 1) * Math.max(0, Math.min(1, (peak - 22) / 95));
                            }
                            let lifted = peak * gain;
                            if (lifted > 235) {
                                const headroom = profile.per_pixel_ink_protection ? 17 : 20;
                                lifted = Math.max(peak, 235 + headroom * (1 - Math.exp(-(lifted - 235) / headroom)));
                            }
                            const scale = lifted / peak;
                            for (let c = 0; c < colours; c++) data[offset+c] = Math.min(255, Math.round(data[offset+c] * scale));
                        }
                    } finally { if (row) row.delete(); }
                }

                // Pixel/detail segmentation keeps sharpening on printed edges and
                // text while avoiding the flat areas of portraits and artwork.
                const detailStrength = Math.max(0, Math.min(0.40, Number(profile.detail_strength) || 0));
                if (detailGrid && detailStrength > 0.001) {
                    if (profile.bounded_detail) {
                        const gray = new cv.Mat(), blur = new cv.Mat(), low = new cv.Mat(), high = new cv.Mat();
                        const kernel = cv.Mat.ones(3, 3, cv.CV_8U);
                        try {
                            if (colours === 1) mat.copyTo(gray);
                            else cv.cvtColor(mat, gray, channels === 4 ? cv.COLOR_RGBA2GRAY : cv.COLOR_RGB2GRAY);
                            cv.GaussianBlur(gray, blur, new cv.Size(3, 3), .82, .82, cv.BORDER_DEFAULT);
                            cv.erode(gray, low, kernel);
                            cv.dilate(gray, high, kernel);
                            // OpenCV Mat.data is an accessor: resolve each view once,
                            // not millions of times inside the print-size pixel loop.
                            const grayPixels=gray.data, blurPixels=blur.data, lowPixels=low.data, highPixels=high.data;
                            for (let y = 0; y < height; y++) {
                                const row = continuous ? null : mat.row(y);
                                try {
                                    const data = row ? row.data : pixels;
                                    for (let x = 0; x < width; x++) {
                                        const u=x/Math.max(1,width-1), v=y/Math.max(1,height-1);
                                        const denom=m[6]*u+m[7]*v+m[8];
                                        if (Math.abs(denom)<1e-9) continue;
                                        const gx=(m[0]*u+m[1]*v+m[2])/denom, gy=(m[3]*u+m[4]*v+m[5])/denom;
                                        if (gx<0 || gy<0 || gx>1 || gy>1) continue;
                                        const fx=gx*(gw-1), fy=gy*(gh-1), at=y*width+x;
                                        const offset=(continuous?at:x)*channels;
                                        let peak=0, minimum=255;
                                        for(let c=0;c<colours;c++){peak=Math.max(peak,data[offset+c]);minimum=Math.min(minimum,data[offset+c]);}
                                        if(peak===0)continue;
                                        let photo=sampleGrid(photoGrid,fx,fy);
                                        if(profile.per_pixel_colour_protection)photo=Math.max(photo,Math.max(0,Math.min(1,((peak-minimum)/peak-.12)/.50)));
                                        const blend=Math.max(0,Math.min(1,.18+sampleGrid(detailGrid,fx,fy)*.82-photo*.40));
                                        const difference=grayPixels[at]-blurPixels[at];
                                        const residual=Math.sign(difference)*Math.max(0,Math.abs(difference)-2);
                                        const delta=Math.max(-3,Math.min(3,residual*detailStrength*blend));
                                        const target=Math.max(lowPixels[at],Math.min(highPixels[at],grayPixels[at]+delta));
                                        const ratio=Math.min(target/Math.max(1,grayPixels[at]),Math.max(peak,252)/peak);
                                        for(let c=0;c<colours;c++)data[offset+c]=Math.round(data[offset+c]*ratio);
                                    }
                                } finally {if(row)row.delete();}
                            }
                        } finally {gray.delete();blur.delete();low.delete();high.delete();kernel.delete();}
                        return;
                    }
                    const blurred = new cv.Mat();
                    const sharpened = new cv.Mat();
                    try {
                        cv.GaussianBlur(mat, blurred, new cv.Size(3, 3), 0.82, 0.82, cv.BORDER_DEFAULT);
                        cv.addWeighted(mat, 1 + detailStrength, blurred, -detailStrength, 0, sharpened);
                        const sourcePixels = mat.data, sharpPixels = sharpened.data;
                        for (let y = 0; y < height; y++) {
                            const v = y / Math.max(1, height - 1);
                            for (let x = 0; x < width; x++) {
                                const u = x / Math.max(1, width - 1), denom = m[6] * u + m[7] * v + m[8];
                                if (Math.abs(denom) < 1e-9) continue;
                                const gx = (m[0] * u + m[1] * v + m[2]) / denom;
                                const gy = (m[3] * u + m[4] * v + m[5]) / denom;
                                if (gx < 0 || gy < 0 || gx > 1 || gy > 1) continue;
                                const fx = Math.max(0, Math.min(gw - 1, gx * (gw - 1)));
                                const fy = Math.max(0, Math.min(gh - 1, gy * (gh - 1)));
                                const detail = sampleGrid(detailGrid, fx, fy);
                                const photo = sampleGrid(photoGrid, fx, fy);
                                const blend = Math.max(0, Math.min(1, 0.18 + detail * 0.82 - photo * 0.40));
                                const offset = (y * width + x) * channels;
                                for (let c = 0; c < colours; c++) {
                                    sourcePixels[offset+c] = Math.round(sourcePixels[offset+c] * (1-blend) + sharpPixels[offset+c] * blend);
                                }
                            }
                        }
                    } finally {
                        blurred.delete();
                        sharpened.delete();
                    }
                }
            } finally { allocated.forEach(m => m.delete()); }
        }

        function applyAdvancedEnhancementWithSettings(mat, settings = {}, mode = 'magic', outputSourceQuad = null) {
            const s = {
                brightness: Number(settings.brightness) || 0,
                contrast: Number(settings.contrast) || 0,
                saturation: Number(settings.saturation) || 0,
                warmth: Number(settings.warmth) || 0,
                sharpness: Number(settings.sharpness) || 0,
                clarity: Number(settings.clarity) || 0
            };
            const contrastAlpha = 1.0 + (s.contrast / 100.0);
            if (settings.documentIllumination) applyDocumentIllumination(mat, settings.documentIllumination, outputSourceQuad);
            const toneStrength = Math.max(0, Math.min(0.55, Number(settings.autoToneStrength) || 0));
            if (toneStrength > 0) {
                applyDocumentShadowCurve(mat, toneStrength);
            }
            mat.convertTo(mat, -1, contrastAlpha, s.brightness * 2.0);

            if (mode === 'bw') {
                cv.cvtColor(mat, mat, cv.COLOR_RGBA2GRAY);
                mat.convertTo(mat, -1, 1.08, 4);
                cv.cvtColor(mat, mat, cv.COLOR_GRAY2RGBA);
            } else {
                const needsSaturation = Math.abs(s.saturation) > 0.1;
                const needsWarmth = Math.abs(s.warmth) > 0.1;
                if (needsSaturation) {
                    const rgb = new cv.Mat();
                    const hsv = new cv.Mat();
                    const hsvPlanes = new cv.MatVector();
                    cv.cvtColor(mat, rgb, cv.COLOR_RGBA2RGB);
                    cv.cvtColor(rgb, hsv, cv.COLOR_RGB2HSV);
                    cv.split(hsv, hsvPlanes);
                    const sat = hsvPlanes.get(1);
                    sat.convertTo(sat, -1, Math.max(0.15, 1 + (s.saturation / 100.0)), 0);
                    cv.merge(hsvPlanes, hsv);
                    cv.cvtColor(hsv, rgb, cv.COLOR_HSV2RGB);
                    cv.cvtColor(rgb, mat, cv.COLOR_RGB2RGBA);
                    sat.delete();
                    hsvPlanes.delete();
                    hsv.delete();
                    rgb.delete();
                }

                if (needsWarmth) {
                    const rgbaPlanes = new cv.MatVector();
                    cv.split(mat, rgbaPlanes);
                    const red = rgbaPlanes.get(0);
                    const blue = rgbaPlanes.get(2);
                    red.convertTo(red, -1, 1, s.warmth * 0.9);
                    blue.convertTo(blue, -1, 1, -s.warmth * 0.9);
                    cv.merge(rgbaPlanes, mat);
                    red.delete();
                    blue.delete();
                    rgbaPlanes.delete();
                }
            }

            const clarityAmount = Math.max(0, s.clarity) / 100;
            if (clarityAmount > 0.001) {
                const blur = new cv.Mat();
                cv.GaussianBlur(mat, blur, new cv.Size(7, 7), 0, 0, cv.BORDER_DEFAULT);
                cv.addWeighted(mat, 1 + clarityAmount, blur, -clarityAmount, 0, mat);
                blur.delete();
            }

            const sharpAmount = Math.max(0, s.sharpness) / 100;
            if (sharpAmount > 0.001) {
                const blur = new cv.Mat();
                cv.GaussianBlur(mat, blur, new cv.Size(3, 3), 0, 0, cv.BORDER_DEFAULT);
                cv.addWeighted(mat, 1 + sharpAmount, blur, -sharpAmount, 0, mat);
                blur.delete();
            }
        }

        async function loadDataUrlToMat(dataUrl) {
            const img = await loadImageFromDataUrl(dataUrl);
            return readImageElementToMat(img);
        }

        function mapEditorPointsToTargetMat(points, targetMat, options = {}) {
            if (!Array.isArray(points) || !isMatUsable(targetMat)) return [];
            const sourceWidth = Math.max(1, Number(options.sourceWidth) || (isMatUsable(srcMat) ? srcMat.cols : 1));
            const sourceHeight = Math.max(1, Number(options.sourceHeight) || (isMatUsable(srcMat) ? srcMat.rows : 1));
            const sourceScale = Math.max(0.0001, Number(options.editorScale) || editorScale || 1);
            const sourceRotation = normalizeRightAngle(Number.isFinite(options.rotationAngle) ? options.rotationAngle : rotationAngle);
            const sourceRotated = getRotatedMatDimensions(sourceWidth, sourceHeight, sourceRotation);
            const targetRotated = getRotatedMatDimensions(targetMat.cols, targetMat.rows, sourceRotation);
            const scaleX = targetRotated.cols / sourceRotated.cols;
            const scaleY = targetRotated.rows / sourceRotated.rows;
            return points.map((point) => ({
                x: (Number(point.x) / sourceScale) * scaleX,
                y: (Number(point.y) / sourceScale) * scaleY
            }));
        }

        async function createHighQualityPdfWarpPair(frontPoints, backPoints, waitMs = 4500) {
            if (!activePdfHighQualityPromise && !activePdfHighQualityDataUrl && !activePdfHighQualityStarter) return null;
            if (!isMatUsable(srcMat)) return null;
            let high = null;
            try {
                const highQualityPromise = activePdfHighQualityDataUrl ? null : startActivePdfHighQualityRaster();
                const result = activePdfHighQualityDataUrl
                    ? { dataUrl: activePdfHighQualityDataUrl }
                    : await withTimeout(highQualityPromise, waitMs, 'High-quality PDF raster not ready');
                const highDataUrl = result?.dataUrl || activePdfHighQualityDataUrl || '';
                if (!highDataUrl) return null;
                high = await loadDataUrlToMat(highDataUrl);
                if (!isMatUsable(high)) return null;
                const toHighSource = (points) => mapEditorPointsToTargetMat(points, high);
                return {
                    frontWarp: createWarpedCardFromSourcePoints(high, toHighSource(frontPoints)),
                    backWarp: createWarpedCardFromSourcePoints(high, toHighSource(backPoints))
                };
            } catch (err) {
                console.warn('High-quality PDF crop fallback skipped', err);
                return null;
            } finally {
                safeDeleteMat(high);
            }
        }

        async function createWarpedCardFromPointsBestQuality(points, waitMs = 4500, options = {}) {
            if (!activePdfHighQualityPromise && !activePdfHighQualityDataUrl && !activePdfHighQualityStarter) {
                return createWarpedCardFromPoints(points, options);
            }
            if (!isMatUsable(srcMat)) return createWarpedCardFromPoints(points, options);
            let high = null;
            try {
                const highQualityPromise = activePdfHighQualityDataUrl ? null : startActivePdfHighQualityRaster();
                const result = activePdfHighQualityDataUrl
                    ? { dataUrl: activePdfHighQualityDataUrl }
                    : await withTimeout(highQualityPromise, waitMs, 'High-quality PDF raster not ready');
                const highDataUrl = result?.dataUrl || activePdfHighQualityDataUrl || '';
                if (!highDataUrl) return createWarpedCardFromPoints(points, options);
                high = await loadDataUrlToMat(highDataUrl);
                if (!isMatUsable(high)) return createWarpedCardFromPoints(points, options);
                const sourcePoints = mapEditorPointsToTargetMat(points, high);
                return createWarpedCardFromSourcePoints(high, sourcePoints, options);
            } catch (err) {
                console.warn('High-quality single crop fallback skipped', err);
                return createWarpedCardFromPoints(points, options);
            } finally {
                safeDeleteMat(high);
            }
        }

        function captureDeferredPvcHighQualityTask(frontPoints, backPoints = null, sourceDataUrl = '', options = {}) {
            if ((!activePdfHighQualityPromise && !activePdfHighQualityDataUrl && !activePdfHighQualityStarter) || !isMatUsable(srcMat)) return null;
            return {
                id: ++pvcHighQualityTaskSequence,
                promise: activePdfHighQualityPromise,
                start: activePdfHighQualityStarter,
                dataUrl: activePdfHighQualityDataUrl || '',
                // If the 30MP background raster is unavailable, rebuild the final
                // 3033x1914 crop from the original PDF preview raster. Never export
                // the lightweight 1011x638 UI preview as the final-quality source.
                fallbackDataUrl: sourceDataUrl || currentPvcSourceDataUrl || currentDocumentSourceDataUrl || '',
                sourceWidth: srcMat.cols,
                sourceHeight: srcMat.rows,
                editorScale: editorScale || 1,
                frontPoints: cloneQuad(frontPoints),
                backPoints: Array.isArray(backPoints) ? cloneQuad(backPoints) : null,
                options: {
                    docType: 'pvc',
                    renderSize: { ...getDocRenderSize('pvc') },
                    rotationAngle,
                    postWarpRotationDegrees: normalizeRightAngle(options.postWarpRotationDegrees || 0),
                    enhanceSettings: { ...getEnhanceSettings() },
                    mode: currentMode
                }
            };
        }

        function createFastPvcPreviewWarp(points, options = {}) {
            if (!isMatUsable(srcMat)) throw new Error("Source image is not available. Please upload again.");
            const sourcePoints = points.map((p) => ({ x: p.x / editorScale, y: p.y / editorScale }));
            return createWarpedCardFromSourcePointsWithOptions(srcMat, sourcePoints, {
                docType: 'pvc',
                renderSize: { width: DOC_TYPES.pvc.w, height: DOC_TYPES.pvc.h },
                rotationAngle,
                postWarpRotationDegrees: normalizeRightAngle(options.postWarpRotationDegrees || 0),
                enhanceSettings: { ...getEnhanceSettings() },
                mode: currentMode
            });
        }

        async function buildPvcTwoPageHighQualitySide(sideTask, options) {
            if (!sideTask?.points?.length) return null;
            let high = null;
            try {
                const result = typeof sideTask.start === 'function' ? await sideTask.start() : null;
                const dataUrl = result?.dataUrl || sideTask.fallbackDataUrl || '';
                if (!dataUrl) return null;
                high = await loadDataUrlToMat(dataUrl);
                if (!isMatUsable(high)) return null;
                const sideOptions = {
                    ...options,
                    rotationAngle: normalizeRightAngle(sideTask.rotationAngle || 0),
                    enhanceSettings: sideTask.enhanceSettings || options?.enhanceSettings,
                    mode: sideTask.mode || options?.mode
                };
                const highPoints = mapEditorPointsToTargetMat(sideTask.points, high, {
                    sourceWidth: sideTask.sourceWidth,
                    sourceHeight: sideTask.sourceHeight,
                    editorScale: 1,
                    rotationAngle: sideOptions.rotationAngle
                });
                return createWarpedCardFromSourcePointsWithOptions(high, highPoints, sideOptions);
            } finally {
                safeDeleteMat(high);
            }
        }

        async function buildPvcHighQualityMats(task) {
            if (!task) return null;
            if (task.type === 'two_page_pdf') {
                let front = null;
                let back = null;
                try {
                    // Render sequentially to avoid holding two 30MP PDF canvases in
                    // memory at once on ordinary shop PCs.
                    front = await buildPvcTwoPageHighQualitySide(task.frontSide, task.options);
                    back = await buildPvcTwoPageHighQualitySide(task.backSide, task.options);
                    if (!front || !back) {
                        safeDeleteMat(front);
                        safeDeleteMat(back);
                        return null;
                    }
                    return { front, back };
                } catch (error) {
                    safeDeleteMat(front);
                    safeDeleteMat(back);
                    throw error;
                }
            }
            let high = null;
            let front = null;
            let back = null;
            try {
                const taskPromise = task.promise || (typeof task.start === 'function' ? task.start() : null);
                const result = task.dataUrl ? { dataUrl: task.dataUrl } : (taskPromise ? await taskPromise : null);
                const highDataUrl = result?.dataUrl || task.dataUrl || task.fallbackDataUrl || '';
                if (!highDataUrl) return null;
                high = await loadDataUrlToMat(highDataUrl);
                if (!isMatUsable(high)) return null;
                const toHighSource = (points) => mapEditorPointsToTargetMat(points, high, {
                    sourceWidth: task.sourceWidth,
                    sourceHeight: task.sourceHeight,
                    editorScale: task.editorScale,
                    rotationAngle: task.options?.rotationAngle || 0
                });
                front = createWarpedCardFromSourcePointsWithOptions(high, toHighSource(task.frontPoints), task.options);
                back = task.backPoints
                    ? createWarpedCardFromSourcePointsWithOptions(high, toHighSource(task.backPoints), task.options)
                    : null;
                return { front, back };
            } catch (err) {
                safeDeleteMat(front);
                safeDeleteMat(back);
                throw err;
            } finally {
                safeDeleteMat(high);
            }
        }

        function upgradePvcItemHighQuality(item) {
            if (!item?.pvcHighQualityTask || item.pvcHighQualityReady || item.pvcDisposed) return Promise.resolve(true);
            if (item._pvcHighQualityUpgradePromise) return item._pvcHighQualityUpgradePromise;
            const task = item.pvcHighQualityTask;
            item._pvcHighQualityUpgradePromise = pvcHighQualityUpgradeQueue.then(async () => {
                const mats = await buildPvcHighQualityMats(task);
                if (!isMatUsable(mats?.front) || ((task.backPoints || task.backSide) && !isMatUsable(mats?.back))) {
                    safeDeleteMat(mats?.front);
                    safeDeleteMat(mats?.back);
                    return false;
                }
                if (item.pvcDisposed || item.pvcHighQualityTask !== task) {
                    safeDeleteMat(mats.front);
                    safeDeleteMat(mats.back);
                    return false;
                }
                const oldFront = item.front;
                const oldBack = item.back;
                item.front = mats.front;
                // A back uploaded after a deferred front crop must not disappear.
                item.back = mats.back || oldBack;
                item.pvcHighQualityReady = true;
                for (const [previous, next] of [[oldFront,item.front],[oldBack,item.back]]) {
                    const prior = previous && enhancementComparisons.get(previous);
                    const updated = next && enhancementComparisons.get(next);
                    if (prior && updated) {
                        updated.elapsed = prior.elapsed;
                        updated.wipeStartedAt = prior.wipeStartedAt;
                        updated.wipeDone = prior.wipeDone;
                        if (prior.wipeDone) updated.before = null;
                    }
                }
                safeDeleteMat(oldFront);
                if (oldBack !== item.back) safeDeleteMat(oldBack);
                primeMatForPreview(item.front);
                if (item.back) primeMatForPreview(item.back);
                if (batchQueue.includes(item)) renderSheet();
                return true;
            }).catch((err) => {
                console.warn('Deferred PVC high-quality upgrade failed', err);
                return false;
            });
            pvcHighQualityUpgradeQueue = item._pvcHighQualityUpgradePromise.catch(() => false);
            return item._pvcHighQualityUpgradePromise;
        }

        async function ensurePvcItemsHighQuality(items = batchQueue) {
            for (const item of (Array.isArray(items) ? items : [])) {
                if (item?.type === 'pvc' && item.pvcHighQualityTask && !item.pvcHighQualityReady) {
                    await upgradePvcItemHighQuality(item);
                }
            }
        }

        function hasPendingPvcHighQuality(items = batchQueue) {
            return (Array.isArray(items) ? items : []).some((item) => (
                item?.type === 'pvc' && item.pvcHighQualityTask && !item.pvcHighQualityReady
            ));
        }

        async function applyPvcDualAutoCrop(frontPoints, backPoints, opts = {}) {
            try {
                const replaceIndex = Number.isInteger(opts.replaceIndex) ? opts.replaceIndex : -1;
                if (pvcRecropMode && replaceIndex < 0) {
                    showModal("Re-Crop Target Missing", "Selected card queue me nahi mila. Preview me card dobara select karke Re-Crop karein.", "error");
                    return false;
                }
                const fast = opts.fast === true;
                const sourceDataUrl = opts.sourceDataUrl || getActivePvcCropSourceDataUrl() || null;
                const frontCropDescriptor = createPvcCropDescriptor(frontPoints);
                const backCropDescriptor = createPvcCropDescriptor(backPoints);
                const deferredHighQualityTask = fast ? captureDeferredPvcHighQualityTask(frontPoints, backPoints, sourceDataUrl || '') : null;
                const highPair = fast ? null : await createHighQualityPdfWarpPair(frontPoints, backPoints, 6500);
                const frontWarp = highPair?.frontWarp || (fast ? createFastPvcPreviewWarp(frontPoints) : createWarpedCardFromPoints(frontPoints));
                const backWarp = highPair?.backWarp || (fast ? createFastPvcPreviewWarp(backPoints) : createWarpedCardFromPoints(backPoints));
                pvcSingleSideAiMode = false;
                isSingleSide = false;
                if (replaceIndex < 0) {
                    queuePvcAutoCropApprovalSample(frontPoints, backPoints, opts.approvalReason || 'auto_crop_upload', {
                        sourceDataUrl,
                        // Fast auto-crop must stay fast. User-confirmed/manual paths
                        // keep paired targets; automatic samples can be re-warped
                        // from their saved source + quad by the training pipeline.
                        rectifiedTargets: fast ? {} : {
                            front: getMatPreviewDataUrl(frontWarp, 720),
                            back: getMatPreviewDataUrl(backWarp, 720)
                        }
                    });
                }

                if (replaceIndex >= 0 && batchQueue[replaceIndex]) {
                    const target = batchQueue[replaceIndex];
                    const replacementFront = frontWarp.clone();
                    const replacementBack = backWarp.clone();
                    if (!fast) {
                        primeMatForPreview(replacementFront);
                        primeMatForPreview(replacementBack);
                    }
                    const oldFront = target.front;
                    const oldBack = target.back;
                    const oldStoredBack = target.pvcStoredBack;
                    target.front = replacementFront;
                    target.back = replacementBack;
                    target.pvcStoredBack = null;
                    target.singleSide = false;
                    target.scaleX = 1;
                    target.scaleY = 1;
                    target.rotation = 0;
                    target.sourceDataUrl = sourceDataUrl;
                    target.frontCropDescriptor = frontCropDescriptor;
                    target.backCropDescriptor = backCropDescriptor;
                    target.pvcHighQualityTask = deferredHighQualityTask;
                    target.pvcHighQualityReady = !deferredHighQualityTask;
                    target.pvcDisposed = false;
                    target._pvcHighQualityUpgradePromise = null;
                    safeDeleteMat(oldFront);
                    safeDeleteMat(oldBack);
                    safeDeleteMat(oldStoredBack);
                    safeDeleteMat(frontWarp);
                    safeDeleteMat(backWarp);
                    selectedItem = {
                        index: replaceIndex,
                        side: selectedItem.index === replaceIndex && selectedItem.side === 'back' ? 'back' : 'front'
                    };
                    closeCropper();
                    syncSelectionToolbar();
                    updateListUI();
                    renderSheetNow();
                    showModal("Re-Crop Updated", "Galat crop replace ho gaya.", "success");
                    return true;
                }

                safeDeleteMat(tempDocs.front);
                safeDeleteMat(tempDocs.back);
                tempDocs.front = frontWarp.clone();
                tempDocs.back = backWarp.clone();
                if (enhancementComparisons.has(frontWarp)) enhancementComparisons.set(tempDocs.front, enhancementComparisons.get(frontWarp));
                if (enhancementComparisons.has(backWarp)) enhancementComparisons.set(tempDocs.back, enhancementComparisons.get(backWarp));
                pendingPvcHighQualityTask = deferredHighQualityTask;
                pendingPvcCropDescriptors = { front: frontCropDescriptor, back: backCropDescriptor };
                if (!fast) {
                    primeMatForPreview(tempDocs.front);
                    primeMatForPreview(tempDocs.back);

                    setThumbBySide('front', getMatPreviewDataUrl(frontWarp));
                    setThumbBySide('back', getMatPreviewDataUrl(backWarp));
                }

                safeDeleteMat(frontWarp);
                safeDeleteMat(backWarp);
                closeCropper();
                if (fast) await addToSheet({ pvcSourceDataUrl: sourceDataUrl });
                else setTimeout(() => addToSheet({ pvcSourceDataUrl: sourceDataUrl }), 80);
                return true;
            } catch (err) {
                console.error('Dual auto crop failed', err);
                return false;
            }
        }

        async function applyPvcSingleAutoCrop(frontPoints, opts = {}) {
            try {
                const replaceIndex = Number.isInteger(opts.replaceIndex) ? opts.replaceIndex : -1;
                if (pvcRecropMode && replaceIndex < 0) {
                    showModal("Re-Crop Target Missing", "Selected card queue me nahi mila. Preview me card dobara select karke Re-Crop karein.", "error");
                    return false;
                }
                const fast = opts.fast === true;
                const sourceDataUrl = opts.sourceDataUrl || getActivePvcCropSourceDataUrl() || null;
                const frontCropDescriptor = createPvcCropDescriptor(frontPoints);
                const postWarpRotation = normalizeRightAngle(opts.outputRotationDegrees || 0);
                if (frontCropDescriptor && opts.docAlignerAutoCrop === true) {
                    frontCropDescriptor.source = 'docaligner';
                    frontCropDescriptor.postCropRotation = postWarpRotation;
                }
                const deferredHighQualityTask = fast
                    ? captureDeferredPvcHighQualityTask(frontPoints, null, sourceDataUrl || '', { postWarpRotationDegrees: postWarpRotation })
                    : null;
                const frontWarp = fast && deferredHighQualityTask
                    ? createFastPvcPreviewWarp(frontPoints, { postWarpRotationDegrees: postWarpRotation })
                    : await createWarpedCardFromPointsBestQuality(frontPoints, 6500, { postWarpRotationDegrees: postWarpRotation });
                pvcSingleSideAiMode = true;
                isSingleSide = true;
                if (replaceIndex < 0) {
                    queuePvcAutoCropApprovalSample(frontPoints, null, opts.approvalReason || 'auto_single_crop_upload', {
                        sourceDataUrl,
                        rectifiedTargets: { front: getMatPreviewDataUrl(frontWarp, 720) }
                    });
                }

                if (replaceIndex >= 0 && batchQueue[replaceIndex]) {
                    const target = batchQueue[replaceIndex];
                    const replacementFront = frontWarp.clone();
                    if (enhancementComparisons.has(frontWarp)) enhancementComparisons.set(replacementFront, enhancementComparisons.get(frontWarp));
                    if (!fast) primeMatForPreview(replacementFront);
                    const oldFront = target.front;
                    const oldBack = target.back;
                    const oldStoredBack = target.pvcStoredBack;
                    target.front = replacementFront;
                    target.back = null;
                    target.pvcStoredBack = null;
                    target.scaleX = 1;
                    target.scaleY = 1;
                    target.rotation = 0;
                    target.singleSide = true;
                    target.sourceDataUrl = sourceDataUrl;
                    target.frontCropDescriptor = frontCropDescriptor;
                    target.backCropDescriptor = null;
                    target.pvcHighQualityTask = deferredHighQualityTask;
                    target.pvcHighQualityReady = !deferredHighQualityTask;
                    target.pvcDisposed = false;
                    target._pvcHighQualityUpgradePromise = null;
                    if (opts.docAlignerAutoCrop === true) target.docAlignerAutoCrop = true;
                    safeDeleteMat(oldFront);
                    safeDeleteMat(oldBack);
                    safeDeleteMat(oldStoredBack);
                    safeDeleteMat(frontWarp);
                    selectedItem = { index: replaceIndex, side: 'front' };
                    closeCropper();
                    syncSelectionToolbar();
                    updateListUI();
                    renderSheetNow();
                    showModal("Single Side Updated", "Single side PVC crop replace ho gaya.", "success");
                    return true;
                }

                safeDeleteMat(tempDocs.front);
                safeDeleteMat(tempDocs.back);
                tempDocs.front = frontWarp.clone();
                if (enhancementComparisons.has(frontWarp)) enhancementComparisons.set(tempDocs.front, enhancementComparisons.get(frontWarp));
                tempDocs.back = null;
                pendingPvcHighQualityTask = deferredHighQualityTask;
                pendingPvcCropDescriptors = { front: frontCropDescriptor, back: null };
                if (!fast) {
                    primeMatForPreview(tempDocs.front);
                    setThumbBySide('front', getMatPreviewDataUrl(frontWarp));
                }
                safeDeleteMat(frontWarp);
                closeCropper();
                const addOptions = { pvcSourceDataUrl: sourceDataUrl, docAlignerAutoCrop: opts.docAlignerAutoCrop === true };
                if (fast) await addToSheet(addOptions);
                else setTimeout(() => addToSheet(addOptions), 80);
                return true;
            } catch (err) {
                console.error('Single side auto crop failed', err);
                return false;
            }
        }

        function beginPvcDualManualFlow(frontPoints, backPoints, noticeMessage = '') {
            pvcDualSession = {
                active: true,
                step: 'front',
                front: normalizePvcCardBoxPoints(frontPoints),
                back: normalizePvcCardBoxPoints(backPoints)
            };
            currentSide = 'front';
            cropperPoints = cloneQuad(pvcDualSession.front);
            setCropStepUI('Step 1/2: Front', 'step-front');
            drawCanvas();
            document.getElementById('mobStatus').innerText = "Manual Front Crop";
            if (noticeMessage) {
                showModal("Manual PVC Crop", noticeMessage, "warn");
            }
        }
       // Is function ko pura replace karein
function refreshEditor(resetPoints = false) {
    if (!isMatUsable(srcMat)) throw new Error("Source image is not available. Please upload again.");
    safeDeleteMat(displayMat);
    displayMat = null;
    
    // 1. Rotate Logic (Same as before)
    let temp = srcMat.clone();
    if(rotationAngle !== 0) {
        let r = new cv.Mat();
        if(rotationAngle === 90 || rotationAngle === -270) cv.rotate(temp, r, cv.ROTATE_90_CLOCKWISE);
        else if(rotationAngle === -90 || rotationAngle === 270) cv.rotate(temp, r, cv.ROTATE_90_COUNTERCLOCKWISE);
        else if(Math.abs(rotationAngle) === 180) cv.rotate(temp, r, cv.ROTATE_180);
        safeDeleteMat(temp); temp = r;
    }

    // =========================================================
    // UPDATE: Performance Optimization (Lag Fix)
    // =========================================================
    editorScale = 1.0; 
    const maxDimension = 1200; // Screen par dikhane ke liye max size 1200px rakhenge
    
    // Agar image badi he to usko chota karo display ke liye
    if (temp.cols > maxDimension || temp.rows > maxDimension) {
        let ratio = maxDimension / Math.max(temp.cols, temp.rows);
        editorScale = ratio; // Scale factor save kar liya
        
        let resized = new cv.Mat();
        cv.resize(temp, resized, new cv.Size(0, 0), ratio, ratio, cv.INTER_AREA);
        
        displayMat = resized; // Display mat ab choti file he (Fast chalegi)
        safeDeleteMat(temp); 
    } else {
        displayMat = temp; // Agar pehle se choti he to waise hi rehne do
    }
    // =========================================================

    if(resetPoints) {
        const w = displayMat.cols, h = displayMat.rows, aspect = DOC_TYPES[currentType].aspect;
        let bw, bh;
        if (pvcTemplatePlacementMode) {
            const d = getDefaultPvcTemplateBoxes(displayMat);
            pvcTemplateBaseBox = { w: d.front.w, h: d.front.h };
            pvcTemplateBoxes = { front: { ...d.front }, back: { ...d.back } };
            applyPvcTemplateBoxSizeFromScale();
            cropperPoints = rectToPoints(pvcTemplateBoxes.front);
            syncPvcSizeUi();
        } else if (pvcDualSession.active) {
            cropperPoints = cloneQuad(pvcDualSession[pvcDualSession.step]);
        } else {
            let autoSet = false;
            if (currentType === 'pvc') {
                autoSet = setAutoPvcCropPoints();
            }
            if(!autoSet) {
                if(currentType === 'a4') { bw = w * 0.85; bh = h * 0.9; } 
                else { if(w/h > aspect) { bh = h * 0.8; bw = bh * aspect; if(bw > w*0.9) { bw = w*0.9; bh = bw/aspect; } } else { bw = w * 0.8; bh = bw / aspect; if(bh > h*0.9) { bh = h*0.9; bw = bh*aspect; } } }
                const cx = w/2, cy = h/2;
                cropperPoints = [{x:cx-bw/2, y:cy-bh/2}, {x:cx+bw/2, y:cy-bh/2}, {x:cx+bw/2, y:cy+bh/2}, {x:cx-bw/2, y:cy+bh/2}];
            }
        }
        
        // Zoom Logic (Same as before)
        const scrollArea = document.getElementById('editorScrollArea');
        const isMob = window.innerWidth < 1024;
        const vMargin = isMob ? 280 : 100; 
        const hMargin = isMob ? 20 : 80;
        const availW = scrollArea.clientWidth - hMargin;
        const availH = scrollArea.clientHeight - vMargin;
        const ratioW = availW / w;
        const ratioH = availH / h;
        let newZoom = Math.min(ratioW, ratioH);
        if (newZoom <= 0) newZoom = 0.5; 
        editorZoom = newZoom;
    }
    
    canvas.width = displayMat.cols; 
    canvas.height = displayMat.rows;
    editorSourceCanvas.width = displayMat.cols;
    editorSourceCanvas.height = displayMat.rows;
    cv.imshow(editorSourceCanvas, displayMat);
    editorEnhancedDirty = true;
    adjustEditorZoom(0); 
}

        function fitCropToFullImage() {
            if (!isMatUsable(displayMat) || pvcTemplatePlacementMode) return;
            const w = displayMat.cols;
            const h = displayMat.rows;
            cropperPoints = [
                { x: 0, y: 0 },
                { x: w, y: 0 },
                { x: w, y: h },
                { x: 0, y: h }
            ];
            drawCanvas();
            document.getElementById('mobStatus').innerText = "Full image selected. Enhance karke Done dabayein.";
        }

        function rotateImage(d) {
            rotationAngle = (rotationAngle + d) % 360;
            markCropperUserInteraction('crop_rotation_changed', { delta_degrees: Number(d || 0), rotation_degrees: rotationAngle });
            refreshEditor(true);
        }

        function setEnhanceValue(id, value) {
            const el = document.getElementById(id);
            if (el) el.value = value;
        }

        function resetEnhanceSettings() {
            activeGpuExposure = currentMode === 'color' ? null : availableGpuExposure;
            const proEnhance = isProUser();
            const defaults = currentMode === 'magic'
                ? { bright: 6, contrast: 14, sat: proEnhance ? 6 : 0, warmth: 0, sharp: proEnhance ? 22 : 0, clarity: proEnhance ? 10 : 0 }
                : currentMode === 'bw'
                    ? { bright: 2, contrast: 18, sat: 0, warmth: 0, sharp: proEnhance ? 18 : 0, clarity: proEnhance ? 8 : 0 }
                    : { bright: 0, contrast: 0, sat: 0, warmth: 0, sharp: 0, clarity: 0 };
            setEnhanceValue('inpBright', defaults.bright);
            setEnhanceValue('inpContrast', defaults.contrast);
            setEnhanceValue('inpSaturation', defaults.sat);
            setEnhanceValue('inpWarmth', defaults.warmth);
            setEnhanceValue('inpSharp', defaults.sharp);
            setEnhanceValue('inpClarity', defaults.clarity);
            if (activeGpuExposure) {
                for (const id of ['inpBright', 'inpContrast', 'inpSaturation', 'inpWarmth', 'inpSharp', 'inpClarity']) setEnhanceValue(id, 0);
            }
            updateFilters();
        }
        
        function setMode(m, userInitiated = true) {
            currentMode = m;
            if (userInitiated) markCropperUserInteraction('enhancement_mode_selected', { enhancement_mode: m });
            const buttons = ['btnColor', 'btnMagic', 'btnBW'];
            buttons.forEach(id => {
                const el = document.getElementById(id);
                if (!el) return;
                if (id.toLowerCase().includes(m)) el.className = "mode-chip active py-3 text-xs font-black rounded-xl";
                else el.className = "mode-chip py-3 text-xs font-black rounded-xl text-slate-600 bg-slate-100 hover:bg-slate-200";
            });
            const mobButtons = ['mobBtnColor', 'mobBtnMagic', 'mobBtnBW'];
            mobButtons.forEach(id => {
                const el = document.getElementById(id);
                if (id.toLowerCase().includes(m)) el.className = "flex-1 py-1.5 text-[10px] font-bold rounded-md text-white bg-brand shadow-sm";
                else el.className = "flex-1 py-1.5 text-[10px] font-bold rounded-md text-gray-500 hover:text-slate-800";
            });
            resetEnhanceSettings();
        }

        function updateFilters() { 
            editorEnhancedDirty = true;
            const settings = getEnhanceSettings();
            const b = settings.brightness, c = settings.contrast;
            document.getElementById('valBright').innerText = b; document.getElementById('valContrast').innerText = c;
            document.getElementById('inpBrightMob').value = b; document.getElementById('mobValBright').innerText = b;
            document.getElementById('inpContrastMob').value = c; document.getElementById('mobValContrast').innerText = c;
            const satLabel = document.getElementById('valSat');
            const warmthLabel = document.getElementById('valWarmth');
            const sharpLabel = document.getElementById('valSharp');
            const clarityLabel = document.getElementById('valClarity');
            if (satLabel) satLabel.innerText = settings.saturation;
            if (warmthLabel) warmthLabel.innerText = settings.warmth;
            if (sharpLabel) sharpLabel.innerText = settings.sharpness;
            if (clarityLabel) clarityLabel.innerText = settings.clarity;
            drawCanvas(); 
        }

        function updateProEnhanceFilter(input) {
            if (!isProUser()) {
                if (input) input.value = 0;
                requireProFeature("Advanced Image Enhancer");
            }
            updateFilters();
        }

        function drawCanvas() {
            if (directCropPreparation) return;
            if(!isMatUsable(displayMat)) {
                displayMat = null;
                return;
            }
            const wrapper = document.getElementById('canvasWrapper');
            if (wrapper) wrapper.classList.toggle('card-box-cropper', usesFixedPvcCardBoxCropper());
            ctx.clearRect(0, 0, canvas.width, canvas.height);
            if (editorEnhancedDirty || editorEnhancedCanvas.width !== canvas.width || editorEnhancedCanvas.height !== canvas.height) {
                editorEnhancedCanvas.width = canvas.width;
                editorEnhancedCanvas.height = canvas.height;
                const previewMat = displayMat.clone();
                applyAdvancedEnhancement(previewMat);
                cv.imshow(editorEnhancedCanvas, previewMat);
                safeDeleteMat(previewMat);
                editorEnhancedDirty = false;
            }
            ctx.drawImage(editorEnhancedCanvas, 0, 0);
            if (pvcTemplatePlacementMode) {
                updateCropHandleOverlay();
                drawPvcTemplateBoxes();
                return;
            }
            ctx.fillStyle = "rgba(255, 255, 255, 0.4)"; ctx.beginPath(); ctx.rect(0,0,canvas.width,canvas.height); ctx.moveTo(cropperPoints[0].x, cropperPoints[0].y); for(let i=1;i<4;i++) ctx.lineTo(cropperPoints[i].x, cropperPoints[i].y); ctx.closePath(); ctx.fill("evenodd");
            const isMobileCropUi = window.innerWidth < 1024 || remoteCropIndex >= 0;
            const visualScale = 1 / editorZoom;
            const lineWidth = (isMobileCropUi ? 1.8 : 2.15) * visualScale;
            ctx.strokeStyle = 'rgba(255,255,255,0.94)';
            ctx.lineWidth = lineWidth + (2.4 * visualScale);
            ctx.beginPath(); ctx.moveTo(cropperPoints[0].x, cropperPoints[0].y); cropperPoints.forEach(p => ctx.lineTo(p.x, p.y)); ctx.closePath(); ctx.stroke();
            ctx.strokeStyle = '#2563eb'; ctx.lineWidth = lineWidth;
            ctx.beginPath(); ctx.moveTo(cropperPoints[0].x, cropperPoints[0].y); cropperPoints.forEach(p => ctx.lineTo(p.x, p.y)); ctx.closePath(); ctx.stroke();
            updateCropHandleOverlay();
        }

        function getTouchDist(e) {
            return Math.hypot(
                e.touches[0].pageX - e.touches[1].pageX,
                e.touches[0].pageY - e.touches[1].pageY
            );
        }

        function handleCropInput(e, phase) {
            try {
                if (e.touches && e.touches.length === 2) {
                    e.preventDefault();
                    const dist = getTouchDist(e);
                    if (phase === 'start' || pinchStartDist === 0) {
                        pinchStartDist = dist;
                        pinchStartZoom = editorZoom;
                        dragIdx = -1; 
                        magCanvas.classList.add('hidden');
                        if (!cropAiActiveDragKind) {
                            cropAiActiveDragKind = 'pinch_zoom';
                            markCropperUserInteraction('crop_interaction_started', { interaction_kind: cropAiActiveDragKind });
                        }
                    } else if (phase === 'move') {
                        const scale = dist / pinchStartDist;
                        editorZoom = pinchStartZoom * scale;
                        if(editorZoom < 0.1) editorZoom = 0.1; if(editorZoom > 5.0) editorZoom = 5.0;
                        document.getElementById('zoomLabel').innerText = Math.round(editorZoom * 100) + "%";
                        
                        // Realtime Scaling for Smoothness
                        const wrapper = document.getElementById('canvasWrapper');
                        wrapper.style.width = (canvas.width * editorZoom) + "px";
                        wrapper.style.height = (canvas.height * editorZoom) + "px";
                        canvas.style.transform = `scale(${editorZoom})`;
                        
                        drawCanvas();
                    }
                    return;
                } else {
                    pinchStartDist = 0;
                }

                if (pvcTemplatePlacementMode) {
                    if(phase === 'end') {
                        if (cropAiActiveDragKind) {
                            recordAiActivity('crop_interaction_completed', {
                                interaction_kind: cropAiActiveDragKind,
                                front_rect: pvcTemplateBoxes.front && isMatUsable(displayMat) ? normalizeRect(pvcTemplateBoxes.front, displayMat.cols, displayMat.rows) : null,
                                back_rect: pvcTemplateBoxes.back && isMatUsable(displayMat) ? normalizeRect(pvcTemplateBoxes.back, displayMat.cols, displayMat.rows) : null
                            });
                            cropAiActiveDragKind = '';
                        }
                        pvcTemplateDragKey = null;
                        pvcTemplateDragMode = 'move';
                        pvcTemplateDragStart = null;
                        magCanvas.classList.add('hidden');
                        return;
                    }
                    const r = canvas.getBoundingClientRect();
                    const pointer = getPointerClient(e);
                    const clientX = pointer.x;
                    const clientY = pointer.y;
                    const x = (clientX - r.left) / editorZoom;
                    const y = (clientY - r.top) / editorZoom;
                    if (phase === 'start') {
                        const hit = hitPvcTemplateTarget(x, y);
                        if (hit) {
                            e.preventDefault();
                            if (!cropAiActiveDragKind) {
                                cropAiActiveDragKind = `pvc_${hit.key}_${hit.mode || 'move'}`;
                                markCropperUserInteraction('crop_interaction_started', { interaction_kind: cropAiActiveDragKind });
                            }
                            const box = pvcTemplateBoxes[hit.key];
                            pvcTemplateDragKey = hit.key;
                            pvcTemplateDragMode = hit.mode || 'move';
                            pvcTemplateDragOffset = { x: x - box.x, y: y - box.y };
                            pvcTemplateDragStart = {
                                rect: { ...box },
                                pointer: { x, y }
                            };
                            magCanvas.classList.remove('hidden');
                            updateMagnifier(clientX, clientY, x, y);
                        } else {
                            pvcTemplateDragKey = null;
                            pvcTemplateDragMode = 'move';
                            pvcTemplateDragStart = null;
                        }
                    } else if (phase === 'move' && pvcTemplateDragKey) {
                        e.preventDefault();
                        const box = pvcTemplateBoxes[pvcTemplateDragKey];
                        if (pvcTemplateDragMode === 'move') {
                            box.x = Math.max(0, Math.min(x - pvcTemplateDragOffset.x, canvas.width - box.w));
                            box.y = Math.max(0, Math.min(y - pvcTemplateDragOffset.y, canvas.height - box.h));
                        } else {
                            resizePvcTemplateBox(box, pvcTemplateDragMode, x, y);
                        }
                        drawCanvas();
                        updateMagnifier(clientX, clientY, x, y);
                    }
                    return;
                }

                if(phase === 'end') {
                    if (cropAiActiveDragKind) {
                        recordAiActivity('crop_interaction_completed', {
                            interaction_kind: cropAiActiveDragKind,
                            crop_quad: normalizeCropperQuad(cropperPoints)
                        });
                        cropAiActiveDragKind = '';
                    }
                    dragIdx = -1;
                    fixedCardBoxDragStart = null;
                    magCanvas.classList.add('hidden');
                    return;
                }
                const r = canvas.getBoundingClientRect();
                const pointer = getPointerClient(e);
                const clientX = pointer.x;
                const clientY = pointer.y;
                const x = (clientX - r.left) / editorZoom; const y = (clientY - r.top) / editorZoom;
                
                if(phase === 'start') {
                    let min = 86 / editorZoom; dragIdx = -1;
                    cropperPoints.forEach((p, i) => { const d = Math.hypot(p.x-x, p.y-y); if(d<min) {min=d; dragIdx=i;} });
                    if (dragIdx < 0 && usesFixedPvcCardBoxCropper()) {
                        const box = pointsToBoundingRect(cropperPoints);
                        if (pointInRect(x, y, box)) {
                            dragIdx = 4;
                            fixedCardBoxDragStart = { rect: { ...box }, pointer: { x, y } };
                        }
                    }
                    if(dragIdx > -1) { 
                        e.preventDefault(); 
                        if (!cropAiActiveDragKind) {
                            cropAiActiveDragKind = dragIdx === 4 ? 'fixed_card_move' : `corner_${dragIdx}`;
                            markCropperUserInteraction('crop_interaction_started', { interaction_kind: cropAiActiveDragKind });
                        }
                        magCanvas.classList.remove('hidden'); 
                        updateMagnifier(clientX, clientY, x, y); 
                    }
                } else if(dragIdx > -1) {
                    e.preventDefault(); 
                    let newX = Math.max(0, Math.min(x, canvas.width)), newY = Math.max(0, Math.min(y, canvas.height));
                    if (usesFixedPvcCardBoxCropper() && dragIdx === 4 && fixedCardBoxDragStart) {
                        const start = fixedCardBoxDragStart;
                        const nextX = Math.max(0, Math.min(start.rect.x + (newX - start.pointer.x), canvas.width - start.rect.w));
                        const nextY = Math.max(0, Math.min(start.rect.y + (newY - start.pointer.y), canvas.height - start.rect.h));
                        cropperPoints = rectToPoints({ x: nextX, y: nextY, w: start.rect.w, h: start.rect.h });
                    } else if (usesFixedPvcCardBoxCropper()) {
                        resizeFixedPvcCardBoxCorner(dragIdx, newX, newY);
                    } else {
                        cropperPoints[dragIdx] = {x: newX, y: newY};
                    }

                    if (!isRenderPending) {
                        requestAnimationFrame(() => {
                            drawCanvas(); 
                            updateMagnifier(clientX, clientY, newX, newY);
                            isRenderPending = false;
                        });
                        isRenderPending = true;
                    }
                }
            } catch(er){ console.log("Drag Error"); }
        }
        
        function updateMagnifier(screenX, screenY, imgX, imgY) {
            const magSize = 180, offset = 40; let magX = screenX + offset, magY = screenY - magSize - offset;
            if(magX + magSize > window.innerWidth) magX = screenX - magSize - offset;
            if(magX < 0) magX = 10; if(magY < 0) magY = screenY + offset + 20;
            magCanvas.style.left = magX + 'px'; magCanvas.style.top = magY + 'px';
            ctxMag.clearRect(0, 0, 180, 180); ctxMag.fillStyle = "white"; ctxMag.fillRect(0,0,180,180);
            const zoomSize = 60 / editorZoom; const srcX = Math.max(0, Math.min(imgX - zoomSize/2, canvas.width - zoomSize)); const srcY = Math.max(0, Math.min(imgY - zoomSize/2, canvas.height - zoomSize));
            ctxMag.drawImage(canvas, srcX, srcY, zoomSize, zoomSize, 0, 0, 180, 180);
            ctxMag.strokeStyle = 'rgba(37,99,235,0.72)';
            ctxMag.lineWidth = 0.75;
            ctxMag.beginPath();
            ctxMag.moveTo(90, 0); ctxMag.lineTo(90, 180);
            ctxMag.moveTo(0, 90); ctxMag.lineTo(180, 90);
            ctxMag.stroke();
            ctxMag.strokeStyle = '#fff';
            ctxMag.lineWidth = 4;
            ctxMag.strokeRect(0,0,180,180);
        }
        canvas.addEventListener('mousemove', e => handleCropInput(e, 'move'), { passive: false });
        canvas.addEventListener('touchmove', e => handleCropInput(e, 'move'), { passive: false });
        canvas.addEventListener('mousedown', e => handleCropInput(e, 'start'));
        canvas.addEventListener('touchstart', e => handleCropInput(e, 'start'), { passive: false });
        document.querySelectorAll('.crop-handle-overlay').forEach((handle) => {
            handle.addEventListener('mousedown', e => handleCropInput(e, 'start'));
            handle.addEventListener('touchstart', e => handleCropInput(e, 'start'), { passive: false });
        });
        window.addEventListener('mousemove', e => { if (dragIdx > -1 || pvcTemplateDragKey) handleCropInput(e, 'move'); }, { passive: false });
        window.addEventListener('touchmove', e => { if (dragIdx > -1 || pvcTemplateDragKey) handleCropInput(e, 'move'); }, { passive: false });
        window.addEventListener('mouseup', e => handleCropInput(e, 'end'));
        window.addEventListener('touchend', e => handleCropInput(e, 'end'));
        ['inpBright', 'inpContrast', 'inpSaturation', 'inpWarmth', 'inpSharp', 'inpClarity', 'inpBrightMob', 'inpContrastMob'].forEach((id) => {
            document.getElementById(id)?.addEventListener('change', () => {
                markCropperUserInteraction('enhancement_settings_changed', {
                    enhancement_mode: currentMode,
                    settings: getEnhanceSettings()
                });
            });
        });

        async function applyCropAndEnhance(isAuto = false) {
            if (cropProcessBusy) return false;
            if (pvcTwoPageRecropState.active && currentType !== 'pvc') {
                // Last-resort invariant: a 2-page pair can only be committed back
                // into PVC mode, even if another UI callback changed the tab.
                switchCurrentTypeForActiveCrop('pvc');
            }
            if (!isAuto) {
                // The Done button claims this upload for the manual result. Any
                // older scheduled GPU callback becomes stale and cannot mutate or
                // add another crop after the user's confirmation.
                activeCropAiRequestId = ++cropAiRequestSequence;
                markCropperUserInteraction('manual_crop_commit_started', {
                    docaligner_state: docAlignerDecisionState
                });
                docAlignerDecisionState = 'manual_committing';
            }
            cropProcessBusy = true;
            setCropActionBusy(true);
            const confirmedQuad = normalizeCropperQuad(cropperPoints);
            const confirmedRotation = normalizeRightAngle(rotationAngle);
            const confirmedSelectionFamily = currentType || '';
            const confirmedSelectionDocType = getAiActivityDocType();
            const autoLabelsAtConfirm = getDocumentAiAutoLabels();
            const learningContextAtConfirm = {
                ...(cloneLearningPlainObject(documentLearningContext) || {}),
                pageCount: Number(documentLearningContext?.pageCount || lastPdfMeta?.page_count || 1),
                pageSizeKey: documentLearningContext?.pageSizeKey || lastPdfMeta?.page_size_key || '',
                renderSizeKey: documentLearningContext?.renderSizeKey || lastPdfMeta?.render_size_key || ''
            };
            const learningCaptureAtConfirm = cloneLearningPlainObject(currentLearningCaptureMeta);
            const pvcLearningMetaAtConfirm = cloneLearningPlainObject(pvcActivePdfMeta);
            const pvcSourceAtConfirm = currentPvcSourceDataUrl || currentDocumentSourceDataUrl || '';
            recordAiActivity('crop_confirmed', {
                is_auto: !!isAuto,
                crop_quad: confirmedQuad,
                rotation_degrees: confirmedRotation,
                enhancement_mode: currentMode,
                enhancement_settings: getEnhanceSettings(),
                ai_suggestion_available: !!autoLabelsAtConfirm.quad || !!shadowPvcAiAnalysis,
                changed_from_ai: !!(confirmedQuad && autoLabelsAtConfirm.quad && quadDiffScore(confirmedQuad, autoLabelsAtConfirm.quad) > 0.012)
            });
            const shouldShowCropLoader = currentType === 'a4' || currentType === 'pvc' || remoteCropIndex >= 0 || pvcTemplatePlacementMode || !!pendingBackFile;
            if (shouldShowCropLoader) {
                showProcessLoader({
                    kind: 'crop',
                    variant: 'fast',
                    title: currentType === 'a4' ? 'A4 scan crop ho raha hai' : (currentType === 'pvc' ? 'PVC crop ready kar rahe hain' : 'Preview bana rahe hain'),
                    message: currentType === 'a4' ? 'High-quality A4 page aur sheet preview taiyar ho rahe hain.' : 'Crop apply ho raha hai. Bas ek pal, sheet preview turant update hoga.',
                    chip: currentType === 'pvc' ? 'AUTO CROP' : 'CROP',
                    subtext: 'Edges, color aur print size polish ho rahe hain'
                });
                await waitForLoaderPaint();
            } else {
                await waitForFastPaint();
            }
            try {
                if (remoteCropIndex >= 0 && remoteCustomerQueue[remoteCropIndex]) {
                    const completedIndex = remoteCropIndex;
                    const completedItem = remoteCustomerQueue[completedIndex];
                    const warped = await createWarpedCardFromPointsBestQuality(cropperPoints, 5200);
                    const c = document.createElement('canvas');
                    cv.imshow(c, warped);
                    const targetSide = remoteCropSide === 'back' ? 'back' : 'front';
                    const cropDataUrl = completedItem.sourceKind === 'pdf' ? c.toDataURL('image/png') : c.toDataURL('image/jpeg', 0.99);
                    if (targetSide === 'back') {
                        completedItem.backDataUrl = cropDataUrl;
                        completedItem.croppedBack = true;
                    } else {
                        completedItem.dataUrl = cropDataUrl;
                        completedItem.cropped = true;
                    }
                    const learningPoints = cloneQuad(cropperPoints);
                    const learningSource = currentType === 'pvc' ? (albumPendingBackSourceDataUrl || currentPvcSourceDataUrl) : currentDocumentSourceDataUrl;
                    const learningQuad = confirmedQuad ? JSON.parse(JSON.stringify(confirmedQuad)) : null;
                    queueBackgroundLearning(() => saveDocumentCropLearningSample(learningPoints, targetSide, learningSource, {
                        rotationDegrees: confirmedRotation,
                        normalizedQuad: learningQuad,
                        selectedFamily: confirmedSelectionFamily,
                        selectedDocType: confirmedSelectionDocType,
                        rectifiedTargetDataUrl: cropDataUrl,
                        autoLabels: autoLabelsAtConfirm,
                        context: learningContextAtConfirm,
                        captureMeta: learningCaptureAtConfirm
                    }), 'Remote document crop learning');
                    safeDeleteMat(warped);
                    remoteCropIndex = -1;
                    remoteCropSide = 'front';
                    closeCropper();
                    renderRemoteCustomerQueue();
                    setRemoteCustomerStatus('Crop updated. Print bhejne ke liye bottom button dabayein.');
                    let hasFollowUp = false;
                    if (getRemoteItemDocType(completedItem) === 'idcard' && targetSide === 'front') {
                        if (completedItem.backDataUrl && !completedItem.croppedBack) {
                            hasFollowUp = true;
                            setTimeout(() => startRemoteCustomerCrop(completedIndex, 'back'), 350);
                        } else if (!completedItem.backDataUrl) {
                            hasFollowUp = true;
                            setTimeout(() => promptRemoteBackUpload(completedIndex), 350);
                        }
                    }
                    if (!hasFollowUp) showModal("Crop Saved", "Document crop preview update ho gaya.", "success");
                    return;
                }

                if (pvcTwoPageRecropState.active) {
                    await advancePvcTwoPageRecrop();
                    return;
                }

                if (albumItemRecropState.active && currentType === 'pvc') {
                    const recropState = { ...albumItemRecropState };
                    const recropDescriptor = createPvcCropDescriptor(cropperPoints);
                    const warped = await createWarpedCardFromPointsBestQuality(cropperPoints, 6500);
                    let rectifiedLearningTarget = '';
                    try {
                        rectifiedLearningTarget = getMatPreviewDataUrl(warped, 720);
                    } catch (learningPreviewError) {
                        console.warn('Selected-side Re-Crop learning preview skipped', learningPreviewError);
                    }
                    if (recropState.preserveQualityPromise) await recropState.preserveQualityPromise;
                    if (!commitAlbumItemRecrop(recropState, warped)) {
                        safeDeleteMat(warped);
                        throw new Error('Album selected-side re-crop could not be saved');
                    }
                    const correctedItem = batchQueue.find((item) => item?.queueItemId === recropState.targetId) || null;
                    queuePvcItemSideCorrectionLearning(
                        correctedItem,
                        recropState.side,
                        recropDescriptor,
                        rectifiedLearningTarget,
                        `album_${recropState.side === 'back' ? 'back' : 'front'}_user_recrop`
                    );
                    recordAiActivity('training_correction_queued', {
                        training_task: 'album_card_side_recrop',
                        crop_side: recropState.side,
                        has_user_correction: true
                    });
                    closeCropper();
                    document.getElementById('mobStatus').innerText = `${recropState.side === 'back' ? 'Back' : 'Front'} side Re-Crop updated.`;
                    showModal('Re-Crop Saved', `Sirf ${recropState.side === 'back' ? 'Back' : 'Front'} side update hui; doosri side safe hai.`, 'success');
                    return;
                }

                if (albumCoverCropState.active && isDocumentAlbumLaunch && currentType === 'pvc') {
                    const coverState = { ...albumCoverCropState };
                    const warped = await createWarpedCardFromPointsBestQuality(cropperPoints, 6500);
                    if (!commitAlbumCoverCrop(coverState.side, warped, coverState.sourceDataUrl)) {
                        safeDeleteMat(warped);
                        throw new Error('Album cover crop could not be saved');
                    }
                    closeCropper();
                    document.getElementById('mobStatus').innerText = `Cover ${coverState.side === 'back' ? 'Back' : 'Front'} saved.`;
                    showModal('Cover Saved', `Album Cover ${coverState.side === 'back' ? 'Back' : 'Front'} crop save ho gaya.`, 'success');
                    return;
                }

                if (pvcTemplatePlacementMode && currentType === 'pvc' && pvcTemplateBoxes.front && pvcTemplateBoxes.back) {
                    if (!isMatUsable(displayMat)) throw new Error("Source image is not available. Please upload again.");
                    const w = displayMat.cols;
                    const h = displayMat.rows;
                    const template = {
                        front: normalizeRect(pvcTemplateBoxes.front, w, h),
                        back: normalizeRect(pvcTemplateBoxes.back, w, h),
                        box_size_mm: getRectSizeMm(pvcTemplateBoxes.front, w, h),
                        box_scale_percent: { width: pvcTemplateScale.w, height: pvcTemplateScale.h },
                        ai_auto_template: pvcTemplateOriginalTemplate ? JSON.parse(JSON.stringify(pvcTemplateOriginalTemplate)) : null
                    };
                    if (pvcApprovalFixState?.templateId) {
                        const teachChoice = getPvcApprovalTeachMode();
                        const ok = teachChoice === 'double_side_card'
                            ? await approvePvcAutoCropTemplate(pvcApprovalFixState.templateId, template)
                            : await teachPvcTemplateType(pvcApprovalFixState.templateId, teachChoice, template);
                        if (ok) {
                            pvcApprovalFixState = null;
                            pvcTemplateOriginalTemplate = null;
                            forcePvcTemplatePlacement = false;
                            pendingPvcPdfDualFlow = false;
                            closeCropper();
                            await openPvcTemplateApprovalModal(false);
                        }
                        return;
                    }
                    const replaceIndex = resolvePvcRecropReplaceIndex();
                    const isUserRecrop = pvcRecropMode || replaceIndex >= 0;
                    const ok = await applyPvcDualAutoCrop(
                        rectToPoints(pvcTemplateBoxes.front),
                        rectToPoints(pvcTemplateBoxes.back),
                        { replaceIndex, sourceDataUrl: getActivePvcCropSourceDataUrl() }
                    );
                    if (ok) {
                        const correctedItem = replaceIndex >= 0 ? batchQueue[replaceIndex] : null;
                        const correctionLearningMeta = correctedItem
                            ? getPvcItemSideLearningMeta(correctedItem, 'front')
                            : pvcLearningMetaAtConfirm;
                        const correctionCaptureMeta = correctedItem
                            ? getPvcItemSideCaptureMeta(correctedItem, 'front')
                            : learningCaptureAtConfirm;
                        const correctionSourceDataUrl = correctedItem?.sourceDataUrl || pvcSourceAtConfirm;
                        let correctionTargets = {};
                        if (correctedItem) {
                            try {
                                correctionTargets = {
                                    front: isMatUsable(correctedItem.front) ? getMatPreviewDataUrl(correctedItem.front, 720) : '',
                                    back: isMatUsable(correctedItem.back) ? getMatPreviewDataUrl(correctedItem.back, 720) : ''
                                };
                            } catch (learningPreviewError) {
                                console.warn('PVC Re-Crop learning targets skipped', learningPreviewError);
                                correctionTargets = {};
                            }
                        }
                        savePvcTemplateToStorage(template, {
                            rotationDegrees: confirmedRotation,
                            captureReason: isUserRecrop ? 'user_recrop' : 'user_manual_template_placement',
                            hasUserCorrection: true,
                            confirmedInCropper: true,
                            sourceDataUrl: correctionSourceDataUrl,
                            pdfMeta: correctionLearningMeta,
                            captureMeta: correctionCaptureMeta,
                            selectedDocType: correctedItem?.pvcDocType || confirmedSelectionDocType,
                            rectifiedTargets: correctionTargets
                        });
                        pvcActiveCropSourceInfo = {
                            crop_source: 'manual_recrop',
                            doc_type: sanitizePvcDocType(pvcAutoCropDocType),
                            doc_label: getPvcDocTypeLabel(pvcAutoCropDocType),
                            match_reason: 'manual crop boxes applied'
                        };
                        recordPvcAutoCropMonitor(template, { trigger: 'manual_recrop_apply' });
                        forcePvcTemplatePlacement = false;
                        clearPvcRecropTarget();
                        if (isUserRecrop) {
                            document.getElementById('mobStatus').innerText = 'Re-Crop updated.';
                        } else if (window.siteConfig?.canViewPvcCoordsModal) {
                            showPvcCoordsModal(template);
                        } else {
                            showModal("Template Saved", "Naya crop template save ho gaya aur auto-crop update ho gaya.", "success");
                        }
                    } else {
                        showModal("Template Apply Failed", "Boxes crop nahi ho paye. Phir se try karein.", "error");
                    }
                    return;
                }

                if (pvcApprovalFixState?.templateId && currentType === 'pvc') {
                    const teachChoice = getPvcApprovalTeachMode();
                    if (teachChoice === 'a4_document') {
                        const quad = normalizeCropperQuad(cropperPoints);
                        if (!quad) {
                            showModal("Invalid A4 Crop", "A4 page ke 4 dots valid nahi hain. Dobara set karein.", "error");
                            return;
                        }
                        const ok = await teachPvcTemplateType(pvcApprovalFixState.templateId, 'a4_document', { quad });
                        if (ok) {
                            pvcApprovalFixState = null;
                            pvcTemplateOriginalTemplate = null;
                            forcePvcTemplatePlacement = false;
                            pendingPvcPdfDualFlow = false;
                            closeCropper();
                            await openPvcTemplateApprovalModal(false);
                        }
                        return;
                    }
                    if (teachChoice === 'single_side_card') {
                        const rect = pointsToBoundingRect(cropperPoints);
                        if (!rect || !isMatUsable(displayMat) || rect.w <= 0 || rect.h <= 0) {
                            showModal("Invalid Single Crop", "Single PVC crop box valid nahi hai. Dobara set karein.", "error");
                            return;
                        }
                        const ok = await teachPvcTemplateType(pvcApprovalFixState.templateId, 'single_side_card', {
                            front: normalizeRect(rect, displayMat.cols, displayMat.rows),
                            quad: normalizeCropperQuad(cropperPoints)
                        });
                        if (ok) {
                            pvcApprovalFixState = null;
                            pvcTemplateOriginalTemplate = null;
                            forcePvcTemplatePlacement = false;
                            pendingPvcPdfDualFlow = false;
                            closeCropper();
                            await openPvcTemplateApprovalModal(false);
                        }
                        return;
                    }
                }

                const saveSide = currentSide;
                const albumImageCropDescriptor = isDocumentAlbumLaunch && albumCardImageUploadActive && currentType === 'pvc'
                    ? createPvcCropDescriptor(cropperPoints)
                    : null;
                if (albumImageCropDescriptor && docAlignerDirectApplyActive) {
                    albumImageCropDescriptor.source = 'docaligner';
                    albumImageCropDescriptor.postCropRotation = normalizeRightAngle(pendingDocAlignerPostCropRotation);
                }
                const warped = await createWarpedCardFromPointsBestQuality(
                    cropperPoints,
                    currentType === 'pvc' ? 6500 : 5200,
                    (currentType !== 'pvc' || isDocumentAlbumLaunch)
                        ? { postWarpRotationDegrees: pendingDocAlignerPostCropRotation }
                        : {}
                );
                const rectifiedLearningTarget = getMatPreviewDataUrl(warped, 720);
                const documentCropDescriptor = currentType !== 'pvc' && confirmedQuad
                    ? {
                        rotation: confirmedRotation,
                        postCropRotation: normalizeRightAngle(pendingDocAlignerPostCropRotation),
                        points: cloneLearningPlainObject(confirmedQuad),
                        enhanceSettings: { ...getEnhanceSettings() },
                        enhanceMode: currentMode,
                        gpuExposure: availableGpuExposure,
                        source: docAlignerDirectApplyActive ? 'docaligner' : 'manual'
                    }
                    : null;
                if (documentItemRecropState.active && currentType !== 'pvc') {
                    const recropState = { ...documentItemRecropState };
                    const recropIndex = batchQueue.findIndex((item) => item?.queueItemId === recropState.targetId);
                    const target = recropIndex >= 0 ? batchQueue[recropIndex] : null;
                    if (!target) {
                        safeDeleteMat(warped);
                        resetDocumentItemRecropState();
                        throw new Error('Selected document re-crop target is no longer available');
                    }
                    const targetSide = recropState.side === 'back' && isMatUsable(target.back) ? 'back' : 'front';
                    const oldMat = targetSide === 'back' ? target.back : target.front;
                    primeMatForPreview(warped);
                    if (targetSide === 'back') {
                        target.back = warped;
                        target.backSourceDataUrl = recropState.sourceDataUrl;
                        target.backCropDescriptor = documentCropDescriptor;
                    } else {
                        target.front = warped;
                        target.sourceDataUrl = recropState.sourceDataUrl;
                        target.frontSourceDataUrl = recropState.sourceDataUrl;
                        target.frontCropDescriptor = documentCropDescriptor;
                    }
                    target.docAlignerAutoCrop = true;
                    safeDeleteMat(oldMat);
                    queueBackgroundLearning(() => saveDocumentCropLearningSample(cloneQuad(cropperPoints), targetSide, recropState.sourceDataUrl, {
                        rotationDegrees: confirmedRotation,
                        normalizedQuad: cloneLearningPlainObject(confirmedQuad),
                        selectedFamily: confirmedSelectionFamily,
                        selectedDocType: confirmedSelectionDocType,
                        rectifiedTargetDataUrl: rectifiedLearningTarget,
                        autoLabels: autoLabelsAtConfirm,
                        context: { ...learningContextAtConfirm, sourceKind: 'docaligner_manual_recrop' },
                        captureMeta: learningCaptureAtConfirm
                    }), 'DocAligner manual re-crop learning');
                    resetDocumentItemRecropState();
                    selectedItem = { index: recropIndex, side: targetSide };
                    closeCropper();
                    syncSelectionToolbar();
                    updateListUI();
                    renderSheetNow();
                    document.getElementById('mobStatus').innerText = 'Re-Crop updated.';
                    showModal('Re-Crop Saved', 'Selected AI crop manually update ho gaya.', 'success');
                    return;
                }
                if (saveSide === 'back' && pendingAttachBackIndex >= 0 && batchQueue[pendingAttachBackIndex] && !batchQueue[pendingAttachBackIndex].back) {
                    const attachIndex = pendingAttachBackIndex;
                    const target = batchQueue[attachIndex];
                    const learningPoints = cloneQuad(cropperPoints);
                    const learningSource = currentDocumentSourceDataUrl;
                    const learningQuad = confirmedQuad ? cloneLearningPlainObject(confirmedQuad) : null;
                    primeMatForPreview(warped);
                    target.back = warped;
                    target.backSourceDataUrl = learningSource || target.backSourceDataUrl || null;
                    target.backCropDescriptor = albumImageCropDescriptor || documentCropDescriptor;
                    if (isDocumentAlbumLaunch) {
                        target.pvcBackLearningMeta = cloneLearningPlainObject(albumPendingBackLearningMeta);
                        target.pvcBackCaptureMeta = cloneLearningPlainObject(albumPendingBackCaptureMeta);
                    }
                    target.singleSide = false;
                    target.backContentRotation = 0;
                    delete target.backPostCropRotationBase;
                    if (docAlignerDirectApplyActive) {
                        // Back upload updates an existing front-only item; it does
                        // not pass through addToSheet. Mark this in-place commit so
                        // the GPU-success path cannot mistake it for a failure and
                        // open the manual cropper afterward.
                        target.docAlignerAutoCrop = true;
                        docAlignerDirectCommitVersion += 1;
                        docAlignerDecisionState = 'gpu_committed';
                    }
                    const layout = getItemLayoutForType(target.type, attachIndex, true);
                    Object.assign(target, layout);
                    setThumbBySide('back', rectifiedLearningTarget);
                    queueBackgroundLearning(() => saveDocumentCropLearningSample(learningPoints, 'back', learningSource, {
                        rotationDegrees: confirmedRotation,
                        normalizedQuad: learningQuad,
                        selectedFamily: confirmedSelectionFamily,
                        selectedDocType: confirmedSelectionDocType,
                        rectifiedTargetDataUrl: rectifiedLearningTarget,
                        autoLabels: autoLabelsAtConfirm,
                        context: learningContextAtConfirm,
                        captureMeta: learningCaptureAtConfirm
                    }), 'Attached Back document crop learning');
                    pendingAttachBackIndex = -1;
                    isSingleSide = false;
                    syncSingleSideUI();
                    closeCropper();
                    clearCurrent();
                    selectedItem = { index: attachIndex, side: 'back' };
                    updateListUI();
                    renderSheet();
                    document.getElementById('mobStatus').innerText = "Back side added.";
                    return;
                }
                safeDeleteMat(tempDocs[saveSide]);
                tempDocs[saveSide] = warped;
                if (albumImageCropDescriptor) pendingPvcCropDescriptors[saveSide] = albumImageCropDescriptor;
                setThumbBySide(saveSide, rectifiedLearningTarget);
                if (isDocumentAlbumLaunch && albumCardImageUploadActive) syncAlbumCardImageUploadUi();
                if (isDocumentAlbumLaunch && albumCardImageUploadActive && currentType === 'pvc' && isMatUsable(displayMat)) {
                    const albumSideRect = pointsToBoundingRect(cropperPoints);
                    const albumSideQuad = normalizeCropperQuad(cropperPoints);
                    const albumSideSource = saveSide === 'back' ? albumPendingBackSourceDataUrl : albumPendingFrontSourceDataUrl;
                    const albumSideMeta = pvcActivePdfMeta ? JSON.parse(JSON.stringify(pvcActivePdfMeta)) : null;
                    const albumSideCaptureMeta = cloneLearningPlainObject(
                        saveSide === 'back' ? albumPendingBackCaptureMeta : albumPendingFrontCaptureMeta
                    ) || learningCaptureAtConfirm;
                    const albumSelectedDocType = sanitizePvcDocType(pvcAutoCropDocType || 'custom_card');
                    if (albumSideRect && albumSideSource && albumSideMeta) {
                        const albumSideTemplate = {
                            front: normalizeRect(albumSideRect, displayMat.cols, displayMat.rows),
                            ...(albumSideQuad ? { quad: albumSideQuad } : {}),
                            mode: 'single_side_card',
                            single_side: true,
                            preset_version: `album-${saveSide}-image-crop`
                        };
                        queueBackgroundLearning(() => savePvcLearnedTemplate(albumSideTemplate, {
                            quiet: true,
                            captureReason: `album_${saveSide}_image_crop_done`,
                            hasUserCorrection: true,
                            rotationDegrees: confirmedRotation,
                            cropSide: saveSide,
                            sourceDataUrl: albumSideSource,
                            pdfMeta: albumSideMeta,
                            captureMeta: albumSideCaptureMeta,
                            selectedDocType: albumSelectedDocType,
                            rectifiedTargets: { [saveSide]: rectifiedLearningTarget }
                        }), `Album ${saveSide} image learning`);
                    }
                }
                if (currentType === 'pvc' && saveSide === 'front' && (isSingleSide || pvcSingleSideAiMode)) {
                    const singleRect = pointsToBoundingRect(cropperPoints);
                    const singleQuad = normalizeCropperQuad(cropperPoints);
                    if (singleRect && isMatUsable(displayMat)) {
                        const singleTemplate = {
                            front: normalizeRect(singleRect, displayMat.cols, displayMat.rows),
                            ...(singleQuad ? { quad: singleQuad } : {}),
                            mode: 'single_side_card',
                            single_side: true,
                            ai_auto_template: shadowPvcAiAnalysis?.classification?.mode === 'single_side_card'
                                ? { mode: 'single_side_card', confidence: shadowPvcAiAnalysis?.classification?.confidence || 0 }
                                : null,
                            preset_version: 'single-side-user-crop'
                        };
                        queueBackgroundLearning(() => savePvcLearnedTemplate(singleTemplate, {
                            quiet: true,
                            captureReason: pvcA4CorrectionMode === 'single_side_card' ? 'user_corrected_a4_to_single_side' : 'user_single_side_crop_done',
                            hasUserCorrection: true,
                            rotationDegrees: confirmedRotation,
                            sourceDataUrl: pvcSourceAtConfirm,
                            pdfMeta: pvcLearningMetaAtConfirm,
                            captureMeta: learningCaptureAtConfirm,
                            selectedDocType: confirmedSelectionDocType,
                            rectifiedTargets: { front: rectifiedLearningTarget }
                        }), 'PVC single-side learning');
                    }
                }
                if (currentType !== 'pvc') {
                    const learningPoints = cloneQuad(cropperPoints);
                    const learningSource = currentDocumentSourceDataUrl;
                    const learningQuad = confirmedQuad ? JSON.parse(JSON.stringify(confirmedQuad)) : null;
                    pendingDocumentCropDescriptors[saveSide] = documentCropDescriptor;
                    pendingDocumentSourceDataUrls[saveSide] = learningSource || '';
                    queueBackgroundLearning(() => saveDocumentCropLearningSample(learningPoints, saveSide, learningSource, {
                        rotationDegrees: confirmedRotation,
                        normalizedQuad: learningQuad,
                        selectedFamily: confirmedSelectionFamily,
                        selectedDocType: confirmedSelectionDocType,
                        rectifiedTargetDataUrl: rectifiedLearningTarget,
                        autoLabels: autoLabelsAtConfirm,
                        context: learningContextAtConfirm,
                        captureMeta: learningCaptureAtConfirm
                    }), 'Document crop learning');
                }

                if (pvcDualSession.active) {
                    pvcDualSession[saveSide] = cloneQuad(cropperPoints);
                    if (saveSide === 'front') {
                        pvcDualSession.step = 'back';
                        currentSide = 'back';
                        cropperPoints = cloneQuad(pvcDualSession.back);
                        setCropStepUI('Step 2/2: Back', 'step-back');
                        drawCanvas();
                        document.getElementById('mobStatus').innerText = "Manual Back Crop";
                        showModal("Back Crop", "Ab back side ka box adjust karke Save Back karein.", "info");
                        return;
                    }
                    if (saveSide === 'back' && isMatUsable(displayMat)) {
                        const dualFrontRect = pointsToBoundingRect(pvcDualSession.front);
                        const dualBackRect = pointsToBoundingRect(pvcDualSession.back);
                        if (dualFrontRect && dualBackRect) {
                            const dualTemplate = {
                                front: normalizeRect(dualFrontRect, displayMat.cols, displayMat.rows),
                                back: normalizeRect(dualBackRect, displayMat.cols, displayMat.rows),
                                front_quad: normalizeCropperQuad(pvcDualSession.front),
                                back_quad: normalizeCropperQuad(pvcDualSession.back),
                                preset_version: 'dual-side-user-crop'
                            };
                            const dualRectifiedTargets = {
                                front: isMatUsable(tempDocs.front) ? getMatPreviewDataUrl(tempDocs.front, 720) : '',
                                back: isMatUsable(tempDocs.back) ? getMatPreviewDataUrl(tempDocs.back, 720) : ''
                            };
                            queueBackgroundLearning(() => savePvcLearnedTemplate(dualTemplate, {
                                quiet: true,
                                captureReason: 'user_dual_side_crop_done',
                                hasUserCorrection: true,
                                rotationDegrees: confirmedRotation,
                                sourceDataUrl: pvcSourceAtConfirm,
                                pdfMeta: pvcLearningMetaAtConfirm,
                                captureMeta: learningCaptureAtConfirm,
                                selectedDocType: confirmedSelectionDocType,
                                rectifiedTargets: dualRectifiedTargets
                            }), 'PVC dual-side learning');
                        }
                    }
                }

                if(pendingBackFile) {
                    const nextBackFile = pendingBackFile;
                    pendingBackFile = null;
                    currentSide = 'back';
                    // The next GPU result must not wait on this crop's busy
                    // flag. Clear it before starting the paired back upload;
                    // the finally block below remains idempotent.
                    cropProcessBusy = false;
                    setCropActionBusy(false);
                    await readFile(nextBackFile);
                    return;
                }

                closeCropper();
                // Commit a single album image so the next upload cannot overwrite
                // its temporary preview. Back can be attached to this item later.
                const albumSingleReady = isDocumentAlbumLaunch && albumCardImageUploadActive && (!docAlignerDirectApplyActive || isSingleSide);
                const isReady = (currentType==='a4') || (tempDocs.front && tempDocs.back) || (tempDocs.front && (isSingleSide || pvcSingleSideAiMode || albumSingleReady));
                if(isReady) await addToSheet();
                else {
                    document.getElementById('mobStatus').innerText = saveSide==='front' ? "Now Scan Back..." : "Front Missing";
                    renderSheet();
                }
            } catch(e) {
                console.error(e);
                recordAiActivity('crop_processing_failed', { error_type: String(e?.name || 'crop_error').slice(0, 60) });
                showModal("Process Error", isAuto ? "Auto cropping failed." : "Cropping failed.", "error");
                if (!isAuto) docAlignerDecisionState = 'manual_failed';
                return false;
            } finally {
                cropProcessBusy = false;
                setCropActionBusy(false);
                if (shouldShowCropLoader) hideProcessLoader();
            }
        }

        async function addToSheet(options = {}){
            if(!tempDocs.front) return null;
            recordAiActivity('document_added_to_sheet', {
                has_front: !!tempDocs.front,
                has_back: !!tempDocs.back,
                single_side: !!isSingleSide || !!pvcSingleSideAiMode
            });
            const pvcSourceDataUrlSnapshot = currentType === 'pvc'
                ? (options.pvcSourceDataUrl || getActivePvcCropSourceDataUrl() || null)
                : null;
            const albumFrontSourceSnapshot = isDocumentAlbumLaunch && currentType === 'pvc' ? (albumPendingFrontSourceDataUrl || '') : '';
            const albumBackSourceSnapshot = isDocumentAlbumLaunch && currentType === 'pvc' ? (albumPendingBackSourceDataUrl || '') : '';
            const pvcFrontSourceSnapshot = currentType === 'pvc'
                ? (options.pvcFrontSourceDataUrl || albumFrontSourceSnapshot || '')
                : '';
            const pvcBackSourceSnapshot = currentType === 'pvc'
                ? (options.pvcBackSourceDataUrl || albumBackSourceSnapshot || '')
                : '';
            const pvcLearningMetaSnapshot = currentType === 'pvc'
                ? cloneLearningPlainObject(options.pvcLearningMeta || pvcActivePdfMeta || lastPdfMeta)
                : null;
            const pvcLearningCaptureSnapshot = currentType === 'pvc'
                ? cloneLearningPlainObject(options.pvcLearningCaptureMeta || currentLearningCaptureMeta)
                : null;
            const pvcFrontLearningMetaSnapshot = currentType === 'pvc'
                ? cloneLearningPlainObject(options.pvcFrontLearningMeta || albumPendingFrontLearningMeta || pvcLearningMetaSnapshot)
                : null;
            const pvcBackLearningMetaSnapshot = currentType === 'pvc'
                ? cloneLearningPlainObject(options.pvcBackLearningMeta || albumPendingBackLearningMeta || pvcLearningMetaSnapshot)
                : null;
            const pvcFrontCaptureMetaSnapshot = currentType === 'pvc'
                ? cloneLearningPlainObject(options.pvcFrontCaptureMeta || albumPendingFrontCaptureMeta || pvcLearningCaptureSnapshot)
                : null;
            const pvcBackCaptureMetaSnapshot = currentType === 'pvc'
                ? cloneLearningPlainObject(options.pvcBackCaptureMeta || albumPendingBackCaptureMeta || pvcLearningCaptureSnapshot)
                : null;
            const documentFrontSourceSnapshot = currentType !== 'pvc'
                ? (pendingDocumentSourceDataUrls.front || currentDocumentSourceDataUrl || '')
                : '';
            const documentBackSourceSnapshot = currentType !== 'pvc'
                ? (pendingDocumentSourceDataUrls.back || '')
                : '';
            const docAlignerAutoCropSnapshot = options.docAlignerAutoCrop === true || docAlignerDirectApplyActive
                || pendingDocumentCropDescriptors.front?.source === 'docaligner'
                || pendingDocumentCropDescriptors.back?.source === 'docaligner';
            const replaceIndex = pendingA4ReplaceIndex >= 0 && currentType === 'a4' && batchQueue[pendingA4ReplaceIndex]
                ? pendingA4ReplaceIndex
                : -1;
            if(replaceIndex < 0 && batchQueue.length >= getCurrentPageItemLimit(currentType)) {
                await autoSaveFilledPageBeforeAdd();
            }
            const idx = replaceIndex >= 0 ? replaceIndex : batchQueue.length;
            const layout = getItemLayoutForType(currentType, idx, !!tempDocs.back);
            const frontDoc = tempDocs.front;
            const backDoc = tempDocs.back || null;
            const itemSingleSide = currentType === 'pvc' ? !!(pvcSingleSideAiMode || !backDoc) : !!isSingleSide;
            tempDocs.front = null;
            tempDocs.back = null;
            primeMatForPreview(frontDoc);
            if (backDoc) primeMatForPreview(backDoc);
            const newItem = {
                queueItemId: createBatchQueueItemId(),
                type: currentType,
                front: frontDoc,
                back: backDoc,
                pvcStoredBack: null,
                w: layout.w,
                h: layout.h,
                xF: layout.xF,
                yF: layout.yF,
                xB: layout.xB,
                yB: layout.yB,
                scale: layout.scale,
                scaleX: 1,
                scaleY: 1,
                rotation: 0,
                frontContentRotation: 0,
                backContentRotation: 0,
                sourceDataUrl: currentType === 'pvc'
                    ? (pvcFrontSourceSnapshot || pvcBackSourceSnapshot || pvcSourceDataUrlSnapshot)
                    : (documentFrontSourceSnapshot || documentBackSourceSnapshot || null),
                frontSourceDataUrl: currentType === 'pvc' ? (pvcFrontSourceSnapshot || null) : (documentFrontSourceSnapshot || null),
                backSourceDataUrl: currentType === 'pvc' ? (pvcBackSourceSnapshot || null) : (documentBackSourceSnapshot || null),
                docAlignerAutoCrop: !!docAlignerAutoCropSnapshot,
                pvcTwoPagePair: currentType === 'pvc' && options.pvcTwoPagePair === true,
                pvcDocType: currentType === 'pvc' ? pvcAutoCropDocType : null,
                pvcLearningMeta: pvcLearningMetaSnapshot,
                pvcLearningCaptureMeta: pvcLearningCaptureSnapshot,
                pvcFrontLearningMeta: pvcFrontLearningMetaSnapshot,
                pvcBackLearningMeta: pvcBackLearningMetaSnapshot,
                pvcFrontCaptureMeta: pvcFrontCaptureMetaSnapshot,
                pvcBackCaptureMeta: pvcBackCaptureMetaSnapshot,
                pvcHighQualityTask: currentType === 'pvc' ? pendingPvcHighQualityTask : null,
                frontCropDescriptor: currentType === 'pvc' ? pendingPvcCropDescriptors.front : pendingDocumentCropDescriptors.front,
                backCropDescriptor: currentType === 'pvc' ? pendingPvcCropDescriptors.back : pendingDocumentCropDescriptors.back,
                pvcHighQualityReady: currentType !== 'pvc' || !pendingPvcHighQualityTask,
                pvcDisposed: false,
                singleSide: itemSingleSide,
                borderEnabled: false,
                borderColor: '#111827',
                borderWidth: 6
            };
            if (replaceIndex >= 0) {
                safeDeleteItemMats(batchQueue[replaceIndex]);
                batchQueue[replaceIndex] = newItem;
            } else {
                batchQueue.push(newItem);
            }
            if (newItem.docAlignerAutoCrop) {
                docAlignerDirectCommitVersion += 1;
                docAlignerDecisionState = 'gpu_committed';
            } else if (docAlignerDecisionState === 'manual_committing') {
                docAlignerDecisionState = 'manual_committed';
            }
            pendingA4ReplaceIndex = -1;
            pendingPvcHighQualityTask = null;
            pendingPvcCropDescriptors = { front: null, back: null };
            pendingDocumentCropDescriptors = { front: null, back: null };
            pendingDocumentSourceDataUrls = { front: '', back: '' };
            documentLearningContext = null;
            pvcSingleSideAiMode = false;
            clearCurrent();
            selectedItem = { index: idx, side: 'front' };
            syncSelectionToolbar();
            updateListUI(); renderSheetNow(); 
            document.getElementById('mobStatus').innerText="Added! Scan Next.";
            if (newItem.type === 'pvc') completeCurrentPvcBatchUpload(true);
            return newItem;
        }

        async function autoSaveFilledPageBeforeAdd() {
            if (batchQueue.length === 0) return;
            await ensurePvcItemsHighQuality(batchQueue);
            const savedCanvas = buildExportCanvas(getCurrentSheetSaveScale());
            try { savedPages.push(encodeCanvasDataUrl(savedCanvas, getCurrentSheetSaveMime(), 1.0)); }
            finally { releaseOutputCanvas(savedCanvas); }
            savedPageMeta.push(buildSavedPageMetaForCurrentPage(currentType));
            batchQueue.forEach(i => safeDeleteItemMats(i));
            batchQueue=[];
            selectedItem = { index: -1, side: null };
            updatePageCountUI();
            updateListUI();
        }

        async function manualNewPage() {
            if (tempDocs.front) {
                const canCommitTemp = currentType === 'a4'
                    || currentType === 'pvc'
                    || !!tempDocs.back
                    || !!isSingleSide;
                if (!canCommitTemp) {
                    showModal("Back Missing", "Page add karne se pehle back side scan karein ya Single Side Mode ON karein.", "warn");
                    return;
                }
                await addToSheet();
            }
            if(batchQueue.length === 0) return;
            const needsHighQuality = hasPendingPvcHighQuality(batchQueue);
            if (needsHighQuality) {
                showProcessLoader({
                    kind: 'print',
                    title: 'Page high quality me save ho raha hai',
                    message: 'Original PDF se final quality card taiyar kiya ja raha hai.',
                    chip: 'HQ SAVE',
                    subtext: 'Quality kam kiye bina naya page banaya ja raha hai'
                });
                await waitForLoaderPaint();
            }
            try {
                await ensurePvcItemsHighQuality(batchQueue);
                const savedCanvas = buildExportCanvas(getCurrentSheetSaveScale());
                try { savedPages.push(encodeCanvasDataUrl(savedCanvas, getCurrentSheetSaveMime(), 1.0)); }
                finally { releaseOutputCanvas(savedCanvas); }
                savedPageMeta.push(buildSavedPageMetaForCurrentPage(currentType));
                batchQueue.forEach(i => safeDeleteItemMats(i)); batchQueue=[];
                selectedItem = { index: -1, side: null };
                clearCurrent();
                updateListUI(); renderSheet(); updatePageCountUI();
                hideControls();
                showModal("Page Saved", "Started Page " + (savedPages.length + 1), "success");
            } finally {
                if (needsHighQuality) hideProcessLoader();
            }
        }

        function updatePageCountUI() {
            const count = savedPages.length + 1;
            document.getElementById('pageIndicator').innerText = "Page " + count;
            document.getElementById('mobPageCount').innerText = "P" + count;
            updatePageTotalBadge();
        }

        function getTotalPageCount() {
            return savedPages.length + ((batchQueue.length > 0 || tempDocs.front) ? 1 : 0);
        }

        function updatePageTotalBadge() {
            const badge = document.getElementById('pageTotalBadge');
            if (!badge) return;
            const total = Math.max(1, getTotalPageCount());
            badge.textContent = total + (total === 1 ? ' Page' : ' Pages');
        }

        function openPagesModal() {
            const grid = document.getElementById('pagesGrid');
            grid.innerHTML = '';
            savedPages.forEach((src, i) => {
                const div = document.createElement('div');
                div.className = 'page-card';
                div.innerHTML = `
                    <div class="flex justify-between items-center mb-2"><p class="text-[11px] font-black text-slate-700">Page ${i+1}</p><button onclick="deleteSavedPage(${i})" class="text-[10px] text-red-500 font-black">DEL</button></div>
                    <div class="page-thumb-frame mb-2"><img src="${src}"></div>
                    <div class="grid grid-cols-[1fr_34px] gap-1.5">
                        <button onclick="restorePage(${i})" class="py-1.5 text-[11px] text-white bg-brand font-black rounded shadow-sm">EDIT</button>
                        <button onclick="downloadSavedPage(${i})" class="h-7 flex items-center justify-center bg-gray-100 text-slate-700 rounded hover:bg-slate-200"><i class="fa-solid fa-download text-xs"></i></button>
                    </div>`;
                grid.appendChild(div);
            });
            if(batchQueue.length > 0 || tempDocs.front) {
                const src = previewCanvas.toDataURL('image/jpeg', 0.8);
                const div = document.createElement('div');
                div.className = 'page-card active';
                div.innerHTML = `<div class="flex justify-between items-center mb-2"><p class="text-[11px] font-black text-brand">Current</p><span class="text-[9px] font-black text-blue-500">ACTIVE</span></div><div class="page-thumb-frame mb-2"><img src="${src}"></div><p class="text-[10px] text-gray-400 text-center font-bold">Currently Editing</p>`;
                grid.appendChild(div);
            }
            if(savedPages.length === 0 && batchQueue.length === 0 && !tempDocs.front) { grid.innerHTML = '<p class="col-span-2 text-center text-gray-400 text-sm py-10">No pages yet.</p>'; }
            document.getElementById('pagesModal').classList.remove('hidden');
        }

        function restorePage(index) {
            showConfirm("Edit Page " + (index+1) + "?", "Current workspace will be replaced.", () => {
                batchQueue.forEach(i => safeDeleteItemMats(i)); batchQueue=[];
                const meta = savedPageMeta[index] || {};
                const pageSrc = savedPages[index] || '';
                const restoredItems = cloneSavedPageItems(getSavedPageMetaItems(meta));
                const removeSavedRecord = () => {
                    cleanupSavedPageMeta(index);
                    savedPages.splice(index, 1);
                    savedPageMeta.splice(index, 1);
                };
                if (restoredItems.length) {
                    removeSavedRecord();
                    setDocType(meta.type || 'pvc');
                    if (meta.type === 'pvc') pvcPageSizeMode = meta.pageMode === 'photo4x6' ? 'photo4x6' : 'a4';
                    batchQueue = restoredItems;
                    relayoutQueueItems(meta.type || currentType);
                    syncPvcPageSizeModeUi();
                    selectedItem = batchQueue.length ? { index: 0, side: 'front' } : { index: -1, side: null };
                    updateListUI();
                    renderSheet();
                    updatePageCountUI();
                    document.getElementById('pagesModal').classList.add('hidden');
                    return;
                }
                let img = new Image();
                img.onload = function() {
                    removeSavedRecord();
                    const fallbackType = meta.type === 'pvc' ? 'a4' : (meta.type || 'a4');
                    let mat = cv.imread(img); setDocType(fallbackType); tempDocs.front = mat;
                    updatePageCountUI(); addToSheet(); document.getElementById('pagesModal').classList.add('hidden');
                };
                img.src = pageSrc;
            });
        }
        
        async function downloadSavedPage(index) {
            if (isOutputBlockedByLaunchMode()) {
                showOutputBlockedNotice();
                return;
            }
            if (!checkGatekeeper('download')) return;
            if (!savedPages[index] || !beginSheetOutput()) return;
            const endBusy = beginDownloadButtonBusy('Save');
            try {
                const snapshot = captureSheetOutputSnapshot(savedPageMeta[index] || { type: 'a4' }, savedPages[index]);
                await ensurePvcItemsHighQuality(snapshot.items);
                downloadOutputBlob(await buildSnapshotJpegBlob(snapshot), `AkPrintHub_Page_${index+1}.jpg`);
            } catch (error) {
                console.error('Saved page download failed', error);
                showModal('Download Error', 'Page download nahi hua. Dobara try karein.', 'error');
            } finally { sheetOutputBusy = false; endBusy(); }
        }

        function deleteSavedPage(i) { showConfirm("Delete Page?", "Cannot undo.", ()=>{ cleanupSavedPageMeta(i); savedPages.splice(i, 1); savedPageMeta.splice(i, 1); updatePageCountUI(); openPagesModal(); }); }
        function deleteCurrentOrLastPage() {
            if (batchQueue.length > 0 || tempDocs.front) {
                showConfirm("Delete Current Page?", "Current page ka content clear ho jayega.", () => {
                    batchQueue.forEach(i => safeDeleteItemMats(i));
                    batchQueue=[];
                    clearCurrent();
                    selectedItem = { index: -1, side: null };
                    hideControls();
                    updateListUI();
                    renderSheet();
                    updatePageCountUI();
                });
                return;
            }
            if (savedPages.length > 0) {
                showConfirm("Delete Last Saved Page?", "Last saved page remove ho jayega.", () => {
                    cleanupSavedPageMeta(savedPages.length - 1);
                    savedPages.pop();
                    savedPageMeta.pop();
                    updatePageCountUI();
                    openPagesModal();
                });
                return;
            }
            showModal("No Page", "Delete karne ke liye koi page nahi hai.", "warn");
        }
        function fullReset() { showConfirm("Reset All?", "Clear all pages?", ()=>{ resetPvcBatchUploadState(); savedPages = []; cleanupAllSavedPageMeta(); batchQueue.forEach(i => safeDeleteItemMats(i)); batchQueue=[]; clearCurrent(); selectedItem = { index: -1, side: null }; hideControls(); updateListUI(); renderSheet(); updatePageCountUI(); }); }
        function clearCurrent(){
            safeDeleteMat(tempDocs.front); tempDocs.front=null;
            safeDeleteMat(tempDocs.back); tempDocs.back=null;
            pendingBackFile = null;
            pendingAttachBackIndex = -1;
            pendingPvcPdfDualFlow = false;
            pendingPvcTwoPagePdf = null;
            pvcTwoPageAutoCompleted = false;
            currentPvcSourceDataUrl = '';
            albumCardImageUploadActive = false;
            albumPendingFrontSourceDataUrl = '';
            albumPendingBackSourceDataUrl = '';
            albumPendingFrontLearningMeta = null;
            albumPendingBackLearningMeta = null;
            albumPendingFrontCaptureMeta = null;
            albumPendingBackCaptureMeta = null;
            pendingPvcCropDescriptors = { front: null, back: null };
            pendingDocumentCropDescriptors = { front: null, back: null };
            pendingDocumentSourceDataUrls = { front: '', back: '' };
            pendingDocAlignerPostCropRotation = 0;
            docAlignerDirectApplyActive = false;
            resetDocumentItemRecropState();
            clearPvcRecropTarget();
            resetPvcTwoPageRecropState();
            resetPvcDualSession();
            pvcTemplatePlacementMode = false;
            pvcTemplateBoxes = { front: null, back: null };
            pvcTemplateScale = { w: 100, h: 100 };
            togglePvcSizePanel(false);
            ['thumbFront','checkFront','thumbBack','checkBack','mobThumbFront','mobThumbBack'].forEach(id=>document.getElementById(id).classList.add('hidden'));
            syncAlbumCardImageUploadUi();
            renderSheet();
        }
        
        function updateListUI(){
            document.getElementById('batchList').innerHTML = batchQueue.map((item, i) => {
                const itemName = isDocumentAlbumLaunch && item?.type === 'pvc'
                    ? `${item.isAlbumCover ? 'Album Cover' : `Album Set ${i + 1}`}${item.back ? ' · Front + Back' : ' · Front only'}`
                    : (item?.pvcTwoPagePair
                        ? `#${i + 1} PVC Card · PDF Page 1 + 2`
                        : `#${i + 1} ${DOC_TYPES[item.type].name}`);
                return `<div class="flex justify-between p-2 bg-white border rounded items-center mb-1 shadow-sm"><span class="text-xs font-bold text-slate-700">${itemName}</span><button onclick="remItem(${i})" class="w-6 h-6 flex items-center justify-center text-red-500 hover:bg-red-50 rounded"><i class="fa-solid fa-trash-can"></i></button></div>`;
            }).join('') || '<p class="text-[10px] text-gray-400 text-center py-4">Queue Empty</p>';
            syncAlbumCoverUploadUi();
            updatePvcRecropToolbarVisibility();
            updatePageTotalBadge();
        }
        
        function remItem(i){ 
            if (!batchQueue[i]) return;
            if (isDocumentAlbumLaunch && i < DOCUMENT_ALBUM_PAGE_LIMIT - 1 && getAlbumCoverItem()) {
                showModal('Cover Slot Locked', 'Cover ready hone ke baad pehle Album Cover set delete karein, phir document set hata sakte hain. Isse fold-order kharab nahi hoga.', 'warn');
                return;
            }
            safeDeleteItemMats(batchQueue[i]); batchQueue.splice(i,1); 
            if (isDocumentAlbumLaunch) relayoutQueueItems('pvc');
            selectedItem = {index:-1, side:null}; hideControls();
            updateListUI(); renderSheetNow(); 
        }

        function syncSelectionToolbar() {
            if (isDocumentAlbumLaunch) syncAlbumCardImageUploadUi();
            const controls = document.getElementById('canvasControls');
            if (!controls) return;
            const item = selectedItem.index >= 0 ? batchQueue[selectedItem.index] : null;
            const isPvcSelection = item?.type === 'pvc';
            const show = !!item && (isDocAlignerDocumentType(item.type) || isPvcSelection);
            controls.classList.toggle('visible', show);
            controls.classList.toggle('pvc-tools-visible', !!isPvcSelection);
            controls.querySelectorAll('.standard-selection-tool').forEach((button) => {
                button.classList.toggle('pvc-hidden', !!isPvcSelection);
            });
            const docAlignerRecrop = document.getElementById('btnDocAlignerRecrop');
            if (docAlignerRecrop) {
                const selectedSide = selectedItem.side === 'back' && isMatUsable(item?.back) ? 'back' : 'front';
                const selectedSource = selectedSide === 'back'
                    ? (item?.backSourceDataUrl || item?.sourceDataUrl)
                    : (item?.frontSourceDataUrl || item?.sourceDataUrl);
                const canDocAlignerRecrop = DOCALIGNER_TEST_MODE
                    && !!item?.docAlignerAutoCrop
                    && isDocAlignerDocumentType(item?.type)
                    && !!selectedSource;
                docAlignerRecrop.classList.toggle('hidden', !canDocAlignerRecrop);
            }
            updatePreviewToolbarVisibility();
            updatePvcRecropToolbarVisibility();
        }

        function updatePreviewPageZoomUi() {
            const label = `${Math.round(previewPageZoom * 100)}%`;
            document.querySelectorAll('[data-preview-page-zoom]').forEach((btn) => {
                if (!btn) return;
                btn.classList.toggle('active', previewPageZoom > 1);
                btn.title = `Page zoom ${label}`;
                const labelEl = btn.querySelector('[data-zoom-label]');
                if (labelEl) labelEl.textContent = label;
            });
        }

        function getPreviewZoomFocus() {
            const page = getSheetSize(currentType);
            let item = null;
            if (selectedItem.index >= 0 && batchQueue[selectedItem.index]) {
                item = batchQueue[selectedItem.index];
            } else if (batchQueue.length) {
                item = batchQueue[batchQueue.length - 1];
            }
            if (item) {
                const itemW = item.w * item.scale * (item.scaleX || 1);
                const itemH = item.h * item.scale * (item.scaleY || 1);
                const rects = [{ x: item.xF, y: item.yF, w: itemW, h: itemH }];
                if (item.back && item.type !== 'a4') rects.push({ x: item.xB, y: item.yB, w: itemW, h: itemH });
                const left = Math.min(...rects.map((r) => r.x));
                const top = Math.min(...rects.map((r) => r.y));
                const right = Math.max(...rects.map((r) => r.x + r.w));
                const bottom = Math.max(...rects.map((r) => r.y + r.h));
                return {
                    x: (left + right) / 2,
                    y: (top + bottom) / 2,
                    xPct: Math.max(0, Math.min(100, ((left + right) / 2 / page.w) * 100)),
                    yPct: Math.max(0, Math.min(100, ((top + bottom) / 2 / page.h) * 100))
                };
            }
            if (tempDocs.front) {
                const layout = getItemLayoutForType(currentType, batchQueue.length, !!tempDocs.back);
                const w = (DOC_TYPES[currentType]?.w || page.w) * (layout.scale || 1);
                const h = (DOC_TYPES[currentType]?.h || page.h) * (layout.scale || 1);
                const left = tempDocs.back ? Math.min(layout.xF, layout.xB) : layout.xF;
                const top = tempDocs.back ? Math.min(layout.yF, layout.yB) : layout.yF;
                const right = tempDocs.back ? Math.max(layout.xF + w, layout.xB + w) : layout.xF + w;
                const bottom = tempDocs.back ? Math.max(layout.yF + h, layout.yB + h) : layout.yF + h;
                return {
                    x: (left + right) / 2,
                    y: (top + bottom) / 2,
                    xPct: Math.max(0, Math.min(100, ((left + right) / 2 / page.w) * 100)),
                    yPct: Math.max(0, Math.min(100, ((top + bottom) / 2 / page.h) * 100))
                };
            }
            return { x: page.w / 2, y: page.h / 2, xPct: 50, yPct: 50 };
        }

        function focusPreviewZoomTarget() {
            const scroller = document.getElementById('printSection');
            const stage = document.getElementById('previewPageStage');
            if (!scroller || !stage) return;
            if (previewZoomCenterAnimation) cancelAnimationFrame(previewZoomCenterAnimation);
            const startedAt = performance.now();
            const preservedScrollTop = scroller.scrollTop;
            const keepPageCentered = (now) => {
                const targetX = stage.offsetLeft + (stage.offsetWidth / 2) - (scroller.clientWidth / 2);
                scroller.scrollTo({
                    left: Math.max(0, targetX),
                    top: preservedScrollTop,
                    behavior: 'auto'
                });
                syncPreviewSelectionVisualScale();
                if (now - startedAt < 380) {
                    previewZoomCenterAnimation = requestAnimationFrame(keepPageCentered);
                } else {
                    previewZoomCenterAnimation = null;
                }
            };
            previewZoomCenterAnimation = requestAnimationFrame(keepPageCentered);
        }

        function applyPreviewPageZoom(shouldFocus = true) {
            resizePreviewCanvas();
            updatePreviewSelectionOverlay();
            if (shouldFocus) focusPreviewZoomTarget();
        }

        function togglePreviewPageZoom() {
            if (savedPages.length === 0 && batchQueue.length === 0 && !tempDocs.front) {
                showModal("Preview Empty", "Zoom ke liye pehle card add/select karein.", "warn");
                return;
            }
            const steps = [1, 1.5, 2, 3, 4];
            const currentIndex = steps.findIndex((step) => Math.abs(step - previewPageZoom) < 0.01);
            previewPageZoom = steps[(currentIndex + 1) % steps.length];
            applyPreviewPageZoom();
        }

        function zoomPreviewPage(direction = 1) {
            if (savedPages.length === 0 && batchQueue.length === 0 && !tempDocs.front) {
                showModal("Preview Empty", "Zoom ke liye pehle card add/select karein.", "warn");
                return;
            }
            const dir = direction < 0 ? -1 : 1;
            previewPageZoom = Math.max(1, Math.min(4, Math.round((previewPageZoom + (dir * 0.2)) * 10) / 10));
            applyPreviewPageZoom();
        }

        function openPreviewZoomModal() { togglePreviewPageZoom(); }
        function closePreviewZoomModal() { previewPageZoom = 1; applyPreviewPageZoom(); }
        
        function zoomSelection(delta) {
            if(selectedItem.index === -1) return;
            const item = batchQueue[selectedItem.index];
            item.scale += delta;
            if(item.scale < 0.2) item.scale = 0.2; if(item.scale > 2.0) item.scale = 2.0;
            requestSmoothPreviewRender();
        }

        function resizeSelectionAxis(axis, delta) {
            if(selectedItem.index === -1) return;
            const item = batchQueue[selectedItem.index];
            if (item.type === 'pvc') return;
            if (axis === 'x') {
                item.scaleX = Math.max(0.25, Math.min(2.5, (item.scaleX || 1) + delta));
            } else {
                item.scaleY = Math.max(0.25, Math.min(2.5, (item.scaleY || 1) + delta));
            }
            requestSmoothPreviewRender();
        }

        function rotateSelection(delta) {
            if (selectedItem.index === -1) return;
            const item = batchQueue[selectedItem.index];
            if (!item || item.type === 'pvc') return;
            const side = selectedItem.side === 'back' && isMatUsable(item.back) ? 'back' : 'front';
            const mat = side === 'back' ? item.back : item.front;
            if (!isMatUsable(mat)) return;

            // This is content orientation, not page placement rotation. Keeping
            // the outer print box unchanged and swapping the draw axes at 90/270
            // cancels the old landscape stretch instead of making Aadhaar flat.
            const rotationKey = side === 'back' ? 'backContentRotation' : 'frontContentRotation';
            const turn = normalizeRightAngle(delta);
            item[rotationKey] = normalizeRightAngle((item[rotationKey] || 0) + turn);

            // Preserve the same reading direction if an AI item is opened in
            // Re-Crop later: that flow rebuilds pixels from the original source.
            const descriptorKey = side === 'back' ? 'backCropDescriptor' : 'frontCropDescriptor';
            const descriptor = item[descriptorKey];
            if (descriptor && typeof descriptor === 'object') {
                const baseKey = side === 'back' ? 'backPostCropRotationBase' : 'frontPostCropRotationBase';
                if (!Number.isFinite(Number(item[baseKey]))) {
                    item[baseKey] = normalizeRightAngle(descriptor.postCropRotation || 0);
                }
                descriptor.postCropRotation = normalizeRightAngle(item[baseKey] + item[rotationKey]);
            }
            recordAiActivity('preview_content_rotated', {
                crop_side: side,
                rotation_degrees: item[rotationKey],
                selected_family: item.type,
                ai_crop: !!item.docAlignerAutoCrop
            });
            document.getElementById('mobStatus').innerText = `${side === 'back' ? 'Back' : 'Front'} image ${item[rotationKey]}° rotate hui; print size same hai.`;
            requestSmoothPreviewRender();
        }

        function resetSelectionPosition() {
            if(selectedItem.index === -1) return;
            const i = selectedItem.index;
            const item = batchQueue[i];
            const conf = DOC_TYPES[item.type];
            item.scale = (item.type === 'a4') ? 0.94 : 1.0; 
            item.scaleX = 1;
            item.scaleY = 1;
            item.rotation = 0;
            item.frontContentRotation = 0;
            item.backContentRotation = 0;
            if (item.frontCropDescriptor && Number.isFinite(Number(item.frontPostCropRotationBase))) {
                item.frontCropDescriptor.postCropRotation = normalizeRightAngle(item.frontPostCropRotationBase);
            }
            if (item.backCropDescriptor && Number.isFinite(Number(item.backPostCropRotationBase))) {
                item.backCropDescriptor.postCropRotation = normalizeRightAngle(item.backPostCropRotationBase);
            }
            const page = getSheetSize(item.type);
            const wCanvas = page.w; const hCanvas = page.h;
            if (item.type === 'a4') {
                const sW = item.w * item.scale; const sH = item.h * item.scale;
                item.xF = (wCanvas - sW) / 2; item.yF = (hCanvas - sH) / 2;
            } else if (item.type === 'pvc' && pvcPageSizeMode === 'photo4x6') {
                const layout = getItemLayoutForType(item.type, 0, !!item.back);
                Object.assign(item, layout);
            } else if (!item.back) {
                const { gap, startY } = getSheetRowLayoutConfig(item.type);
                item.xF = (wCanvas - item.w) / 2;
                item.yF = startY + (i * (item.h + gap));
                item.xB = item.xF + item.w + gap;
                item.yB = item.yF;
            } else {
                const { gap, startY } = getSheetRowLayoutConfig(item.type); const totalRowW=(conf.w*2)+gap; const startX=(wCanvas-totalRowW)/2;
                const rowY=startY+(i*(conf.h+gap)); 
                item.xF = startX; item.yF = rowY;
                if(item.back) { item.xB = startX+conf.w+gap; item.yB = rowY; }
            }
            renderSheet();
        }

        function deleteSelection() { if(selectedItem.index === -1) return; remItem(selectedItem.index); }
        function hideControls() { document.getElementById('canvasControls').classList.remove('visible'); selectedItem = {index:-1, side:null}; updatePreviewToolbarVisibility(); renderSheet(); }

        function initSheetDrag(){
            let dragStart = {x:0,y:0};
            let resizeStart = null;
            const getCoord=e=>{
                const sheet = getSheetSize(currentType);
                const sheetW = sheet.w;
                const sheetH = sheet.h;
                const r=previewCanvas.getBoundingClientRect();
                const p=getPointerClient(e);
                const cssW=Math.max(1,r.width), cssH=Math.max(1,r.height);
                return {
                    x:(p.x-r.left)*(sheetW/cssW),
                    y:(p.y-r.top)*(sheetH/cssH),
                    cssToSheetX: sheetW / cssW,
                    cssToSheetY: sheetH / cssH,
                    dragPaddingX: 2 * (sheetW / cssW),
                    dragPaddingY: 2 * (sheetH / cssH)
                };
            };
            const getPreviewHandles = (x, y, w, h) => ([
                { mode: 'resize-left-top', x, y },
                { mode: 'resize-top', x: x + w / 2, y },
                { mode: 'resize-right-top', x: x + w, y },
                { mode: 'resize-right', x: x + w, y: y + h / 2 },
                { mode: 'resize-right-bottom', x: x + w, y: y + h },
                { mode: 'resize-bottom', x: x + w / 2, y: y + h },
                { mode: 'resize-left-bottom', x, y: y + h },
                { mode: 'resize-left', x, y: y + h / 2 }
            ]);
            const hitResizeHandle = (m, x, y, w, h, item) => {
                if (item.type === 'pvc') return '';
                let best = null;
                getPreviewHandles(x, y, w, h).forEach((handle) => {
                    const isCorner = handle.mode.includes('left-') || handle.mode.includes('right-');
                    const isHorizontalPill = handle.mode === 'resize-top' || handle.mode === 'resize-bottom';
                    const halfWidthPx = isCorner ? 6 : (isHorizontalPill ? 10 : 4.5);
                    const halfHeightPx = isCorner ? 6 : (isHorizontalPill ? 4.5 : 10);
                    const hitX = (halfWidthPx + 4) * (m.cssToSheetX || 1);
                    const hitY = (halfHeightPx + 4) * (m.cssToSheetY || 1);
                    const dx = Math.abs(m.x - handle.x);
                    const dy = Math.abs(m.y - handle.y);
                    const d = Math.hypot(dx / Math.max(1, hitX), dy / Math.max(1, hitY));
                    if (dx <= hitX && dy <= hitY && (!best || d < best.d)) best = { mode: handle.mode, d };
                });
                return best ? best.mode : '';
            };
            const pointInSheetRect = (m, x, y, w, h) => {
                const padX = m.dragPaddingX || 0;
                const padY = m.dragPaddingY || 0;
                return m.x >= x - padX && m.x <= x + w + padX && m.y >= y - padY && m.y <= y + h + padY;
            };
            const getItemSideRect = (item, side) => {
                const w = item.w * item.scale * (item.scaleX || 1);
                const h = item.h * item.scale * (item.scaleY || 1);
                return side === 'back'
                    ? { x: item.xB, y: item.yB, w, h }
                    : { x: item.xF, y: item.yF, w, h };
            };
            const clampItemToSheet = (item, side) => {
                const sheet = getSheetSize(item.type || currentType);
                const sheetW = sheet.w;
                const sheetH = sheet.h;
                const xKey = side === 'back' ? 'xB' : 'xF';
                const yKey = side === 'back' ? 'yB' : 'yF';
                const handlePad = 42;
                const maxSheetW = Math.max(1, sheetW - (handlePad * 2));
                const maxSheetH = Math.max(1, sheetH - (handlePad * 2));
                const baseW = item.w * item.scale;
                const baseH = item.h * item.scale;
                if (baseW * (item.scaleX || 1) > maxSheetW) item.scaleX = maxSheetW / Math.max(1, baseW);
                if (baseH * (item.scaleY || 1) > maxSheetH) item.scaleY = maxSheetH / Math.max(1, baseH);
                const w = item.w * item.scale * (item.scaleX || 1);
                const h = item.h * item.scale * (item.scaleY || 1);
                item[xKey] = Math.max(handlePad, Math.min(item[xKey], sheetW - w - handlePad));
                item[yKey] = Math.max(handlePad, Math.min(item[yKey], sheetH - h - handlePad));
            };
            const beginTarget = (i, side, mode, m, rect) => {
                sheetDragIndex = i;
                sheetDragTarget = mode || side;
                sheetDragOffset = { x: m.x - rect.x, y: m.y - rect.y };
                resizeStart = { side, x: rect.x, y: rect.y, w: rect.w, h: rect.h };
                selectedItem = { index: i, side };
            };
            const findTarget = (m) => {
                for(let i=batchQueue.length-1;i>=0;i--){
                    const item=batchQueue[i];
                    const sides = item.back && item.type !== 'a4' ? ['back', 'front'] : ['front'];
                    for (const side of sides) {
                        const rect = getItemSideRect(item, side);
                        const resizeMode = hitResizeHandle(m, rect.x, rect.y, rect.w, rect.h, item);
                        if (resizeMode) return { i, side, mode: resizeMode, rect };
                    }
                    for (const side of sides) {
                        const rect = getItemSideRect(item, side);
                        if (pointInSheetRect(m, rect.x, rect.y, rect.w, rect.h)) return { i, side, mode: side, rect };
                    }
                }
                return '';
            };
            
            const start=e=>{
                if(e.target.closest('#canvasControls')) return;
                const m=getCoord(e);
                dragStart = m;
                resizeStart = null;
                const forcedHandle = e.target?.dataset?.handle || '';
                let found = findTarget(m);
                if (!found && forcedHandle && selectedItem.index >= 0 && batchQueue[selectedItem.index]) {
                    const selected = batchQueue[selectedItem.index];
                    const side = selectedItem.side === 'back' && selected.back && selected.type !== 'a4' ? 'back' : 'front';
                    found = { i: selectedItem.index, side, mode: forcedHandle, rect: getItemSideRect(selected, side) };
                }

                if(found) {
                    if (isDocumentAlbumLaunch) {
                        selectedItem = { index: found.i, side: found.side };
                        sheetDragIndex = -1;
                        sheetDragTarget = null;
                        syncSelectionToolbar();
                        renderSheet();
                        e.preventDefault();
                        return;
                    }
                    beginTarget(found.i, found.side, forcedHandle || found.mode, m, found.rect);
                    isDraggingSheet = true;
                    previewCanvas.classList.add('dragging');
                    syncSelectionToolbar();
                    e.preventDefault(); 
                } else {
                    hideControls();
                }
                renderSheet();
            };
            
            const move=e=>{
                if(sheetDragIndex===-1) return;
                e.preventDefault();
                const m=getCoord(e);
                const item=batchQueue[sheetDragIndex];
                if(!item) return;
                const sheet = getSheetSize(item.type || currentType);
                const sheetW = sheet.w;
                const sheetH = sheet.h;
                if(sheetDragTarget.startsWith('resize') && resizeStart){
                    const xKey = resizeStart.side === 'back' ? 'xB' : 'xF';
                    const yKey = resizeStart.side === 'back' ? 'yB' : 'yF';
                    const baseW = item.w * item.scale;
                    const baseH = item.h * item.scale;
                    const minW = baseW * 0.25;
                    const minH = baseH * 0.25;
                    const leftEdge = sheetDragTarget.includes('left');
                    const rightEdge = sheetDragTarget.includes('right');
                    const topEdge = sheetDragTarget.includes('top');
                    const bottomEdge = sheetDragTarget.includes('bottom');
                    if (leftEdge || rightEdge) {
                        const rawW = leftEdge ? (resizeStart.x + resizeStart.w - m.x) : (m.x - resizeStart.x);
                        const maxWBySheet = leftEdge ? (resizeStart.x + resizeStart.w - 42) : (sheetW - resizeStart.x - 42);
                        const nextW = Math.max(minW, Math.min(baseW * 2.5, maxWBySheet, rawW));
                        item.scaleX = nextW / baseW;
                        if (leftEdge) item[xKey] = resizeStart.x + resizeStart.w - nextW;
                    }
                    if (topEdge || bottomEdge) {
                        const rawH = topEdge ? (resizeStart.y + resizeStart.h - m.y) : (m.y - resizeStart.y);
                        const maxHBySheet = topEdge ? (resizeStart.y + resizeStart.h - 42) : (sheetH - resizeStart.y - 42);
                        const nextH = Math.max(minH, Math.min(baseH * 2.5, maxHBySheet, rawH));
                        item.scaleY = nextH / baseH;
                        if (topEdge) item[yKey] = resizeStart.y + resizeStart.h - nextH;
                    }
                    clampItemToSheet(item, resizeStart.side);
                } else if(sheetDragTarget==='front'){item.xF=m.x-sheetDragOffset.x;item.yF=m.y-sheetDragOffset.y; clampItemToSheet(item, 'front');}
                else{item.xB=m.x-sheetDragOffset.x;item.yB=m.y-sheetDragOffset.y; clampItemToSheet(item, 'back');}
                requestSmoothPreviewRender();
            };
            
            const end=()=>{
                sheetDragIndex=-1; resizeStart = null; isDraggingSheet = false; previewCanvas.classList.remove('dragging');
                previewFastRenderUntil = 0;
                renderSheet();
            };
            
            ['mousedown','touchstart'].forEach(e=>previewCanvas.addEventListener(e,start,{passive:false})); 
            ['mousemove','touchmove'].forEach(e=>previewCanvas.addEventListener(e,move,{passive:false})); 
            document.querySelectorAll('.preview-select-handle').forEach((handle) => {
                ['mousedown','touchstart'].forEach(e=>handle.addEventListener(e,start,{passive:false}));
            });
            ['mousemove','touchmove'].forEach(e=>window.addEventListener(e, (ev) => { if (sheetDragIndex !== -1) move(ev); }, {passive:false}));
            ['mouseup','touchend'].forEach(e=>window.addEventListener(e,end));
        }

        function renderPageToCanvas(targetCanvas, targetCtx, opts = {}) {
            const sheet = getSheetSize(currentType);
            const baseW = sheet.w, baseH = sheet.h;
            // A PDF/print strip renders at the full sheet scale, translated by
            // its caller. The backing canvas is only a small slice of that page.
            const outW = opts.outputWidth || targetCanvas.width || baseW;
            const outH = opts.outputHeight || targetCanvas.height || baseH;
            const scaleX = outW / baseW;
            const scaleY = outH / baseH;

            targetCtx.imageSmoothingEnabled = true;
            targetCtx.imageSmoothingQuality = targetCtx.canvas === previewCanvas && isPreviewFastRendering() ? 'medium' : 'high';
            targetCtx.fillStyle="white";
            targetCtx.fillRect(0,0,outW,outH);
            
            batchQueue.forEach((item, idx)=>{
                const sW = (item.w * item.scale * (item.scaleX || 1)) * scaleX;
                const sH = (item.h * item.scale * (item.scaleY || 1)) * scaleY;
                const xF = item.xF * scaleX;
                const yF = item.yF * scaleY;
                const xB = item.xB * scaleX;
                const yB = item.yB * scaleY;
                const shouldMirror = item.type === 'pvc' && pvcMirrorOutput;
                const albumRotation = item.type === 'pvc' && isDocumentAlbumLaunch && idx % 2 === 1 ? 180 : 0;
                const frontRotation = (item.rotation || 0) + albumRotation;
                const backRotation = (item.rotation || 0) + albumRotation + (item.type === 'pvc' && pvcPageSizeMode === 'photo4x6' ? 180 : 0);
                drawCardOnContext(targetCtx, item.front, xF, yF, sW, sH, false, shouldMirror, frontRotation, item.frontContentRotation || 0, item.type === 'smart');
                drawDocumentAlbumSlotBorder(targetCtx, xF, yF, sW, sH, scaleX);
                drawPvcItemBorderOnContext(targetCtx, item, xF, yF, sW, sH, frontRotation);
                if(!opts.skipSelection && selectedItem.index === idx && selectedItem.side === 'front') drawSelectionBoxOnContext(targetCtx, xF, yF, sW, sH, scaleX, frontRotation);
                
                if(item.back && item.type !== 'a4') {
                    drawCardOnContext(targetCtx, item.back, xB, yB, sW, sH, false, shouldMirror, backRotation, item.backContentRotation || 0, item.type === 'smart');
                    drawDocumentAlbumSlotBorder(targetCtx, xB, yB, sW, sH, scaleX);
                    drawPvcItemBorderOnContext(targetCtx, item, xB, yB, sW, sH, backRotation);
                    if(!opts.skipSelection && selectedItem.index === idx && selectedItem.side === 'back') drawSelectionBoxOnContext(targetCtx, xB, yB, sW, sH, scaleX, backRotation);
                }
            });

            const conf=DOC_TYPES[currentType];
            if(batchQueue.length<getCurrentPageItemLimit(currentType) && (tempDocs.front||tempDocs.back)){
                if(currentType==='a4'){
                    if(tempDocs.front){
                        const c = getMatCanvas(tempDocs.front);
                        if (!c) return;
                        const sc = 0.94;
                        const sW=outW*sc,sH=outH*sc,offsetX=(outW-sW)/2,offsetY=(outH-sH)/2;
                        targetCtx.drawImage(c,offsetX,offsetY,sW,sH);
                        if (!opts.skipSelection) { targetCtx.strokeStyle="#2563eb"; targetCtx.lineWidth=Math.max(4, 4 * scaleX); targetCtx.strokeRect(offsetX,offsetY,sW,sH); }
                    }
                }
                else{
                    const idx=batchQueue.length;
                    const tempIsSingleSide = currentType === 'pvc' ? !!(isSingleSide || pvcSingleSideAiMode || !tempDocs.back) : !!isSingleSide;
                    const layout = getItemLayoutForType(currentType, idx, !!tempDocs.back && !tempIsSingleSide);
                    const startX = layout.xF * scaleX;
                    const y = layout.yF * scaleY;
                    const shouldMirror = currentType === 'pvc' && pvcMirrorOutput;
                    const tempAlbumRotation = currentType === 'pvc' && isDocumentAlbumLaunch && idx % 2 === 1 ? 180 : 0;
                    const tempBackRotation = tempAlbumRotation + (currentType === 'pvc' && pvcPageSizeMode === 'photo4x6' ? 180 : 0);
                    const tempWidth = layout.w * layout.scale * scaleX;
                    const tempHeight = layout.h * layout.scale * scaleY;
                    drawCardOnContext(targetCtx,tempDocs.front,startX,y,tempWidth,tempHeight,true,shouldMirror,tempAlbumRotation,0,currentType === 'smart');
                    drawDocumentAlbumSlotBorder(targetCtx, startX, y, tempWidth, tempHeight, scaleX);
                    if(tempDocs.back && !tempIsSingleSide) {
                        const tempBackX = layout.xB * scaleX;
                        const tempBackY = layout.yB * scaleY;
                        drawCardOnContext(targetCtx,tempDocs.back,tempBackX,tempBackY,tempWidth,tempHeight,true,shouldMirror,tempBackRotation,0,currentType === 'smart');
                        drawDocumentAlbumSlotBorder(targetCtx, tempBackX, tempBackY, tempWidth, tempHeight, scaleX);
                    }
                }
            }
            drawDocumentAlbumCutFoldGuides(targetCtx, scaleX, scaleY);
        }

        function drawDocumentAlbumCutFoldGuides(targetCtx, scaleX = 1, scaleY = 1) {
            if (!isDocumentAlbumLaunch) return;
            const cardWidth = DOC_TYPES.pvc.w * DOCUMENT_ALBUM_CARD_SCALE;
            const cardHeight = DOC_TYPES.pvc.h * DOCUMENT_ALBUM_CARD_SCALE;
            const startX = (2480 - ((cardWidth * 2) + DOCUMENT_ALBUM_DOCUMENT_GAP)) / 2;
            const rowStep = cardHeight + DOCUMENT_ALBUM_DOCUMENT_GAP;
            const rowY = [0, 1, 2, 3].map((row) => DOCUMENT_ALBUM_START_Y + (row * rowStep));
            const centerX = startX + cardWidth + (DOCUMENT_ALBUM_DOCUMENT_GAP / 2);
            // Mini-album fold pattern: only the centre slit is cut. It starts in
            // the first row-gap and ends in the third row-gap; fold lines are not
            // printed so the final sheet stays clean, exactly like the reference.
            const cutStartY = rowY[0] + cardHeight + (DOCUMENT_ALBUM_DOCUMENT_GAP / 2);
            const cutEndY = rowY[2] + cardHeight + (DOCUMENT_ALBUM_DOCUMENT_GAP / 2);
            const lineScale = Math.max(0.5, Math.min(scaleX, scaleY));
            const drawLine = (x1, y1, x2, y2) => {
                targetCtx.beginPath();
                targetCtx.moveTo(x1 * scaleX, y1 * scaleY);
                targetCtx.lineTo(x2 * scaleX, y2 * scaleY);
                targetCtx.stroke();
            };
            targetCtx.save();
            targetCtx.strokeStyle = '#64748b';
            targetCtx.lineWidth = Math.max(1, 1.5 * lineScale);
            targetCtx.setLineDash([10 * lineScale, 8 * lineScale]);
            drawLine(centerX, cutStartY, centerX, cutEndY);
            targetCtx.restore();
        }

        function drawDocumentAlbumSlotBorder(targetCtx, x, y, width, height, scaleFactor = 1) {
            if (!isDocumentAlbumLaunch || width <= 0 || height <= 0) return;
            const lineWidth = Math.max(1, 2 * Math.max(0.5, Number(scaleFactor) || 1));
            const inset = lineWidth / 2;
            targetCtx.save();
            targetCtx.strokeStyle = '#0f172a';
            targetCtx.lineWidth = lineWidth;
            targetCtx.setLineDash([]);
            targetCtx.strokeRect(x + inset, y + inset, Math.max(0, width - lineWidth), Math.max(0, height - lineWidth));
            targetCtx.restore();
        }

        function drawPvcItemBorderOnContext(targetCtx, item, x, y, width, height, rotation = 0) {
            if (!item || item.type !== 'pvc' || item.borderEnabled !== true || width <= 0 || height <= 0) return;
            const baseWidth = Math.max(2, Math.min(24, Number(item.borderWidth) || 6));
            const itemBaseWidth = Math.max(1, Number(item.w) || DOC_TYPES.pvc.w);
            const itemBaseHeight = Math.max(1, Number(item.h) || DOC_TYPES.pvc.h);
            const lineWidth = Math.max(1, baseWidth * Math.min(width / itemBaseWidth, height / itemBaseHeight));
            targetCtx.save();
            targetCtx.translate(x + width / 2, y + height / 2);
            if (rotation) targetCtx.rotate(rotation * Math.PI / 180);
            targetCtx.translate(-width / 2, -height / 2);
            targetCtx.strokeStyle = /^#[0-9a-f]{6}$/i.test(item.borderColor || '') ? item.borderColor : '#111827';
            targetCtx.lineWidth = lineWidth;
            targetCtx.lineJoin = 'miter';
            targetCtx.setLineDash([]);
            const inset = lineWidth / 2;
            targetCtx.strokeRect(inset, inset, Math.max(0, width - lineWidth), Math.max(0, height - lineWidth));
            targetCtx.restore();
        }

        function getMatCanvas(mat, maxPreviewDim = 0) {
            if (!isMatUsable(mat)) return null;
            const sourceMaxDim = Math.max(mat.cols, mat.rows);
            const usePreviewCache = maxPreviewDim > 0 && sourceMaxDim > maxPreviewDim;
            const cache = usePreviewCache
                ? (maxPreviewDim <= 1200 ? matFastPreviewCanvasCache : matPreviewCanvasCache)
                : matCanvasCache;
            let cached = cache.get(mat);
            const wantedRenderedDim = usePreviewCache ? Math.min(sourceMaxDim, maxPreviewDim) : sourceMaxDim;
            const cachedRenderedDim = Number(cached?.dataset?.akRenderedSourceDim || 0);
            if (!cached || cachedRenderedDim + 2 < wantedRenderedDim) {
                if (!cached) cached = document.createElement('canvas');
                if (usePreviewCache) {
                    const ratio = maxPreviewDim / Math.max(mat.cols, mat.rows);
                    const resized = new cv.Mat();
                    cv.resize(mat, resized, new cv.Size(0, 0), ratio, ratio, cv.INTER_AREA);
                    cv.imshow(cached, resized);
                    safeDeleteMat(resized);
                } else {
                    cv.imshow(cached, mat);
                }
                cached.dataset.akRenderedSourceDim = String(wantedRenderedDim);
                cache.set(mat, cached);
            }
            return cached;
        }

        function getMatPreviewDataUrl(mat, maxPreviewDim = 840) {
            const c = getMatCanvas(mat, maxPreviewDim);
            return c ? c.toDataURL('image/jpeg', 0.92) : '';
        }

        function primeMatForPreview(mat) {
            if (!mat) return;
            try {
                getMatCanvas(mat, Math.max(mat.cols, mat.rows) <= 4096 ? 0 : 1800);
            } catch (e) {
                console.warn('Preview cache warmup failed', e);
            }
        }

        function renderSheetNow() {
            renderPageToCanvas(previewCanvas, ctxPre);
            updatePreviewSelectionOverlay();
            updatePreviewToolbarVisibility();
        }

        function isPreviewFastRendering() {
            return Date.now() < previewFastRenderUntil;
        }

        function requestSmoothPreviewRender() {
            previewFastRenderUntil = Date.now() + 220;
            renderSheet();
            if (previewHighRenderTimer) clearTimeout(previewHighRenderTimer);
            previewHighRenderTimer = setTimeout(() => {
                previewFastRenderUntil = 0;
                renderSheetNow();
            }, 140);
        }

        function renderSheet(){
            if (previewRenderQueued) return;
            previewRenderQueued = true;
            requestAnimationFrame(() => {
                previewRenderQueued = false;
                renderSheetNow();
            });
        }

        function syncPreviewSelectionVisualScale() {
            const box = document.getElementById('previewSelectBox');
            const frame = document.getElementById('previewPageFrame');
            if (!box || !frame) return;
            const renderedWidth = frame.getBoundingClientRect().width;
            const actualZoom = frame.offsetWidth > 0 ? (renderedWidth / frame.offsetWidth) : (previewPageZoom || 1);
            const inverseZoom = 1 / Math.max(0.1, actualZoom || 1);
            box.style.setProperty('--preview-ui-inverse-scale', String(inverseZoom));
            box.style.setProperty('--preview-border-width', `${2 * inverseZoom}px`);
            box.style.setProperty('--preview-ring-width', `${3 * inverseZoom}px`);
            box.style.setProperty('--preview-shadow-y', `${10 * inverseZoom}px`);
            box.style.setProperty('--preview-shadow-blur', `${24 * inverseZoom}px`);
            box.style.setProperty('--preview-corner-radius', `${2 * inverseZoom}px`);
        }

        function updatePreviewSelectionOverlay() {
            const box = document.getElementById('previewSelectBox');
            if (!box) return;
            const item = selectedItem.index >= 0 ? batchQueue[selectedItem.index] : null;
            if (!item) {
                box.style.display = 'none';
                box.classList.remove('pvc-static-selection');
                return;
            }
            const side = selectedItem.side === 'back' && item.back && item.type !== 'a4' ? 'back' : 'front';
            const page = getSheetSize(item.type || currentType);
            const sx = (previewCanvas.offsetWidth || 1) / page.w;
            const sy = (previewCanvas.offsetHeight || 1) / page.h;
            const w = item.w * item.scale * (item.scaleX || 1) * sx;
            const h = item.h * item.scale * (item.scaleY || 1) * sy;
            const x = (side === 'back' ? item.xB : item.xF) * sx;
            const y = (side === 'back' ? item.yB : item.yF) * sy;
            const albumRotation = item.type === 'pvc' && isDocumentAlbumLaunch && selectedItem.index % 2 === 1 ? 180 : 0;
            const displayRotation = (item.rotation || 0) + albumRotation + (side === 'back' && item.type === 'pvc' && pvcPageSizeMode === 'photo4x6' ? 180 : 0);
            syncPreviewSelectionVisualScale();
            box.classList.toggle('pvc-static-selection', item.type === 'pvc');
            box.style.display = 'block';
            box.style.left = `${x}px`;
            box.style.top = `${y}px`;
            box.style.width = `${w}px`;
            box.style.height = `${h}px`;
            box.style.transform = `rotate(${displayRotation}deg)`;
        }
        
        function drawSelectionBoxOnContext(targetCtx, x, y, w, h, scaleFactor = 1, rotation = 0) {
            if (targetCtx.canvas === previewCanvas) return;
            const drawRoundRect = (ctx, x, y, width, height, radius) => {
                const rr = Math.min(radius, width / 2, height / 2);
                ctx.beginPath();
                ctx.moveTo(x + rr, y);
                ctx.lineTo(x + width - rr, y);
                ctx.quadraticCurveTo(x + width, y, x + width, y + rr);
                ctx.lineTo(x + width, y + height - rr);
                ctx.quadraticCurveTo(x + width, y + height, x + width - rr, y + height);
                ctx.lineTo(x + rr, y + height);
                ctx.quadraticCurveTo(x, y + height, x, y + height - rr);
                ctx.lineTo(x, y + rr);
                ctx.quadraticCurveTo(x, y, x + rr, y);
                ctx.closePath();
            };
            targetCtx.save();
            targetCtx.translate(x + (w / 2), y + (h / 2));
            if (rotation) targetCtx.rotate(rotation * Math.PI / 180);
            targetCtx.translate(-(w / 2), -(h / 2));
            const ui = Math.max(scaleFactor, 0.36);
            const blue = '#2563eb';
            targetCtx.lineJoin = 'round';
            targetCtx.strokeStyle = 'rgba(255,255,255,0.96)';
            targetCtx.lineWidth = Math.max(5, 10 * ui);
            targetCtx.strokeRect(0, 0, w, h);
            targetCtx.strokeStyle = blue;
            targetCtx.lineWidth = Math.max(2.2, 4.4 * ui);
            targetCtx.strokeRect(0, 0, w, h);

            const handles = [
                { x: 0, y: 0, type: 'corner' },
                { x: w / 2, y: 0, type: 'v' },
                { x: w, y: 0, type: 'corner' },
                { x: w, y: h / 2, type: 'h' },
                { x: w, y: h, type: 'corner' },
                { x: w / 2, y: h, type: 'v' },
                { x: 0, y: h, type: 'corner' },
                { x: 0, y: h / 2, type: 'h' }
            ];
            handles.forEach((handle) => {
                targetCtx.save();
                targetCtx.translate(handle.x, handle.y);
                targetCtx.fillStyle = "#ffffff";
                targetCtx.strokeStyle = blue;
                targetCtx.lineWidth = Math.max(2, 4 * ui);
                targetCtx.shadowColor = 'rgba(15,23,42,0.18)';
                targetCtx.shadowBlur = 8 * ui;
                targetCtx.shadowOffsetY = 2 * ui;
                if (handle.type === 'corner') {
                    const r = Math.max(8, 17 * ui);
                    targetCtx.beginPath();
                    targetCtx.arc(0, 0, r, 0, Math.PI * 2);
                    targetCtx.fill();
                    targetCtx.stroke();
                } else {
                    const pillW = Math.max(handle.type === 'h' ? 14 : 24, (handle.type === 'h' ? 30 : 16) * ui);
                    const pillH = Math.max(handle.type === 'h' ? 24 : 14, (handle.type === 'h' ? 16 : 30) * ui);
                    drawRoundRect(targetCtx, -pillW / 2, -pillH / 2, pillW, pillH, 999 * ui);
                    targetCtx.fill();
                    targetCtx.stroke();
                }
                targetCtx.restore();
            });
            targetCtx.restore();
        }

        function getIdCardCornerRadius(width, height) {
            const xRadius = Math.abs(Number(width) || 0) * ID_CARD_CORNER_RADIUS_MM / ID_CARD_PHYSICAL_WIDTH_MM;
            const yRadius = Math.abs(Number(height) || 0) * ID_CARD_CORNER_RADIUS_MM / ID_CARD_PHYSICAL_HEIGHT_MM;
            return Math.min(xRadius, yRadius, Math.abs(width) / 2, Math.abs(height) / 2);
        }

        function roundedIdCardPath(targetCtx, x, y, width, height) {
            const radius = getIdCardCornerRadius(width, height);
            targetCtx.beginPath();
            targetCtx.moveTo(x + radius, y);
            targetCtx.arcTo(x + width, y, x + width, y + height, radius);
            targetCtx.arcTo(x + width, y + height, x, y + height, radius);
            targetCtx.arcTo(x, y + height, x, y, radius);
            targetCtx.arcTo(x, y, x + width, y, radius);
            targetCtx.closePath();
        }

        function drawCardOnContext(targetCtx,m,x,y,cw,ch,isPreview=false,mirror=false,rotation=0,contentRotation=0,roundedCorners=false){
            if (m && !isMatUsable(m) && targetCtx.canvas !== previewCanvas) throw new Error('A document image is no longer available. Please re-upload that document.');
            if(isMatUsable(m)){
                let previewSourceLimit = 0;
                if (targetCtx.canvas === previewCanvas) {
                    const sourceMaxDim = Math.max(m.cols, m.rows);
                    previewSourceLimit = isPreviewFastRendering()
                        ? 1200
                        : (sourceMaxDim <= 4096 ? 0 : Math.min(4096, Math.max(previewCanvas.width, previewCanvas.height)));
                }
                const c = getMatCanvas(m, previewSourceLimit);
                if (!c) {
                    targetCtx.fillStyle="#f8fafc";targetCtx.fillRect(x,y,cw,ch);targetCtx.strokeStyle="#cbd5e1";targetCtx.setLineDash([15,15]);targetCtx.strokeRect(x,y,cw,ch);targetCtx.setLineDash([]);
                    return;
                }
                targetCtx.save();
                targetCtx.translate(x + (cw / 2), y + (ch / 2));
                if (rotation) targetCtx.rotate(rotation * Math.PI / 180);
                if (roundedCorners) {
                    roundedIdCardPath(targetCtx, -(cw / 2), -(ch / 2), cw, ch);
                    targetCtx.clip();
                }
                targetCtx.save();
                if (mirror) targetCtx.scale(-1, 1);
                const normalizedContentRotation = normalizeRightAngle(contentRotation);
                if (normalizedContentRotation) targetCtx.rotate(normalizedContentRotation * Math.PI / 180);
                const swapsAxes = normalizedContentRotation === 90 || normalizedContentRotation === 270;
                const drawWidth = swapsAxes ? ch : cw;
                const drawHeight = swapsAxes ? cw : ch;
                targetCtx.drawImage(c, -(drawWidth / 2), -(drawHeight / 2), drawWidth, drawHeight);
                drawInCardEnhancementWipe(targetCtx, m, drawWidth, drawHeight);
                targetCtx.restore();
                if (targetCtx.canvas === previewCanvas && !isPreview) {
                    targetCtx.strokeStyle = "rgba(148,163,184,0.34)";
                    targetCtx.lineWidth = Math.max(1, cw / 1100);
                    if (roundedCorners) {
                        roundedIdCardPath(targetCtx, -(cw / 2), -(ch / 2), cw, ch);
                        targetCtx.stroke();
                    } else {
                        targetCtx.strokeRect(-(cw / 2), -(ch / 2), cw, ch);
                    }
                }
                targetCtx.restore();
            }
            else{ targetCtx.fillStyle="#f8fafc";targetCtx.fillRect(x,y,cw,ch);targetCtx.strokeStyle="#cbd5e1";targetCtx.setLineDash([15,15]);targetCtx.strokeRect(x,y,cw,ch);targetCtx.setLineDash([]); }
        }

        function getUniqueFilename(ext) {
            const now = new Date();
            const ts = now.getFullYear() + String(now.getMonth()+1).padStart(2,'0') + String(now.getDate()).padStart(2,'0') + "_" + String(now.getHours()).padStart(2,'0') + String(now.getMinutes()).padStart(2,'0') + String(now.getSeconds()).padStart(2,'0');
            return `AkPrintHub_${ts}.${ext}`;
        }

        function inferDataUrlExt(dataUrl) {
            if ((dataUrl || '').startsWith('data:image/png')) return 'png';
            if ((dataUrl || '').startsWith('data:image/webp')) return 'webp';
            return 'jpg';
        }

        function inferDataUrlFormat(dataUrl) {
            return inferDataUrlExt(dataUrl).toUpperCase() === 'JPG' ? 'JPEG' : inferDataUrlExt(dataUrl).toUpperCase();
        }

        function beginDownloadButtonBusy(label = 'Processing') {
            const btn = window.event?.currentTarget || document.activeElement;
            if (!btn || !btn.classList || btn.dataset.downloadBusy === '1') return () => {};
            btn.dataset.downloadBusy = '1';
            btn.dataset.originalHtml = btn.innerHTML;
            btn.disabled = true;
            btn.classList.add('download-action-busy');
            btn.innerHTML = `<i class="fa-solid fa-spinner fa-spin"></i> ${escapeHtml(label)}`;
            return () => {
                btn.disabled = false;
                btn.classList.remove('download-action-busy');
                btn.innerHTML = btn.dataset.originalHtml || btn.innerHTML;
                delete btn.dataset.originalHtml;
                delete btn.dataset.downloadBusy;
            };
        }

        function downloadDataUrlFile(dataUrl, fileName) {
            const a = document.createElement('a');
            a.download = fileName;
            a.href = dataUrl;
            a.click();
        }

        function buildExportCanvas(scale = 1) {
            const exportCanvas = document.createElement('canvas');
            const page = getSheetSize(currentType);
            scale = getSafeSheetBitmapScale(page, scale);
            exportCanvas.width = Math.round(page.w * scale);
            exportCanvas.height = Math.round(page.h * scale);
            const exportCtx = exportCanvas.getContext('2d');
            if (!exportCtx) throw new Error('Browser could not allocate the export image. Please close other heavy tabs and retry.');
            renderPageToCanvas(exportCanvas, exportCtx, { skipSelection: true });
            return exportCanvas;
        }

        // Full-page JPG must fit in one bitmap. PDF/print use lossless strips at
        // the original export resolution and are not subject to this JPG cap.
        function getSafeSheetBitmapScale(page, requestedScale = 1) {
            const lowMemory = /Android|iPhone|iPad|iPod/i.test(navigator.userAgent || '')
                || (navigator.deviceMemory && navigator.deviceMemory <= 4);
            const maxPixels = lowMemory ? 14000000 : 36000000;
            return Math.min(Math.max(0.1, requestedScale), Math.sqrt(maxPixels / (page.w * page.h)), 8192 / Math.max(page.w, page.h));
        }

        function encodeCanvasDataUrl(canvas, mime = 'image/png', quality = 1) {
            const result = canvas.toDataURL(mime, quality);
            if (!result || result === 'data:,' || result.length < 32) throw new Error('Browser image export failed. Original crops are still available; please retry.');
            return result;
        }

        function releaseOutputCanvas(canvas) {
            if (canvas) { canvas.width = 0; canvas.height = 0; }
        }

        function canvasToBlobChecked(canvas, mime = 'image/png', quality = 1) {
            return new Promise((resolve, reject) => canvas.toBlob((blob) => {
                if (blob?.size) resolve(blob);
                else reject(new Error('Browser could not encode the image. Please retry.'));
            }, mime, quality));
        }

        function downloadOutputBlob(blob, name) {
            const url = URL.createObjectURL(blob);
            const a = document.createElement('a');
            a.href = url;
            a.download = name;
            document.body.appendChild(a);
            a.click();
            a.remove();
            setTimeout(() => URL.revokeObjectURL(url), 60000);
        }

        let sheetOutputBusy = false;
        let pendingPrintCleanup = null;
        function beginSheetOutput() {
            if (sheetOutputBusy) return false;
            if (pendingPrintCleanup) pendingPrintCleanup();
            sheetOutputBusy = true;
            return true;
        }

        function captureSheetOutputSnapshot(meta = null, image = '') {
            const type = meta?.type || currentType;
            const pageMode = meta ? meta.pageMode : pvcPageSizeMode;
            return {
                type, pageMode,
                page: meta?.page || getSheetSize(type),
                items: meta ? getSavedPageMetaItems(meta) : batchQueue.slice(),
                temp: meta ? { front: null, back: null } : { ...tempDocs },
                singleSide: isSingleSide,
                singleAi: pvcSingleSideAiMode,
                mirror: pvcMirrorOutput,
                image
            };
        }

        function getSheetOutputPages() {
            const pages = savedPages.map((image, index) => captureSheetOutputSnapshot(savedPageMeta[index] || { type: 'a4' }, image));
            if (batchQueue.length || tempDocs.front) pages.push(captureSheetOutputSnapshot());
            return pages;
        }

        function withSheetOutputSnapshot(snapshot, render) {
            const previous = { currentType, pvcPageSizeMode, batchQueue, tempDocs, isSingleSide, pvcSingleSideAiMode, pvcMirrorOutput };
            try {
                currentType = snapshot.type;
                pvcPageSizeMode = snapshot.pageMode;
                batchQueue = snapshot.items;
                tempDocs = snapshot.temp;
                isSingleSide = snapshot.singleSide;
                pvcSingleSideAiMode = snapshot.singleAi;
                pvcMirrorOutput = snapshot.mirror;
                return render(); // Synchronous only: restore before yielding.
            } finally {
                ({ currentType, pvcPageSizeMode, batchQueue, tempDocs, isSingleSide, pvcSingleSideAiMode, pvcMirrorOutput } = previous);
            }
        }

        function getOutputPageMm(snapshot) {
            return snapshot.type === 'pvc' && snapshot.pageMode === 'photo4x6'
                ? { w: 101.6, h: 152.4, format: [101.6, 152.4] }
                : { w: 210, h: 297, format: 'a4' };
        }

        async function forEachSheetOutputTile(snapshot, quality, consume) {
            const hasItems = snapshot.items.length || snapshot.temp.front;
            const image = !hasItems && snapshot.image ? await loadImageFromDataUrl(snapshot.image) : null;
            if (!hasItems && !image) throw new Error('No document available on this page.');
            const scale = withSheetOutputSnapshot(snapshot, () => getCurrentSheetExportScaleForQuality(quality));
            const width = image ? image.naturalWidth : Math.round(snapshot.page.w * scale);
            const height = image ? image.naturalHeight : Math.round(snapshot.page.h * scale);
            // Under 2MP per strip, even for a 900 DPI A4 sheet. No JPEG loss in
            // PDF/print, and no 300MB full-sheet canvas allocation.
            const stripHeight = Math.max(64, Math.min(768, Math.floor(2000000 / width)));
            try {
                for (let top = 0; top < height; top += stripHeight) {
                    const canvas = document.createElement('canvas');
                    canvas.width = width;
                    canvas.height = Math.min(stripHeight, height - top);
                    try {
                        const context = canvas.getContext('2d');
                        if (!context) throw new Error('Browser memory is low. Please close other heavy tabs and retry.');
                        if (image) context.drawImage(image, 0, top, width, canvas.height, 0, 0, width, canvas.height);
                        else {
                            context.translate(0, -top);
                            withSheetOutputSnapshot(snapshot, () => renderPageToCanvas(canvas, context, { skipSelection: true, outputWidth: width, outputHeight: height }));
                        }
                        await consume(canvas, { top, width, height, stripHeight: canvas.height });
                    } finally { releaseOutputCanvas(canvas); }
                    await new Promise((resolve) => setTimeout(resolve, 0));
                }
            } finally { if (image) image.src = ''; }
        }

        async function buildSnapshotJpegBlob(snapshot, quality = 'normal') {
            let canvas = null;
            let image = null;
            try {
                if (snapshot.items.length || snapshot.temp.front) {
                    canvas = withSheetOutputSnapshot(snapshot, () => buildExportCanvas(getCurrentSheetExportScaleForQuality(quality)));
                } else {
                    image = await loadImageFromDataUrl(snapshot.image);
                    const page = { w: image.naturalWidth, h: image.naturalHeight };
                    const scale = getSafeSheetBitmapScale(page, 1);
                    canvas = document.createElement('canvas');
                    canvas.width = Math.round(page.w * scale);
                    canvas.height = Math.round(page.h * scale);
                    const context = canvas.getContext('2d');
                    if (!context) throw new Error('Browser could not allocate the image.');
                    context.fillStyle = '#fff';
                    context.fillRect(0, 0, canvas.width, canvas.height);
                    context.drawImage(image, 0, 0, canvas.width, canvas.height);
                }
                return await canvasToBlobChecked(canvas, 'image/jpeg', 0.98);
            } finally {
                releaseOutputCanvas(canvas);
                if (image) image.src = '';
            }
        }

        async function addSheetSnapshotToPdf(pdf, snapshot, quality, imageCache, progress) {
            const mm = getOutputPageMm(snapshot);
            if (snapshot.type !== 'pvc' || (!snapshot.items.length && !snapshot.temp.front)) {
                return forEachSheetOutputTile(snapshot, quality, async (canvas, tile) => {
                    progress(Math.round((tile.top + tile.stripHeight) / tile.height * 100));
                    const bytes = new Uint8Array(await (await canvasToBlobChecked(canvas)).arrayBuffer());
                    pdf.addImage(bytes, 'PNG', 0, tile.top / tile.height * mm.h, mm.w, tile.stripHeight / tile.height * mm.h, undefined, 'SLOW');
                });
            }
            // Store only the actual card pixels, not a 900 DPI white A4 image.
            // Reusing a Mat + transform reuses the same PDF image resource.
            const items = snapshot.items.slice();
            if (snapshot.temp.front && items.length < getCurrentPageItemLimit('pvc')) {
                const layout = withSheetOutputSnapshot(snapshot, () => getItemLayoutForType('pvc', items.length, !!snapshot.temp.back));
                items.push({ type: 'pvc', ...layout, front: snapshot.temp.front, back: snapshot.temp.back });
            }
            const mmX = mm.w / snapshot.page.w, mmY = mm.h / snapshot.page.h;
            for (let index = 0; index < items.length; index++) {
                const item = items[index];
                const width = item.w * item.scale * (item.scaleX || 1);
                const height = item.h * item.scale * (item.scaleY || 1);
                for (const side of ['front', 'back']) {
                    const mat = item[side];
                    if (!mat && side === 'back') continue;
                    if (!isMatUsable(mat)) throw new Error('A document is unavailable. Please re-upload it.');
                    const rotation = (item.rotation || 0) + (isDocumentAlbumLaunch && index % 2 ? 180 : 0)
                        + (side === 'back' && snapshot.pageMode === 'photo4x6' ? 180 : 0);
                    const contentRotation = normalizeRightAngle(item[`${side}ContentRotation`] || 0);
                    const swapsAxes = contentRotation === 90 || contentRotation === 270;
                    const density = Math.max(mat.cols / (swapsAxes ? height : width), mat.rows / (swapsAxes ? width : height));
                    const radians = rotation * Math.PI / 180;
                    const boundW = Math.abs(Math.cos(radians)) * width + Math.abs(Math.sin(radians)) * height;
                    const boundH = Math.abs(Math.sin(radians)) * width + Math.abs(Math.cos(radians)) * height;
                    const offsetX = (boundW - width) / 2, offsetY = (boundH - height) / 2;
                    const key = JSON.stringify([width, height, rotation, contentRotation, snapshot.mirror, !!item.borderEnabled, item.borderWidth, item.borderColor, isDocumentAlbumLaunch]);
                    let cache = imageCache.get(mat);
                    if (!cache) { cache = new Map(); imageCache.set(mat, cache); }
                    let encoded = cache.get(key);
                    if (!encoded) {
                        const canvas = document.createElement('canvas');
                        // Exact native dimensions for unrotated/right-angle cards.
                        canvas.width = Math.max(1, Math.ceil(boundW * density - 1e-7));
                        canvas.height = Math.max(1, Math.ceil(boundH * density - 1e-7));
                        try {
                            const context = canvas.getContext('2d');
                            if (!context) throw new Error('Browser memory is low. Please retry.');
                            context.scale(canvas.width / boundW, canvas.height / boundH);
                            drawCardOnContext(context, mat, offsetX, offsetY, width, height, false, snapshot.mirror, rotation, contentRotation);
                            drawDocumentAlbumSlotBorder(context, offsetX, offsetY, width, height, 1);
                            drawPvcItemBorderOnContext(context, item, offsetX, offsetY, width, height, rotation);
                            encoded = new Uint8Array(await (await canvasToBlobChecked(canvas)).arrayBuffer());
                            cache.set(key, encoded);
                        } finally { releaseOutputCanvas(canvas); }
                    }
                    const x = Number(item[side === 'back' ? 'xB' : 'xF']) - offsetX;
                    const y = Number(item[side === 'back' ? 'yB' : 'yF']) - offsetY;
                    pdf.addImage(encoded, 'PNG', x * mmX, y * mmY, boundW * mmX, boundH * mmY, undefined, 'SLOW');
                    await new Promise((resolve) => setTimeout(resolve, 0));
                }
                progress(Math.round((index + 1) / items.length * 100));
            }
            if (isDocumentAlbumLaunch) {
                const h = DOC_TYPES.pvc.h * DOCUMENT_ALBUM_CARD_SCALE;
                const gap = DOCUMENT_ALBUM_DOCUMENT_GAP;
                const start = DOCUMENT_ALBUM_START_Y + h + gap / 2;
                pdf.setDrawColor('#64748b');
                pdf.setLineWidth(1.5 * mmX);
                pdf.setLineDashPattern([10 * mmX, 8 * mmX], 0);
                pdf.line(mm.w / 2, start * mmY, mm.w / 2, (start + 2 * (h + gap)) * mmY);
                pdf.setLineDashPattern([], 0);
            }
        }

        function getDataUrlBytes(dataUrl) {
            const comma = String(dataUrl || '').indexOf(',');
            const b64Length = comma >= 0 ? String(dataUrl).length - comma - 1 : String(dataUrl || '').length;
            return Math.ceil((b64Length * 3) / 4);
        }

        async function buildSizedPrintDataUrl(printMode = 'color') {
            await ensurePvcItemsHighQuality(batchQueue);
            const normalizedMode = normalizePrintMode(printMode);
            let scale = getRemotePrintScale();
            const maxBytes = getMaxRemotePrintPayloadBytes();
            for (let attempt = 0; attempt < 4; attempt++) {
                const exportCanvas = buildExportCanvas(scale);
                let dataUrl = exportCanvas.toDataURL('image/jpeg', attempt === 0 ? 0.99 : 0.96);
                if (normalizedMode === 'gray') {
                    dataUrl = await applyPrintModeToDataUrl(dataUrl, normalizedMode);
                }
                if (getDataUrlBytes(dataUrl) <= maxBytes) return dataUrl;
                scale *= 0.82;
            }
            let fallbackDataUrl = buildExportCanvas(1).toDataURL('image/jpeg', 0.95);
            if (normalizedMode === 'gray') {
                fallbackDataUrl = await applyPrintModeToDataUrl(fallbackDataUrl, normalizedMode);
            }
            return fallbackDataUrl;
        }

        function getMatPngDataUrl(mat, mirror = false, scale = getProExportScale(), borderItem = null) {
            const baseCanvas = document.createElement('canvas');
            cv.imshow(baseCanvas, mat);
            const exportCanvas = document.createElement('canvas');
            exportCanvas.width = Math.round(baseCanvas.width * scale);
            exportCanvas.height = Math.round(baseCanvas.height * scale);
            const exportCtx = exportCanvas.getContext('2d');
            exportCtx.imageSmoothingEnabled = true;
            exportCtx.imageSmoothingQuality = 'high';
            exportCtx.save();
            if (mirror) {
                exportCtx.translate(exportCanvas.width, 0);
                exportCtx.scale(-1, 1);
            }
            exportCtx.drawImage(baseCanvas, 0, 0, exportCanvas.width, exportCanvas.height);
            exportCtx.restore();
            if (borderItem?.borderEnabled === true) {
                drawPvcItemBorderOnContext(exportCtx, { ...borderItem, type: 'pvc', w: baseCanvas.width, h: baseCanvas.height }, 0, 0, exportCanvas.width, exportCanvas.height, 0);
            }
            return exportCanvas.toDataURL('image/png');
        }

        function getSingleCardPngDataUrl(item, side = 'front') {
            if (!item) return '';
            const normalizedSide = side === 'back' && isMatUsable(item.back) ? 'back' : 'front';
            const mat = normalizedSide === 'back' ? item.back : item.front;
            const sourceCanvas = getMatCanvas(mat, 0);
            if (!sourceCanvas) return '';

            const rotation = normalizeRightAngle(normalizedSide === 'back'
                ? item.backContentRotation
                : item.frontContentRotation);
            const swapsAxes = rotation === 90 || rotation === 270;
            const outputCanvas = document.createElement('canvas');
            outputCanvas.width = swapsAxes ? sourceCanvas.height : sourceCanvas.width;
            outputCanvas.height = swapsAxes ? sourceCanvas.width : sourceCanvas.height;
            const outputCtx = outputCanvas.getContext('2d');
            outputCtx.imageSmoothingEnabled = true;
            outputCtx.imageSmoothingQuality = 'high';
            outputCtx.save();
            if (item.type === 'smart') {
                roundedIdCardPath(outputCtx, 0, 0, outputCanvas.width, outputCanvas.height);
                outputCtx.clip();
            }
            outputCtx.translate(outputCanvas.width / 2, outputCanvas.height / 2);
            if (rotation) outputCtx.rotate(rotation * Math.PI / 180);
            if (item.type === 'pvc' && pvcMirrorOutput) outputCtx.scale(-1, 1);
            outputCtx.drawImage(sourceCanvas, -sourceCanvas.width / 2, -sourceCanvas.height / 2);
            outputCtx.restore();
            if (item.type === 'pvc' && item.borderEnabled === true) {
                drawPvcItemBorderOnContext(outputCtx, {
                    ...item,
                    type: 'pvc',
                    w: outputCanvas.width,
                    h: outputCanvas.height
                }, 0, 0, outputCanvas.width, outputCanvas.height, 0);
            }
            return outputCanvas.toDataURL('image/png');
        }

        async function downloadSelectedCropImage() {
            if (isOutputBlockedByLaunchMode()) {
                showOutputBlockedNotice();
                return;
            }
            if (!checkGatekeeper('download')) return;
            const selectedIndex = Number(selectedItem.index);
            const item = selectedIndex >= 0 ? batchQueue[selectedIndex] : null;
            if (!item) {
                showModal('Select Card', 'Preview me jis card ko single image me chahiye, pehle us par click karein.', 'warn');
                return;
            }
            const side = selectedItem.side === 'back' && isMatUsable(item.back) ? 'back' : 'front';
            const endBusy = beginDownloadButtonBusy('PNG');
            try {
                if (item.type === 'pvc') await ensurePvcItemsHighQuality([item]);
                const selectedDataUrl = getSingleCardPngDataUrl(item, side);
                if (!selectedDataUrl) throw new Error('Selected crop pixels are unavailable');
                const timestampedName = getUniqueFilename('png').replace(
                    '.png',
                    `_card-${selectedIndex + 1}-${side}.png`
                );
                downloadDataUrlFile(selectedDataUrl, timestampedName);
                document.getElementById('mobStatus').innerText = `${side === 'back' ? 'Back' : 'Front'} single PNG download ho gaya.`;
                showModal('Card Downloaded', `Selected ${side === 'back' ? 'Back' : 'Front'} card bina A4 background ke PNG me save ho gaya.`, 'success');
                if (!window.siteConfig.isLoggedIn) logActivity('increment_download_count');
            } catch (error) {
                console.error('Selected crop download failed', error);
                showModal('Download Error', 'Selected card image download nahi ho payi.', 'error');
            } finally {
                setTimeout(endBusy, 300);
            }
        }

        async function downloadPvcZip() {
            if (isOutputBlockedByLaunchMode()) {
                showOutputBlockedNotice();
                return;
            }
            if (currentType !== 'pvc') {
                showModal("PVC Required", "Front/Back PNG export sirf PVC mode me available hai.", "warn");
                return;
            }
            if (!checkGatekeeper('download')) return;
            const endBusy = beginDownloadButtonBusy('PNG');

            const pvcItems = batchQueue.filter((item) => item?.type === 'pvc');
            if (currentType === 'pvc' && tempDocs.front) {
                pvcItems.push({
                    type: 'pvc',
                    front: tempDocs.front,
                    back: tempDocs.back || null,
                    pvcDocType: pvcAutoCropDocType
                });
            }
            if (pvcItems.length === 0) {
                endBusy();
                showModal("No PVC Item", "Pehle PVC auto crop items sheet me add karein.", "warn");
                return;
            }

            try {
                await loadToolLibrary('ZIP', 'https://cdnjs.cloudflare.com/ajax/libs/jszip/3.10.1/jszip.min.js', () => !!window.JSZip);
                await waitForLoaderPaint();
                await ensurePvcItemsHighQuality(pvcItems);
                const zip = new window.JSZip();
                const scale = getProExportScale();
                pvcItems.forEach((item, index) => {
                    const itemNo = index + 1;
                    const docTypeLabel = (item.pvcDocType || pvcAutoCropDocType || 'pvc').toLowerCase();
                    if (item.front) {
                        const frontBase64 = getMatPngDataUrl(item.front, pvcMirrorOutput, scale, item).split(',')[1];
                        zip.file(`${docTypeLabel}/item-${itemNo}-front.png`, frontBase64, { base64: true });
                    }
                    if (item.back) {
                        const backBase64 = getMatPngDataUrl(item.back, pvcMirrorOutput, scale, item).split(',')[1];
                        zip.file(`${docTypeLabel}/item-${itemNo}-back.png`, backBase64, { base64: true });
                    }
                });

                const blob = await zip.generateAsync({
                    type: 'blob',
                    compression: 'DEFLATE',
                    compressionOptions: { level: 6 }
                });
                const fileName = getUniqueFilename('zip').replace('.zip', '_pvc-front-back-png.zip');
                const url = URL.createObjectURL(blob);
                downloadDataUrlFile(url, fileName);
                setTimeout(() => URL.revokeObjectURL(url), 4000);
                showModal("Downloaded", `${pvcItems.length} PVC item ke front/back PNG ZIP me save ho gaye.`, "success");
            } catch (e) {
                console.error(e);
                showModal("ZIP Error", "Front/back PNG ZIP generate nahi ho paya.", "error");
                return;
            } finally {
                endBusy();
            }

            if (!window.siteConfig.isLoggedIn) {
                logActivity('increment_download_count');
            }
        }

        // --- ★ MODIFIED PROTECTED ACTIONS ★ ---

        function createShopToken() {
            return 'shop_' + Math.random().toString(36).slice(2, 10) + Date.now().toString(36);
        }

        function getCurrentShopQrBaseUrl() {
            const url = new URL(window.location.href);
            url.search = '';
            url.hash = '';
            return url.toString();
        }

        function getShopQrBaseUrl() {
            let baseUrl = localStorage.getItem(SHOP_QR_BASE_KEY) || '';
            try {
                if (baseUrl) {
                    const parsed = new URL(baseUrl, window.location.origin);
                    parsed.search = '';
                    parsed.hash = '';
                    return parsed.toString();
                }
            } catch (e) {
                baseUrl = '';
            }
            baseUrl = getCurrentShopQrBaseUrl();
            localStorage.setItem(SHOP_QR_BASE_KEY, baseUrl);
            return baseUrl;
        }

        function getShopToken() {
            let token = localStorage.getItem(SHOP_TOKEN_KEY) || '';
            if (!token) {
                token = createShopToken();
                localStorage.setItem(SHOP_TOKEN_KEY, token);
            }
            return token.replace(/[^a-zA-Z0-9_-]/g, '').slice(0, 80);
        }

        function getShopRuntimeKey() {
            let key = localStorage.getItem(SHOP_RUNTIME_KEY) || '';
            key = key.replace(/[^a-zA-Z0-9_-]/g, '').slice(0, 80);
            if (!key) {
                const bytes = new Uint8Array(18);
                if (window.crypto?.getRandomValues) {
                    window.crypto.getRandomValues(bytes);
                    key = Array.from(bytes, (value) => value.toString(16).padStart(2, '0')).join('');
                } else {
                    key = `rt_${Date.now()}_${Math.random().toString(16).slice(2)}`;
                }
                key = key.replace(/[^a-zA-Z0-9_-]/g, '').slice(0, 80);
                localStorage.setItem(SHOP_RUNTIME_KEY, key);
            }
            return key;
        }

        function getShopQrUrl() {
            const url = new URL(getShopQrBaseUrl(), window.location.origin);
            url.searchParams.set('quick_print', getShopToken());
            return url.toString();
        }

        function renderShopQr() {
            const box = document.getElementById('shopQrCanvas');
            const input = document.getElementById('shopQrUrlInput');
            const pretty = document.getElementById('shopQrPrettyUrl');
            if (!box || !input) return;
            if (!hasShopAutoPrintPlan()) {
                input.value = '';
                if (pretty) pretty.textContent = 'Auto Print subscription required';
                box.innerHTML = '<div class="w-[148px] h-[148px] rounded-xl border border-amber-200 bg-amber-50 text-amber-700 flex items-center justify-center text-center text-[10px] font-black p-3">Rs 499 Auto Print plan ke baad QR generate hoga</div>';
                return;
            }
            const qrUrl = getShopQrUrl();
            input.value = qrUrl;
            if (pretty) {
                const shortToken = getShopToken().replace(/^shop_/, '').slice(-8).toUpperCase();
                pretty.textContent = `${window.location.host}/quick-print/${shortToken}`;
            }
            box.innerHTML = '';
            if (window.QRCode) {
                new window.QRCode(box, { text: qrUrl, width: 148, height: 148, correctLevel: window.QRCode.CorrectLevel.M });
            } else {
                box.innerHTML = '<p class="text-[10px] text-slate-500 text-center">QR library loading...</p>';
            }
        }

        function formatMoney(value) {
            const amount = normalizeMoney(value);
            return `Rs ${amount.toFixed(amount % 1 ? 2 : 0)}`;
        }

        function getCustomerWalletId() {
            let id = localStorage.getItem(CUSTOMER_WALLET_KEY) || '';
            if (!id) {
                id = 'cust_' + Math.random().toString(36).slice(2, 10) + Date.now().toString(36);
                localStorage.setItem(CUSTOMER_WALLET_KEY, id);
            }
            return id.replace(/[^a-zA-Z0-9_-]/g, '').slice(0, 80);
        }

        function getShopPrintInvoiceUrl(job) {
            const url = new URL('invoice.php', window.location.origin);
            const mode = normalizePrintMode(job?.print_mode);
            const copies = normalizeRemoteCopies(job?.copies || 1);
            url.searchParams.set('source', 'shop_print');
            url.searchParams.set('amount', String(normalizeMoney(job?.payment_amount || 0)));
            url.searchParams.set('color', mode === 'color' ? String(copies) : '0');
            url.searchParams.set('gray', mode === 'gray' ? String(copies) : '0');
            url.searchParams.set('order', String(job?.id || 'SHOP-PRINT'));
            const upi = getShopPaymentSettings().upiId;
            if (upi) url.searchParams.set('upi', upi);
            return url.toString();
        }

        async function renderShopPrintHistory(showPlanModal = false) {
            const box = document.getElementById('shopPrintHistoryList');
            if (!box) return;
            if (!hasShopAutoPrintPlan()) {
                box.dataset.loaded = '1';
                box.innerHTML = '<div class="rounded-xl bg-amber-50 border border-amber-100 p-3 text-amber-700 font-bold">Rs 499 Auto Print subscription ke baad customer jobs, payment history aur approval list active hogi.</div>';
                if (showPlanModal) requireAutoPrintSubscriptionFor('Print list refresh');
                return;
            }
            if (shopHistoryRefreshBusy) return;
            shopHistoryRefreshBusy = true;
            if (!box.dataset.loaded) {
                box.innerHTML = '<div class="rounded-xl bg-white border border-slate-200 p-3 text-slate-500 font-bold">Loading history...</div>';
            }
            try {
                const res = await postShopPrintAction('shop_list_print_history', { shop_token: getShopToken() });
                if (res.status !== 'success') throw new Error(res.message || 'History load failed');
                const jobs = (res.jobs || []).slice(0, 100);
                box.dataset.loaded = '1';
                const walletSummary = document.getElementById('shopWalletSummary');
                const walletBalance = document.getElementById('shopWalletBalance');
                const walletBalanceHeader = document.getElementById('shopWalletBalanceHeader');
                const wallet = res.wallet || {};
                renderShopWalletDashboard(wallet, jobs.length);
                if (walletBalanceHeader) walletBalanceHeader.textContent = formatMoney(wallet.balance || 0);
                if (!jobs.length) {
                    box.innerHTML = '<div class="rounded-xl bg-white border border-slate-200 p-3 text-slate-500 font-bold">Abhi koi customer print job nahi hai.</div>';
                    return;
                }
                Object.keys(shopPrintPreviewCache).forEach((key) => delete shopPrintPreviewCache[key]);
                box.innerHTML = jobs.map((job) => {
                    const status = String(job.status || 'queued');
                    const needsApproval = status === 'payment_review';
                    const paymentPending = status === 'payment_pending';
                    const mode = normalizePrintMode(job.print_mode);
                    const statusClass = (needsApproval || paymentPending) ? 'text-amber-700 bg-amber-50 border-amber-100' : (status === 'printed' ? 'text-emerald-700 bg-emerald-50 border-emerald-100' : 'text-blue-700 bg-blue-50 border-blue-100');
                    const created = job.created_at ? new Date(job.created_at).toLocaleString() : '';
                    const paymentLabel = job.payment_mode === 'online' ? (paymentPending ? 'Online verify pending' : 'Online paid') : (job.payment_mode === 'cash' ? 'Cash at counter' : 'No payment');
                    const statusLabel = paymentPending ? 'payment check' : (needsApproval ? 'approval wait' : status.replace('_', ' '));
                    const sourceName = job.source_name || '';
                    const pageInfo = Number(job.pdf_page_count || 1) > 1 ? `Page ${Number(job.pdf_page_number || 1)}/${Number(job.pdf_page_count || 1)}` : '';
                    const previewId = String(job.id || '').replace(/[^a-zA-Z0-9_-]/g, '');
                    const jobId = escapeHtml(previewId || job.id || '');
                    if (previewId && job.preview_data) shopPrintPreviewCache[previewId] = job.preview_data;
                    return `
                        <div class="rounded-xl bg-white border border-slate-200 p-3">
                            <div class="grid grid-cols-[56px_1fr_auto] items-start gap-2">
                                <button type="button" ${job.preview_data ? `onclick="openShopPrintPreview('${escapeHtml(previewId)}')"` : ''} class="w-14 h-20 rounded-lg bg-slate-50 border border-slate-200 overflow-hidden flex items-center justify-center ${job.preview_data ? 'cursor-zoom-in' : 'cursor-default'}">
                                    ${job.preview_data ? `<img src="${job.preview_data}" alt="Print preview" class="w-full h-full object-contain">` : '<i class="fa-solid fa-file-image text-slate-300"></i>'}
                                </button>
                                <div class="min-w-0">
                                    <p class="font-black text-slate-800 truncate">${escapeHtml(job.customer_name || 'Customer')} - ${escapeHtml(getPrintModeLabel(mode))} - ${normalizeRemoteCopies(job.copies)} copy</p>
                                    ${sourceName || pageInfo ? `<p class="mt-1 text-[11px] font-bold text-slate-600 truncate">${escapeHtml([sourceName, pageInfo].filter(Boolean).join(' - '))}</p>` : ''}
                                    <p class="mt-1 text-[11px] font-bold text-slate-500">${escapeHtml(paymentLabel)} - ${escapeHtml(job.payment_summary || created || job.id || '')}</p>
                                </div>
                                <span class="shrink-0 rounded-full border px-2 py-1 text-[10px] font-black ${statusClass}">${escapeHtml(statusLabel)}</span>
                            </div>
                            <div class="mt-2 flex items-center justify-between gap-2">
                                <span class="text-[11px] font-black text-slate-700">${job.payment_mode === 'online' ? formatMoney(job.payment_amount || 0) : paymentLabel}</span>
                                <span class="flex items-center gap-2">
                                    ${job.payment_mode === 'online' ? `<a href="${getShopPrintInvoiceUrl(job)}" target="_blank" class="rounded-lg bg-slate-100 px-3 py-2 text-[11px] font-black text-slate-700">Receipt</a>` : ''}
                                    ${needsApproval ? `<button onclick="approveShopPaidJob('${jobId}')" class="rounded-lg bg-emerald-600 px-3 py-2 text-[11px] font-black text-white">Approve & Print</button>` : ''}
                                    ${window.siteConfig?.isAutoPrintAdmin ? `<button onclick="deleteShopPrintJob('${jobId}')" class="rounded-lg bg-red-50 border border-red-100 px-3 py-2 text-[11px] font-black text-red-600">Delete</button>` : ''}
                                </span>
                            </div>
                        </div>`;
                }).join('');
            } catch (e) {
                box.innerHTML = `<div class="rounded-xl bg-red-50 border border-red-100 p-3 text-red-600 font-bold">${escapeHtml(e?.message || 'History load failed')}</div>`;
            } finally {
                shopHistoryRefreshBusy = false;
            }
        }

        function renderShopWalletDashboard(wallet = {}, jobCount = 0) {
            const balance = document.getElementById('shopWalletBalance');
            const received = document.getElementById('shopWalletReceived');
            const pending = document.getElementById('shopWalletPending');
            const transferred = document.getElementById('shopWalletTransferred');
            const summary = document.getElementById('shopWalletSummary');
            const list = document.getElementById('shopWalletTxnList');
            const txs = Array.isArray(wallet.transactions) ? wallet.transactions : [];
            const settlementUpi = getShopPaymentSettings().upiId || getShopPaymentSettings().paytmMerchantUpi || '';
            if (balance) balance.textContent = formatMoney(wallet.balance || 0);
            if (received) received.textContent = formatMoney(wallet.total_received || 0);
            if (pending) pending.textContent = formatMoney(wallet.pending_withdrawal || 0);
            if (transferred) transferred.textContent = formatMoney(wallet.total_transferred || 0);
            if (summary) summary.textContent = `Last ${wallet.period_days || 42} days: ${txs.length} entries, ${jobCount} recent print docs. Settlement: ${settlementUpi || 'UPI missing'}.`;
            if (!list) return;
            if (!txs.length) {
                list.innerHTML = '<div class="rounded-xl bg-slate-50 border border-slate-200 p-3 text-slate-500 font-bold">Abhi wallet transaction nahi hai.</div>';
                return;
            }
            list.innerHTML = txs.slice(0, 8).map((tx) => {
                const type = String(tx.type || 'credit');
                const isCredit = type === 'credit';
                const isRequest = type === 'withdraw_request';
                const label = isCredit ? 'Received' : (isRequest ? 'Withdraw request' : 'Transferred');
                const tone = isCredit ? 'text-emerald-700 bg-emerald-50 border-emerald-100' : (isRequest ? 'text-amber-700 bg-amber-50 border-amber-100' : 'text-slate-700 bg-slate-50 border-slate-200');
                const created = tx.created_at ? new Date(tx.created_at).toLocaleString() : '';
                return `
                    <div class="rounded-xl bg-white border border-slate-200 p-3 flex items-start justify-between gap-3">
                        <div class="min-w-0">
                            <p class="font-black text-slate-800 truncate">${escapeHtml(tx.note || label)}</p>
                            <p class="mt-1 text-[11px] font-bold text-slate-500">${escapeHtml(created)} ${tx.customer_name ? '- ' + escapeHtml(tx.customer_name) : ''}</p>
                        </div>
                        <div class="text-right shrink-0">
                            <span class="rounded-full border px-2 py-1 text-[10px] font-black ${tone}">${escapeHtml(label)}</span>
                            <p class="mt-2 text-sm font-black text-slate-900">${isCredit ? '+' : (isRequest ? '' : '-')}${formatMoney(tx.amount || 0)}</p>
                        </div>
                    </div>`;
            }).join('');
        }

        async function requestShopWalletWithdrawal() {
            if (!requireAutoPrintSubscriptionFor('Wallet withdrawal')) return;
            const settlementUpi = getShopPaymentSettings().upiId || getShopPaymentSettings().paytmMerchantUpi || '';
            if (!settlementUpi) {
                showModal('Settlement UPI Missing', 'Withdrawal request se pehle Payment Settings me Settlement UPI ID save karein.', 'warn');
                setAutoPrintStep('settings');
                return;
            }
            const raw = prompt('Withdrawal request amount enter karein');
            if (raw == null) return;
            const amount = normalizeMoney(raw);
            if (amount <= 0) {
                showModal('Invalid Amount', 'Valid withdrawal amount enter karein.', 'warn');
                return;
            }
            try {
                const res = await postShopPrintAction('shop_wallet_withdraw_request', {
                    shop_token: getShopToken(),
                    amount,
                    note: `Shop requested payout to ${settlementUpi}`
                });
                if (res.status !== 'success') throw new Error(res.message || 'Withdraw request failed');
                renderShopWalletDashboard(res.wallet || {}, 0);
                showModal('Request Saved', 'Withdrawal request admin record me save ho gayi.', 'success');
            } catch (e) {
                showModal('Request Failed', e?.message || 'Withdrawal request save nahi hui.', 'error');
            }
        }

        async function loadAdminWalletPanel() {
            if (!window.siteConfig?.isAutoPrintAdmin) return false;
            const box = document.getElementById('adminWalletList');
            const summary = document.getElementById('adminWalletSummary');
            const limitSelect = document.getElementById('adminAutoPrintListLimit');
            if (limitSelect) limitSelect.value = String(adminAutoPrintListLimit);
            if (box) box.innerHTML = '<div class="rounded-xl bg-slate-50 border border-slate-200 p-3 text-slate-500 font-bold">Loading wallet records...</div>';
            try {
                const res = await postShopPrintAction('admin_list_auto_print_wallets');
                if (res.status !== 'success') throw new Error(res.message || 'Wallet list failed');
                const allShops = Array.isArray(res.shops) ? res.shops : [];
                const hasWalletRequest = (shop) => {
                    const wallet = shop?.wallet || {};
                    return Number(wallet.withdraw_request_count || 0) > 0 || normalizeMoney(wallet.pending_withdrawal || 0) > 0;
                };
                const requestShopsAll = allShops.filter(hasWalletRequest);
                const otherShopsAll = allShops.filter((shop) => !hasWalletRequest(shop));
                const shops = requestShopsAll.concat(otherShopsAll).slice(0, adminAutoPrintListLimit);
                const requestShops = shops.filter(hasWalletRequest);
                const otherShops = shops.filter((shop) => !hasWalletRequest(shop));
                if (summary) summary.textContent = `Last ${res.period_days || 42} days: ${requestShopsAll.length} payout request user(s), ${otherShopsAll.length} other wallet record(s). Showing ${shops.length}.`;
                if (!box) return true;
                if (!shops.length) {
                    box.innerHTML = '<div class="rounded-xl bg-slate-50 border border-slate-200 p-3 text-slate-500 font-bold">Abhi koi wallet payment record nahi hai.</div>';
                    return true;
                }
                const renderAdminWalletCards = (list, startIndex, requestGroup = false) => list.map((shop, offset) => {
                    const index = startIndex + offset;
                    const wallet = shop.wallet || {};
                    const printStats = shop.print_stats || {};
                    const settlement = shop.settlement || {};
                    const settlementUpi = settlement.upi_id || settlement.paytm_merchant_upi || '';
                    const settlementName = String(settlement.upi_name || '').trim();
                    const tokens = Array.isArray(shop.shop_tokens) && shop.shop_tokens.length ? shop.shop_tokens : [shop.shop_token || ''];
                    const token = escapeHtml(shop.shop_token || tokens[0] || '');
                    const tokenPayload = encodeURIComponent(JSON.stringify(tokens.filter(Boolean)));
                    const ownerRaw = String(shop.owner_email || shop.owner_user_uid || 'Unknown shop');
                    const owner = escapeHtml(ownerRaw);
                    const payoutPayload = encodeURIComponent(JSON.stringify({
                        tokens: tokens.filter(Boolean),
                        upi: settlementUpi,
                        name: settlementName || ownerRaw,
                        amount: normalizeMoney(wallet.balance || 0),
                        owner: ownerRaw
                    }));
                    const txs = Array.isArray(wallet.transactions) ? wallet.transactions.slice(0, 10) : [];
                    const requestCount = Number(wallet.withdraw_request_count || 0);
                    const totalRequested = normalizeMoney(wallet.total_requested || wallet.pending_withdrawal || 0);
                    const pendingWithdrawal = normalizeMoney(wallet.pending_withdrawal || 0);
                    const latestRequest = txs.find((tx) => String(tx.type || '') === 'withdraw_request') || null;
                    const latestRequestText = latestRequest
                        ? `${escapeHtml(latestRequest.created_at ? new Date(latestRequest.created_at).toLocaleString() : '')} - ${formatMoney(latestRequest.amount || 0)}${latestRequest.settlement_upi ? ' to ' + escapeHtml(latestRequest.settlement_upi) : ''}`
                        : 'No request detail found';
                    const detailId = `adminWalletTx_${index}_${String(shop.shop_token || '').replace(/[^a-zA-Z0-9_-]/g, '')}`;
                    return `
                        <div class="rounded-2xl bg-white border ${requestGroup ? 'border-amber-200 ring-2 ring-amber-100' : 'border-slate-200'} p-3">
                            <div class="flex items-start justify-between gap-3">
                                <div class="min-w-0">
                                    <div class="flex flex-wrap items-center gap-2">
                                        <p class="font-black text-slate-900 truncate">${owner}</p>
                                        ${requestGroup ? '<span class="rounded-full bg-amber-100 text-amber-800 px-2 py-1 text-[9px] font-black">Payout Request</span>' : ''}
                                    </div>
                                    <p class="mt-1 text-[10px] font-bold text-slate-400 truncate">${token}${Number(shop.token_count || tokens.length) > 1 ? ` +${Number(shop.token_count || tokens.length) - 1} token` : ''}</p>
                                </div>
                                <div class="shrink-0 flex items-center gap-2">
                                    <button type="button" onclick="toggleAdminWalletTransactions('${detailId}')" class="px-3 py-2 rounded-xl bg-slate-100 text-slate-700 text-[10px] font-black">Show Details</button>
                                    <button type="button" ${settlementUpi && Number(wallet.balance || 0) > 0 ? `onclick="openAdminWalletPayoutQr('${payoutPayload}')"` : 'disabled'} class="px-3 py-2 rounded-xl ${settlementUpi && Number(wallet.balance || 0) > 0 ? 'bg-emerald-600 text-white' : 'bg-slate-100 text-slate-400'} text-[10px] font-black">Pay QR</button>
                                    <button type="button" onclick="recordAdminWalletTransfer('${tokenPayload}', ${Number(wallet.balance || 0)})" class="px-3 py-2 rounded-xl bg-indigo-600 text-white text-[10px] font-black">Mark Transfer</button>
                                </div>
                            </div>
                            <div class="mt-3 grid grid-cols-2 sm:grid-cols-4 gap-2">
                                <span class="rounded-xl bg-indigo-50 border border-indigo-100 p-2"><b class="block text-[10px] text-indigo-700">Balance</b>${formatMoney(wallet.balance || 0)}</span>
                                <span class="rounded-xl bg-emerald-50 border border-emerald-100 p-2"><b class="block text-[10px] text-emerald-700">Received</b>${formatMoney(wallet.total_received || 0)}</span>
                                <span class="rounded-xl bg-slate-50 border border-slate-200 p-2"><b class="block text-[10px] text-slate-600">Sent</b>${formatMoney(wallet.total_transferred || 0)}</span>
                                <span class="rounded-xl bg-amber-50 border border-amber-100 p-2"><b class="block text-[10px] text-amber-700">Pending Request</b>${formatMoney(pendingWithdrawal)}</span>
                            </div>
                            <div class="mt-2 grid grid-cols-2 sm:grid-cols-3 gap-2">
                                <span class="rounded-xl bg-amber-50 border border-amber-100 p-2"><b class="block text-[10px] text-amber-700">Request Count</b>${requestCount}</span>
                                <span class="rounded-xl bg-orange-50 border border-orange-100 p-2"><b class="block text-[10px] text-orange-700">Total Requested</b>${formatMoney(totalRequested)}</span>
                                <span class="rounded-xl bg-cyan-50 border border-cyan-100 p-2"><b class="block text-[10px] text-cyan-700">Wallet Balance</b>${formatMoney(wallet.balance || 0)}</span>
                            </div>
                            <div class="mt-2 grid grid-cols-2 sm:grid-cols-5 gap-2">
                                <span class="rounded-xl bg-blue-50 border border-blue-100 p-2"><b class="block text-[10px] text-blue-700">Prints</b>${Number(printStats.total || 0)}</span>
                                <span class="rounded-xl bg-emerald-50 border border-emerald-100 p-2"><b class="block text-[10px] text-emerald-700">Printed</b>${Number(printStats.printed || 0)}</span>
                                <span class="rounded-xl bg-amber-50 border border-amber-100 p-2"><b class="block text-[10px] text-amber-700">Pending</b>${Number(printStats.pending || 0)}</span>
                                <span class="rounded-xl bg-red-50 border border-red-100 p-2"><b class="block text-[10px] text-red-700">Failed</b>${Number(printStats.failed || 0)}</span>
                                <span class="rounded-xl bg-purple-50 border border-purple-100 p-2"><b class="block text-[10px] text-purple-700">Paid Jobs</b>${Number(printStats.paid || 0)}</span>
                            </div>
                            <div class="mt-2 rounded-xl bg-slate-50 border border-slate-200 p-2 text-[11px] font-bold text-slate-600">
                                Settlement: ${settlementUpi ? escapeHtml(settlementUpi) : '<span class="text-red-600">UPI missing</span>'} ${settlementName ? `| Name: ${escapeHtml(settlementName)}` : '<span class="text-amber-600"> | Name missing</span>'} ${settlement.paytm_mid ? `| MID: ${escapeHtml(settlement.paytm_mid)}` : ''} | Requests: ${requestCount} | Transfers: ${Number(wallet.transfer_count || 0)}
                            </div>
                            <div class="mt-2 rounded-xl ${requestGroup ? 'bg-amber-50 border-amber-100 text-amber-800' : 'bg-slate-50 border-slate-200 text-slate-600'} border p-2 text-[11px] font-bold">
                                Latest request: ${latestRequestText}
                            </div>
                            <div class="mt-2 rounded-xl bg-slate-50 border border-slate-200 p-2 text-[11px] font-bold text-slate-600">
                                Payment list: ${formatMoney(wallet.total_received || 0)} received by ${owner}; sent ${formatMoney(wallet.total_transferred || 0)}; pending withdrawal ${formatMoney(pendingWithdrawal)}
                            </div>
                            <div id="${detailId}" class="hidden mt-2 grid gap-1">
                                ${txs.length ? txs.map((tx) => `<p class="rounded-lg bg-slate-50 px-2 py-1 text-[10px] font-bold text-slate-500">${escapeHtml(tx.created_at ? new Date(tx.created_at).toLocaleString() : '')} - ${escapeHtml(tx.type || '')} - ${formatMoney(tx.amount || 0)} - ${escapeHtml(tx.note || '')}</p>`).join('') : '<p class="rounded-lg bg-slate-50 px-2 py-1 text-[10px] font-bold text-slate-400">No transaction detail.</p>'}
                            </div>
                        </div>`;
                }).join('');
                const requestHtml = requestShops.length
                    ? `<div class="rounded-2xl bg-amber-50 border border-amber-100 p-3">
                            <p class="text-[10px] font-black uppercase tracking-wide text-amber-700">Payout Requests</p>
                            <p class="mt-1 text-xs font-bold text-amber-800">Jinhone payment/withdraw request lagayi hai woh yahan top par dikh rahe hain.</p>
                       </div>${renderAdminWalletCards(requestShops, 0, true)}`
                    : '<div class="rounded-2xl bg-slate-50 border border-slate-200 p-3 text-slate-500 font-bold">Abhi koi payout request pending/list me nahi hai.</div>';
                const otherHtml = otherShops.length
                    ? `<div class="mt-2 rounded-2xl bg-slate-50 border border-slate-200 p-3">
                            <p class="text-[10px] font-black uppercase tracking-wide text-slate-500">Other Wallets</p>
                            <p class="mt-1 text-xs font-bold text-slate-600">Baki auto print wallet records niche hain.</p>
                       </div>${renderAdminWalletCards(otherShops, requestShops.length, false)}`
                    : '';
                box.innerHTML = requestHtml + otherHtml;
                return true;
            } catch (e) {
                if (box) box.innerHTML = `<div class="rounded-xl bg-red-50 border border-red-100 p-3 text-red-600 font-bold">${escapeHtml(e?.message || 'Wallet list failed')}</div>`;
                return false;
            }
        }

        function setAdminAutoPrintListLimit(value) {
            const next = Math.max(10, Math.min(100, parseInt(value, 10) || 10));
            adminAutoPrintListLimit = [10, 20, 50, 100].includes(next) ? next : 10;
            loadAdminWalletPanel();
        }

        function toggleAdminWalletTransactions(id) {
            const el = document.getElementById(id);
            if (el) el.classList.toggle('hidden');
        }

        function parseAdminWalletTokens(shopTokenPayload) {
            try {
                const decoded = decodeURIComponent(String(shopTokenPayload || ''));
                const parsed = JSON.parse(decoded);
                if (Array.isArray(parsed)) {
                    return parsed.map((token) => String(token || '').replace(/[^a-zA-Z0-9_-]/g, '')).filter(Boolean);
                }
            } catch (e) {
                const fallbackToken = String(shopTokenPayload || '').replace(/[^a-zA-Z0-9_-]/g, '');
                if (fallbackToken) return [fallbackToken];
            }
            return [];
        }

        function closeAdminWalletPayoutQr() {
            const modal = document.getElementById('adminWalletPayoutQrModal');
            if (modal) modal.remove();
        }

        function openAdminWalletPayoutQr(payloadText) {
            let payload = {};
            try {
                payload = JSON.parse(decodeURIComponent(String(payloadText || '')));
            } catch (e) {
                showModal('QR Error', 'Payout QR data open nahi ho paya.', 'error');
                return;
            }
            const tokens = Array.isArray(payload.tokens) ? payload.tokens.map((token) => String(token || '').replace(/[^a-zA-Z0-9_-]/g, '')).filter(Boolean) : [];
            const upi = String(payload.upi || '').replace(/[^\w.\-@]/g, '').slice(0, 80);
            const name = sanitizeShopUpiName(payload.name || payload.owner || 'Shop Payout') || 'Shop Payout';
            const amount = normalizeMoney(payload.amount || 0);
            if (!tokens.length || !upi || amount <= 0) {
                showModal('Payout Missing', 'UPI, token ya wallet balance missing hai.', 'warn');
                return;
            }
            closeAdminWalletPayoutQr();
            const modalId = 'adminWalletPayoutQrModal';
            const qrId = 'adminWalletPayoutQrBox';
            const amountInputId = 'adminWalletPayoutAmountInput';
            const safePayload = encodeURIComponent(JSON.stringify({ tokens, upi, name, amount }));
            const amountText = amount.toFixed(2);
            const upiLink = `upi://pay?pa=${encodeURIComponent(upi)}&pn=${encodeURIComponent(name)}&am=${encodeURIComponent(amountText)}&cu=INR&tn=${encodeURIComponent('S Printer wallet payout')}`;
            document.body.insertAdjacentHTML('beforeend', `
                <div id="${modalId}" class="fixed inset-0 z-[160] bg-slate-900/60 backdrop-blur-sm flex items-center justify-center px-4">
                    <div class="w-full max-w-sm rounded-2xl bg-white p-5 shadow-2xl text-slate-900">
                        <div class="flex items-start justify-between gap-3">
                            <div>
                                <p class="text-[10px] font-black uppercase tracking-wide text-emerald-600">Wallet payout QR</p>
                                <h3 class="text-lg font-black">Pay ${formatMoney(amount)}</h3>
                                <p class="mt-1 text-[11px] font-bold text-slate-500">${escapeHtml(name)} - ${escapeHtml(upi)}</p>
                            </div>
                            <button type="button" onclick="closeAdminWalletPayoutQr()" class="w-9 h-9 rounded-xl bg-slate-100 text-slate-600 font-black">x</button>
                        </div>
                        <div id="${qrId}" class="mt-4 mx-auto w-[220px] h-[220px] rounded-2xl bg-white border border-slate-200 p-3 flex items-center justify-center"></div>
                        <a href="${escapeHtml(upiLink)}" class="mt-3 block text-center rounded-xl bg-emerald-50 border border-emerald-100 px-3 py-2 text-[11px] font-black text-emerald-700">Open UPI App</a>
                        <label class="mt-3 block">
                            <span class="text-[10px] font-bold uppercase tracking-wider text-slate-500">Paid Amount</span>
                            <input id="${amountInputId}" type="number" min="0" step="0.01" value="${amountText}" class="mt-1 w-full rounded-xl border border-slate-200 px-3 py-3 text-sm font-black text-slate-800">
                        </label>
                        <div class="mt-3 flex items-center gap-2">
                            <button type="button" onclick="submitAdminWalletQrTransfer('${safePayload}')" class="flex-1 rounded-xl bg-indigo-600 px-4 py-3 text-xs font-black text-white">Submit Paid</button>
                            <button type="button" onclick="closeAdminWalletPayoutQr()" class="rounded-xl bg-slate-100 px-4 py-3 text-xs font-black text-slate-700">Cancel</button>
                        </div>
                    </div>
                </div>
            `);
            const qrBox = document.getElementById(qrId);
            if (qrBox && window.QRCode) {
                qrBox.innerHTML = '';
                new window.QRCode(qrBox, { text: upiLink, width: 196, height: 196, correctLevel: window.QRCode.CorrectLevel.M });
            } else if (qrBox) {
                qrBox.innerHTML = `<img alt="Payout QR" class="w-full h-full object-contain" src="https://api.qrserver.com/v1/create-qr-code/?size=220x220&margin=8&data=${encodeURIComponent(upiLink)}">`;
            }
        }

        async function submitAdminWalletQrTransfer(payloadText) {
            let payload = {};
            try {
                payload = JSON.parse(decodeURIComponent(String(payloadText || '')));
            } catch (e) {
                showModal('Transfer Failed', 'Payout data invalid hai.', 'error');
                return;
            }
            const tokens = Array.isArray(payload.tokens) ? payload.tokens.map((token) => String(token || '').replace(/[^a-zA-Z0-9_-]/g, '')).filter(Boolean) : [];
            const amount = normalizeMoney(document.getElementById('adminWalletPayoutAmountInput')?.value || payload.amount || 0);
            if (!tokens.length || amount <= 0) {
                showModal('Invalid Amount', 'Valid paid amount enter karein.', 'warn');
                return;
            }
            try {
                const res = await postShopPrintAction('admin_record_wallet_transfer', {
                    shop_token: tokens[0],
                    shop_tokens: JSON.stringify(tokens),
                    amount,
                    note: `UPI payout paid to ${payload.upi || ''}`
                });
                if (res.status !== 'success') throw new Error(res.message || 'Transfer save failed');
                closeAdminWalletPayoutQr();
                showModal('Transfer Saved', 'Paid amount wallet se minus ho gaya.', 'success');
                loadAdminWalletPanel();
            } catch (e) {
                showModal('Transfer Failed', e?.message || 'Transfer record save nahi hua.', 'error');
            }
        }

        async function recordAdminWalletTransfer(shopTokenPayload, currentBalance = 0) {
            const raw = prompt(`Transfer amount enter karein. Current balance: ${formatMoney(currentBalance)}`, String(currentBalance || ''));
            if (raw == null) return;
            const amount = normalizeMoney(raw);
            if (amount <= 0) {
                showModal('Invalid Amount', 'Valid transfer amount enter karein.', 'warn');
                return;
            }
            try {
                let shopTokens = parseAdminWalletTokens(shopTokenPayload);
                if (!shopTokens.length) throw new Error('Shop token missing');
                const res = await postShopPrintAction('admin_record_wallet_transfer', {
                    shop_token: shopTokens[0],
                    shop_tokens: JSON.stringify(shopTokens),
                    amount,
                    note: 'Payout transferred to shop'
                });
                if (res.status !== 'success') throw new Error(res.message || 'Transfer save failed');
                showModal('Transfer Saved', 'Admin transfer record save ho gaya aur wallet balance update ho gaya.', 'success');
                loadAdminWalletPanel();
            } catch (e) {
                showModal('Transfer Failed', e?.message || 'Transfer record save nahi hua.', 'error');
            }
        }

        function startShopHistoryAutoRefresh() {
            if (remoteShopToken || shopHistoryRefreshTimer) return;
            if (hasShopAutoPrintPlan()) renderShopPrintHistory();
        }

        function stopShopHistoryAutoRefresh() {
            if (shopHistoryRefreshTimer) clearInterval(shopHistoryRefreshTimer);
            shopHistoryRefreshTimer = null;
        }

        async function loadRemoteShopSettings() {
            if (!remoteShopToken) return false;
            try {
                const res = await postShopPrintAction('shop_get_print_settings', { shop_token: remoteShopToken });
                if (res.status !== 'success') throw new Error(res.message || 'Settings load failed');
                const settings = res.settings || {};
                remoteShopAutoPrintEnabled = String(res.auto_print_enabled ?? '1') === '1';
                remoteShopRuleFromUrl = normalizeShopPrintModeRule(settings.print_rule || remoteShopRuleFromUrl);
                remotePaymentMode = normalizePaymentMode(settings.payment_mode || remotePaymentMode);
                remoteApprovalRequired = String(settings.approval_required || '0') === '1';
                remoteRateColor = normalizeMoney(settings.rate_color || remoteRateColor || 0);
                remoteRateGray = normalizeMoney(settings.rate_gray || remoteRateGray || 0);
                remoteShopUpiId = String(settings.upi_id || remoteShopUpiId || '').replace(/[^\w.\-@]/g, '').slice(0, 80);
                const paytmConfig = normalizeShopPaytmConfig(
                    settings.paytm_receiver_mode === 'shop' ? 'shop' : 'admin',
                    settings.paytm_merchant_upi,
                    settings.paytm_mid
                );
                remotePaytmReceiverMode = paytmConfig.receiverMode;
                remotePaytmMerchantUpi = paytmConfig.merchantUpi;
                remotePaytmMid = paytmConfig.merchantMid;
                remoteSettingsLoaded = true;
                updateRemoteCustomerUi();
                renderRemoteCustomerQueue();
                if (!remoteShopAutoPrintEnabled) {
                    setRemoteCustomerStatus('Is shop ka Auto Print subscription active nahi hai. Shop owner se subscription activate karne ko bolein.');
                }
                return true;
            } catch (e) {
                console.warn('Remote shop settings load failed', e);
                remoteSettingsLoaded = true;
                updateRemoteCustomerUi();
                return false;
            }
        }

        async function renderCustomerWalletHistory() {
            if (!remoteShopToken) return;
            try {
                const res = await postShopPrintAction('customer_list_print_history', {
                    shop_token: remoteShopToken,
                    customer_wallet_id: getCustomerWalletId()
                });
                if (res.status !== 'success') return;
                const paidTotal = res.wallet?.paid_total || 0;
                if (paidTotal > 0) {
                    setRemoteCustomerStatus(`Aapki online payment history: ${formatMoney(paidTotal)} paid. Recent print shop history me saved hai.`);
                }
            } catch (e) {
                console.warn('Customer wallet history failed', e);
            }
        }

        async function approveShopPaidJob(jobId) {
            const id = String(jobId || '').replace(/[^a-zA-Z0-9_-]/g, '');
            if (!id) return;
            try {
                const res = await postShopPrintAction('shop_approve_paid_job', { shop_token: getShopToken(), job_id: id });
                if (res.status !== 'success') throw new Error(res.message || 'Approve failed');
                showModal('Approved', 'Job approve ho gayi. Ab auto-print queue me chali gayi hai.', 'success');
                renderShopPrintHistory();
                startShopAutoPrintListener({ silent: true });
            } catch (e) {
                showModal('Approve Failed', e?.message || 'Payment approve nahi ho paya.', 'error');
            }
        }

        async function deleteShopPrintJob(jobId) {
            if (!window.siteConfig?.isAutoPrintAdmin) return false;
            const id = String(jobId || '').replace(/[^a-zA-Z0-9_-]/g, '');
            if (!id) return false;
            if (!confirm('Is print job ko list se delete karna hai?')) return false;
            try {
                const res = await postShopPrintAction('admin_delete_print_job', { shop_token: getShopToken(), job_id: id });
                if (res.status !== 'success') throw new Error(res.message || 'Delete failed');
                showModal('Deleted', 'Print job list se delete ho gayi.', 'success');
                renderShopPrintHistory(false);
                return true;
            } catch (e) {
                showModal('Delete Failed', e?.message || 'Print job delete nahi hui.', 'error');
                return false;
            }
        }

        function openShopPrintPreview(jobId) {
            const id = String(jobId || '').replace(/[^a-zA-Z0-9_-]/g, '');
            const src = shopPrintPreviewCache[id] || '';
            if (!src) {
                showModal('Preview Missing', 'Is job ka preview available nahi hai.', 'warn');
                return;
            }
            let modal = document.getElementById('shopPrintPreviewModal');
            if (!modal) {
                modal = document.createElement('div');
                modal.id = 'shopPrintPreviewModal';
                modal.className = 'fixed inset-0 z-[130] hidden bg-slate-950/75 backdrop-blur-sm p-4 items-center justify-center';
                modal.innerHTML = `
                    <div class="w-full max-w-md rounded-3xl bg-white p-4 shadow-2xl">
                        <div class="flex items-center justify-between gap-3 mb-3">
                            <h3 class="text-sm font-black text-slate-900">Print Preview</h3>
                            <button type="button" onclick="closeShopPrintPreview()" class="w-9 h-9 rounded-full bg-slate-100 text-slate-600"><i class="fa-solid fa-xmark"></i></button>
                        </div>
                        <div class="rounded-2xl bg-slate-100 border border-slate-200 p-2 max-h-[70vh] overflow-auto flex items-start justify-center">
                            <img id="shopPrintPreviewImage" alt="Print preview" class="max-w-full h-auto rounded-lg bg-white">
                        </div>
                    </div>`;
                document.body.appendChild(modal);
            }
            const img = document.getElementById('shopPrintPreviewImage');
            if (img) img.src = src;
            modal.classList.remove('hidden');
            modal.classList.add('flex');
        }

        function closeShopPrintPreview() {
            const modal = document.getElementById('shopPrintPreviewModal');
            if (!modal) return;
            modal.classList.add('hidden');
            modal.classList.remove('flex');
        }

        function hasDownloadedPrintAgentSetup() {
            return localStorage.getItem(PRINT_AGENT_SETUP_DOWNLOADED_KEY) === '1' || printAgentConnected;
        }

        function getAutoPrintAccessStatusEl() {
            return document.getElementById('autoPrintAccessStatus');
        }

        function setAutoPrintAccessStatus(message, tone = 'info') {
            const el = getAutoPrintAccessStatusEl();
            if (!el) return;
            const classes = {
                info: 'mt-3 rounded-xl bg-slate-50 border border-slate-200 px-3 py-2 text-[11px] text-slate-500 font-bold',
                success: 'mt-3 rounded-xl bg-emerald-50 border border-emerald-100 px-3 py-2 text-[11px] text-emerald-700 font-bold',
                warn: 'mt-3 rounded-xl bg-amber-50 border border-amber-100 px-3 py-2 text-[11px] text-amber-700 font-bold',
                error: 'mt-3 rounded-xl bg-red-50 border border-red-100 px-3 py-2 text-[11px] text-red-600 font-bold'
            };
            el.className = classes[tone] || classes.info;
            el.textContent = message;
        }

        function normalizeAutoPrintEmailList(text) {
            return Array.from(new Set(String(text || '')
                .split(/[\s,;]+/)
                .map((email) => email.trim().toLowerCase())
                .filter((email) => /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email))));
        }

        function renderAutoPrintAccessPanel(config = window.siteConfig?.autoPrintAccessConfig || {}) {
            const toggle = document.getElementById('autoPrintAllSubscribersToggle');
            const showForPro = document.getElementById('autoPrintShowForProToggle');
            const input = document.getElementById('autoPrintAllowedEmailsInput');
            if (toggle) toggle.checked = !!config.all_subscribers;
            if (showForPro) showForPro.checked = config.show_for_pro !== false;
            if (input) input.value = (Array.isArray(config.allowed_emails) ? config.allowed_emails : []).join('\n');
            setAutoPrintAccessStatus(`Loaded: ${(config.allowed_emails || []).length} allowed user(s). Pro button ${config.show_for_pro === false ? 'hidden' : 'visible'}. Dedicated Auto Print subscribers: active by plan.`);
        }

        async function loadAutoPrintAccessPanel() {
            if (!window.siteConfig?.isAutoPrintAdmin) return false;
            try {
                setAutoPrintAccessStatus('Loading access list...');
                const res = await postShopPrintAction('admin_get_auto_print_access');
                if (res.status !== 'success') throw new Error(res.message || 'Access load failed');
                window.siteConfig.autoPrintAccessConfig = res.config || {};
                renderAutoPrintAccessPanel(window.siteConfig.autoPrintAccessConfig);
                return true;
            } catch (e) {
                setAutoPrintAccessStatus(e?.message || 'Access load failed', 'error');
                return false;
            }
        }

        async function saveAutoPrintAccessPanel() {
            if (!window.siteConfig?.isAutoPrintAdmin) return false;
            const toggle = document.getElementById('autoPrintAllSubscribersToggle');
            const showForPro = document.getElementById('autoPrintShowForProToggle');
            const input = document.getElementById('autoPrintAllowedEmailsInput');
            const emails = normalizeAutoPrintEmailList(input?.value || '');
            try {
                setAutoPrintAccessStatus('Saving access list...');
                const res = await postShopPrintAction('admin_save_auto_print_access', {
                    all_subscribers: toggle?.checked ? '1' : '0',
                    show_for_pro: showForPro?.checked ? '1' : '0',
                    allowed_emails: emails.join('\n')
                });
                if (res.status !== 'success') throw new Error(res.message || 'Access save failed');
                window.siteConfig.autoPrintAccessConfig = res.config || {};
                renderAutoPrintAccessPanel(window.siteConfig.autoPrintAccessConfig);
                setAutoPrintAccessStatus('Saved. Allowlist rule ab backend par active hai.', 'success');
                return true;
            } catch (e) {
                setAutoPrintAccessStatus(e?.message || 'Access save failed', 'error');
                return false;
            }
        }

        function addCurrentUserToAutoPrintTrial() {
            const email = String(window.siteConfig?.userEmail || '').trim().toLowerCase();
            const input = document.getElementById('autoPrintAllowedEmailsInput');
            if (!email || !input) return;
            const emails = normalizeAutoPrintEmailList(`${input.value}\n${email}`);
            input.value = emails.join('\n');
            setAutoPrintAccessStatus(`${email} allowlist me add ho gaya. Save Access dabayein.`, 'warn');
        }

        function setAutoPrintStep(step) {
            if (step === 'qr' && !hasShopAutoPrintPlan()) {
                renderShopQr();
                showAutoPrintSubscriptionModal();
            }
            const allowedSteps = window.siteConfig?.isAutoPrintAdmin
                ? ['install', 'settings', 'paytm', 'qr', 'list', 'admin']
                : ['install', 'settings', 'paytm', 'qr', 'list'];
            autoPrintActiveStep = allowedSteps.includes(step) ? step : 'install';
            updateAutoPrintStepTabs();
            if (autoPrintActiveStep === 'admin') {
                renderAutoPrintAccessPanel(window.siteConfig?.autoPrintAccessConfig || {});
                loadAdminWalletPanel();
            }
            if (autoPrintActiveStep === 'list') renderShopPrintHistory(false);
        }

        function updateAutoPrintStepTabs() {
            const steps = window.siteConfig?.isAutoPrintAdmin
                ? ['install', 'settings', 'paytm', 'qr', 'list', 'admin']
                : ['install', 'settings', 'paytm', 'qr', 'list'];
            const progress = document.getElementById('autoPrintProgressBar');
            steps.forEach((step) => {
                const tab = document.getElementById(`autoStepTab${step.charAt(0).toUpperCase()}${step.slice(1)}`);
                const panel = step === 'install'
                    ? document.getElementById('autoPrintDownloadStep')
                    : (step === 'settings'
                        ? document.getElementById('autoPrintConnectStep')
                        : (step === 'paytm'
                            ? document.getElementById('autoPrintPaytmStep')
                            : (step === 'qr'
                                ? document.getElementById('autoPrintQrStep')
                                : (step === 'admin' ? document.getElementById('autoPrintAdminStep') : document.getElementById('autoPrintListStep')))));
                if (tab) tab.classList.toggle('active', autoPrintActiveStep === step);
                if (panel) panel.classList.toggle('active', autoPrintActiveStep === step);
            });
            if (progress) {
                progress.style.width = autoPrintActiveStep === 'install' ? '20%' : (autoPrintActiveStep === 'settings' ? '40%' : (autoPrintActiveStep === 'paytm' ? '60%' : (autoPrintActiveStep === 'qr' ? '80%' : '100%')));
            }
            const grid = document.getElementById('autoPrintBodyGrid');
            if (grid) grid.classList.toggle('compact', autoPrintActiveStep !== 'install');
        }

        function setAutoPrintVerifyStatus(message, tone = 'info') {
            const status = document.getElementById('autoPrintVerifyStatus');
            if (!status) return;
            const toneClass = {
                info: 'mt-3 rounded-xl bg-slate-50 border border-slate-200 px-3 py-2 text-[11px] text-slate-500 font-bold leading-relaxed',
                success: 'mt-3 rounded-xl bg-emerald-50 border border-emerald-100 px-3 py-2 text-[11px] text-emerald-700 font-bold leading-relaxed',
                warn: 'mt-3 rounded-xl bg-amber-50 border border-amber-100 px-3 py-2 text-[11px] text-amber-700 font-bold leading-relaxed',
                error: 'mt-3 rounded-xl bg-red-50 border border-red-100 px-3 py-2 text-[11px] text-red-600 font-bold leading-relaxed'
            };
            status.className = toneClass[tone] || toneClass.info;
            status.textContent = message;
        }

        function showAutoPrintSubscriptionModal() {
            const modal = document.getElementById('autoPrintSubscriptionModal');
            if (!modal) {
                showConfirm(
                    'Auto Print Rs 499 Required',
                    'Aapka Pro plan active ho sakta hai, lekin QR generate, listener start, queue polling aur silent Auto Print ke liye dedicated Rs 499/month Auto Print subscription chahiye. Payment page open karein?',
                    () => { goToAutoPrintInvoice(); }
                );
                return;
            }
            modal.classList.remove('hidden');
            modal.classList.add('flex');
        }

        function closeAutoPrintSubscriptionModal() {
            const modal = document.getElementById('autoPrintSubscriptionModal');
            if (!modal) return;
            modal.classList.add('hidden');
            modal.classList.remove('flex');
        }

        function goToAutoPrintInvoice() {
            window.location.href = window.siteConfig?.autoPrintSubscribeUrl || '/invoice?plan=auto_print';
        }

