            panel.innerHTML = `
                <div class="flex items-start justify-between gap-3">
                    <div>
                        <p class="text-[10px] font-black uppercase tracking-wide text-emerald-600">${remotePaymentMode === 'online' ? 'Online Payment' : 'Cash Payment'}</p>
                        <h3 class="text-lg font-black text-slate-900">${formatMoney(summary.amount)} <span class="text-xs text-slate-500">${docLabel}</span></h3>
                    </div>
                    <span class="rounded-full bg-emerald-50 border border-emerald-100 px-3 py-1 text-[10px] font-black text-emerald-700">${summary.totalCopies} print</span>
                </div>
                <div class="mt-3 grid grid-cols-2 gap-2 text-xs font-bold text-slate-600">
                    <div class="rounded-2xl bg-slate-50 p-3">Color: ${summary.colorCopies} x ${formatMoney(remoteRateColor)}</div>
                    <div class="rounded-2xl bg-slate-50 p-3">Gray: ${summary.grayCopies} x ${formatMoney(remoteRateGray)}</div>
                </div>
                <p class="mt-3 text-[11px] font-semibold text-slate-500">${
                    remotePaymentMode === 'online'
                    ? (remotePaytmReceiverMode === 'shop'
                        ? `Payment shop ke Paytm Business QR par direct hoga.${remoteApprovalRequired ? ' Shop approval ke baad print hoga.' : ' Auto verify ke baad direct print hoga.'}`
                        : `Payment Cashfree secure checkout par hoga. Shop wallet/settlement me 4% gateway charge katkar net amount add hoga.${remoteApprovalRequired ? ' Shop approval ke baad print hoga.' : ' Auto verify ke baad direct print hoga.'}`)
                        : (remoteApprovalRequired ? 'Cash counter par dena hai. Shop approval ke baad print hoga.' : 'Cash counter par dena hai. File direct auto print queue me jayegi.')
                }</p>`;
