        async function postInvoicePaymentAction(action, extra = {}) {
            const formData = new FormData();
            formData.append('action_type', action);
            formData.append('csrf_token', window.siteConfig.csrfToken);
            Object.entries(extra).forEach(([key, value]) => formData.append(key, value == null ? '' : value));
            const response = await fetch(SHOP_PRINT_API_URL, {
                method: 'POST',
                body: formData,
                cache: 'no-store',
                headers: { 'Accept': 'application/json' }
            });
            const text = await response.text();
            let data = null;
            try {
                data = JSON.parse(text);
            } catch (e) {
                const htmlTitle = String(text || '').match(/<title[^>]*>(.*?)<\/title>/i)?.[1] || '';
                const firstLine = String(text || '').replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 120);
                const hint = htmlTitle || firstLine || (response.status === 404 ? 'payment endpoint file nahi mila' : 'server ne JSON ki jagah HTML response diya');
                throw new Error(`Payment endpoint error: ${hint}. /shop-print-api.php direct JSON response nahi de raha.`);
            }
            if (!response.ok) {
                throw new Error(data?.msg || data?.message || `Payment endpoint HTTP ${response.status}`);
            }
            return data;
        }

        function getRemotePaymentPhone() {
            const key = 'ak_customer_cashfree_phone';
            let phone = String(localStorage.getItem(key) || '').replace(/\D/g, '');
            if (!/^[6-9]\d{9}$/.test(phone)) {
                phone = String(prompt('Cashfree payment ke liye customer ka 10 digit mobile number daalein') || '').replace(/\D/g, '');
            }
            if (!/^[6-9]\d{9}$/.test(phone)) {
                throw new Error('Valid 10 digit mobile number required hai.');
            }
            localStorage.setItem(key, phone);
            return phone;
        }

        function loadCashfreeRemoteSdk() {
            if (window.Cashfree) return Promise.resolve();
            return new Promise((resolve, reject) => {
                const existing = document.querySelector('script[data-cashfree-sdk="1"]');
                if (existing) {
                    existing.addEventListener('load', resolve, { once: true });
                    existing.addEventListener('error', reject, { once: true });
                    return;
                }
                const script = document.createElement('script');
                script.src = 'https://sdk.cashfree.com/js/v3/cashfree.js';
                script.async = true;
                script.dataset.cashfreeSdk = '1';
                script.onload = resolve;
                script.onerror = () => reject(new Error('Cashfree SDK load nahi ho paya.'));
                document.head.appendChild(script);
            });
        }

        function isRemoteIosBrowser() {
            return /iPad|iPhone|iPod/.test(navigator.userAgent || '')
                || (navigator.platform === 'MacIntel' && navigator.maxTouchPoints > 1);
        }

        async function openCashfreeRemotePayment(payment) {
            if (!payment?.payment_session_id) throw new Error('Cashfree payment session missing hai.');
            await loadCashfreeRemoteSdk();
            const cashfree = window.Cashfree({ mode: payment.mode || 'production' });
            await cashfree.checkout({
                paymentSessionId: payment.payment_session_id,
                redirectTarget: isRemoteIosBrowser() ? '_self' : '_modal'
            });
            if (!isRemoteIosBrowser()) await checkRemotePrintPayment();
        }

        async function initiateRemotePrintPayment(summary) {
            const paytmConfig = normalizeShopPaytmConfig(remotePaytmReceiverMode, remotePaytmMerchantUpi, remotePaytmMid);
            remotePaytmReceiverMode = paytmConfig.receiverMode;
            remotePaytmMerchantUpi = paytmConfig.merchantUpi;
            remotePaytmMid = paytmConfig.merchantMid;
            const res = await postInvoicePaymentAction('shop_print_initiate_payment', {
                amount: normalizeMoney(summary.amount).toFixed(2),
                shop_token: remoteShopToken,
                customer_wallet_id: getCustomerWalletId(),
                customer_phone: getRemotePaymentPhone(),
                receiver_mode: paytmConfig.receiverMode,
                merchant_upi: paytmConfig.merchantUpi,
                merchant_mid: paytmConfig.merchantMid
            });
            if (res.status !== 'success') throw new Error(res.msg || 'Payment start failed');
            pendingRemotePayment = res;
            return res;
        }

        async function checkRemotePrintPayment() {
            if (!pendingRemotePayment?.order_id) return false;
            const res = await postInvoicePaymentAction('shop_print_check_status', {
                order_id: pendingRemotePayment.order_id,
                merchant_mid: pendingRemotePayment.mid || '',
                shop_token: remoteShopToken
            });
            if (res.status !== 'success') return false;
            if (res.paid) {
                closeRemotePaymentSheet();
                if (pendingRemotePayment.staged) {
                    showModal(
                        remoteApprovalRequired ? "Sent for Approval" : "Print Sent",
                        remoteApprovalRequired
                            ? "Payment verify ho gayi. Job shop approval me chali gayi hai."
                            : "Payment verify ho gayi. Job auto print queue me chali gayi hai.",
                        "success"
                    );
                    setRemoteCustomerStatus(remoteApprovalRequired ? 'Shop approval ke liye bhej diya gaya.' : 'Print queue me bhej diya gaya. Zarurat ho to aur file add karein.');
                    remoteCustomerQueue = [];
                    renderRemoteCustomerQueue();
                    renderCustomerWalletHistory();
                } else {
                    submitRemoteCustomerQueue({
                        paymentConfirmed: true,
                        paymentOrderId: pendingRemotePayment.order_id,
                        paymentRef: res.utr || pendingRemotePayment.order_id
                    });
                }
                return true;
            }
            setRemoteCustomerStatus(`Payment status: ${res.gateway_status || 'PENDING'}. Payment complete hone ka wait hai.`);
            return false;
        }

        function openRemotePaymentSheet(summary, payment) {
            pendingRemotePaymentSummary = summary;
            pendingRemotePayment = payment || pendingRemotePayment;
            const sheet = document.getElementById('remotePaymentSheet');
            const amount = document.getElementById('remotePaymentAmount');
            const breakup = document.getElementById('remotePaymentBreakup');
            const upi = document.getElementById('remotePaymentUpi');
            const qr = document.getElementById('remotePaymentQr');
            const sub = document.getElementById('remotePaymentSheetSub');
            const appChoices = document.getElementById('remotePaymentAppChoices');
            const qrDownloadBtn = document.getElementById('remotePaymentQrDownloadBtn');
            const cashfreeBtn = document.getElementById('remoteCashfreePayBtn');
            const isCashfreePayment = pendingRemotePayment?.gateway === 'cashfree';
            if (amount) amount.textContent = formatMoney(summary.amount);
            if (breakup) breakup.textContent = `Color: ${summary.colorCopies} x ${formatMoney(remoteRateColor)} | Gray: ${summary.grayCopies} x ${formatMoney(remoteRateGray)}`;
            if (upi) upi.textContent = isCashfreePayment ? 'Cashfree secure checkout' : (pendingRemotePayment?.upi_id || 'S Printer Paytm Business');
            if (sub) sub.textContent = isCashfreePayment
                ? (remoteApprovalRequired ? 'Cashfree payment ke baad 4% gateway charge katkar shop approval lagega.' : 'Cashfree verify hote hi 4% gateway charge katkar print queue submit hogi.')
                : (remoteApprovalRequired ? 'Payment shop Paytm account me direct jayega; verify hone ke baad approval lagega.' : 'Payment shop Paytm account me direct jayega; verify hote hi file auto print queue me jayegi.');
            if (appChoices) appChoices.classList.toggle('hidden', isCashfreePayment);
            if (qrDownloadBtn) qrDownloadBtn.classList.toggle('hidden', isCashfreePayment);
            if (cashfreeBtn) cashfreeBtn.classList.toggle('hidden', !isCashfreePayment || !isRemoteIosBrowser());
            if (qr) {
                qr.innerHTML = '';
                const upiUri = pendingRemotePayment?.upi_link || '';
                if (isCashfreePayment) {
                    qr.innerHTML = '<div class="w-[132px] h-[132px] rounded-xl bg-indigo-50 border border-indigo-100 flex items-center justify-center text-indigo-700 text-center text-[11px] font-black px-3">Opening Cashfree...</div>';
                    if (!isRemoteIosBrowser()) {
                        openCashfreeRemotePayment(pendingRemotePayment).catch((e) => showModal('Payment Error', e?.message || 'Cashfree open nahi ho paya.', 'error'));
                    }
                } else if (upiUri) {
                    if (window.QRCode) {
                        new window.QRCode(qr, {
                            text: upiUri,
                            width: 132,
                            height: 132,
                            correctLevel: window.QRCode.CorrectLevel.M
                        });
                    } else {
                        const qrImg = document.createElement('img');
                        qrImg.src = pendingRemotePayment?.qr_url || `https://api.qrserver.com/v1/create-qr-code/?size=300x300&margin=10&data=${encodeURIComponent(upiUri)}`;
                        qrImg.alt = 'Payment QR';
                        qrImg.className = 'w-[132px] h-[132px] object-contain';
                        qr.appendChild(qrImg);
                    }
                } else {
                    qr.innerHTML = '<p class="text-[10px] text-slate-500 text-center font-bold">Shop UPI ID missing</p>';
                }
            }
            if (sheet) {
                sheet.classList.remove('hidden');
                sheet.classList.add('flex');
            }
            if (remotePaymentPollTimer) clearInterval(remotePaymentPollTimer);
            remotePaymentPollTimer = setInterval(() => checkRemotePrintPayment().catch(() => false), 3000);
        }

