        function getRemoteUiText(key) {
            const pack = REMOTE_CUSTOMER_UI_TEXT_SAFE[remoteCustomerUiLang] || REMOTE_CUSTOMER_UI_TEXT_SAFE.en;
            return pack[key] || REMOTE_CUSTOMER_UI_TEXT_SAFE.en[key] || key;
        }

        function setRemoteCustomerUiLang(lang = 'en') {
            remoteCustomerUiLang = lang === 'hi' ? 'hi' : 'en';
            try { localStorage.setItem(REMOTE_UI_LANG_KEY, remoteCustomerUiLang); } catch (e) {}
            const select = document.getElementById('remoteUiLangSelect');
            if (select) select.value = remoteCustomerUiLang;
            const setText = (id, key) => {
                const el = document.getElementById(id);
                if (el) el.textContent = getRemoteUiText(key);
            };
            setText('remoteUiTitle', 'title');
            setText('remoteUploadTitle', 'uploadTitle');
            setText('remoteUploadHelp', 'uploadHelp');
            setText('remoteAddMoreText', 'addMore');
            setText('remoteSendBtnText', 'send');
            document.querySelectorAll('[data-remote-i18n]').forEach((el) => {
                el.textContent = getRemoteUiText(el.getAttribute('data-remote-i18n') || '');
            });
            const status = document.getElementById('remoteCustomerStatus');
            if (status && (!remoteCustomerQueue.length || /QR connected|Files select|Select files/i.test(status.textContent || ''))) {
                status.textContent = getRemoteUiText('statusReady');
            }
        }

        function removeRemoteCustomerItem(index) {
            remoteCustomerQueue.splice(index, 1);
            renderRemoteCustomerQueue();
            setRemoteCustomerStatus(remoteCustomerQueue.length ? `${remoteCustomerQueue.length} file(s) ready.` : getRemoteUiText('statusReady'));
        }

        function normalizeRemoteCopies(value) {
            return Math.max(1, Math.min(10, parseInt(value, 10) || 1));
        }

        function setRemoteItemCopies(index, delta) {
            const item = remoteCustomerQueue[index];
            if (!item) return;
            item.copies = normalizeRemoteCopies((item.copies || 1) + delta);
            renderRemoteCustomerQueue();
        }

        function clearRemoteCustomerQueue() {
            if (remoteCustomerQueue.length === 0) return;
            showConfirm("Clear files?", "Selected preview files remove ho jayengi.", () => {
                remoteCustomerQueue = [];
                renderRemoteCustomerQueue();
                setRemoteCustomerStatus(getRemoteUiText('statusReady'));
            });
        }

        async function stageRemotePaymentPrintJobs(summary, payment) {
            const requestedMode = getCustomerPrintMode();
            const docLabel = getRemoteQueueDocLabel();
            const totalCopies = remoteCustomerQueue.reduce((sum, item) => sum + normalizeRemoteCopies(item.copies), 0);
            showProcessLoader({
                kind: 'upload',
                variant: 'fast',
                title: 'Payment print secure ho raha hai',
                message: `${remoteCustomerQueue.length} file(s), ${totalCopies} total ${docLabel} print copy payment ke saath lock ho rahi hain.`,
                chip: 'SAFE',
                subtext: 'Payment ke baad backend same transaction id se auto verify karega'
            });
            await waitForFastPaint();
            try {
                const batchId = 'batch_' + Date.now().toString(36) + '_' + Math.random().toString(36).slice(2, 7);
                for (let i = 0; i < remoteCustomerQueue.length; i++) {
                    const item = remoteCustomerQueue[i];
                    const itemDocType = getRemoteItemDocType(item);
                    const itemDocLabel = itemDocType === 'idcard' ? 'ID Card' : 'A4';
                    updateProcessLoader({
                        kind: 'upload',
                        variant: 'fast',
                        title: `Print ${i + 1}/${remoteCustomerQueue.length} payment queue me save ho raha hai`,
                        message: `${getPrintModeLabel(requestedMode)} mode me ${itemDocLabel} output ready kar rahe hain.`,
                        chip: 'PAY',
                        subtext: `${item.name} - ${normalizeRemoteCopies(item.copies)} copy`
                    });
                    const printData = itemDocType === 'idcard'
                        ? await fitIdCardItemOnCanvas(item)
                        : await fitDataUrlOnA4Canvas(item.dataUrl);
                    const previewData = await makePrintPreviewDataUrl(printData);
                    const itemBill = getRemoteItemBill(item, requestedMode);
                    const res = await postShopPrintAction('shop_submit_print_job', {
                        shop_token: remoteShopToken,
                        print_data: printData,
                        preview_data: previewData,
                        copies: normalizeRemoteCopies(item.copies),
                        print_mode: requestedMode,
                        paper: itemDocType === 'idcard' ? 'idcard' : 'a4',
                        source: 'customer-qr-ui',
                        source_name: item.name || '',
                        batch_id: batchId,
                        pdf_page_number: item.pdfPageNumber || 1,
                        pdf_page_count: item.pdfPageCount || 1,
                        customer_name: 'QR Customer',
                        customer_wallet_id: getCustomerWalletId(),
                        payment_mode: remotePaymentMode,
                        approval_required: remoteApprovalRequired ? '1' : '0',
                        payment_required: '1',
                        payment_deferred: '1',
                        payment_amount: itemBill.amount,
                        payment_order_id: payment.order_id || '',
                        payment_mid: payment.mid || '',
                        receiver_mode: payment.receiver_mode || remotePaytmReceiverMode,
                        payment_ref: payment.order_id || '',
                        payment_summary: `${itemDocLabel} ${getPrintModeLabel(itemBill.mode)} ${itemBill.copies} copy, total bill ${formatMoney(summary.amount)}`
                    });
                    if (res.status !== 'success') throw new Error(res.message || 'Payment print save failed');
                }
                payment.staged = true;
                setRemoteCustomerStatus('Cashfree checkout ready hai. Payment hote hi backend auto verify karke print queue me bhej dega.');
                return true;
            } finally {
                hideProcessLoader();
            }
        }

        function startRemoteCustomerCrop(index, side = 'front') {
            const item = remoteCustomerQueue[index];
            if (!item) return;
            const cropSide = side === 'back' && item.backDataUrl ? 'back' : 'front';
            remoteCropIndex = index;
            remoteCropSide = cropSide;
            currentType = getRemoteItemDocType(item) === 'idcard' ? 'smart' : 'a4';
            currentSide = cropSide;
            pendingBackFile = null;
            pendingDocumentAiAnalysis = null;
            shadowDocumentAiAnalysis = null;
            const sourceDataUrl = cropSide === 'back' ? item.backDataUrl : item.dataUrl;
            currentDocumentSourceDataUrl = sourceDataUrl;
            currentLearningGroupRef = String(item.id || currentLearningGroupRef || `remote_${Date.now().toString(36)}`)
                .toLowerCase().replace(/[^a-z0-9_-]/g, '').slice(0, 80);
            currentLearningCaptureMeta = normalizeLearningCaptureMeta({
                uploadChannel: 'shop_qr_mobile',
                sourceMedia: 'image',
                mimeGroup: String(item.type || '').startsWith('image/') ? 'image' : 'rendered_upload',
                fileExtension: fileExtensionOnly({
                    name: cropSide === 'back' ? item.backName : item.name,
                    type: item.type || ''
                }),
                fileSizeBucket: fileSizeBucket(cropSide === 'back' ? item.backSize : item.size),
                customerMobileFlow: true,
                pdfRender: item.sourceKind === 'pdf',
                groupRef: currentLearningGroupRef,
                side: cropSide
            });
            documentLearningContext = {
                docType: currentType === 'a4' ? 'a4_document' : 'id_card',
                docLabel: currentType === 'a4' ? 'A4 Document' : 'Mobile Card Photo',
                sourceKind: currentType === 'a4' ? 'remote_customer_document' : 'mobile_customer_card_photo',
                contentKind: currentType === 'a4' ? 'a4_document' : 'physical_laminated_card_photo',
                captureReason: currentType === 'a4' ? 'remote_customer_a4_crop_done' : 'mobile_card_restore_crop_done',
                captureMeta: currentLearningCaptureMeta
            };
            loadDataUrlToEditor(sourceDataUrl).then(async () => {
                setRemoteCustomerStatus(`${cropSide === 'back' ? 'Back' : 'Front'} crop box corners drag karein, phir Done dabayein.`);
                if (getRemoteItemDocType(item) === 'a4') {
                    const w = displayMat?.cols || canvas?.width || 1;
                    const h = displayMat?.rows || canvas?.height || 1;
                    cropperPoints = [
                        { x: 0, y: 0 },
                        { x: w, y: 0 },
                        { x: w, y: h },
                        { x: 0, y: h }
                    ];
                    drawCanvas();
                    updateCropHandleOverlay();
                    setRemoteCustomerStatus('Full page selected. Crop only if you want to trim the page.');
                    return;
                }
                scheduleCropAiAnalysis('analyze_document_crop_ai', sourceDataUrl, null, {
                    docType: currentType === 'a4' ? 'a4_document' : 'id_card',
                    fileName: item.name || 'remote-crop',
                    sourceKind: 'customer_image'
                });
            }).catch((e) => {
                console.error(e);
                remoteCropIndex = -1;
                remoteCropSide = 'front';
                showModal("Crop Error", "Preview crop ke liye open nahi ho paya.", "error");
            });
        }

        async function submitRemoteCustomerQueue(options = {}) {
            if (!remoteShopToken || remoteCustomerQueue.length === 0) {
                showModal("Empty", "Pehle file upload karein.", "warn");
                return false;
            }
            if (!remoteSettingsLoaded) {
                await loadRemoteShopSettings();
            }
            if (!remoteShopAutoPrintEnabled) {
                showModal("Subscription Required", "Is shop ka Auto Print subscription active nahi hai, isliye print queue me nahi bheja ja sakta.", "warn");
                setRemoteCustomerStatus('Shop Auto Print subscription inactive hai.');
                return false;
            }
            const requestedMode = getCustomerPrintMode();
            const docLabel = getRemoteQueueDocLabel();
            const totalCopies = remoteCustomerQueue.reduce((sum, item) => sum + normalizeRemoteCopies(item.copies), 0);
            const billSummary = getRemoteBillingSummary();
            if (remotePaymentMode === 'online' && billSummary.amount > 0 && !options.paymentConfirmed) {
                try {
                    const payment = await initiateRemotePrintPayment(billSummary);
                    await stageRemotePaymentPrintJobs(billSummary, payment);
                    openRemotePaymentSheet(billSummary, payment);
                } catch (e) {
                    showModal("Payment Error", e?.message || "Payment start nahi ho paya.", "error");
                    return false;
                }
                return false;
            }
            showProcessLoader({
                kind: 'upload',
                variant: 'fast',
                title: 'Shop printer ko bhej rahe hain',
                message: `${remoteCustomerQueue.length} file(s), ${totalCopies} total ${docLabel} print copy queue me submit ho rahi hain.`,
                chip: 'SEND',
                subtext: 'Upload complete hone tak screen open rakhein'
            });
            await waitForFastPaint();
            try {
                const batchId = 'batch_' + Date.now().toString(36) + '_' + Math.random().toString(36).slice(2, 7);
                for (let i = 0; i < remoteCustomerQueue.length; i++) {
                    const item = remoteCustomerQueue[i];
                    const itemDocType = getRemoteItemDocType(item);
                    const itemDocLabel = itemDocType === 'idcard' ? 'ID Card' : 'A4';
                    updateProcessLoader({
                        kind: 'upload',
                        variant: 'fast',
                        title: `Print ${i + 1}/${remoteCustomerQueue.length} prepare ho raha hai`,
                        message: `${getPrintModeLabel(requestedMode)} mode me ${itemDocLabel} output ready kar rahe hain.`,
                        chip: 'QUEUE',
                        subtext: `${item.name} - ${normalizeRemoteCopies(item.copies)} copy`
                    });
                    const printData = itemDocType === 'idcard'
                        ? await fitIdCardItemOnCanvas(item)
                        : await fitDataUrlOnA4Canvas(item.dataUrl);
                    const previewData = await makePrintPreviewDataUrl(printData);
                    const itemBill = getRemoteItemBill(item, requestedMode);
                    const res = await postShopPrintAction('shop_submit_print_job', {
                        shop_token: remoteShopToken,
                        print_data: printData,
                        preview_data: previewData,
                        copies: normalizeRemoteCopies(item.copies),
                        print_mode: requestedMode,
                        paper: itemDocType === 'idcard' ? 'idcard' : 'a4',
                        source: 'customer-qr-ui',
                        source_name: item.name || '',
                        batch_id: batchId,
                        pdf_page_number: item.pdfPageNumber || 1,
                        pdf_page_count: item.pdfPageCount || 1,
                        customer_name: 'QR Customer',
                        customer_wallet_id: getCustomerWalletId(),
                        payment_mode: remotePaymentMode,
                        approval_required: remoteApprovalRequired ? '1' : '0',
                        payment_required: remotePaymentMode === 'online' && billSummary.amount > 0 ? '1' : '0',
                        payment_amount: itemBill.amount,
                        payment_order_id: options.paymentOrderId || pendingRemotePayment?.order_id || '',
                        payment_mid: pendingRemotePayment?.mid || '',
                        receiver_mode: pendingRemotePayment?.receiver_mode || remotePaytmReceiverMode,
                        payment_ref: remotePaymentMode === 'online' ? (options.paymentRef || pendingRemotePayment?.order_id || '') : '',
                        payment_summary: remotePaymentMode !== 'none'
                            ? `${itemDocLabel} ${getPrintModeLabel(itemBill.mode)} ${itemBill.copies} copy, total bill ${formatMoney(billSummary.amount)}`
                            : `${itemDocLabel} ${getPrintModeLabel(itemBill.mode)} ${itemBill.copies} copy, no payment`
                    });
                    if (res.status !== 'success') throw new Error(res.message || 'Job submit failed');
                }
                const waitApproval = remoteApprovalRequired;
                showModal(
                    waitApproval ? "Sent for Approval" : "Print Sent",
                    waitApproval
                        ? `${remoteCustomerQueue.length} ${docLabel} file(s) shop approval me bhej di gayi. Approval ke baad print niklega.`
                        : `${remoteCustomerQueue.length} ${docLabel} file(s) shop printer queue me bhej di gayi.`,
                    "success"
                );
                setRemoteCustomerStatus(waitApproval ? 'Shop approval ke liye bhej diya gaya.' : 'Print queue me bhej diya gaya. Zarurat ho to aur file add karein.');
                remoteCustomerQueue = [];
                renderRemoteCustomerQueue();
                renderCustomerWalletHistory();
                return true;
            } catch (e) {
                console.error(e);
                showModal("Print Failed", e?.message || "Shop queue me print submit nahi ho paya.", "error");
                return false;
            } finally {
                hideProcessLoader();
            }
        }

        function updateRemoteCustomerUi() {
            if (!remoteShopToken) return;
            const status = document.getElementById('mobStatus');
            const paymentText = remotePaymentMode === 'online' ? 'online pay' : (remotePaymentMode === 'cash' ? 'cash' : 'no payment');
            const docType = getRemoteCustomerDocType();
            if (status) status.textContent = `Shop QR mode: ${docType === 'idcard' ? 'ID Card' : 'A4'}, ${customerPrintMode === 'gray' ? 'Gray' : 'Color'}, ${paymentText}${remoteApprovalRequired ? ', approval on' : ''}`;
            const pageIndicator = document.getElementById('pageIndicator');
            if (pageIndicator) pageIndicator.textContent = 'Shop Print';
            const badge = document.getElementById('remoteShopRuleBadge');
            if (badge) badge.textContent = remoteShopRuleFromUrl === 'gray' ? 'Gray only' : (remoteShopRuleFromUrl === 'color' ? 'Color only' : 'Color or Gray');
            document.querySelectorAll('#remoteDocTypeChoices .remote-doc-chip').forEach((btn) => {
                btn.classList.toggle('active', (btn.getAttribute('data-type') || 'a4') === docType);
            });
            const choices = document.getElementById('remotePrintModeChoices');
            if (choices) {
                choices.style.gridTemplateColumns = remoteShopRuleFromUrl !== 'customer' ? '1fr' : 'repeat(2, minmax(0, 1fr))';
            }
            document.querySelectorAll('#remotePrintModeChoices .remote-mode-chip').forEach((btn) => {
                const mode = btn.getAttribute('data-mode') || 'color';
                const forced = remoteShopRuleFromUrl !== 'customer' && mode !== remoteShopRuleFromUrl;
                btn.classList.toggle('hidden', forced);
                btn.classList.toggle('active', mode === getCustomerPrintMode());
            });
            renderRemoteBilling();
        }

        function normalizePrintMode(mode) {
            return String(mode || '').toLowerCase() === 'gray' ? 'gray' : 'color';
        }

        function normalizeShopPrintModeRule(mode) {
            const value = String(mode || '').toLowerCase();
            return value === 'color' || value === 'gray' ? value : 'customer';
        }

        function getCustomerPrintMode() {
            if (remoteShopToken && remoteShopRuleFromUrl !== 'customer') {
                customerPrintMode = remoteShopRuleFromUrl;
                return customerPrintMode;
            }
            customerPrintMode = normalizePrintMode(localStorage.getItem(PRINT_MODE_KEY) || customerPrintMode);
            return customerPrintMode;
        }

        function normalizeCustomerCopies(value) {
            return Math.max(1, Math.min(10, parseInt(value, 10) || 1));
        }

        function getCustomerCopies() {
            customerCopies = normalizeCustomerCopies(localStorage.getItem(CUSTOMER_COPIES_KEY) || customerCopies);
            return customerCopies;
        }

        function getCustomerPrepareMode() {
            customerPrepareMode = (localStorage.getItem(CUSTOMER_PREPARE_MODE_KEY) || customerPrepareMode) === 'direct' ? 'direct' : 'crop';
            return customerPrepareMode;
        }

        function normalizeRemoteDocType(type) {
            return String(type || '').toLowerCase() === 'idcard' ? 'idcard' : 'a4';
        }

        function getRemoteItemDocType(item) {
            return normalizeRemoteDocType(item?.docType || getRemoteCustomerDocType());
        }

        function getRemoteQueueDocLabel() {
            if (!remoteCustomerQueue.length) {
                return getRemoteCustomerDocType() === 'idcard' ? 'ID Card' : 'A4';
            }
            const types = Array.from(new Set(remoteCustomerQueue.map((item) => getRemoteItemDocType(item))));
            if (types.length > 1) return 'Mixed';
            return types[0] === 'idcard' ? 'ID Card' : 'A4';
        }

        function getRemoteCustomerDocType() {
            remoteCustomerDocType = (localStorage.getItem(CUSTOMER_DOC_TYPE_KEY) || remoteCustomerDocType) === 'idcard' ? 'idcard' : 'a4';
            return remoteCustomerDocType;
        }

        function getShopPrintModeRule() {
            shopPrintModeRule = normalizeShopPrintModeRule(localStorage.getItem(SHOP_PRINT_MODE_RULE_KEY) || shopPrintModeRule);
            return shopPrintModeRule;
        }

        function normalizeMoney(value) {
            return Math.max(0, Math.round((parseFloat(value) || 0) * 100) / 100);
        }

        function normalizePaymentMode(mode) {
            const value = String(mode || '').toLowerCase();
            return ['none', 'cash', 'online'].includes(value) ? value : 'none';
        }

        function sanitizeShopPaytmUpi(value) {
            return String(value || '').replace(/[^\w.\-@]/g, '').slice(0, 80);
        }

        function sanitizeShopPaytmMid(value) {
            return String(value || '').replace(/[^a-zA-Z0-9_-]/g, '').slice(0, 80);
        }

        function sanitizeShopUpiName(value) {
            return String(value || '').replace(/[^a-zA-Z0-9_\- .]/g, '').slice(0, 80).trim();
        }

        function normalizeShopPaytmConfig(receiverMode, merchantUpi, merchantMid) {
            const cleanUpi = sanitizeShopPaytmUpi(merchantUpi);
            const cleanMid = sanitizeShopPaytmMid(merchantMid);
            const canUseShopPaytm = receiverMode === 'shop' && cleanUpi && cleanMid;
            return {
                receiverMode: canUseShopPaytm ? 'shop' : 'admin',
                merchantUpi: cleanUpi,
                merchantMid: cleanMid
            };
        }

        function getShopPaymentSettings() {
            const legacyEnabled = localStorage.getItem(SHOP_PAYMENT_ENABLED_KEY) === '1';
            const savedMode = localStorage.getItem(SHOP_PAYMENT_MODE_KEY);
            const receiverMode = (localStorage.getItem(SHOP_PAYTM_RECEIVER_KEY) || 'admin') === 'shop' ? 'shop' : 'admin';
            return {
                paymentMode: normalizePaymentMode(savedMode || (legacyEnabled ? 'online' : 'none')),
                approvalRequired: localStorage.getItem(SHOP_APPROVAL_REQUIRED_KEY) === '1',
                rateColor: normalizeMoney(localStorage.getItem(SHOP_RATE_COLOR_KEY) || 10),
                rateGray: normalizeMoney(localStorage.getItem(SHOP_RATE_GRAY_KEY) || 5),
                upiId: String(localStorage.getItem(SHOP_UPI_ID_KEY) || '').replace(/[^\w.\-@]/g, '').slice(0, 80),
                upiName: sanitizeShopUpiName(localStorage.getItem(SHOP_UPI_NAME_KEY)),
                paytmReceiverMode: receiverMode,
                paytmMerchantUpi: sanitizeShopPaytmUpi(localStorage.getItem(SHOP_PAYTM_MERCHANT_UPI_KEY)),
                paytmMid: sanitizeShopPaytmMid(localStorage.getItem(SHOP_PAYTM_MID_KEY))
            };
        }

        function renderShopPaymentControls() {
            const settings = getShopPaymentSettings();
            const mode = document.getElementById('shopPaymentMode');
            const approval = document.getElementById('shopApprovalRequired');
            const color = document.getElementById('shopRateColor');
            const gray = document.getElementById('shopRateGray');
            const upi = document.getElementById('shopUpiId');
            const upiName = document.getElementById('shopUpiName');
            const receiver = document.getElementById('shopPaytmReceiverMode');
            const merchantUpi = document.getElementById('shopPaytmMerchantUpi');
            const mid = document.getElementById('shopPaytmMid');
            if (mode) mode.value = settings.paymentMode;
            if (approval) approval.checked = settings.approvalRequired;
            if (color) color.value = settings.rateColor || '';
            if (gray) gray.value = settings.rateGray || '';
            if (upi) upi.value = settings.upiId;
            if (upiName) upiName.value = settings.upiName;
            if (receiver) receiver.value = settings.paytmReceiverMode;
            if (merchantUpi) merchantUpi.value = settings.paytmMerchantUpi;
            if (mid) mid.value = settings.paytmMid;
        }

        function setShopPaymentEnabled(enabled) {
            setShopPaymentMode(enabled ? 'online' : 'none');
        }

        function setShopPaymentMode(mode) {
            const value = normalizePaymentMode(mode);
            localStorage.setItem(SHOP_PAYMENT_MODE_KEY, value);
            localStorage.setItem(SHOP_PAYMENT_ENABLED_KEY, value === 'online' ? '1' : '0');
            renderShopPaymentControls();
            publishShopPrintSettings();
            renderShopQr();
        }

        function setShopApprovalRequired(enabled) {
            localStorage.setItem(SHOP_APPROVAL_REQUIRED_KEY, enabled ? '1' : '0');
            renderShopPaymentControls();
            publishShopPrintSettings();
            renderShopQr();
        }

        function setShopPaymentRate(type, value) {
            const key = type === 'gray' ? SHOP_RATE_GRAY_KEY : SHOP_RATE_COLOR_KEY;
            localStorage.setItem(key, String(normalizeMoney(value)));
            renderShopPaymentControls();
            publishShopPrintSettings();
            renderShopQr();
        }

        function setShopUpiId(value) {
            localStorage.setItem(SHOP_UPI_ID_KEY, String(value || '').replace(/[^\w.\-@]/g, '').slice(0, 80));
            renderShopPaymentControls();
            publishShopPrintSettings();
            renderShopQr();
        }

        function setShopUpiName(value) {
            localStorage.setItem(SHOP_UPI_NAME_KEY, sanitizeShopUpiName(value));
            renderShopPaymentControls();
            publishShopPrintSettings();
        }

        function setShopPaytmReceiverMode(value) {
            localStorage.setItem(SHOP_PAYTM_RECEIVER_KEY, value === 'shop' ? 'shop' : 'admin');
            renderShopPaymentControls();
            publishShopPrintSettings();
        }

        function setShopPaytmMerchantUpi(value) {
            const cleanUpi = sanitizeShopPaytmUpi(value);
            localStorage.setItem(SHOP_PAYTM_MERCHANT_UPI_KEY, cleanUpi);
            if (!cleanUpi) localStorage.setItem(SHOP_PAYTM_RECEIVER_KEY, 'admin');
            renderShopPaymentControls();
            publishShopPrintSettings();
        }

        function setShopPaytmMid(value) {
            const cleanMid = sanitizeShopPaytmMid(value);
            localStorage.setItem(SHOP_PAYTM_MID_KEY, cleanMid);
            if (!cleanMid) localStorage.setItem(SHOP_PAYTM_RECEIVER_KEY, 'admin');
            renderShopPaymentControls();
            publishShopPrintSettings();
        }

        function publishShopPrintSettings() {
            if (remoteShopToken) return Promise.resolve(false);
            if (!hasShopAutoPrintPlan()) return Promise.resolve(false);
            const payment = getShopPaymentSettings();
            const paytmConfig = normalizeShopPaytmConfig(payment.paytmReceiverMode, payment.paytmMerchantUpi, payment.paytmMid);
            return postShopPrintAction('shop_save_print_settings', {
                shop_token: getShopToken(),
                runtime_key: getShopRuntimeKey(),
                print_rule: getShopPrintModeRule(),
                payment_mode: payment.paymentMode,
                approval_required: payment.approvalRequired ? '1' : '0',
                rate_color: payment.rateColor,
                rate_gray: payment.rateGray,
                upi_id: payment.upiId,
                upi_name: payment.upiName,
                paytm_receiver_mode: paytmConfig.receiverMode,
                paytm_merchant_upi: paytmConfig.merchantUpi,
                paytm_mid: paytmConfig.merchantMid
            }).catch((e) => {
                console.warn('Shop settings save failed', e);
                return false;
            });
        }

